-- COPY-DATABASE-OBJECT: "BND"."VIW_LIBERACOES_BNDES"
CREATE OR REPLACE VIEW "BND"."VIW_LIBERACOES_BNDES" (
    IDOPERACAOCREDITO,
    IDPESSOA,
    NUMCONTRATOCREDITO,
    DATACONTRATACAO,
    DATAVENCIMENTO,
    VALORCONTRATADO,
    NUMREFBACEN,
    IDINSTITUICAO,
    IDUNIDADEINST,
    NUMPARCELA,
    DATALIBERACAO,
    VALORPARCELA,
    IDEMPREENDIMENTORURAL,
    IDEMPREENDIMENTOBACEN,
    IDMUNICIPIO,
    NUMREGCAR,
    CODPRODUTOPDC,
    BOLCPRBNDES,
    SIGLACADASTROPROPOSTA,
    SIGLAPROGRAMA
) AS
SELECT OP.IDOPERACAOCREDITO AS idOperacaoCredito,
    EC.IDPESSOA AS idPessoa,
    P.NUMCONTRATOCREDITO AS numContratoCredito,
    P.DATACONTRATACAO AS dataContratacao,
    OP.DATAVENCIMENTOOPERACAO AS dataVencimento,
    P.VALOROPERACAO AS valorContratado,
    envioSicor.NUMREFBACEN AS numRefBacen,
    P.IDINSTITUICAO AS idInstituicao,
    p.idUnidadeInstituicao AS idUnidadeInst,
    PL.NUMPARCELA AS numParcela,
    PL.DATALIBERACAOCLIENTE AS dataLiberacao,
    PL.VALORLIBERADOBNDES AS valorParcela,
    EMPR.IDEMPREENDIMENTORURAL AS idEmpreendimentoRural,
    EMPR.IDEMPREENDIMENTOBACEN AS idEmpreendimentoBacen,
    EMPR.IDMUNICIPIO AS idMunicipio,
    EMPIM.NUMREGCAR AS numRegCar,
    CASE
        WHEN PB.CODPRODUTOSISBR = 7 THEN 2
        WHEN PB.CODPRODUTOSISBR = 6 THEN 4
    END AS CODPRODUTOPDC,
    PB.BOLCPRBNDES,
    PB.SIGLACADASTROPROPOSTA,
    PB.SIGLAPROGRAMA
FROM BND.PREPROPOSTABNDES P
    INNER JOIN BND.ENQUADRAMENTOCLIENTE EC ON EC.IDENQUADRAMENTOCLIENTE = P.IDENQUADRAMENTOCLIENTE
    INNER JOIN BND.PEDIDOLIBERACAOBNDES PL ON PL.IDPREPROPOSTABNDES = P.IDPREPROPOSTABNDES
    INNER JOIN CRE.OPERACAOCREDITO OP ON OP.IDOPERACAOCREDITO = P.IDOPERACAOCREDITO
    INNER JOIN BND.PROGRAMABNDES PB ON PB.CODPROGRAMABNDES = P.CODPROGRAMABNDES
    LEFT JOIN CRE.EMPREENDIMENTORURALINTEGRACAO EMPINT ON EMPINT.IDNEGOCIO = P.IDPREPROPOSTABNDES
    LEFT JOIN CRE.EMPREENDIMENTORURAL EMPR ON EMPR.IDEMPREENDIMENTORURAL = EMPINT.IDEMPREENDIMENTORURAL
    LEFT JOIN CRE.EMPREENDIMENTORURALIMOVEL EMPIM ON EMPIM.IDEMPREENDIMENTORURAL = EMPINT.IDEMPREENDIMENTORURAL
    LEFT JOIN TABLE (
        SELECT ENVIO.NUMCONTROLEIF,
            RETORNO.NUMREFBACEN,
            ENVIO.IDOPERACAOCREDITO
        FROM CRE.OPERACAOCREDITORETORNOSICOR RETORNO
            JOIN CRE.OPERACAOCREDITOENVIOSICOR ENVIO ON ENVIO.NUMCONTROLEIF = RETORNO.NUMCONTROLEIF
        WHERE ENVIO.IDOPERACAOCREDITO = P.IDOPERACAOCREDITO
            AND RETORNO.NUMREFBACEN IS NOT NULL
            AND ENVIO.NUMTIPOENVIOMENSAGERIASICOR = 1
            AND RETORNO.CODMENSAGEM = 'COR0001R1'
        ORDER BY ENVIO.DATAHORAEMISSAO DESC
        FETCH FIRST 1 ROW ONLY
    ) envioSicor ON 1 = 1
WHERE PL.DATALIBERACAOCLIENTE IS NOT NULL
    AND PL.NUMPARCELA = 1
    AND OP.IDSITUACAOCREDITO IN (21, 22, 23, 24, 96)
GROUP BY OP.IDOPERACAOCREDITO,
    EC.IDPESSOA,
    P.NUMCONTRATOCREDITO,
    P.DATACONTRATACAO,
    OP.DATAVENCIMENTOOPERACAO,
    P.VALOROPERACAO,
    envioSicor.NUMREFBACEN,
    P.IDINSTITUICAO,
    p.idUnidadeInstituicao,
    PL.NUMPARCELA,
    PL.DATALIBERACAOCLIENTE,
    PL.VALORLIBERADOBNDES,
    EMPR.IDEMPREENDIMENTORURAL,
    EMPR.IDEMPREENDIMENTOBACEN,
    EMPR.IDMUNICIPIO,
    EMPIM.NUMREGCAR,
    PB.CODPRODUTOSISBR,
    PB.BOLCPRBNDES,
    PB.SIGLACADASTROPROPOSTA,
    PB.SIGLAPROGRAMA
HAVING EMPIM.NUMREGCAR IS NULL OR COUNT(DISTINCT EMPIM.NUMREGCAR) = 1
;
