CREATE OR REPLACE VIEW "BNDU"."VIW_GESTAO_BENS_ANEXOS_FECHADOS"
    (
        ID_INSTITUICAO,
        ID_UNIDADE_INSTITUICAO,
        ID_GESTAO_BEM,
        ID_PESSOA_BEM,
        ID_BEM_CAPES,
        NUMERO_CARTORIO,
        NUMERO_MATRICULA,
        PLACA_VEICULO,
        RENAVAM_VEICULO,
        CHASSI_VEICULO,
        ANO_FABRICACAO,
        ANO_MODELO,
        DESCRICAO_BEM,
        OBSERVACOES_BEM,
        ATIVO,
        BEM_TERCEIRO,
        DATA_HORA_CRIACAO,
        NUMERO_GESTAO_BEM,
        DATA_HORA_RECEBIMENTO,
        DETALHE_DESCRICAO_BEM,
        ID_STATUS_BEM,
        STATUS_BEM,
        ID_SITUACAO_BEM,
        SITUACAO_BEM,
        ID_DETALHE_LOCAL_USO,
        DETALHE_LOCAL_USO,
        CLASSIFICACAO_LOCAL_USO,
        ID_TIPO_BEM,
        TIPO_BEM,
        ID_FORMA_RECEBIMENTO,
        FORMA_RECEBIMENTO,
        NUMERO_CONTRATO,
        CREDITO_ID_PROCESSO_BEM,
        ID_PROCESSO_PESCOA_CREDITO,
        ID_CONTRATO_CREDITO,
        ID_PAGAMENTO_SISBR,
        SALDO_FINANCEIRO,
        SALDO_DEVEDOR_CONTABIL,
        DATA_HORA_PAGAMENTO,
        ID_PROCESSO_TIPO_FINANCEIRO,
        NUMERO_CONTA_CORRENTE,
        VALOR_PAGAMENTO_PARCIAL,
        ID_GESTAO_AVALIACAO_BEM,
        AVALIACAO_ID_GESTAO_BEM,
        DESCRICAO_AVALIACAO,
        VALOR_AVALIACAO,
        VALOR_CONTABIL,
        VALOR_PROVISAO,
        VALOR_CONTA_REDUTORA,
        VALOR_SALDO_DEVEDOR,
        VALOR_DESCONTO,
        VALOR_DESPESA,
        LISTA_DOCUMENTOS_ANEXOS
    ) AS
SELECT
    -- 1. Dados do Processo e Bem
    pb.IDINSTITUICAO       AS ID_INSTITUICAO,
    pb.IDUNIDADEINST       AS ID_UNIDADE_INSTITUICAO,
    gb.IDGESTAOBEM         AS ID_GESTAO_BEM,
    gb.IDPESSOABEM         AS ID_PESSOA_BEM,
    gb.IDBEMCAPES          AS ID_BEM_CAPES,
    gb.NUMCARTORIO         AS NUMERO_CARTORIO,
    gb.NUMMATRICULA        AS NUMERO_MATRICULA,
    gb.NUMPLACA            AS PLACA_VEICULO,
    gb.NUMRENAVAM          AS RENAVAM_VEICULO,
    gb.NUMCHASSI           AS CHASSI_VEICULO,
    gb.ANOFABRICACAO       AS ANO_FABRICACAO,
    gb.ANOMODELO           AS ANO_MODELO,
    gb.DESCBEM             AS DESCRICAO_BEM,
    gb.DESCOBSERVACAOBEM   AS OBSERVACOES_BEM,
    gb.BOLATIVO            AS ATIVO,
    gb.BOLBEMTERCEIRO      AS BEM_TERCEIRO,
    gb.DATAHORACRIACAO     AS DATA_HORA_CRIACAO,
    gb.NUMGESTAOBEM        AS NUMERO_GESTAO_BEM,
    gb.DATAHORARECEBIMENTO AS DATA_HORA_RECEBIMENTO,
    gb.DESCBEMDETALHE      AS DETALHE_DESCRICAO_BEM,
    -- Domínios do Bem
    gb.IDSTATUSTIPOBEM                        AS ID_STATUS_BEM,
    stb.NOMESTATUSTIPOBEM                     AS STATUS_BEM,
    gb.IDSITUACAOTIPOBEM                      AS ID_SITUACAO_BEM,
    sob.NOMESITUACAOTIPOBEM                   AS SITUACAO_BEM,
    gb.IDTIPOCLASSIFICACAOLOCALUSODETALHE     AS ID_DETALHE_LOCAL_USO,
    tcud.NOMETIPOCLASSIFICACAOLOCALUSODETALHE AS DETALHE_LOCAL_USO,
    tcu.NOMETIPOCLASSIFICACAOLOCALUSO         AS CLASSIFICACAO_LOCAL_USO,
    gb.IDTIPOBEM                              AS ID_TIPO_BEM,
    tb.NOMETIPOBEM                            AS TIPO_BEM,
    gb.IDFORMARECEBIMENTO                     AS ID_FORMA_RECEBIMENTO,
    fr.NOMEFORMARECEBIMENTO                   AS FORMA_RECEBIMENTO,
    -- 2. Dados de Crédito (ppc) Abertos Linha a Linha
    ppc.NUMEROCONTRATO           AS NUMERO_CONTRATO,
    ppc.IDPROCESSOBEM            AS CREDITO_ID_PROCESSO_BEM,
    ppc.IDPROCESSOPESSOACREDITO  AS ID_PROCESSO_PESCOA_CREDITO,
    ppc.IDCONTRATOCREDITO        AS ID_CONTRATO_CREDITO,
    ppc.IDPAGAMENTOCREDITOSISBR  AS ID_PAGAMENTO_SISBR,
    ppc.VALORSALDOFINANCEIRO     AS SALDO_FINANCEIRO,
    ppc.VALORSALDODEVCONTABIL    AS SALDO_DEVEDOR_CONTABIL,
    ppc.DATAHORAPAGAMENTO        AS DATA_HORA_PAGAMENTO,
    ppc.IDPROCESSOTIPOFINANCEIRO AS ID_PROCESSO_TIPO_FINANCEIRO,
    ppc.NUMCONTACORRENTE         AS NUMERO_CONTA_CORRENTE,
    ppc.VALORPAGAMENTOPARCIAL    AS VALOR_PAGAMENTO_PARCIAL,
    -- 3. Dados de Avaliação (gab) Abertos Linha a Linha
    gab.IDGESTAOAVALIACAOBEM AS ID_GESTAO_AVALIACAO_BEM,
    gab.IDGESTAOBEM          AS AVALIACAO_ID_GESTAO_BEM,
    gab.DESCAVALIACAOBEM     AS DESCRICAO_AVALIACAO,
    gab.VALORAVALIACAO       AS VALOR_AVALIACAO,
    gab.VALORCONTABIL        AS VALOR_CONTABIL,
    gab.VALORPROVISAO        AS VALOR_PROVISAO,
    gab.VALORCONTAREDUTORA   AS VALOR_CONTA_REDUTORA,
    gab.VALORSALDODEVEDOR    AS VALOR_SALDO_DEVEDOR,
    gab.VALORDESCONTO        AS VALOR_DESCONTO,
    gab.VALORDESPESA         AS VALOR_DESPESA,
    -- 4. Apenas Anexos Fechados em Lista (CLOB)
    ANEXOS.LISTA_DOCUMENTOS AS LISTA_DOCUMENTOS_ANEXOS
FROM
    BNDU.GESTAOBEM gb
INNER JOIN
    BNDU.PROCESSOBEM pb
ON
    pb.IDPROCESSOBEM = gb.IDPROCESSOBEM
LEFT JOIN
    BNDU.STATUSTIPOBEM stb
ON
    gb.IDSTATUSTIPOBEM = stb.IDSTATUSTIPOBEM
LEFT JOIN
    BNDU.SITUACAOTIPOBEM sob
ON
    gb.IDSITUACAOTIPOBEM = sob.IDSITUACAOTIPOBEM
LEFT JOIN
    BNDU.TIPOCLASSIFICACAOLOCALUSODETALHE tcud
ON
    gb.IDTIPOCLASSIFICACAOLOCALUSODETALHE = tcud.IDTIPOCLASSIFICACAOLOCALUSODETALHE
LEFT JOIN
    BNDU.TIPOCLASSIFICACAOLOCALUSO tcu
ON
    tcud.IDTIPOCLASSIFICACAOLOCALUSO = tcu.IDTIPOCLASSIFICACAOLOCALUSO
LEFT JOIN
    BNDU.TIPOBEM tb
ON
    tb.IDTIPOBEM = gb.IDTIPOBEM
LEFT JOIN
    BNDU.FORMARECEBIMENTO fr
ON
    fr.IDFORMARECEBIMENTO = gb.IDFORMARECEBIMENTO
LEFT JOIN
    BNDU.PROCESSOPESSOACREDITO ppc
ON
    ppc.IDPROCESSOBEM = pb.IDPROCESSOBEM
AND ppc.BOLATIVO = 1
LEFT JOIN
    BNDU.GESTAOAVALIACAOBEM gab
ON
    gab.IDGESTAOBEM = gb.IDGESTAOBEM
AND gab.BOLATIVO = 1
LEFT JOIN
    (
        SELECT
            gxb.IDGESTAOBEM,
            REPLACE(REPLACE( XMLSERIALIZE(CONTENT XMLAGG( XMLELEMENT(NAME "X", CAST
            (gxb.IDDOCUMENTOANEXO AS VARCHAR(50)) || ' - ' || gxb.NOMEDOCUMENTOANEXO || '; ' )
            ORDER BY gxb.NOMEDOCUMENTOANEXO ) AS CLOB), '<X>', ''), '</X>', '') AS LISTA_DOCUMENTOS
        FROM
            BNDU.GESTAOANEXOBEM gxb
        WHERE
            gxb.BOLATIVO = 1
        GROUP BY
            gxb.IDGESTAOBEM ) ANEXOS
ON
    ANEXOS.IDGESTAOBEM = gb.IDGESTAOBEM
;
