CREATE OR REPLACE VIEW "CCL"."VIW_CONSULTALIMITECCLPAR" AS
SELECT 
    l.IDLIMITECONCESSAO,
    l.IDINFORMACAOLIMITE,
    l.IDLIMITECONCESSAOPAI,  
    l.BOLATIVO,
    l.CODTIPORECEBIVEL,
    tr.NOMETIPORECEBIVEL,
    l.CODTIPOGRUPORECEBIVEL,
    t.NOMEGRUPORECEBIVEL,
    l.CODTIPOLIMITE,
    i.IDOPERACAOCREDITO,
    i.CODSITUACAOLIMITE,
    s.DESCSITUACAOLIMITE,
    cf.NUMCONTACORRENTE,
    l.VALORLIMITETOTAL,
    i.VALORCONTRATO,
    i.NUMCONTRATO,
    i.NUMPROTOCOLO AS CCB,
    i.DATAINICIOVIGENCIA,
    i.DATAFIMVIGENCIA,
    p.QTDDIAPRAZOVENCIMENTO, 
    p.PERCTAXAJUROSMAX,
    p.PERCTAXAJUROSMIN,
    p.PERCTAXAMORTIZACAOMAX,
    p.PERCTAXAMORTIZACAOMIN,
    p.PERCTAXAMULTAMAX,
    p.PERCTAXAMULTAMIN, 
    i.IDINSTITUICAO,
    i.IDPESSOA,
    vp.VALORTOTALCLS AS VALORATRIBUIDO,
    vp.VALORMARGEM AS VALORDISPONIVEL,
    vp.VALORUTILIZADO
FROM ccl.LIMITECONCESSAO l 
INNER JOIN ccl.INFORMACAOLIMITE i 
    ON i.IDINFORMACAOLIMITE = l.IDINFORMACAOLIMITE 
INNER JOIN ccl.INFORMACAOLIMITEPAR p 
    ON p.IDINFORMACAOLIMITE = l.IDINFORMACAOLIMITE
INNER JOIN ccl.SITUACAOLIMITE s
	ON s.CODSITUACAOLIMITE = i.CODSITUACAOLIMITE
INNER JOIN ccl.CONTAFAVORECIDO cf
	ON cf.IDINFORMACAOLIMITE = i.IDINFORMACAOLIMITE
INNER JOIN ccl.POSICAOLIMITECONCESSAO po 
    ON po.IDLIMITECONCESSAO = l.IDLIMITECONCESSAO 
LEFT JOIN ccl.TIPOGRUPORECEBIVEL t 
    ON t.CODTIPOGRUPORECEBIVEL = l.CODTIPOGRUPORECEBIVEL 
LEFT JOIN ccl.TIPORECEBIVELPAR tr  
    ON tr.CODTIPORECEBIVEL = l.CODTIPORECEBIVEL
LEFT JOIN ccl.MAPEAMENTOCLS mcls 
    ON mcls.IDMAPEAMENTOCLS = t.IDMAPEAMENTOCLS
LEFT JOIN (
    SELECT 
        vp.VALORUTILIZADO, 
        vp.VALORMARGEM, 
        vp.VALORTOTALCLS,
        vp.IDPESSOA,
        vp.IDINSTITUICAO,
        vp.IDMODALIDADEBACEN,
        vp.IDSUBMODALIDADEBACEN,
        vp.IDDOMINIOORIGEM,
        vp.IDDOMINIOCALCULO,
        vp.IDDOMINIOCONSIGNADO,
        vp.IDDOMINIOPARCELA,
        vp.IDDOMINIOVENCIMENTO
    FROM cls.VIW_POSICAOLIMITETOMADOR vp
    FETCH FIRST 99999999999 ROWS ONLY
) AS vp (
    VALORUTILIZADO, VALORMARGEM, VALORTOTALCLS,
    IDPESSOA, IDINSTITUICAO, IDMODALIDADEBACEN,
    IDSUBMODALIDADEBACEN, IDDOMINIOORIGEM, IDDOMINIOCALCULO,
    IDDOMINIOCONSIGNADO, IDDOMINIOPARCELA, IDDOMINIOVENCIMENTO
)
    ON vp.IDPESSOA = i.IDPESSOA 
    AND vp.IDINSTITUICAO = i.IDINSTITUICAO
    AND vp.IDMODALIDADEBACEN = mcls.IDMODALIDADEBACEN
    AND vp.IDSUBMODALIDADEBACEN = mcls.IDSUBMODALIDADEBACEN
    AND vp.IDDOMINIOORIGEM = mcls.IDDOMINIOORIGEM
    AND vp.IDDOMINIOCALCULO = mcls.IDDOMINIOCALCULO
    AND vp.IDDOMINIOCONSIGNADO = mcls.IDDOMINIOCONSIGNADO
    AND vp.IDDOMINIOPARCELA = mcls.IDDOMINIOPARCELA
    AND vp.IDDOMINIOVENCIMENTO = mcls.IDDOMINIOVENCIMENTO
WHERE i.CODTIPODOMINIO = 3
;
