-- COPY-DATABASE-OBJECT: "CCL"."VIW_LISTARLIMITESCCLPORTIPO"
CREATE OR REPLACE VIEW "CCL"."VIW_LISTARLIMITESCCLPORTIPO" AS
SELECT 
      i.IDOPERACAOCREDITO
	, i.IDINSTITUICAO
	, i.IDPESSOA
	, COALESCE(c.NUMCONTACORRENTE, c2.NUMCONTACORRENTE) NUMCONTACORRENTE
	, i.VALORCONTRATO
	, i.CODSITUACAOLIMITE
	, s.DESCSITUACAOLIMITE
	, t.CODTIPODOMINIO
	, t.DESCDOMINIO
	, i.DATAINICIOVIGENCIA
    , i.DATAFIMVIGENCIA
FROM ccl.INFORMACAOLIMITE i
INNER JOIN ccl.TIPODOMINIO t ON t.CODTIPODOMINIO = i.CODTIPODOMINIO 
INNER JOIN ccl.SITUACAOLIMITE s ON s.CODSITUACAOLIMITE = i.CODSITUACAOLIMITE
LEFT JOIN ccl.INFORMACAOLIMITECONTACORRENTE c ON c.IDINFORMACAOLIMITE = i.IDINFORMACAOLIMITE
LEFT JOIN ccl.CONTAFAVORECIDO c2 ON c2.IDINFORMACAOLIMITE = i.IDINFORMACAOLIMITE 
WHERE i.CODSITUACAOLIMITE NOT IN (3, 4)
  AND s.CODSITUACAOLIMITE NOT IN (3, 4)
  AND t.CODTIPODOMINIO IN (3, 4, 6, 5)
  AND i.CODTIPODOMINIO IN (3, 4, 6, 5)
;
-- COPY-DATABASE-OBJECT: "CCL"."VIW_REPOSITORIOCREDAUTO"
CREATE VIEW "CCL"."VIW_REPOSITORIOCREDAUTO" AS 
SELECT
	IDINSTITUICAO, IDPESSOA, CODMODOPERACAOBACEN, CODSUBMODOPERACAOBACEN, IDPERFILTOMADOR, VALORMARGEMAUTOMATICO, BOLLINHAPREAPROVADA, DATAHORAPROCESSAMENTONPC
	, VALORPARCELAMAX, VALORLIMITENPC, VALORPARCELAMIN, VALORMINLIMITE, VALORPARCELANPC, DATAHORAENDIVIDAMENTOSCR
FROM
	CCL.TMPTOMADORFABRICALIMITE T
WHERE
	CODMODOPERACAOBACEN = 2
AND CODSUBMODOPERACAOBACEN IN (3,15,16)
AND VALORMARGEMAUTOMATICO > 0
AND (
	SELECT COALESCE (
				(SELECT VALORPARAMETROINSTITUICAO FROM  CCL.PARAMETROINSTITUICAO  WHERE IDINSTITUICAO = T.IDINSTITUICAO AND CODPARAMETRO = P.CODPARAMETRO AND VALORPARAMETROINSTITUICAO = 1)
		, VALORPARAMETRO) VALORPAR
	FROM CCL.PARAMETRO P
	WHERE CODPARAMETRO = 36
	) = 1
;
