                        ,e.DESCESTRATEGIANEGOCIO
                        ,h.IDHIERARQUIAVALORJUSTO
                        ,h.CODHIERARQUIAVALORJUSTO
                        ,h.DESCHIERARQUIAVALORJUSTO
                        ,i.IDINSTRUMENTOFINANCEIRO
                        ,i.CODINSTRUMENTOFINANCEIRO
                        ,i.DESCINSTRUMENTOFINANCEIRO
