                        ,c2.CODMODALIDADECR
                        ,c2.CODSUBMODALIDADECR
                    FROM CIF.REGISTROCLASSIFICACAOINSTRUMENTOFINANCEIRO r
                    INNER JOIN CIF.CONTROLECARTEIRA c2
                        ON R.IDCONTROLECARTEIRA = C2.IDCONTROLECARTEIRA
                    INNER JOIN CIF.REGISTROTESTESPPJ r3
                        ON r.IDCONTROLECARTEIRA = R3.IDCONTROLECARTEIRA
                    INNER JOIN cif.MODELONEGOCIO m
                        ON r.IDMODELONEGOCIO = m.IDMODELONEGOCIO
                    INNER JOIN cif.CLASSIFICACAOINSTRUMENTOFINANCEIRO c
                        ON r.IDCLASSIFICACAOINSTRUMENTOFINANCEIRO = c.IDCLASSIFICACAOINSTRUMENTOFINANCEIRO
                    INNER JOIN cif.ESTRATEGIANEGOCIO e
                        ON r.IDESTRATEGIANEGOCIO = e.IDESTRATEGIANEGOCIO
                    INNER JOIN cif.HIERARQUIAVALORJUSTO h
                        ON c2.IDHIERARQUIAVALORJUSTO = h.IDHIERARQUIAVALORJUSTO
                    INNER JOIN cif.INSTRUMENTOFINANCEIRO i
                        ON c2.IDINSTRUMENTOFINANCEIRO = i.IDINSTRUMENTOFINANCEIRO
					INNER JOIN cif.PRODUTOCIF p
						ON c2.IDPRODUTOCIF = p.IDPRODUTOCIF
