-- COPY-DATABASE-OBJECT: "CLI"."VIW_BEMLEGADO"
CREATE OR REPLACE VIEW  "CLI"."VIW_BEMLEGADO"
   (
      IDBEMNOVO,
      IDPESSOA,
      IDBEMVELHO,
      RELEVANCIA,
      IDINSTITUICAO
   ) AS
SELECT B.IDBEMNOVO
	,PC.IDPESSOA
	,B.IDBEMPESSOA AS IDBEMVELHO
	,1 AS RELEVANCIA
	,TP.IDINSTITUICAO
FROM CLI.BEMPESSOA B
INNER JOIN CLI.PESSOACOMPARTILHAMENTO PC ON B.IDPESSOACOMPARTILHAMENTO = PC.IDPESSOACOMPARTILHAMENTO
INNER JOIN CLI.TRANSICAOPESSOA TP ON PC.IDPESSOACOMPARTILHAMENTO = TP.IDPESSOACOMPARTILHAMENTO
WHERE B.DATAHORAINICIO IS NOT NULL

UNION

SELECT B.IDBEMNOVO
	,PCP.IDPESSOA
	,B.IDBEMPESSOA AS IDBEMVELHO
	,2 AS RELEVANCIA
	,TP.IDINSTITUICAO
FROM CLI.BEMPESSOA B
INNER JOIN CLI.BEMPESSOAIMOVEL BI ON B.IDBEMPESSOA = BI.IDBEMPESSOA
INNER JOIN CLI.BEMPESSOAPOSSE BP ON BI.IDBEMPESSOA = BP.IDBEMPESSOA
INNER JOIN CLI.PESSOACOMPARTILHAMENTO PCP ON BP.IDPESSOACOMPARTILHAMENTOPARCEIRO = PCP.IDPESSOACOMPARTILHAMENTO
INNER JOIN CLI.TRANSICAOPESSOA TP ON PCP.IDPESSOACOMPARTILHAMENTO = TP.IDPESSOACOMPARTILHAMENTO
WHERE B.DATAHORAINICIO IS NOT NULL
;
-- COPY-DATABASE-OBJECT: "CLI"."VIW_BEMPESSOA"
CREATE OR REPLACE VIEW "CLI"."VIW_BEMPESSOA" AS
SELECT 
        BPI.DESCDENOMINACAO,
        BPI.QTDAREAIMOVEL,
        BPI.DESCMUNICIPIOIMOVEL,
        BPI.SIGLAUFMUNICIPIOIMOVEL,
        BR.DESCMATRICULAREGISTRO,
        BP.IDBEMPESSOA,
        BP.IDBEMNOVO,
        P.NUMCPFCNPJ, 
        P.IDPESSOA,
        PC.CODCOMPARTILHAMENTOCADASTRO,
        TP.IDINSTITUICAO 
        FROM 
                CLI.BEMPESSOA BP
                LEFT JOIN CLI.BEMPESSOAREGISTRO BR ON BR.IDBEMPESSOA = BP.IDBEMPESSOA
                INNER JOIN CLI.BEMPESSOAIMOVEL BPI ON BPI.IDBEMPESSOA = BP.IDBEMPESSOA
                INNER JOIN CLI.PESSOACOMPARTILHAMENTO PC ON PC.IDPESSOACOMPARTILHAMENTO = BP.IDPESSOACOMPARTILHAMENTO
                INNER JOIN CLI.PESSOA P ON P.IDPESSOA = PC.IDPESSOA
                INNER JOIN CLI.TRANSICAOPESSOA TP ON TP.IDPESSOACOMPARTILHAMENTO = BP.IDPESSOACOMPARTILHAMENTO
WHERE 
        BP.DATAHORAINICIO IS NOT NULL 
        AND BP.IDINSTITUICAOATUALIZACAO IS NULL
;
-- COPY-DATABASE-OBJECT: "CLI"."VIW_BEMPROPERIETARIOPARCEIRO"
CREATE OR REPLACE VIEW "CLI"."VIW_BEMPROPERIETARIOPARCEIRO" ( IDBEM , DESCRICAOBEM , COMPLEMENTO , DENOMINACAO , INFORMACAOGERAL , MATRICULA , NUMERO , IDLOCALIDADE , IDLOGRADOURO , IDPESSOA , CLASSIFICACAOBEM , IDINSTITUICAO , TIPOBEMMOVEL , TIPOCHASSIBEM , NUMEROCHASSI , ANOFABRICACAOAUTOMOVEL , ANOCONSTRUCAOEMBARCACAO , ANOCONSTRUCAOAERONAVE , NUMRENAVAN , ANOMODELOAUTOMOVEL , DESCRICAOEMBARCACAO , DESCRICAOMATRICULAAERONAVE , UF , PLACA ) AS SELECT B.IDBEM , B.DESCBEM , BI.DESCCOMPLEMENTO , BI.DESCDENOMINACAO , BI.DESCINFORMACAOGERAL , BI.DESCMATRICULA , BI.DESCNUMERO , BI.IDLOCALIDADE , BI.IDLOGRADOURO , PC.IDPESSOA , B.CODTIPOCLASSIFICACAOBEM AS CLASSIFICACAOBEM , TP.IDINSTITUICAO , BM.CODTIPOBEMMOVEL AS TIPOBEMMOVEL , BM.CODTIPOCHASSIBEM AS TIPOCHASSIBEM , BM.NUMCHASSI AS NUMEROCHASSI , BM.ANOFABRICACAOAUTOMOVEL AS ANOFABRICACAOAUTOMOVEL , BM.ANOCONSTRUCAOEMBARCACAO AS ANOCONSTRUCAOEMBARCACAO , BM.ANOCONSTRUCAOAERONAVE AS ANOCONSTRUCAOAERONAVE , BM.NUMRENAVAN AS NUMRENAVAN , BM.ANOMODELOAUTOMOVEL AS ANOMODELOAUTOMOVEL , BM.DESCINCRICAOEMBARCACAO AS DESCRICAOEMBARCACAO , BM.DESCMATRICULAAERONAVE AS DESCRICAOMATRICULAAERONAVE , BM.SIGLAUF AS UF , BM.DESCPLACA AS PLACA FROM CLI.BEM B INNER JOIN CLI.BEMPESSOACOMPARTILHAMENTO BPC ON BPC.IDBEM = B.IDBEM INNER JOIN CLI.PESSOACOMPARTILHAMENTO PC ON PC.IDPESSOACOMPARTILHAMENTO = BPC.IDPESSOACOMPARTILHAMENTO INNER JOIN CLI.TRANSICAOPESSOA TP ON TP.IDPESSOACOMPARTILHAMENTO = PC.IDPESSOACOMPARTILHAMENTO LEFT JOIN CLI.BEMIMOVEL BI ON BI.IDBEM = B.IDBEM LEFT JOIN CLI.BEMMOVEL BM ON BM.IDBEM = B.IDBEM LEFT JOIN CLI.TIPOINFUTILIZAINFPESSOA TI ON TI.IDINFORMACAOPESSOA = B.IDBEM AND TI.IDTIPOINFORMACAOPESSOA = 6 WHERE B.DATAHORAINICIO IS NOT NULL UNION ALL SELECT B.IDBEM , B.DESCBEM , BI.DESCCOMPLEMENTO , BI.DESCDENOMINACAO , BI.DESCINFORMACAOGERAL , BI.DESCMATRICULA , BI.DESCNUMERO , BI.IDLOCALIDADE , BI.IDLOGRADOURO , PC.IDPESSOA , B.CODTIPOCLASSIFICACAOBEM AS CLASSIFICACAOBEM , TP.IDINSTITUICAO , NULL AS TIPOBEMMOVEL , NULL AS TIPOCHASSIBEM , NULL AS NUMEROCHASSI , NULL AS ANOFABRICACAOAUTOMOVEL , NULL AS ANOCONSTRUCAOEMBARCACAO , NULL AS ANOCONSTRUCAOAERONAVE , NULL AS NUMRENAVAN , NULL AS ANOMODELOAUTOMOVEL , NULL AS DESCRICAOEMBARCACAO , NULL AS DESCRICAOMATRICULAAERONAVE , NULL AS UF , NULL AS PLACA FROM CLI.BEM B INNER JOIN CLI.BEMIMOVEL BI ON BI.IDBEM = B.IDBEM INNER JOIN CLI.BEMIMOVELTIPORELACIONAMENTOPESSOA BITRP ON BITRP.IDBEM = B.IDBEM INNER JOIN CLI.PESSOACOMPARTILHAMENTO PC ON PC.IDPESSOACOMPARTILHAMENTO = BITRP.IDPESSOACOMPARTILHAMENTO INNER JOIN CLI.TRANSICAOPESSOA TP ON TP.IDPESSOACOMPARTILHAMENTO = PC.IDPESSOACOMPARTILHAMENTO WHERE B.DATAHORAINICIO IS NOT NULL
;
-- COPY-DATABASE-OBJECT: "CLI"."VIW_BEM_AVALIACAO"
CREATE OR REPLACE VIEW "CLI"."VIW_BEM_AVALIACAO" 
    ( 
        NUMCPFCNPJ, 
        IDPESSOA, 
        IDINSTITUICAO, 
        EMAQUISICAO, 
        REPLICADO, 
        BLOQUEADO, 
        AVANCADO, 
        DESCUTILIZAINFORMACAOPESSOA, 
        IDUTILIZAINFORMACAOPESSOA, 
        DESCTIPOINFORMACAOPESSOA, 
        IDTIPOINFORMACAOPESSOA, 
        IDBEM, 
        IDBEMPESSOALEGADO, 
        CODTIPOCLASSIFICACAOBEM, 
        DESCTIPOCLASSIFICACAOBEM, 
        BOLBEMINTERNO, 
        DATAHORAULTIMAALTERACAO, 
        DESCBEM, 
        VALORBEM, 
        BOLVALORBEMNAOINFORMADO, 
        MESRENOVACAOSEGURO, 
        PERCPROPRIETARIO, 
        VALORCOMPRAVENDA, 
        DATACOMPRAVENDA, 
        VALORAVALIACAO, 
        DATAAVALIACAO, 
        IDPESSOAAVALIADOR, 
        NUMCPFCNPJAVALIADOR, 
        DATAAVALIACAOANTERIOR, 
        CODTIPOESTADOCONSERVACAOBEM, 
        IDUSUARIOAPROVACAO, 
        IDUSUARIOALTERACAO 
    ) 
    AS 
SELECT
    PU.NUMCPFCNPJ,
    PU.IDPESSOA,
    PU.IDINSTITUICAO,
    CASE
        WHEN ( 
                BIA.BOLEMPROCESSOAQUISICAO = 1
            OR  BIA.BOLEMPROCESSOAQUISICAO = 1)
        THEN 1
        ELSE 0
    END AS EMAQUISICAO,
    CASE
        WHEN ( 
                BP.DATAHORAINICIO IS NOT NULL)
        THEN 1
        ELSE 0
    END AS REPLICADO,
    CASE
        WHEN ( 
                TINF.IDTIPOINFORMACAOPESSOA IS NOT NULL)
        THEN 1
        ELSE 0
    END AS BLOQUEADO,
    CASE
        WHEN( 
                ( 
                    BI.CODTIPOLOCALIZACAOBEM = 1
                AND BI.IDPESSOACOMPARTILHAMENTOCARTORIO IS NOT NULL
                AND BI.DESCMATRICULA IS NOT NULL)
            OR  ( 
                    BI.CODTIPOLOCALIZACAOBEM = 2
                AND ( 
                        BI.DESCNIRF IS NOT NULL
                    AND BI.DESCINCRA IS NOT NULL)
                OR  BI.DESCROTEIRO IS NOT NULL) )
        THEN 1
        ELSE 0
    END AS AVANCADO,
    UT.DESCUTILIZAINFORMACAOPESSOA,
    UT.IDUTILIZAINFORMACAOPESSOA,
    TINF.DESCTIPOINFORMACAOPESSOA,
    TINF.IDTIPOINFORMACAOPESSOA,
    B.IDBEM,
    BP.IDBEMPESSOA AS IDBEMPESSOALEGADO,
    B.CODTIPOCLASSIFICACAOBEM,
    TCB.DESCTIPOCLASSIFICACAOBEM,
    B.BOLBEMINTERNO,
    B.DATAHORAINICIO AS DATAHORAULTIMAALTERACAO,
    B.DESCBEM,
    B.VALORBEM,
    B.BOLVALORBEMNAOINFORMADO,
    B.MESRENOVACAOSEGURO,
    BPC.PERCPROPRIETARIO,
    CASE
        WHEN B.CODTIPOCLASSIFICACAOBEM = 1
        THEN BIA.VALORCOMPRAVENDA
        ELSE BMA.VALORCOMPRAVENDA
    END AS VALORCOMPRAVENDA,
    CASE
        WHEN B.CODTIPOCLASSIFICACAOBEM = 1
        THEN BIA.DATACOMPRAVENDA
        ELSE BMA.DATACOMPRAVENDA
    END AS DATACOMPRAVENDA,
    CASE
        WHEN B.CODTIPOCLASSIFICACAOBEM = 1
        THEN BIA.VALORAVALIACAO
        ELSE BMA.VALORAVALIACAO
    END AS VALORAVALIACAO,
    CASE
        WHEN B.CODTIPOCLASSIFICACAOBEM = 1
        THEN BIA.DATAAVALIACAO
        ELSE BMA.DATAAVALIACAO
    END            AS DATAAVALIACAO,
    PU2.IDPESSOA   AS IDPESSOAAVALIADOR,
    PU2.NUMCPFCNPJ AS NUMCPFCNPJAVALIADOR,
    CASE
        WHEN B.CODTIPOCLASSIFICACAOBEM = 1
        THEN 
            (   SELECT 
                    MAX(HBIA.DATAAVALIACAO) 
                FROM 
                    CLI.HISTBEMIMOVELAVALIACAO HBIA 
                INNER JOIN 
                    CLI.HISTBEM HB 
                ON 
                    HBIA.IDHISTBEM = HB.IDHISTBEM 
                WHERE 
                    HB.IDBEM = B.IDBEM 
                AND HBIA.DATAAVALIACAO < BIA.DATAAVALIACAO)
        ELSE 
             (   SELECT 
                     MAX(HBMA.DATAAVALIACAO) 
                 FROM 
                     CLI.HISTBEMMOVELAVALIACAO HBMA 
                 INNER JOIN 
                     CLI.HISTBEM HB 
                 ON 
                     HBMA.IDHISTBEM = HB.IDHISTBEM 
                 WHERE 
                     HB.IDBEM = B.IDBEM 
                 AND HBMA.DATAAVALIACAO < BMA.DATAAVALIACAO)
    END AS DATAAVALIACAOANTERIOR,
    BMA.CODTIPOESTADOCONSERVACAOBEM,
    B.IDUSUARIOAPROV AS IDUSUARIOAPROVACAO,
    B.IDUSUARIOENVIO AS IDUSUARIOALTERACAO
FROM 
    CLI.BEM B 
INNER JOIN 
    CLI.BEMPESSOACOMPARTILHAMENTO BPC 
ON 
    BPC.IDBEM = B.IDBEM
INNER JOIN 
    CLI.PESSOAUNIFICADA PU 
ON 
    PU.IDPESSOACOMPARTILHAMENTO = BPC.IDPESSOACOMPARTILHAMENTO
AND PU.CODCOMPARTILHAMENTOCADASTRO = 1
LEFT JOIN 
    CLI.TIPOCLASSIFICACAOBEM TCB 
ON 
    TCB.CODTIPOCLASSIFICACAOBEM = B.CODTIPOCLASSIFICACAOBEM
LEFT JOIN 
    CLI.BEMIMOVEL BI 
ON 
    BI.IDBEM = B.IDBEM
LEFT JOIN 
    CLI.BEMPESSOA BP 
ON 
    BP.IDBEMNOVO = B.IDBEM
AND BP.IDPESSOACOMPARTILHAMENTO = BPC.IDPESSOACOMPARTILHAMENTO
LEFT JOIN 
    CLI.BEMIMOVELAVALIACAO BIA 
ON 
    BIA.IDBEM = B.IDBEM
LEFT JOIN 
    CLI.BEMMOVELAVALIACAO BMA 
ON 
    BMA.IDBEM = B.IDBEM
LEFT JOIN 
    CLI.PESSOAUNIFICADA PU2 
ON 
    PU.CODCOMPARTILHAMENTOCADASTRO = 1
AND 
    ( 
        PU2.IDPESSOACOMPARTILHAMENTO = BIA.IDPESSOACOMPARTILHAMENTOAVALIADOR
    OR  PU2.IDPESSOACOMPARTILHAMENTO = BMA.IDPESSOACOMPARTILHAMENTOAVALIADOR)
LEFT JOIN 
    CLI.TIPOINFUTILIZAINFPESSOA TI 
ON 
    TI.IDINFORMACAOPESSOA = B.IDBEM
AND TI.IDTIPOINFORMACAOPESSOA = 6
LEFT JOIN 
    CLI.UTILIZAINFORMACAOPESSOA UT 
ON 
    UT.IDUTILIZAINFORMACAOPESSOA = TI.IDUTILIZAINFORMACAOPESSOA
LEFT JOIN 
    CLI.TIPOINFORMACAOPESSOA TINF 
ON 
    TINF.IDTIPOINFORMACAOPESSOA = TI.IDTIPOINFORMACAOPESSOA
WHERE 
    B.DATAHORAINICIO IS NOT NULL
;
-- COPY-DATABASE-OBJECT: "CLI"."VIW_BEM_COMPLETO"
