RIOENVIO_SEFAZ, IDUSUARIOEXCLUSAO_SEFAZ, IDBEMRENAJUD, DATABEMRENAJUD, DESCBEMRENAJUD, NOMETRIBUNALRENAJUD, NOMEORGAOJUDICIARIORENAJUD, DESCPROCESSORENAJUD, DESCMENSAGEMRENAJUD, DATAHORAINICIO_RENAJUD, DESCOBSERVACAOBEMRENAJUD, IDUSUARIOAPROVACAO_RENAJUD, IDUSUARIOENVIO_RENAJUD, IDUSUARIOEXCLUSAO_RENAJUD, IDBEMMOVELLICENCIAMENTO, BOLEXISTEPENDENCIALICENCIAMENTO, VALORPENDENCIALICENCIAMENTO, DATAHORAINICIO_LICENCIAMENTO, DESCOBSERVACAOBEMMOVELLICENCIAMENTO, IDUSUARIOAPROVACAO_LICENCIAMENTO, IDUSUARIOENVIO_LICENCIAMENTO, IDUSUARIOEXCLUSAO_LICENCIAMENTO, IDBEMMOVELPRF, BOLNADACONSTA, BOLEXISTEMULTA, DATAHORAINICIO_PRF, DESCOBSERVACAOBEMMOVELPRF, IDUSUARIOAPROVACAO_PRF, IDUSUARIOENVIO_PRF, IDUSUARIOEXCLUSAO_PRF, IDPESSOA_AVALIADOR ) AS SELECT P.IDPESSOA, P.NUMCPFCNPJ, B.IDBEM, B.CODTIPOCLASSIFICACAOBEM, B.CODCOMPARTILHAMENTOCADASTRO, B.DESCBEM, B.BOLBEMINTERNO, B.VALORBEM, B.BOLVALORBEMNAOINFORMADO, B.MESRENOVACAOSEGURO, B.IDINSTITUICAOATUALIZACAO, B.IDUSUARIOAPROV, B.DATAHORAINICIO AS DATAHORAINICIO_BEM, B.IDUSUARIOENVIO, BM.CODTIPOBEMMOVEL, BM.CODTIPOCHASSIBEM, BM.NUMCHASSI, BM.NUMRENAVAN, BM.ANOFABRICACAOAUTOMOVEL, BM.ANOMODELOAUTOMOVEL, BM.DESCINCRICAOEMBARCACAO, BM.ANOCONSTRUCAOEMBARCACAO, BM.DESCMATRICULAAERONAVE, BM.CODTIPOCORAUTOMOVEL, BM.SIGLAUF, BM.DESCPLACA, BM.ANOCONSTRUCAOAERONAVE, BM.DESCMARCAVEICULO, BM.DESCMODELOVEICULO, BM.DESCTIPOVEICULO, BM.SIGLAUFLICENCIAMENTO, BDP.IDBEMDETALHEPESSOA, BDP.DESCBEMDETALHEPESSOA, BDP.DATAHORAINICIO            AS DATAHORAINICIO_BEMDETALHEPESSOA, BDP.IDUSUARIOSISTEMAAPROVACAO AS IDUSUARIOAPROVACAO_BEMDETALHEPESSOA, BDP.IDUSUARIOSISTEMAENVIO     AS IDUSUARIOENVIO_BEMDETALHEPESSOA, BDP.IDUSUARIOSISTEMAEXCLUSAO  AS IDUSUARIOEXCLUSAO_BEMDETALHEPESSOA, BF.IDBEMFINANCIAMENTO, BF.DESCAGENTEFINANCIAMENTO, BF.DATAINCLUSAOFINANCIAMENTO, BF.DATAVIGENCIACONTRATOFINANCIAMENTO, BF.NUMCONTRATOFINANCIAMENTO, BF.NUMRESTRICAOFINANCIAMENTO, BF.NUMTRANSACAOFINANCIAMENTO, BF.DATAHORAINICIO AS DATAHORAINICIO_BEMFINANCIAMENTO, BF.DESCBEMFINANCIAMENTO, BF.IDUSUARIOSISTEMAAPROVACAO AS IDUSUARIOAPROVACAO_BEMFINANCIAMENTO, BF.IDUSUARIOSISTEMAENVIO     AS IDUSUARIOENVIO_BEMFINANCIAMENTO, BF.IDUSUARIOSISTEMAEXCLUSAO  AS IDUSUARIOEXCLUSAO_BEMFINANCIAMENTO, AE.IDAVALIACAOEXTERNABEM, AE.DATAHORAINICIO AS DATAHORAINICIO_AVALIACAO, AE.CODFORNECEDOREXTERNO, AE.IDUSUARIOSISTEMAAPROVACAO AS IDUSUARIOAPROVACAO_AVALIACAO, AE.IDUSUARIOSISTEMAENVIO     AS IDUSUARIOENVIO_AVALIACAO, AE.IDUSUARIOSISTEMAEXCLUSAO  AS IDUSUARIOEXCLUSAO_AVALIACAO, IPVA.IDBEMMOVELIPVA, IPVA.BOLEXISTEPENDENCIAIPVA, IPVA.VALORPENDENCIAIPVA, IPVA.DATAHORAINICIO AS DATAHORAINICIO_IPVA, IPVA.DESCOBSERVACAOBEMMOVELIPVA, IPVA.IDUSUARIOSISTEMAAPROVACAO AS IDUSUARIOAPROVACAO_IPVA, IPVA.IDUSUARIOSISTEMAENVIO     AS IDUSUARIOENVIO_IPVA, IPVA.IDUSUARIOSISTEMAEXCLUSAO  AS IDUSUARIOEXCLUSAO_IPVA, DPVAT.IDBEMMOVELDPVAT, DPVAT.BOLEXISTEPENDENCIADPVAT, DPVAT.VALORPENDENCIADPVAT, DPVAT.DATAHORAINICIO AS DATAHORAINICIO_DPVAT, DPVAT.DESCOBSERVACAOBEMMOVELDPVAT, DPVAT.IDUSUARIOSISTEMAAPROVACAO AS IDUSUARIOAPROVACAO_DPVAT, DPVAT.IDUSUARIOSISTEMAENVIO     AS IDUSUARIOENVIO_DPVAT, DPVAT.IDUSUARIOSISTEMAEXCLUSAO  AS IDUSUARIOEXCLUSAO_DPVAT, DNIT.IDBEMMOVELDNIT, DNIT.DESCMENSAGEMDNIT, DNIT.NUMTOTALDNIT, DNIT.DATAHORAINICIO AS DATAHORAINICIO_DNIT, DNIT.DESCOBSERVACAODNIT, DNIT.IDUSUARIOSISTEMAAPROVACAO AS IDUSUARIOAPROVACAO_DNIT, DNIT.IDUSUARIOSISTEMAENVIO     AS IDUSUARIOENVIO_DNIT, DNIT.IDUSUARIOSISTEMAEXCLUSAO  AS IDUSUARIOEXCLUSAO_DNIT, ( SELECT LISTAGG( 'ID=' || M.IDBEMMOVELMULTA || ';BOLEXISTEPENDENCIA=' || M.BOLEXISTEPENDENCIA || ';VALORPENDENCIAMULTA=' || COALESCE(DECIMAL(M.VALORPENDENCIAMULTA,10,2),0) || ';QTDMULTA=' || COALESCE(M.QTDMULTA,0) || ';VALORTOTALMULTA=' || COALESCE(DECIMAL(M.VALORTOTALMULTA,10,2),0) || ';OBSERVACAO=' || COALESCE(M.DESCOBSERVACAOBEMMOVELMULTA , '') , ' | ' ) FROM CLI.BEMMOVELMULTA M WHERE M.IDBEM = B.IDBEM ) AS LISTA_MULTAS, ( SELECT LISTAGG( 'ID=' || IA.IDBEMINFORMACAOAVULSA || ';DESC=' || COALESCE (IA.DESCBEMINFORMACAOAVULSA,'') || ';VALOR=' || COALESCE(IA.VALORINFORMACAOAVULSA,'') , ' | ' ) FROM CLI.BEMINFORMACAOAVULSA IA WHERE IA.IDBEM = B.IDBEM ) AS LISTA_INFORMACOES_AVULSAS, ( SELECT LISTAGG( 'ID=' || R.IDBEMRESTRICAODEBITO || ';TIPO=' || COALESCE(TR.DESCTIPOBEMRESTRICAO, '') || ';GERAL=' || R.BOLRESTRICAOGERAL || ';RENAJUD=' || R.BOLRESTRICAORENAJUD || ';ROUBOFURTO=' || R.BOLRESTRICAOROUBOFURTO || ';FINANCIAMENTO=' || R.BOLRESTRICAOFINANCIAMENTO || ';OBS=' || COALESCE(R.DESCOBSBEMRESTRICAODEBITO, '') , ' | ') FROM   CLI.BEMRESTRICAODEBITO R JOIN   CLI.TIPOBEMRESTRICAO TR ON TR.IDTIPOBEMRESTRICAO = R.IDTIPOBEMRESTRICAO WHERE  R.IDBEM = B.IDBEM ) AS LISTA_RESTRICOES, SEFAZ.IDBEMSEFAZ, SEFAZ.BOLCOMUNICACAOVENDA, SEFAZ.DATACOMUNICAVENDA, SEFAZ.DATAHORAINICIO       AS DATAHORAINICIO_SEFAZ, SEFAZ.DESCOBSERVACAOSEFAZ, SEFAZ.IDUSUARIOSISTEMAAPROVACAO AS IDUSUARIOAPROVACAO_SEFAZ, SEFAZ.IDUSUARIOSISTEMAENVIO     AS IDUSUARIOENVIO_SEFAZ, SEFAZ.IDUSUARIOSISTEMAEXCLUSAO  AS IDUSUARIOEXCLUSAO_SEFAZ, RENAJUD.IDBEMRENAJUD, RENAJUD.DATABEMRENAJUD, RENAJUD.DESCBEMRENAJUD, RENAJUD.NOMETRIBUNALRENAJUD, RENAJUD.NOMEORGAOJUDICIARIORENAJUD, RENAJUD.DESCPROCESSORENAJUD, RENAJUD.DESCMENSAGEMRENAJUD, RENAJUD.DATAHORAINICIO         AS DATAHORAINICIO_RENAJUD, RENAJUD.DESCOBSERVACAOBEMRENAJUD, RENAJUD.IDUSUARIOSISTEMAAPROVACAO AS IDUSUARIOAPROVACAO_RENAJUD, RENAJUD.IDUSUARIOSISTEMAENVIO     AS IDUSUARIOENVIO_RENAJUD, RENAJUD.IDUSUARIOSISTEMAEXCLUSAO  AS IDUSUARIOEXCLUSAO_RENAJUD, LIC.IDBEMMOVELLICENCIAMENTO, LIC.BOLEXISTEPENDENCIALICENCIAMENTO, LIC.VALORPENDENCIALICENCIAMENTO, LIC.DATAHORAINICIO AS DATAHORAINICIO_LICENCIAMENTO, LIC.DESCOBSERVACAOBEMMOVELLICENCIAMENTO, LIC.IDUSUARIOSISTEMAAPROVACAO AS IDUSUARIOAPROVACAO_LICENCIAMENTO, LIC.IDUSUARIOSISTEMAENVIO     AS IDUSUARIOENVIO_LICENCIAMENTO, LIC.IDUSUARIOSISTEMAEXCLUSAO  AS IDUSUARIOEXCLUSAO_LICENCIAMENTO, PRF.IDBEMMOVELPRF, PRF.BOLNADACONSTA, PRF.BOLEXISTEMULTA, PRF.DATAHORAINICIO AS DATAHORAINICIO_PRF, PRF.DESCOBSERVACAOBEMMOVELPRF, PRF.IDUSUARIOSISTEMAAPROVACAO AS IDUSUARIOAPROVACAO_PRF, PRF.IDUSUARIOSISTEMAENVIO     AS IDUSUARIOENVIO_PRF, PRF.IDUSUARIOSISTEMAEXCLUSAO  AS IDUSUARIOEXCLUSAO_PRF, ABIA.IDPESSOA AS IDPESSOAAVALIADOR FROM CLI.BEM B INNER JOIN CLI.BEMPESSOACOMPARTILHAMENTO BP ON BP.IDBEM = B.IDBEM INNER JOIN CLI.PESSOACOMPARTILHAMENTO PC ON PC.IDPESSOACOMPARTILHAMENTO = BP.IDPESSOACOMPARTILHAMENTO AND PC.CODCOMPARTILHAMENTOCADASTRO = 1 INNER JOIN CLI.PESSOA P ON P.IDPESSOA = PC.IDPESSOA INNER JOIN CLI.BEMMOVEL BM ON B.IDBEM = BM.IDBEM LEFT JOIN  CLI.BEMMOVELAVALIACAO BA ON B.IDBEM = BA.IDBEM LEFT JOIN  CLI.PESSOACOMPARTILHAMENTO ABIA ON ABIA.IDPESSOACOMPARTILHAMENTO = BA.IDPESSOACOMPARTILHAMENTOAVALIADOR LEFT JOIN  CLI.BEMDETALHEPESSOA BDP ON B.IDBEM = BDP.IDBEM LEFT JOIN  CLI.BEMFINANCIAMENTO BF ON B.IDBEM = BF.IDBEM LEFT JOIN  CLI.AVALIACAOEXTERNABEM AE ON B.IDBEM = AE.IDBEM LEFT JOIN  CLI.BEMMOVELIPVA IPVA ON B.IDBEM = IPVA.IDBEM LEFT JOIN  CLI.BEMMOVELDPVAT DPVAT ON B.IDBEM = DPVAT.IDBEM LEFT JOIN  CLI.BEMMOVELDNIT DNIT ON B.IDBEM = DNIT.IDBEM LEFT JOIN CLI.BEMSEFAZ SEFAZ ON B.IDBEM = SEFAZ.IDBEM LEFT JOIN CLI.BEMRENAJUD RENAJUD ON B.IDBEM = RENAJUD.IDBEM LEFT JOIN CLI.BEMMOVELLICENCIAMENTO LIC ON B.IDBEM = LIC.IDBEM LEFT JOIN CLI.BEMMOVELPRF PRF ON B.IDBEM = PRF.IDBEM
;
