        ) AS

SELECT P.IDPESSOA
        ,P.NUMCPFCNPJ
        ,B.IDBEM
        ,B.CODTIPOCLASSIFICACAOBEM
        ,B.CODCOMPARTILHAMENTOCADASTRO
        ,B.DESCBEM
