        ,B.IDINSTITUICAOATUALIZACAO
        ,B.IDUSUARIOAPROV
        ,B.DATAHORAINICIO AS DATAHORAINICIO_BEM
        ,B.IDUSUARIOENVIO
        ,BM.CODTIPOBEMMOVEL
