        ,BDP.IDUSUARIOSISTEMAENVIO AS IDUSUARIOENVIO_BEMDETALHEPESSOA
        ,BDP.IDUSUARIOSISTEMAEXCLUSAO AS IDUSUARIOEXCLUSAO_BEMDETALHEPESSOA
        ,BF.IDBEMFINANCIAMENTO
        ,BF.DESCAGENTEFINANCIAMENTO
        ,BF.DATAINCLUSAOFINANCIAMENTO
        ,BF.DATAVIGENCIACONTRATOFINANCIAMENTO
        ,BF.NUMCONTRATOFINANCIAMENTO
        ,BF.NUMRESTRICAOFINANCIAMENTO
        ,BF.NUMTRANSACAOFINANCIAMENTO
        ,BF.DATAHORAINICIO AS DATAHORAINICIO_BEMFINANCIAMENTO
        ,BF.DESCBEMFINANCIAMENTO
        ,BF.IDUSUARIOSISTEMAAPROVACAO AS IDUSUARIOAPROVACAO_BEMFINANCIAMENTO
        ,BF.IDUSUARIOSISTEMAENVIO AS IDUSUARIOENVIO_BEMFINANCIAMENTO
        ,BF.IDUSUARIOSISTEMAEXCLUSAO AS IDUSUARIOEXCLUSAO_BEMFINANCIAMENTO
        ,AE.IDAVALIACAOEXTERNABEM
        ,AE.DATAHORAINICIO AS DATAHORAINICIO_AVALIACAO
        ,AE.CODFORNECEDOREXTERNO
        ,AE.IDUSUARIOSISTEMAAPROVACAO AS IDUSUARIOAPROVACAO_AVALIACAO
        ,AE.IDUSUARIOSISTEMAENVIO AS IDUSUARIOENVIO_AVALIACAO
        ,AE.IDUSUARIOSISTEMAEXCLUSAO AS IDUSUARIOEXCLUSAO_AVALIACAO
        ,IPVA.IDBEMMOVELIPVA
        ,IPVA.BOLEXISTEPENDENCIAIPVA
        ,IPVA.VALORPENDENCIAIPVA
        ,IPVA.DATAHORAINICIO AS DATAHORAINICIO_IPVA
        ,IPVA.DESCOBSERVACAOBEMMOVELIPVA
        ,IPVA.IDUSUARIOSISTEMAAPROVACAO AS IDUSUARIOAPROVACAO_IPVA
        ,IPVA.IDUSUARIOSISTEMAENVIO AS IDUSUARIOENVIO_IPVA
        ,IPVA.IDUSUARIOSISTEMAEXCLUSAO AS IDUSUARIOEXCLUSAO_IPVA
        ,DPVAT.IDBEMMOVELDPVAT
        ,DPVAT.BOLEXISTEPENDENCIADPVAT
        ,DPVAT.VALORPENDENCIADPVAT
        ,DPVAT.DATAHORAINICIO AS DATAHORAINICIO_DPVAT
        ,DPVAT.DESCOBSERVACAOBEMMOVELDPVAT
        ,DPVAT.IDUSUARIOSISTEMAAPROVACAO AS IDUSUARIOAPROVACAO_DPVAT
        ,DPVAT.IDUSUARIOSISTEMAENVIO AS IDUSUARIOENVIO_DPVAT
        ,DPVAT.IDUSUARIOSISTEMAEXCLUSAO AS IDUSUARIOEXCLUSAO_DPVAT
        ,DNIT.IDBEMMOVELDNIT
        ,DNIT.DESCMENSAGEMDNIT
        ,DNIT.NUMTOTALDNIT
        ,DNIT.DATAHORAINICIO AS DATAHORAINICIO_DNIT
        ,DNIT.DESCOBSERVACAODNIT
        ,DNIT.IDUSUARIOSISTEMAAPROVACAO AS IDUSUARIOAPROVACAO_DNIT
        ,DNIT.IDUSUARIOSISTEMAENVIO AS IDUSUARIOENVIO_DNIT
        ,DNIT.IDUSUARIOSISTEMAEXCLUSAO AS IDUSUARIOEXCLUSAO_DNIT
        ,(
                SELECT LISTAGG('ID=' || M.IDBEMMOVELMULTA || ';BOLEXISTEPENDENCIA=' || M.BOLEXISTEPENDENCIA || ';VALORPENDENCIAMULTA=' || COALESCE(DECIMAL(M.VALORPENDENCIAMULTA, 10, 2), 0) || ';QTDMULTA=' || COALESCE(M.QTDMULTA, 0) || ';VALORTOTALMULTA=' || COALESCE(DECIMAL(M.VALORTOTALMULTA, 10, 2), 0) || ';OBSERVACAO=' || COALESCE(M.DESCOBSERVACAOBEMMOVELMULTA, ''), ' | ')
                FROM CLI.BEMMOVELMULTA M
                WHERE M.IDBEM = B.IDBEM
                ) AS LISTA_MULTAS
        ,(
                SELECT LISTAGG('ID=' || IA.IDBEMINFORMACAOAVULSA || ';DESC=' || COALESCE(IA.DESCBEMINFORMACAOAVULSA, '') || ';VALOR=' || COALESCE(IA.VALORINFORMACAOAVULSA, ''), ' | ')
                FROM CLI.BEMINFORMACAOAVULSA IA
                WHERE IA.IDBEM = B.IDBEM
                ) AS LISTA_INFORMACOES_AVULSAS
        ,(
                SELECT LISTAGG('ID=' || R.IDBEMRESTRICAODEBITO || ';TIPO=' || COALESCE(TR.DESCTIPOBEMRESTRICAO, '') || ';GERAL=' || R.BOLRESTRICAOGERAL || ';RENAJUD=' || R.BOLRESTRICAORENAJUD || ';ROUBOFURTO=' || R.BOLRESTRICAOROUBOFURTO || ';FINANCIAMENTO=' || R.BOLRESTRICAOFINANCIAMENTO || ';OBS=' || COALESCE(R.DESCOBSBEMRESTRICAODEBITO, ''), ' | ')
                FROM CLI.BEMRESTRICAODEBITO R
                JOIN CLI.TIPOBEMRESTRICAO TR ON TR.IDTIPOBEMRESTRICAO = R.IDTIPOBEMRESTRICAO
                WHERE R.IDBEM = B.IDBEM
                ) AS LISTA_RESTRICOES
        ,
        
        SEFAZ.IDBEMSEFAZ
        ,SEFAZ.BOLCOMUNICACAOVENDA
        ,SEFAZ.DATACOMUNICAVENDA
        ,SEFAZ.DATAHORAINICIO AS DATAHORAINICIO_SEFAZ
        ,SEFAZ.DESCOBSERVACAOSEFAZ
        ,SEFAZ.IDUSUARIOSISTEMAAPROVACAO AS IDUSUARIOAPROVACAO_SEFAZ
        ,SEFAZ.IDUSUARIOSISTEMAENVIO AS IDUSUARIOENVIO_SEFAZ
        ,SEFAZ.IDUSUARIOSISTEMAEXCLUSAO AS IDUSUARIOEXCLUSAO_SEFAZ
        ,
        
        RENAJUD.IDBEMRENAJUD
        ,RENAJUD.DATABEMRENAJUD
        ,RENAJUD.DESCBEMRENAJUD
        ,RENAJUD.NOMETRIBUNALRENAJUD
        ,RENAJUD.NOMEORGAOJUDICIARIORENAJUD
        ,RENAJUD.DESCPROCESSORENAJUD
        ,RENAJUD.DESCMENSAGEMRENAJUD
        ,RENAJUD.DATAHORAINICIO AS DATAHORAINICIO_RENAJUD
        ,RENAJUD.DESCOBSERVACAOBEMRENAJUD
        ,RENAJUD.IDUSUARIOSISTEMAAPROVACAO AS IDUSUARIOAPROVACAO_RENAJUD
        ,RENAJUD.IDUSUARIOSISTEMAENVIO AS IDUSUARIOENVIO_RENAJUD
        ,RENAJUD.IDUSUARIOSISTEMAEXCLUSAO AS IDUSUARIOEXCLUSAO_RENAJUD
        ,
        
        LIC.IDBEMMOVELLICENCIAMENTO
        ,LIC.BOLEXISTEPENDENCIALICENCIAMENTO
        ,LIC.VALORPENDENCIALICENCIAMENTO
        ,LIC.DATAHORAINICIO AS DATAHORAINICIO_LICENCIAMENTO
        ,LIC.DESCOBSERVACAOBEMMOVELLICENCIAMENTO
        ,LIC.IDUSUARIOSISTEMAAPROVACAO AS IDUSUARIOAPROVACAO_LICENCIAMENTO
        ,LIC.IDUSUARIOSISTEMAENVIO AS IDUSUARIOENVIO_LICENCIAMENTO
        ,LIC.IDUSUARIOSISTEMAEXCLUSAO AS IDUSUARIOEXCLUSAO_LICENCIAMENTO
        ,
        
        PRF.IDBEMMOVELPRF
        ,PRF.BOLNADACONSTA
        ,PRF.BOLEXISTEMULTA
        ,PRF.DATAHORAINICIO AS DATAHORAINICIO_PRF
        ,PRF.DESCOBSERVACAOBEMMOVELPRF
        ,PRF.IDUSUARIOSISTEMAAPROVACAO AS IDUSUARIOAPROVACAO_PRF
        ,PRF.IDUSUARIOSISTEMAENVIO AS IDUSUARIOENVIO_PRF
        ,PRF.IDUSUARIOSISTEMAEXCLUSAO AS IDUSUARIOEXCLUSAO_PRF
        ,
        
        ABIA.IDPESSOA AS IDPESSOAAVALIADOR
FROM CLI.BEM B

INNER JOIN CLI.BEMPESSOACOMPARTILHAMENTO BP ON BP.IDBEM = B.IDBEM

INNER JOIN CLI.PESSOACOMPARTILHAMENTO PC ON PC.IDPESSOACOMPARTILHAMENTO = BP.IDPESSOACOMPARTILHAMENTO
        AND PC.CODCOMPARTILHAMENTOCADASTRO = 1

INNER JOIN CLI.PESSOA P ON P.IDPESSOA = PC.IDPESSOA

INNER JOIN CLI.BEMMOVEL BM ON B.IDBEM = BM.IDBEM

LEFT JOIN CLI.BEMIMOVELAVALIACAO BIA ON B.IDBEM = BIA.IDBEM

LEFT JOIN CLI.PESSOACOMPARTILHAMENTO ABIA ON ABIA.IDPESSOACOMPARTILHAMENTO = BIA.IDPESSOACOMPARTILHAMENTOAVALIADOR

LEFT JOIN CLI.BEMDETALHEPESSOA BDP ON B.IDBEM = BDP.IDBEM

LEFT JOIN CLI.BEMFINANCIAMENTO BF ON B.IDBEM = BF.IDBEM

LEFT JOIN CLI.AVALIACAOEXTERNABEM AE ON B.IDBEM = AE.IDBEM

LEFT JOIN CLI.BEMMOVELIPVA IPVA ON B.IDBEM = IPVA.IDBEM

LEFT JOIN CLI.BEMMOVELDPVAT DPVAT ON B.IDBEM = DPVAT.IDBEM

LEFT JOIN CLI.BEMMOVELDNIT DNIT ON B.IDBEM = DNIT.IDBEM

LEFT JOIN CLI.BEMSEFAZ SEFAZ ON B.IDBEM = SEFAZ.IDBEM

LEFT JOIN CLI.BEMRENAJUD RENAJUD ON B.IDBEM = RENAJUD.IDBEM

LEFT JOIN CLI.BEMMOVELLICENCIAMENTO LIC ON B.IDBEM = LIC.IDBEM

LEFT JOIN CLI.BEMMOVELPRF PRF ON B.IDBEM = PRF.IDBEM
;
-- COPY-DATABASE-OBJECT: "CLI"."VIW_EMAILPESSOAHISTORICO"
CREATE OR REPLACE VIEW "CLI"."VIW_EMAILPESSOAHISTORICO" ( NUMCPFCNPJ ,IDINSTITUICAO ,DESCEMAIL ,CODTIPOEMAIL ,DESCTIPOEMAIL ,DATAHORAINICIO ,DATAHORAFIM ,IDPESSOA ,ORIGEM_INFORMACAO ) AS SELECT P.NUMCPFCNPJ AS NUMCPFCNPJ ,TRP.IDINSTITUICAO AS IDINSTITUICAO ,EMP.DESCEMAIL AS DESCEMAIL ,EMP.CODTIPOEMAIL AS CODTIPOEMAIL ,TE.DESCTIPOEMAIL AS DESCTIPOEMAIL ,EMP.DATAHORAINICIO AS DATAHORAINICIO ,NULL AS DATAHORAFIM ,P.IDPESSOA AS IDPESSOA ,'V' AS ORIGEM_INFORMACAO FROM CLI.PESSOACOMPARTILHAMENTO PC INNER JOIN CLI.PESSOA P ON P.IDPESSOA = PC.IDPESSOA INNER JOIN CLI.TRANSICAOPESSOA TRP ON TRP.IDPESSOACOMPARTILHAMENTO = PC.IDPESSOACOMPARTILHAMENTO INNER JOIN CLI.EMAILPESSOA EMP ON EMP.IDPESSOACOMPARTILHAMENTO = PC.IDPESSOACOMPARTILHAMENTO INNER JOIN CLI.TIPOEMAIL TE ON TE.CODTIPOEMAIL = EMP.CODTIPOEMAIL UNION ALL SELECT P.NUMCPFCNPJ AS NUMCPFCNPJ ,TRP.IDINSTITUICAO AS IDINSTITUICAO ,HEMP.DESCEMAIL AS DESCEMAIL ,HEMP.CODTIPOEMAIL AS CODTIPOEMAIL ,TE.DESCTIPOEMAIL AS DESCTIPOEMAIL ,HEMP.DATAHORAINICIO AS DATAHORAINICIO ,HEMP.DATAHORAFIM AS DATAHORAFIM ,P.IDPESSOA AS IDPESSOA ,'H' AS ORIGEM_INFORMACAO FROM CLI.PESSOACOMPARTILHAMENTO PC INNER JOIN CLI.PESSOA P ON P.IDPESSOA = PC.IDPESSOA INNER JOIN CLI.TRANSICAOPESSOA TRP ON TRP.IDPESSOACOMPARTILHAMENTO = PC.IDPESSOACOMPARTILHAMENTO INNER JOIN CLI.HISTEMAILPESSOA HEMP ON HEMP.IDPESSOACOMPARTILHAMENTO = PC.IDPESSOACOMPARTILHAMENTO INNER JOIN CLI.TIPOEMAIL TE ON TE.CODTIPOEMAIL = HEMP.CODTIPOEMAIL
;
-- COPY-DATABASE-OBJECT: "CLI"."VIW_ENDERECOPESSOAHISTORICO"
CREATE OR REPLACE VIEW "CLI"."VIW_ENDERECOPESSOAHISTORICO" ( NUMCPFCNPJ ,IDPESSOA ,IDINSTITUICAO ,IDTIPOLOGRADOURO ,DESCNUMERO ,DESCCOMPLEMENTO ,CODCEP ,DESCLOGRADOURO ,NOMEBAIRRO ,IDLOCALIDADE ,DATAHORAINICIO ,DATAHORAFIM ,IDENDERECOPESSOA ,ORIGEM_INFORMACAO ) AS SELECT P.NUMCPFCNPJ AS NUMCPFCNPJ ,P.IDPESSOA AS IDPESSOA ,TRP.IDINSTITUICAO AS IDINSTITUICAO_TRP ,EP.IDTIPOLOGRADOURO AS IDTIPOLOGRADOURO ,EP.DESCNUMERO AS DESCNUMERO ,EP.DESCCOMPLEMENTO AS DESCCOMPLEMENTO ,EP.CODCEP AS CODCEP ,EP.DESCLOGRADOURO AS DESCLOGRADOURO ,EP.NOMEBAIRRO AS NOMEBAIRRO ,EP.IDLOCALIDADE AS IDLOCALIDADE ,EP.DATAHORAINICIO AS DATAHORAINICIO ,NULL AS DATAHORAFIM ,EP.IDENDERECOPESSOA AS IDENDERECOPESSOA ,'V' AS ORIGEM_INFORMACAO FROM CLI.PESSOACOMPARTILHAMENTO PC INNER JOIN CLI.PESSOA P ON P.IDPESSOA = PC.IDPESSOA INNER JOIN CLI.TRANSICAOPESSOA TRP ON TRP.IDPESSOACOMPARTILHAMENTO = PC.IDPESSOACOMPARTILHAMENTO INNER JOIN CLI.ENDERECOPESSOA EP ON EP.IDPESSOACOMPARTILHAMENTO = PC.IDPESSOACOMPARTILHAMENTO AND EP.DATAHORAINICIO IS NOT NULL UNION ALL SELECT P.NUMCPFCNPJ AS NUMCPFCNPJ ,P.IDPESSOA AS IDPESSOA ,TRP.IDINSTITUICAO AS IDINSTITUICAO_TRP ,HEP.IDTIPOLOGRADOURO AS IDTIPOLOGRADOURO ,HEP.DESCNUMERO AS DESCNUMERO ,HEP.DESCCOMPLEMENTO AS DESCCOMPLEMENTO ,HEP.CODCEP AS CODCEP ,HEP.DESCLOGRADOURO AS DESCLOGRADOURO ,HEP.NOMEBAIRRO AS NOMEBAIRRO ,HEP.IDLOCALIDADE AS IDLOCALIDADE ,HEP.DATAHORAINICIO AS DATAHORAINICIO ,HEP.DATAHORAFIM AS DATAHORAFIM ,HEP.IDENDERECOPESSOA AS IDENDERECOPESSOA ,'H' AS ORIGEM_INFORMACAO FROM CLI.PESSOACOMPARTILHAMENTO PC INNER JOIN CLI.PESSOA P ON P.IDPESSOA = PC.IDPESSOA INNER JOIN CLI.TRANSICAOPESSOA TRP ON TRP.IDPESSOACOMPARTILHAMENTO = PC.IDPESSOACOMPARTILHAMENTO INNER JOIN CLI.HISTENDERECOPESSOA HEP ON HEP.IDPESSOACOMPARTILHAMENTO = PC.IDPESSOACOMPARTILHAMENTO
;
-- COPY-DATABASE-OBJECT: "CLI"."VIW_FONTERENDA"
CREATE OR REPLACE VIEW "CLI"."VIW_FONTERENDA" ( VALORRECEITABRUTAMENSAL ,IDPESSOA ,IDINSTITUICAO ,IDUNIDADEINST ) AS SELECT SUM(FR.VALORRECEITABRUTAMENSAL) AS VALORRECEITABRUTAMENSAL ,PC.IDPESSOA ,TP.IDINSTITUICAO ,TP.IDUNIDADEINST FROM CLI.PESSOACOMPARTILHAMENTO PC INNER JOIN CLI.TRANSICAOPESSOA TP ON TP.IDPESSOACOMPARTILHAMENTO = PC.IDPESSOACOMPARTILHAMENTO INNER JOIN CLI.FONTERENDA FR ON PC.IDPESSOACOMPARTILHAMENTO = FR.IDPESSOACOMPARTILHAMENTO WHERE FR.DATAHORAINICIO IS NOT NULL GROUP BY PC.IDPESSOA ,TP.IDINSTITUICAO ,TP.IDUNIDADEINST
;
-- COPY-DATABASE-OBJECT: "CLI"."VIW_FONTERENDAPESSOAJURIDICA"
CREATE OR REPLACE VIEW "CLI"."VIW_FONTERENDAPESSOAJURIDICA" ( IDINSTITUICAO ,NUMPAC ,NUMCPFCNPJ ,DATAINCLUSAOSISTEMA ,IDPESSOA ,CODCNAE ,BOLAUTORIZACONSULTABACEN ,CODTIPOEMPRESA ,CODESFERAADMINISTRATIVA ,CODTIPOPESSOA ,NUMCLIENTE ,VALORRECEITABRUTAMENSAL ,VALORFATURAMENTOMENSAL ) AS SELECT TP.IDINSTITUICAO ,TP.IDUNIDADEINST ,P.NUMCPFCNPJ ,PC.DATAINCLUSAOSISTEMA ,P.IDPESSOA ,PC.CODCNAE ,PC.BOLAUTORIZACONSULTABACEN ,PJ.CODTIPOEMPRESA ,PJ.CODESFERAADMINISTRATIVA ,P.CODTIPOPESSOA ,TP.IDPESSOALEGADO ,( SELECT VFR.VALORRECEITABRUTAMENSAL FROM CLI.VIW_FONTERENDA VFR WHERE VFR.IDINSTITUICAO = TP.IDINSTITUICAO AND VFR.IDPESSOA = P.IDPESSOA ) ,( SELECT SUM(FR.VALORRECEITABRUTAMENSAL) FROM CLI.FONTERENDA FR WHERE FR.CODTIPOFONTERENDA = 7 AND FR.DATAHORAINICIO IS NOT NULL AND FR.IDPESSOACOMPARTILHAMENTO = PC.IDPESSOACOMPARTILHAMENTO ) FROM CLI.PESSOA P INNER JOIN CLI.PESSOACOMPARTILHAMENTO PC ON PC.IDPESSOA = P.IDPESSOA INNER JOIN CLI.TRANSICAOPESSOA TP ON TP.IDPESSOACOMPARTILHAMENTO = PC.IDPESSOACOMPARTILHAMENTO LEFT JOIN CLI.PESSOAJURIDICA PJ ON PJ.IDPESSOACOMPARTILHAMENTO = PC.IDPESSOACOMPARTILHAMENTO
;
-- COPY-DATABASE-OBJECT: "CLI"."VIW_FONTERENDAVIGENTEHISTORICO"
CREATE OR REPLACE VIEW "CLI"."VIW_FONTERENDAVIGENTEHISTORICO" ( DESCTIPOFONTERENDA ,CODTIPOFONTERENDA ,IDPESSOA ,VALORRECEITABRUTAMENSAL ,DATAHORAINICIO ,DATAHORAFIM ,ORIGEM_INFORMACAO ) AS SELECT TFR.DESCTIPOFONTERENDA ,FR.CODTIPOFONTERENDA ,PC.IDPESSOA ,FR.VALORRECEITABRUTAMENSAL ,FR.DATAHORAINICIO ,NULL AS DATAHORAFIM ,'V' AS ORIGEM_INFORMACAO FROM CLI.FONTERENDA FR INNER JOIN CLI.TIPOFONTERENDA TFR ON TFR.CODTIPOFONTERENDA = FR.CODTIPOFONTERENDA INNER JOIN CLI.PESSOACOMPARTILHAMENTO PC ON PC.IDPESSOACOMPARTILHAMENTO = FR.IDPESSOACOMPARTILHAMENTO AND FR.DATAHORAINICIO IS NOT NULL UNION ALL SELECT TFR.DESCTIPOFONTERENDA ,HFR.CODTIPOFONTERENDA ,PC.IDPESSOA ,HFR.VALORRECEITABRUTAMENSAL ,HFR.DATAHORAINICIO ,HFR.DATAHORAFIM ,'H' AS ORIGEM_INFORMACAO FROM CLI.HISTFONTERENDA HFR INNER JOIN CLI.PESSOACOMPARTILHAMENTO PC ON PC.IDPESSOACOMPARTILHAMENTO = HFR.IDPESSOACOMPARTILHAMENTO INNER JOIN CLI.TIPOFONTERENDA TFR ON TFR.CODTIPOFONTERENDA = HFR.CODTIPOFONTERENDA
;
-- COPY-DATABASE-OBJECT: "CLI"."VIW_GRUPO_ECONOMICO"
CREATE OR REPLACE VIEW "CLI"."VIW_GRUPO_ECONOMICO" AS SELECT P.IDPESSOA, GI.IDINSTITUICAO, TP.IDUNIDADEINST, P.NUMCPFCNPJ, TP.DATAHORAINTEGRACAO             AS DATACADASTRAMENTOCLIENTE, GE.IDGRUPOECONOMICOCENTRALIZADO   AS IDGRUPOECONOMICO, GE.NOMEGRUPOECONOMICOCENTRALIZADO AS DESCGRUPOECONOMICO, PJ.CODESFERAADMINISTRATIVA, PJ.CODTIPOEMPRESA, PC.BOLAUTORIZACONSULTABACEN, P.CODTIPOPESSOA, TP.IDPESSOALEGADO, TCGE.CODTIPOCONEXAOGRUPOECONOMICO, TCGE.DESCTIPOCONEXAOGRUPOECONOMICO FROM CLI.GRUPOECONOMICOCENTRALIZADO AS GE INNER JOIN CLI.GRUPOECONOMICOMANUALPESSOA AS GMP ON GE.IDGRUPOECONOMICOCENTRALIZADO = GMP.IDGRUPOECONOMICOCENTRALIZADO LEFT JOIN cli.TIPOCONEXAOGRUPOECONOMICO AS TCGE ON GMP.CODTIPOCONEXAOGRUPOECONOMICO = TCGE.CODTIPOCONEXAOGRUPOECONOMICO INNER JOIN CLI.GRUPOECONOMICOINSTITUICAO AS GI ON GI.IDGRUPOECONOMICOCENTRALIZADO = GE.IDGRUPOECONOMICOCENTRALIZADO INNER JOIN CLI.PESSOACOMPARTILHAMENTO AS PC ON GMP.IDPESSOACOMPARTILHAMENTO = PC.IDPESSOACOMPARTILHAMENTO INNER JOIN CLI.PESSOA AS P ON PC.IDPESSOA = P.IDPESSOA INNER JOIN CLI.TRANSICAOPESSOA AS TP ON PC.IDPESSOACOMPARTILHAMENTO = TP.IDPESSOACOMPARTILHAMENTO AND     gi.IDINSTITUICAO = tp.IDINSTITUICAO LEFT JOIN CLI.PESSOAJURIDICA AS PJ ON PC.IDPESSOACOMPARTILHAMENTO = PJ.IDPESSOACOMPARTILHAMENTO WHERE GMP.IDGRUPOECONOMICOAUTOMATICO IS NULL UNION ALL SELECT P.IDPESSOA, GI.IDINSTITUICAO, TP.IDUNIDADEINST, P.NUMCPFCNPJ, TP.DATAHORAINTEGRACAO             AS DATACADASTRAMENTOCLIENTE, GE.IDGRUPOECONOMICOCENTRALIZADO   AS IDGRUPOECONOMICO, GE.NOMEGRUPOECONOMICOCENTRALIZADO AS DESCGRUPOECONOMICO, PJ.CODESFERAADMINISTRATIVA, PJ.CODTIPOEMPRESA, PC.BOLAUTORIZACONSULTABACEN, P.CODTIPOPESSOA, TP.IDPESSOALEGADO, TCGE.CODTIPOCONEXAOGRUPOECONOMICO, TCGE.DESCTIPOCONEXAOGRUPOECONOMICO FROM CLI.GRUPOECONOMICOCENTRALIZADO AS GE INNER JOIN CLI.GRUPOECONOMICOAUTOMATICOPESSOA AS GAP ON GE.IDGRUPOECONOMICOCENTRALIZADO = GAP.IDGRUPOECONOMICOCENTRALIZADO INNER JOIN CLI.GRUPOECONOMICOINSTITUICAO AS GI ON GI.IDGRUPOECONOMICOCENTRALIZADO = GE.IDGRUPOECONOMICOCENTRALIZADO LEFT JOIN CLI.GRUPOECONOMICOAUTOMATICOTIPOCONEXAOINSTITUICAO AS GATC ON GAP.IDGRUPOECONOMICOCENTRALIZADO = GATC.IDGRUPOECONOMICOCENTRALIZADO AND GAP.IDPESSOACOMPARTILHAMENTO = GATC.IDPESSOACOMPARTILHAMENTO AND GI.IDINSTITUICAO = GATC.IDINSTITUICAO LEFT JOIN cli.TIPOCONEXAOGRUPOECONOMICO AS TCGE ON GATC.CODTIPOCONEXAOGRUPOECONOMICO = TCGE.CODTIPOCONEXAOGRUPOECONOMICO INNER JOIN CLI.PESSOACOMPARTILHAMENTO AS PC ON GAP.IDPESSOACOMPARTILHAMENTO = PC.IDPESSOACOMPARTILHAMENTO INNER JOIN CLI.PESSOA AS P ON PC.IDPESSOA = P.IDPESSOA INNER JOIN CLI.TRANSICAOPESSOA AS TP ON PC.IDPESSOACOMPARTILHAMENTO = TP.IDPESSOACOMPARTILHAMENTO AND     gi.IDINSTITUICAO = tp.IDINSTITUICAO LEFT JOIN CLI.PESSOAJURIDICA AS PJ ON PC.IDPESSOACOMPARTILHAMENTO = PJ.IDPESSOACOMPARTILHAMENTO WHERE 1=1 AND     NOT EXISTS ( SELECT 1 FROM CLI.GRUPOECONOMICOMANUALPESSOA GMP INNER JOIN CLI.GRUPOECONOMICOINSTITUICAO AS GI2 ON GMP.IDGRUPOECONOMICOCENTRALIZADO = GI2.IDGRUPOECONOMICOCENTRALIZADO WHERE GE.IDGRUPOECONOMICOCENTRALIZADO = GMP.IDGRUPOECONOMICOAUTOMATICO AND     GI.IDINSTITUICAO = GI2.IDINSTITUICAO ) AND     GAP.IDGRUPOECONOMICOAUTOMATICOPESSOA = ( SELECT MAX(GAP2.IDGRUPOECONOMICOAUTOMATICOPESSOA) FROM CLI.GRUPOECONOMICOAUTOMATICOPESSOA GAP2 WHERE GAP.IDPESSOACOMPARTILHAMENTO = GAP2.IDPESSOACOMPARTILHAMENTO) UNION ALL SELECT P.IDPESSOA, gi.IDINSTITUICAO, TP.IDUNIDADEINST, P.NUMCPFCNPJ, TP.DATAHORAINTEGRACAO             AS DATACADASTRAMENTOCLIENTE, GE.IDGRUPOECONOMICOCENTRALIZADO   AS IDGRUPOECONOMICO, GE.NOMEGRUPOECONOMICOCENTRALIZADO AS DESCGRUPOECONOMICO, PJ.CODESFERAADMINISTRATIVA, PJ.CODTIPOEMPRESA, PC.BOLAUTORIZACONSULTABACEN, P.CODTIPOPESSOA, TP.IDPESSOALEGADO, TCGE.CODTIPOCONEXAOGRUPOECONOMICO, TCGE.DESCTIPOCONEXAOGRUPOECONOMICO FROM CLI.GRUPOECONOMICOMANUALPESSOA AS GMP INNER JOIN CLI.GRUPOECONOMICOAUTOMATICOPESSOA AS GAP ON GAP.IDGRUPOECONOMICOCENTRALIZADO = GMP.IDGRUPOECONOMICOAUTOMATICO INNER JOIN CLI.GRUPOECONOMICOCENTRALIZADO AS GE ON GE.IDGRUPOECONOMICOCENTRALIZADO = GMP.IDGRUPOECONOMICOCENTRALIZADO INNER JOIN CLI.GRUPOECONOMICOINSTITUICAO AS GI ON GI.IDGRUPOECONOMICOCENTRALIZADO = GE.IDGRUPOECONOMICOCENTRALIZADO LEFT JOIN CLI.GRUPOECONOMICOAUTOMATICOTIPOCONEXAOINSTITUICAO AS GATC ON GAP.IDGRUPOECONOMICOCENTRALIZADO = GATC.IDGRUPOECONOMICOCENTRALIZADO AND GAP.IDPESSOACOMPARTILHAMENTO = GATC.IDPESSOACOMPARTILHAMENTO AND GI.IDINSTITUICAO = GATC.IDINSTITUICAO LEFT JOIN cli.TIPOCONEXAOGRUPOECONOMICO AS TCGE ON GATC.CODTIPOCONEXAOGRUPOECONOMICO = TCGE.CODTIPOCONEXAOGRUPOECONOMICO INNER JOIN CLI.PESSOACOMPARTILHAMENTO AS PC ON GAP.IDPESSOACOMPARTILHAMENTO = PC.IDPESSOACOMPARTILHAMENTO INNER JOIN CLI.PESSOA AS P ON PC.IDPESSOA = P.IDPESSOA INNER JOIN CLI.TRANSICAOPESSOA AS TP ON PC.IDPESSOACOMPARTILHAMENTO = TP.IDPESSOACOMPARTILHAMENTO AND     gi.IDINSTITUICAO = tp.IDINSTITUICAO LEFT JOIN CLI.PESSOAJURIDICA AS PJ ON PC.IDPESSOACOMPARTILHAMENTO = PJ.IDPESSOACOMPARTILHAMENTO WHERE 1=1 AND     GAP.IDGRUPOECONOMICOAUTOMATICOPESSOA = ( SELECT MAX(GAP2.IDGRUPOECONOMICOAUTOMATICOPESSOA) FROM CLI.GRUPOECONOMICOAUTOMATICOPESSOA GAP2 WHERE GAP.IDPESSOACOMPARTILHAMENTO = GAP2.IDPESSOACOMPARTILHAMENTO) AND     GMP.IDGRUPOECONOMICOMANUALPESSOA = ( SELECT MAX(GMP2.IDGRUPOECONOMICOMANUALPESSOA) FROM CLI.GRUPOECONOMICOMANUALPESSOA GMP2 WHERE GMP.IDGRUPOECONOMICOCENTRALIZADO = GMP2.IDGRUPOECONOMICOCENTRALIZADO AND     GMP.IDGRUPOECONOMICOAUTOMATICO = GMP2.IDGRUPOECONOMICOAUTOMATICO )
;
-- COPY-DATABASE-OBJECT: "CLI"."VIW_INFORMACAOPROFISSIONAL"
CREATE OR REPLACE VIEW "CLI"."VIW_INFORMACAOPROFISSIONAL" ( IDINFORMACAOPROFISSIONAL ,DESCOCUPACAOPROFISSIONAL ,DESCMATRICULAFUNC ,DESCEMPRESATRABALHA ,DATAADMISSAO ,IDPESSOAFISICA ,NUMPESSOAFISICA ,IDPESSOAJURIDICA ,NUMPESSOAJURIDICA ,CODTIPOFUNCIONARIO ,CODSITUACAOFUNCIONARIO ,CODTIPOAFASTAMENTO ,DIAMESAQUISICAOFERIAS ,IDINSTITUICAO ) AS SELECT INF.IDINFORMACAOPROFISSIONAL ,INF.DESCCARGO AS DESCOCUPACAOPROFISSIONAL ,INF.NUMMATRICULA AS DESCMATRICULAFUNC ,PC2.NOMECOMPLETO AS DESCEMPRESATRABALHA ,INF.DATAADMISSAO ,P.IDPESSOA AS IDPESSOAFISICA ,TP.IDPESSOALEGADO AS NUMPESSOAFISICA ,P2.IDPESSOA AS IDPESSOAJURIDICA ,TP2.IDPESSOALEGADO AS NUMPESSOAJURIDICA ,INF.CODTIPOFUNCIONARIO ,INF.CODSITUACAOFUNCIONARIO ,INF.CODTIPOAFASTAMENTO ,INF.DIAMESAQUISICAOFERIAS ,TP.IDINSTITUICAO FROM CLI.INFORMACAOPROFISSIONAL INF INNER JOIN CLI.PESSOA P ON P.IDPESSOA = INF.IDPESSOA INNER JOIN CLI.PESSOACOMPARTILHAMENTO PC ON PC.IDPESSOA = P.IDPESSOA AND PC.CODCOMPARTILHAMENTOCADASTRO = 1 INNER JOIN CLI.TRANSICAOPESSOA TP ON TP.IDPESSOACOMPARTILHAMENTO = PC.IDPESSOACOMPARTILHAMENTO AND TP.IDINSTITUICAO = INF.IDINSTITUICAO LEFT JOIN CLI.PESSOA P2 ON P2.IDPESSOA = INF.IDPESSOAEMPREGADOR LEFT JOIN CLI.PESSOACOMPARTILHAMENTO PC2 ON PC2.IDPESSOA = P2.IDPESSOA AND PC2.CODCOMPARTILHAMENTOCADASTRO = 1 RIGHT JOIN CLI.TRANSICAOPESSOA TP2 ON TP2.IDPESSOACOMPARTILHAMENTO = PC2.IDPESSOACOMPARTILHAMENTO AND TP2.IDINSTITUICAO = TP.IDINSTITUICAO
;
-- COPY-DATABASE-OBJECT: "CLI"."VIW_PESSOA"
CREATE OR REPLACE VIEW  "CLI"."VIW_PESSOA" ( CODCOMPARTILHAMENTOCADASTRO, CODTIPOPESSOA, IDPESSOA, NOMEPESSOA, NUMCPFCNPJ, NOMECOMPLETO, NOMEAPELIDO, IDINSTITUICAO, IDUNIDADEINST, IDPESSOALEGADO, IDINSTITUICAORESPONSAVEL ) AS SELECT CODCOMPARTILHAMENTOCADASTRO , CODTIPOPESSOA , IDPESSOA , NOMEPESSOA , NUMCPFCNPJ , NOMECOMPLETO , NOMEAPELIDO , IDINSTITUICAO , IDUNIDADEINST , IDPESSOALEGADO , IDINSTITUICAO FROM CLI.PESSOAUNIFICADA
;
-- COPY-DATABASE-OBJECT: "CLI"."VIW_PESSOAFISICA"
CREATE VIEW "CLI"."VIW_PESSOAFISICA" (
	IDINSTITUICAO
	,IDPESSOA
	,DATANASCIMENTO
	,BOLMENOREMANCIPADO
	,NOMEPAI
	,NOMEMAE
	,CODTIPODOCUMENTOIDENTIFICACAO
	,DESCTIPODOCUMENTOIDENTIFICACAO
	,NUMDOCUMENTOIDENTIFICACAO
	,DESCORGAOEXPDOCUMENTOIDENTIFICACAO
	,SIGLAUFORGEXPDOCUMENTOIDENTIFICACAO
	,DATAEMISSAODOCUMENTOIDENTIFICACAO
	,CODTIPOSEXO
	,IDOCUPACAOPROFISSIONAL
	,CODOCUPACAO
	,DESCOCUPACAO
	,CODESTADOCIVIL
	,DESCESTADOCIVIL
	,CODREGIMECASAMENTO
	,DESCREGIMECASAMENTO
	,QTDDEPENDENTE
	,BOLUNIAOESTAVEL
	,CODGRAUINSTRUCAO
	,DESCGRAUINSTRUCAO
	,IDNATURALIDADE
	,DESCNATURALIDADE
	,CODVINCULOEMPREGATICIO
	,DESCVINCULOEMPREGATICIO
	,CODNACIONALIDADE
	,DESCNACIONALIDADE
	,IDPESSOACONJUGE
	,NUMCPFCNPJCONJUGE
	)
AS
SELECT TP.IDINSTITUICAO
	,PC.IDPESSOA
	,PF.DATANASCIMENTO
	,PF.BOLMENOREMANCIPADO
	,PF.NOMEPAI
	,PF.NOMEMAE
	,PF.CODTIPODOCUMENTOIDENTIFICACAO
	,TD.DESCTIPODOCUMENTOIDENTIFICACAO
	,PF.NUMDOCUMENTOIDENTIFICACAO
	,PF.DESCORGAOEXPDOCUMENTOIDENTIFICACAO
	,PF.SIGLAUFORGEXPDOCUMENTOIDENTIFICACAO
	,PF.DATAEMISSAODOCUMENTOIDENTIFICACAO
	,PF.CODTIPOSEXO
	,PF.IDOCUPACAOPROFISSIONAL
	,OP.CODOCUPACAO
	,OP.DESCOCUPACAO
	,PF.CODESTADOCIVIL
	,EC.DESCESTADOCIVIL
	,PF.CODREGIMECASAMENTO
	,RC.DESCREGIMECASAMENTO
	,PF.QTDDEPENDENTE
	,PF.BOLUNIAOESTAVEL
	,PF.CODGRAUINSTRUCAO
	,GI.DESCGRAUINSTRUCAO
	,PF.IDNATURALIDADE
	,PF.DESCNATURALIDADE
	,PF.CODVINCULOEMPREGATICIO
	,VE.DESCVINCULOEMPREGATICIO
	,PF.CODNACIONALIDADE
	,N.DESCNACIONALIDADE
	,P2.IDPESSOA AS IDPESSOACONJUGE
	,P2.NUMCPFCNPJ AS NUMCPFCNPJCONJUGE
FROM CLI.PESSOAFISICA PF
INNER JOIN CLI.TRANSICAOPESSOA TP            ON PF.IDPESSOACOMPARTILHAMENTO = TP.IDPESSOACOMPARTILHAMENTO
INNER JOIN CLI.PESSOACOMPARTILHAMENTO PC     ON PC.IDPESSOACOMPARTILHAMENTO = TP.IDPESSOACOMPARTILHAMENTO
LEFT JOIN  CLI.TIPODOCUMENTOIDENTIFICACAO TD ON TD.CODTIPODOCUMENTOIDENTIFICACAO = PF.CODTIPODOCUMENTOIDENTIFICACAO
LEFT JOIN  CLI.OCUPACAOPROFISSIONAL OP       ON OP.IDOCUPACAOPROFISSIONAL = PF.IDOCUPACAOPROFISSIONAL
LEFT JOIN  CLI.REGIMECASAMENTO RC            ON RC.CODREGIMECASAMENTO = PF.CODREGIMECASAMENTO
LEFT JOIN  CLI.ESTADOCIVIL EC                ON EC.CODESTADOCIVIL = PF.CODESTADOCIVIL
LEFT JOIN  CLI.GRAUINSTRUCAO GI              ON GI.CODGRAUINSTRUCAO = PF.CODGRAUINSTRUCAO
LEFT JOIN  CLI.VINCULOEMPREGATICIO VE        ON VE.CODVINCULOEMPREGATICIO = PF.CODVINCULOEMPREGATICIO
LEFT JOIN  CLI.NACIONALIDADE N               ON N.CODNACIONALIDADE = PF.CODNACIONALIDADE
LEFT JOIN  CLI.PESSOACOMPARTILHAMENTO PC2    ON PC2.IDPESSOACOMPARTILHAMENTO = PF.IDPESSOACOMPARTILHAMENTOCONJUGE
LEFT JOIN  CLI.PESSOA P2                     ON P2.IDPESSOA = PC2.IDPESSOA
;
-- COPY-DATABASE-OBJECT: "CLI"."VIW_PESSOAINSTITUICAO"
CREATE OR REPLACE VIEW "CLI"."VIW_PESSOAINSTITUICAO" ( IDPESSOA ,NUMCPFCNPJ ,CODTIPOPESSOA ,IDINSTITUICAO ,IDUNIDADEINST ,CODCNAE ,CODATIVIDADEECONOMICA ,NOMEPESSOA ,NOMECOMPLETO ,CODTIPOSEXO ,IDOCUPACAOPROFISSIONAL ,CODESTADOCIVIL ,DATAHORAINICIO ) AS SELECT P.IDPESSOA ,P.NUMCPFCNPJ ,P.CODTIPOPESSOA ,PI.IDINSTITUICAO ,PI.IDUNIDADEINST ,PC.CODCNAE ,PC.CODATIVIDADEECONOMICA ,PC.NOMEPESSOA ,PC.NOMECOMPLETO ,PF.CODTIPOSEXO ,PF.IDOCUPACAOPROFISSIONAL ,PF.CODESTADOCIVIL ,PI.DATAHORAINICIO FROM CLI.PESSOA P INNER JOIN CLI.PESSOACOMPARTILHAMENTO PC ON PC.IDPESSOA = P.IDPESSOA INNER JOIN CLI.PESSOAINSTITUICAO PI ON PI.IDPESSOA = P.IDPESSOA INNER JOIN CLI.GRUPOCOMPARTILHAMENTO GC ON GC.CODCOMPARTILHAMENTOCADASTRO = PC.CODCOMPARTILHAMENTOCADASTRO AND GC.IDINSTITUICAO = PI.IDINSTITUICAO LEFT JOIN CLI.PESSOAFISICA PF ON PF.IDPESSOACOMPARTILHAMENTO = PC.IDPESSOACOMPARTILHAMENTO
;
-- COPY-DATABASE-OBJECT: "CLI"."VIW_PESSOAJURIDICAHISTORICO"
CREATE OR REPLACE VIEW "CLI"."VIW_PESSOAJURIDICAHISTORICO" ( CODTIPOEMPRESA ,BOLMEI ,VALORCAPITALSOCIAL ,DATACONSTITUICAO ,CODCNAE ,NUMCPFCNPJ ,NOMEPESSOA ,NOMEAPELIDO ,DATAHORAINICIO ,DATAHORAFIM ,IDPESSOACOMPARTILHAMENTO ,IDPESSOA ,ORIGEM_INFORMACAO ) AS SELECT PJ.CODTIPOEMPRESA AS CODTIPOEMPRESA ,PJ.BOLMEI AS BOLMEI ,PJ.VALORCAPITALSOCIAL AS VALORCAPITALSOCIAL ,PJ.DATACONSTITUICAO AS DATACONSTITUICAO ,PC.CODCNAE AS CODCNAE ,P.NUMCPFCNPJ AS NUMCPFCNPJ ,PC.NOMEPESSOA AS NOMEPESSOA ,PC.NOMEAPELIDO AS NOMEAPELIDO ,PC.DATAHORAINICIO AS DATAHORAINICIO ,NULL AS DATAHORAFIM ,PC.IDPESSOACOMPARTILHAMENTO AS IDPESSOACOMPARTILHAMENTO ,P.IDPESSOA AS IDPESSOA ,'V' AS ORIGEM_INFORMACAO FROM CLI.PESSOAJURIDICA PJ INNER JOIN CLI.PESSOACOMPARTILHAMENTO PC ON PC.IDPESSOACOMPARTILHAMENTO = PJ.IDPESSOACOMPARTILHAMENTO AND PC.DATAHORAINICIO IS NOT NULL INNER JOIN CLI.PESSOA P ON P.IDPESSOA = PC.IDPESSOA AND P.CODTIPOPESSOA = 1 INNER JOIN CLI.TRANSICAOPESSOA TP ON TP.IDPESSOACOMPARTILHAMENTO = PC.IDPESSOACOMPARTILHAMENTO UNION ALL SELECT HPJ.CODTIPOEMPRESA AS CODTIPOEMPRESA ,HPJ.BOLMEI AS BOLMEI ,HPJ.VALORCAPITALSOCIAL AS VALORCAPITALSOCIAL ,HPJ.DATACONSTITUICAO AS DATACONSTITUICAO ,HPC.CODCNAE AS CODCNAE ,P.NUMCPFCNPJ AS NUMCPFCNPJ ,HPC.NOMEPESSOA AS NOMEPESSOA ,HPC.NOMEAPELIDO AS NOMEAPELIDO ,HPC.DATAHORAINICIO AS DATAHORAINICIO ,HPC.DATAHORAFIM AS DATAHORAFIM ,HPC.IDPESSOACOMPARTILHAMENTO AS IDPESSOACOMPARTILHAMENTO ,P.IDPESSOA AS IDPESSOA ,'H' AS ORIGEM_INFORMACAO FROM CLI.HISTPESSOAJURIDICA HPJ INNER JOIN CLI.PESSOACOMPARTILHAMENTO PC ON PC.IDPESSOACOMPARTILHAMENTO = HPJ.IDHISTPESSOACOMPARTILHAMENTO INNER JOIN CLI.HISTPESSOACOMPARTILHAMENTO HPC ON HPC.IDPESSOACOMPARTILHAMENTO = PC.IDPESSOACOMPARTILHAMENTO INNER JOIN CLI.PESSOA P ON P.IDPESSOA = PC.IDPESSOA AND P.CODTIPOPESSOA = 1 INNER JOIN CLI.TRANSICAOPESSOA TP ON TP.IDPESSOACOMPARTILHAMENTO = PC.IDPESSOACOMPARTILHAMENTO
;
-- COPY-DATABASE-OBJECT: "CLI"."VIW_PESSOA_JURIDICA"
CREATE OR REPLACE VIEW "CLI"."VIW_PESSOA_JURIDICA" ( IDINSTITUICAO, IDPESSOA, NOMECOMPLETO, NOMEAPELIDO, NOMEPESSOA, CODCNAE, CODPERFILCADASTRO, CODATIVIDADEECONOMICA, DATARENOVACAOCADASTRAL, DATACONSTITUICAO, VALORCAPITALSOCIAL, NUMINSCRICAOESTADUAL, CODESFERAADMINISTRATIVA, CODTIPOEMPRESA, CODTIPOFORMACONSTITUICAO, NUMREGISTROJUNTACOMERCIAL, DATAREGISTROJUNTACOMERCIAL, NUMULTIMAALTERACAOCONTRATOSOCIAL, DATAULTIMAALTERACAOCONTRATOSOCIAL, NUMREGISTROREPRESENTACAO, DATAREGISTROREPRESENTACAO, DESCCONTRATOSOCIAL, NUMINSCRICAOMUNICIPAL, CODNACIONALIDADE, BOLMEI, DESCTIPOFORMACONSTITUICAO, DESCCNAE, DESTIPOEMPRESA ) AS SELECT TP.IDINSTITUICAO, PC.IDPESSOA, PC.NOMECOMPLETO, PC.NOMEAPELIDO, PC.NOMEPESSOA, PC.CODCNAE, PC.CODPERFILCADASTRO, PC.CODATIVIDADEECONOMICA, PC.DATARENOVACAOCADASTRAL, PJ.DATACONSTITUICAO, PJ.VALORCAPITALSOCIAL, PJ.NUMINSCRICAOESTADUAL, PJ.CODESFERAADMINISTRATIVA, PJ.CODTIPOEMPRESA, PJ.CODTIPOFORMACONSTITUICAO, PJ.NUMREGISTROJUNTACOMERCIAL, PJ.DATAREGISTROJUNTACOMERCIAL, PJ.NUMULTIMAALTERACAOCONTRATOSOCIAL, PJ.DATAULTIMAALTERACAOCONTRATOSOCIAL, PJ.NUMREGISTROREPRESENTACAO, PJ.DATAREGISTROREPRESENTACAO, PJ.DESCCONTRATOSOCIAL, PJ.NUMINSCRICAOMUNICIPAL, PJ.CODNACIONALIDADE, PJ.BOLMEI, TFC.DESCTIPOFORMACONSTITUICAO, CN.DESCCNAE, TE.DESTIPOEMPRESA FROM CLI.PESSOAJURIDICA PJ INNER JOIN     CLI.TRANSICAOPESSOA TP            ON     PJ.IDPESSOACOMPARTILHAMENTO = TP.IDPESSOACOMPARTILHAMENTO INNER JOIN     CLI.PESSOACOMPARTILHAMENTO PC     ON     PC.IDPESSOACOMPARTILHAMENTO = TP.IDPESSOACOMPARTILHAMENTO INNER JOIN     CLI.TIPOFORMACONSTITUICAO TFC     ON     TFC.CODTIPOFORMACONSTITUICAO = PJ.CODTIPOFORMACONSTITUICAO LEFT JOIN 	   CLI.CNAEFISCAL CN                 ON     CN.CODCNAE = PC.CODCNAE LEFT JOIN      CLI.TIPOEMPRESA TE                ON     TE.CODTIPOEMPRESA = PJ.CODTIPOEMPRESA WHERE PC.DATAHORAINICIO IS NOT NULL
;
-- COPY-DATABASE-OBJECT: "CLI"."VIW_PESSOA_JURIDICA_MEI"
CREATE OR REPLACE VIEW "CLI"."VIW_PESSOA_JURIDICA_MEI" ( IDPESSOA, NUMCPFCNPJ, IDINSTITUICAO, BOLMEI, IDPESSOALEGADO ) AS SELECT P.IDPESSOA, P.NUMCPFCNPJ, TP.IDINSTITUICAO, PJ.BOLMEI, TP.IDPESSOALEGADO FROM CLI.PESSOA P INNER JOIN CLI.PESSOACOMPARTILHAMENTO PC ON PC.IDPESSOA = P.IDPESSOA AND PC.CODCOMPARTILHAMENTOCADASTRO = 1 INNER JOIN CLI.PESSOAJURIDICA PJ ON PJ.IDPESSOACOMPARTILHAMENTO = PC.IDPESSOACOMPARTILHAMENTO INNER JOIN CLI.TRANSICAOPESSOA TP ON TP.IDPESSOACOMPARTILHAMENTO = PC.IDPESSOACOMPARTILHAMENTO
;
-- COPY-DATABASE-OBJECT: "CLI"."VIW_PRODUTOR_RURAL"
CREATE OR REPLACE VIEW "CLI"."VIW_PRODUTOR_RURAL" 
    ( 
        CODCOMPARTILHAMENTOCADASTRO, 
        CODTIPOPESSOA, 
        IDPESSOA, 
        NOMEPESSOA, 
        NUMCPFCNPJ, 
        NOMECOMPLETO, 
        NOMEAPELIDO, 
        IDINSTITUICAO, 
        IDUNIDADEINST, 
        IDPESSOALEGADO, 
        IDINSTITUICAORESPONSAVEL, 
        DESCCATEGORIAPRODUTOR, 
        DESCTIPOBENEFICIARIOSICOR, 
        CODTIPOBENEFICIARIOSICOR, 
        CODCATEGORIAPRODUTOR, 
        NomeSocial, 
        CodinscricaoProdutorRural 
    ) 
    AS 
SELECT A.CODCOMPARTILHAMENTOCADASTRO, 
    A.CODTIPOPESSOA, 
    A.IDPESSOA, 
    A.NOMEPESSOA, 
    A.NUMCPFCNPJ, 
    A.NOMECOMPLETO, 
    A.NOMEAPELIDO, 
    A.IDINSTITUICAO, 
    A.IDUNIDADEINST, 
    A.IDPESSOALEGADO, 
    A.IDINSTITUICAORESPONSAVEL, 
    CP.DESCCATEGORIAPRODUTOR, 
    TB.DESCTIPOBENEFICIARIOSICOR, 
    TB.CODTIPOBENEFICIARIOSICOR, 
    CP.CODCATEGORIAPRODUTOR, 
    A.NomeSocial, 
    P.CodinscricaoProdutorRural 
FROM CLI.PESSOAUNIFICADA                A 
    INNER JOIN CLI.PESSOAPRODUTOR       P  ON P.IDPESSOACOMPARTILHAMENTO = a.IDPESSOACOMPARTILHAMENTO AND P.DATAHORAINICIO IS NOT NULL 
    LEFT JOIN CLI.CATEGORIAPRODUTOR     CP ON CP.CODCATEGORIAPRODUTOR = P.CODCATEGORIAPRODUTOR 
    LEFT JOIN CLI.TIPOBENEFICIARIOSICOR TB ON P.CODTIPOBENEFICIARIOSICOR = TB.CODTIPOBENEFICIARIOSICOR
;
-- COPY-DATABASE-OBJECT: "CLI"."VIW_RELACIONAMENTO"
CREATE OR REPLACE VIEW "CLI"."VIW_RELACIONAMENTO" ( IDRELACIONAMENTOPESSOA ,IDINSTITUICAO ,IDPESSOA ,IDPESSOARELACIONADA ,DATAINICIOMANDATO ,DATAFIMMANDATO ,CODTIPORELACIONAMENTOPESSOA ,DESCTIPORELACIONAMENTOPESSOA ,PERCCAPITALEMPRESA ,DATAHORA_INCLUSAO ,DATAHORA_ALTERACAO ,DATAINICIORELACIONAMENTO_SICOOB ,ORIGEM_INFORMACAO ) AS SELECT RE.IDRELACIONAMENTOPESSOA ,TP.IDINSTITUICAO ,RE.IDPESSOA ,RE.IDPESSOARELACIONADA ,RE.DATAINICIOMANDATO ,RE.DATAFIMMANDATO ,RE.CODTIPORELACIONAMENTOPESSOA ,TR.DESCTIPORELACIONAMENTOPESSOA ,RE.PERCCAPITALEMPRESA ,RE.DATAHORAINICIO AS DATAHORA_INCLUSAO ,NULL AS DATAHORA_ALTERACAO ,RE.DATAINICIORELACIONAMENTO AS DATAINICIORELACIONAMENTO_SICOOB ,'P' AS ORIGEM_INFORMACAO FROM CLI.RELACIONAMENTOPESSOA RE INNER JOIN CLI.TIPORELACIONAMENTOPESSOA TR ON TR.CODTIPORELACIONAMENTOPESSOA = RE.CODTIPORELACIONAMENTOPESSOA INNER JOIN CLI.TRANSICAOPESSOA TP ON RE.IDPESSOACOMPARTILHAMENTO = TP.IDPESSOACOMPARTILHAMENTO WHERE RE.DATAHORAINICIO IS NOT NULL AND (   TR.BOLPERMITECOMPARTILHAMENTO = 1 OR (    RE.IDINSTITUICAO = TP.IDINSTITUICAO AND TR.BOLPERMITECOMPARTILHAMENTO = 0 ) ) UNION ALL SELECT RE.IDRELACIONAMENTOPESSOA ,TP.IDINSTITUICAO ,RE.IDPESSOA ,RE.IDPESSOARELACIONADA ,RE.DATAINICIOMANDATO ,RE.DATAFIMMANDATO ,RE.CODTIPORELACIONAMENTOPESSOA ,TR.DESCTIPORELACIONAMENTOPESSOA ,RE.PERCCAPITALEMPRESA ,RE.DATAHORAINICIO AS DATAHORA_INCLUSAO ,RE.DATAHORAFIM AS DATAHORA_ALTERACAO ,DATAINICIORELACIONAMENTO AS DATAINICIORELACIONAMENTO_SICOOB ,'H' AS ORIGEM_INFORMACAO FROM CLI.HISTRELACIONAMENTOPESSOA RE INNER JOIN CLI.TIPORELACIONAMENTOPESSOA TR ON TR.CODTIPORELACIONAMENTOPESSOA = RE.CODTIPORELACIONAMENTOPESSOA INNER JOIN CLI.PESSOACOMPARTILHAMENTO PC ON RE.IDPESSOA = PC.IDPESSOA INNER JOIN CLI.TRANSICAOPESSOA TP ON PC.IDPESSOACOMPARTILHAMENTO = TP.IDPESSOACOMPARTILHAMENTO WHERE ((    TR.BOLPERMITECOMPARTILHAMENTO = 1 AND RE.IDINSTITUICAO != TP.IDINSTITUICAO AND RE.IDPESSOACOMPARTILHAMENTO IS NOT NULL ) OR (RE.IDINSTITUICAO = TP.IDINSTITUICAO))
;
-- COPY-DATABASE-OBJECT: "CLI"."VIW_RELACIONAMENTOPESSOAHISTORICO"
CREATE OR REPLACE VIEW "CLI"."VIW_RELACIONAMENTOPESSOAHISTORICO" ( NUMCPFCNPJ ,NOME_COMPLETO ,IDRELACIONAMENTOPESSOA ,IDPESSOARELACIONADA ,PERCCAPITALEMPRESA ,DATAINICIORELACIONAMENTO ,DATAFIMMANDATO ,IDINSTITUICAO ,CODTIPORELACIONAMENTOPESSOA ,DESCTIPORELACIONAMENTOPESSOA ,PESSOARELACIONADA_NUMCPFCNPJ ,PESSOARELACIONADA_NOME_COMPLETO ,DATAHORAINICIO ,DATAHORAFIM ,IDPESSOA ,ORIGEM_INFORMACAO ) AS SELECT P.NUMCPFCNPJ AS NUMCPFCNPJ ,PC.NOMECOMPLETO AS NOME_COMPLETO ,RP.IDRELACIONAMENTOPESSOA AS IDRELACIONAMENTOPESSOA ,RP.IDPESSOARELACIONADA AS IDPESSOARELACIONADA ,RP.PERCCAPITALEMPRESA AS PERCCAPITALEMPRESA ,RP.DATAINICIORELACIONAMENTO AS DATAINICIORELACIONAMENTO ,RP.DATAFIMMANDATO AS DATAFIMMANDATO ,TRP.IDINSTITUICAO AS IDINSTITUICAO ,RP.CODTIPORELACIONAMENTOPESSOA AS CODTIPORELACIONAMENTOPESSOA ,TPR.DESCTIPORELACIONAMENTOPESSOA AS DESCTIPORELACIONAMENTOPESSOA ,P2.NUMCPFCNPJ AS PESSOARELACIONADA_NUMCPFCNPJ ,PC2.NOMECOMPLETO AS PESSOARELACIONADA_NOME_COMPLETO ,RP.DATAHORAINICIO AS DATAHORAINICIO ,NULL AS DATAHORAFIM ,P.IDPESSOA AS IDPESSOA ,'V' AS ORIGEM_INFORMACAO FROM CLI.PESSOACOMPARTILHAMENTO PC INNER JOIN CLI.PESSOA P ON P.IDPESSOA = PC.IDPESSOA INNER JOIN CLI.RELACIONAMENTOPESSOA RP ON RP.IDPESSOACOMPARTILHAMENTO = PC.IDPESSOACOMPARTILHAMENTO AND RP.DATAHORAINICIO IS NOT NULL INNER JOIN CLI.PESSOA P2 ON P2.IDPESSOA = RP.IDPESSOARELACIONADA INNER JOIN CLI.PESSOACOMPARTILHAMENTO PC2 ON PC2.IDPESSOA = P2.IDPESSOA AND PC2.CODCOMPARTILHAMENTOCADASTRO = 1 AND PC.CODCOMPARTILHAMENTOCADASTRO = 1 INNER JOIN CLI.TRANSICAOPESSOA TRP ON TRP.IDPESSOACOMPARTILHAMENTO = PC.IDPESSOACOMPARTILHAMENTO INNER JOIN CLI.TIPORELACIONAMENTOPESSOA TPR ON TPR.CODTIPORELACIONAMENTOPESSOA = RP.CODTIPORELACIONAMENTOPESSOA AND ( TPR.BOLPERMITECOMPARTILHAMENTO = 1 OR ( RP.IDINSTITUICAO = TRP.IDINSTITUICAO AND TPR.BOLPERMITECOMPARTILHAMENTO = 0 ) ) UNION ALL SELECT P.NUMCPFCNPJ AS NUMCPFCNPJ ,PC.NOMECOMPLETO AS NOME_COMPLETO ,HRP.IDRELACIONAMENTOPESSOA AS IDRELACIONAMENTOPESSOA ,HRP.IDPESSOARELACIONADA AS IDPESSOARELACIONADA ,HRP.PERCCAPITALEMPRESA AS PERCCAPITALEMPRESA ,HRP.DATAINICIORELACIONAMENTO AS DATAINICIORELACIONAMENTO ,HRP.DATAFIMMANDATO AS DATAFIMMANDATO ,TRP.IDINSTITUICAO AS IDINSTITUICAO ,HRP.CODTIPORELACIONAMENTOPESSOA AS CODTIPORELACIONAMENTOPESSOA ,TPR.DESCTIPORELACIONAMENTOPESSOA AS DESCTIPORELACIONAMENTOPESSOA ,P2.NUMCPFCNPJ AS PESSOARELACIONADA_NUMCPFCNPJ ,PC2.NOMECOMPLETO AS PESSOARELACIONADA_NOME_COMPLETO ,HRP.DATAHORAINICIO AS DATAHORAINICIO ,HRP.DATAHORAFIM AS DATAHORAFIM ,P.IDPESSOA AS IDPESSOA ,'H' AS ORIGEM_INFORMACAO FROM CLI.PESSOACOMPARTILHAMENTO PC INNER JOIN CLI.PESSOA P ON P.IDPESSOA = PC.IDPESSOA INNER JOIN CLI.HISTRELACIONAMENTOPESSOA HRP ON HRP.IDPESSOACOMPARTILHAMENTO = PC.IDPESSOACOMPARTILHAMENTO INNER JOIN CLI.PESSOA P2 ON P2.IDPESSOA = HRP.IDPESSOARELACIONADA INNER JOIN CLI.PESSOACOMPARTILHAMENTO PC2 ON PC2.IDPESSOA = P2.IDPESSOA AND PC2.CODCOMPARTILHAMENTOCADASTRO = 1 AND PC.CODCOMPARTILHAMENTOCADASTRO = 1 INNER JOIN CLI.TRANSICAOPESSOA TRP ON TRP.IDPESSOACOMPARTILHAMENTO = PC.IDPESSOACOMPARTILHAMENTO INNER JOIN CLI.TIPORELACIONAMENTOPESSOA TPR ON TPR.CODTIPORELACIONAMENTOPESSOA = HRP.CODTIPORELACIONAMENTOPESSOA AND ( TPR.BOLPERMITECOMPARTILHAMENTO = 1 OR ( HRP.IDINSTITUICAO = TRP.IDINSTITUICAO AND TPR.BOLPERMITECOMPARTILHAMENTO = 0 ) )
;
-- COPY-DATABASE-OBJECT: "CLI"."VIW_TELEFONEPESSOAHISTORICO"
CREATE OR REPLACE VIEW "CLI"."VIW_TELEFONEPESSOAHISTORICO" ( NUMCPFCNPJ ,IDINSTITUICAO ,NUMRAMAL ,NUMDDD ,NUMTELEFONE ,CODTIPOTELEFONE ,DESCTIPOTELEFONE ,DESCOBSERVACAO ,DATAHORAINICIO ,DATAHORAFIM ,IDTELEFONEPESSOA ,IDPESSOA ,ORIGEM_INFORMACAO ) AS SELECT P.NUMCPFCNPJ AS NUMCPFCNPJ ,TRP.IDINSTITUICAO AS IDINSTITUICAO ,TP.NUMRAMAL AS NUMRAMAL ,TP.NUMDDD AS NUMDDD ,TP.NUMTELEFONE AS NUMTELEFONE ,TP.CODTIPOTELEFONE AS CODTIPOTELEFONE ,TT.DESCTIPOTELEFONE AS DESCTIPOTELEFONE ,TP.DESCOBSERVACAO AS DESCOBSERVACAO ,TP.DATAHORAINICIO AS DATAHORAINICIO ,NULL AS DATAHORAFIM ,TP.IDTELEFONEPESSOA AS IDTELEFONEPESSOA ,P.IDPESSOA AS IDPESSOA ,'V' AS ORIGEM_INFORMACAO FROM CLI.PESSOACOMPARTILHAMENTO PC INNER JOIN CLI.PESSOA P ON P.IDPESSOA = PC.IDPESSOA INNER JOIN CLI.TELEFONEPESSOA TP ON TP.IDPESSOACOMPARTILHAMENTO = PC.IDPESSOACOMPARTILHAMENTO AND TP.DATAHORAINICIO IS NOT NULL INNER JOIN CLI.TIPOTELEFONE TT ON TT.CODTIPOTELEFONE = TP.CODTIPOTELEFONE INNER JOIN CLI.TRANSICAOPESSOA TRP ON TRP.IDPESSOACOMPARTILHAMENTO = PC.IDPESSOACOMPARTILHAMENTO UNION ALL SELECT P.NUMCPFCNPJ AS NUMCPFCNPJ ,TRP.IDINSTITUICAO AS IDINSTITUICAO ,HTP.NUMRAMAL AS NUMRAMAL ,HTP.NUMDDD AS NUMDDD ,HTP.NUMTELEFONE AS NUMTELEFONE ,HTP.CODTIPOTELEFONE AS CODTIPOTELEFONE ,TTP.DESCTIPOTELEFONE AS DESCTIPOTELEFONE ,HTP.DESCOBSERVACAO AS DESCOBSERVACAO ,HTP.DATAHORAINICIO AS DATAHORAINICIO ,HTP.DATAHORAFIM AS DATAHORAFIM ,HTP.IDTELEFONEPESSOA AS IDTELEFONEPESSOA ,P.IDPESSOA AS IDPESSOA ,'H' AS ORIGEM_INFORMACAO FROM CLI.PESSOACOMPARTILHAMENTO PC INNER JOIN CLI.PESSOA P ON P.IDPESSOA = PC.IDPESSOA INNER JOIN CLI.HISTTELEFONEPESSOA HTP ON HTP.IDPESSOACOMPARTILHAMENTO = PC.IDPESSOACOMPARTILHAMENTO INNER JOIN CLI.TIPOTELEFONE TTP ON TTP.CODTIPOTELEFONE = HTP.CODTIPOTELEFONE INNER JOIN CLI.TRANSICAOPESSOA TRP ON TRP.IDPESSOACOMPARTILHAMENTO = PC.IDPESSOACOMPARTILHAMENTO
;
