-- COPY-DATABASE-OBJECT: "CRE"."MQT_LINHAS"
CREATE TABLE CRE.MQT_LINHAS AS ( 
    SELECT linhaversaoatual.idlinhaatual idlinhaatuallinhaversaoatual, 
           linhaversaoatual.idlinhacredito, 
           linhaversaoatual.datacadastrolinha, 
           linhacredito.idlinhacredito    idlinhacreditolinhacredito, 
           linhacredito.datacadastrolinha datacadastrolinhalinhacredito, 
           linhacredito.idproduto, 
           linhatipopessoa.codtipopessoa, 
           linhatipopessoa.idlinhacredito    idlinhacreditolinhatipopessoa, 
           linhatipopessoa.datacadastrolinha datacadastrolinhalinhatipopessoa, 
           linhagrupooperacao.codgrupooperacao, 
           linhagrupooperacao.idlinhacredito    idlinhacreditolinhagrupooperacao, 
           linhagrupooperacao.datacadastrolinha datacadastrolinhalinhagrupooperacao, 
           instituicaolinha.idinstituicao, 
           instituicaolinha.idlinhaatual, 
           instituicaolinha.idsituacaocredito,
           produto.idproduto idprodutoproduto,
           produto.descproduto,
           produto.siglaproduto,
           produto.idprodutosisbr            
    FROM cre.linhaversaoatual   linhaversaoatual, 
         cre.linhacredito       linhacredito, 
         cre.linhatipopessoa    linhatipopessoa, 
         cre.linhagrupooperacao linhagrupooperacao, 
         cre.instituicaolinha   instituicaolinha,
         cre.produto            produto
    WHERE linhaversaoatual.idlinhacredito      = linhacredito.idlinhacredito 
      AND linhaversaoatual.datacadastrolinha   = linhacredito.datacadastrolinha 
      AND linhatipopessoa.idlinhacredito       = linhacredito.idlinhacredito 
      AND linhatipopessoa.datacadastrolinha    = linhacredito.datacadastrolinha 
      AND linhagrupooperacao.idlinhacredito    = linhacredito.idlinhacredito 
      AND linhagrupooperacao.datacadastrolinha = linhacredito.datacadastrolinha 
      AND instituicaolinha.idlinhaatual        = linhaversaoatual.idlinhaatual
      AND linhacredito.idproduto               = produto.idproduto)       
DATA INITIALLY DEFERRED REFRESH IMMEDIATE ENABLE QUERY OPTIMIZATION MAINTAINED BY SYSTEM
;
