CREATE OR REPLACE VIEW "CRE"."VIW_INTEGRACAOOPERACAORURALEMPREENDIMENTO" AS (
   SELECT ocr.IDOPERACAOCREDITO,
          ocr.IDOPERACAOCREDITORURAL,
          ocr.IDINSTITUICAOOPERACAO,
          ocr.IDUNIDADEINSTITUICAOOPERACAO,
          ocr.IDINSTRUMENTOCREDITOBACEN,
          ocr.CODDAP,
          CAST(ocr.NUMREFBACEN AS VARCHAR(11)) AS NUMREFBACEN,
          ocr.DATACONTRATACAO,
          er.IDEMPREENDIMENTORURAL
   FROM cre.OPERACAOCREDITORURAL ocr INNER JOIN cre.EMPREENDIMENTORURAL er ON ocr.IDOPERACAOCREDITORURAL = er.IDOPERACAOCREDITORURAL
   UNION ALL
   SELECT voc.IDOPERACAOCREDITO,
          NULL AS IDOPERACAOCREDITORURAL,
          voc.IDINSTITUICAOOPERACAO,
          voc.IDUNIDADEINSTOPERACAO AS IDUNIDADEINSTITUICAOOPERACAO,
          ocf.IDTPINSTCREDBACEN AS IDINSTRUMENTOCREDITOBACEN,
          emitente.numDap AS CODDAP,
          ocfr.NUMREFBACEN AS NUMREFBACEN,
          ocfr.DATAHORAGERACAONUMREFBACEN  AS DATACONTRATACAO,
          eri.IDEMPREENDIMENTORURAL
   FROM CRE.VIW_OPERACAOCREDITO voc INNER JOIN FCO.OPERACAOCREDITOFC               ocf      ON voc.IDOPERACAOCREDITO      = ocf.IDOPERACAOCREDITO
                                    INNER JOIN FCO.EMPREENDIMENTOOPERACAOCREDITOFC eocf     ON ocf.IDOPERACAOCREDITOFC    = eocf.IDOPERACAOCREDITOFC
                                    INNER JOIN CRE.EMPREENDIMENTORURALINTEGRACAO   eri      ON eocf.CODEMPREENDIMENTO     = eri.IDEMPREENDIMENTORURALINTEGRACAO
                                     LEFT JOIN CRE.IntegracaoSICOROperacaoCredito  ocfr     ON ocfr.IDOPERACAOCREDITO     = voc.IDOPERACAOCREDITO
                                     LEFT JOIN CRE.INTEGRACAOSICOREMITENTE         emitente ON emitente.IDOPERACAOCREDITO = ocfr.IDOPERACAOCREDITO
                                                                                           AND emitente.IDPESSOA          = voc.IDPESSOA)
;
-- COPY-DATABASE-OBJECT: "CRE"."VIW_LIMITECARTAOPREAPROVADO"
/* -------------------------------------------------------------*/
/*  Generated by Enterprise Architect Version 13.0 	        	*/
/*  Modelo     : Des_CLS_ControleLimiteSicoob_TBP_DB2			*/
/*  Created On : 05-fev-2019 17:02      						*/
/*  CSS        : 1902-012270									*/
/* -------------------------------------------------------------*/

CREATE OR REPLACE VIEW "CRE"."VIW_LIMITECARTAOPREAPROVADO" AS
SELECT
	IDPESSOA,
	IDINSTITUICAO,
	RISCOCRL,
	VALORMARGEMCREDAUTOMATICO,
	VALORMARGEMPREAPROVADO,
	DATAHORAENQUADRAMENTO
FROM (
SELECT
	L.IDPESSOA,
	L.IDINSTITUICAO,M.IDPORTFOLIO,
	RISCO.RISCOCRL,
	P.VALORMARGEMCREDAUTOMATICO,
	P.VALORMARGEMPREAPROVADO,
	L.DATAHORAENQUADRAMENTO,
	ROW_NUMBER() OVER(PARTITION BY L.IDPESSOA, L.IDINSTITUICAO, M.IDPORTFOLIO) AS SEQ
FROM CRE.LIMITETOMADOR L 
    INNER JOIN CRE.POSICAOLIMITETOMADOR P ON
        P.IDLIMITETOMADOR = L.IDLIMITETOMADOR
    INNER JOIN CRE.MAPAPORTFOLIOBACEN M ON
          M.IDPORTFOLIO = L.IDPORTFOLIO 
      AND M.IDTIPOTOMADOR = L.IDTIPOTOMADOR 
      AND M.IDTIPOTOMADORSUBCLASSE = L.IDTIPOTOMADORSUBCLASSE
    INNER JOIN CRL.VIW_RISCOTOMADOR RISCO ON
          RISCO.IDPESSOA = L.IDPESSOA 
      AND RISCO.IDINSTITUICAO = L.IDINSTITUICAO
    LEFT JOIN CRE.REGISTROOPERACAO R ON
          R.IDLIMITETOMADOR = L.IDLIMITETOMADOR
WHERE L.BOLATIVO = 1  
  AND L.IDVINCULOPERFILLIMITETOMADOR IS NOT NULL 
  AND M.IDDOMINIOORIGEM = 11
  AND m.bolativo = 1
  AND RISCO.BOLATIVO = 1 
  AND R.IDLIMITETOMADOR IS NULL   ) WHERE SEQ = 1
;
