-- COPY-DATABASE-OBJECT: "CRE"."VIW_OPERACAOCREDITORURAL"
CREATE OR REPLACE VIEW "CRE"."VIW_OPERACAOCREDITORURAL" AS 
SELECT
    ocr.IDOPERACAOCREDITORURAL,
    ocr.IDOPERACAOCREDITO,
    ocr.DATACONTRATACAO,
    ocr.IDLINHACREDITO,
    ocr.DATACADASTROLINHA,
    ocr.IDPLANOLIBERACAO,
    ocr.VALORTOTALFINANCIADO,
    fb.IDFONTERECURSOBACEN,
    fb.DESCFONTERECURSOBACEN,
    fb.DATAINICIOVIGENCIA,
    fb.DATAFIMVIGENCIA,
    fb.BOLRECURSOCONTROLADO,
    lu.IDLIMITECCL,
    lu.IDINSTITUICAO AS IDINSTITUICAOLIMITECCL,
    lu.IDUNIDADEINSTITUICAO AS IDUNIDADEINSTITUICAOLIMITECCL,
    lu.DATAHORAVINCULACAO AS DATAHORAVINCULACAOLIMITECCL,
    ocrm.NUMCONTRATOCREDITOMAE,
    plr.IDATIVIDADEBACEN,
    plr.IDFINALIDADEBACEN,
    ocr.NUMREFBACEN,
    ocr.IDPROGRAMABACEN,
    ocr.IDPRESTADORORIENTACAOTECNICA,
    ocr.IDSAFRA 
FROM
    cre.OPERACAOCREDITORURAL ocr
JOIN cre.PARAMETROLINHARURAL plr ON
    ocr.IDLINHACREDITO = plr.IDLINHACREDITO
    AND ocr.DATACADASTROLINHA = plr.DATACADASTROLINHA
LEFT JOIN cre.GRUPOFONTERECURSO gfr1 ON 
    gfr1.IDGRUPOFONTERECURSO = ocr.IDGRUPOFONTERECURSO
LEFT JOIN cre.GRUPOFONTERECURSO gfr2 ON 
    gfr2.IDTIPOGRUPOFONTE = plr.IDTIPOGRUPOFONTE 
    AND gfr2.BOLATIVO = 1
JOIN cre.FONTERECURSOBACEN fb ON 
    fb.IDFONTERECURSOBACEN = COALESCE(
        gfr1.IDFONTERECURSOBACEN,
        plr.IDFONTERECURSOBACEN,
        gfr2.IDFONTERECURSOBACEN
    )
LEFT JOIN cre.LIMITEUTILIZADOOPERACAORURAL lu ON
    ocr.IDOPERACAOCREDITORURAL = lu.IDOPERACAOCREDITORURAL
LEFT JOIN cre.OPERACAOCREDITORURALMAE ocrm ON
    ocrm.IDOPERACAOCREDITORURAL = ocr.IDOPERACAOCREDITORURAL
;
