, ER.DATAPLANTIOSEMEADURAINICIO
, ER.DATAPLANTIOSEMEADURAFIM
, ER.DATACOLHEITAINICIO
, ER.DATACOLHEITAFIM

, SAFRA.DESCSAFRA

, ERI.IDIMOVEL
, ERI.IDBEMIMOVEL
, ERI.NUMNIRF
, ERI.NUMSNCR
, ERI.NUMREGCAR
, ERI.VALORAREAEXPLORADA

, ERIG.IDGLEBA 

, ERC.VALORFINANCIADO
, ERC.VALORRECURSOPROPRIO
, ERC.VALORPREVISAOPRODUCAO
, ERC.QTDPRODUTIVIDADE
, CASE WHEN ERC.IDUNIDADEMEDIDAEXPLORADA = 2 THEN ERC.VALOREXPLORACAO ELSE 0 END AS VALOREXPLORACAO

, ERS.IDFASECICLOPRODUCAOBACEN
, ERS.IDGRAOSEMENTEBACEN
, ERS.IDTIPOAGROPECUARIABACEN
, ERS.IDTIPOCULTIVOBACEN
, ERS.IDTIPOIRRIGACAOBACEN
, ERS.IDTIPOCONSORCIOBACEN
, ERS.IDPRODUTOCONSORCIADO
, ERS.IDTIPOCLIMABACEN

FROM CRE.OPERACAOCREDITORURAL OCR

    JOIN CRE.EMPREENDIMENTORURAL ER ON ER.IDOPERACAOCREDITORURAL = OCR.IDOPERACAOCREDITORURAL

    LEFT JOIN CRE.EMPREENDIMENTORURALIMOVEL ERI ON ERI.IDEMPREENDIMENTORURAL = ER.IDEMPREENDIMENTORURAL

    JOIN CRE.SAFRA SAFRA ON SAFRA.IDSAFRA = ER.IDSAFRA

    LEFT JOIN CRE.EMPREENDIMENTORURALIMOVELGLEBAGEO ERIG ON ERIG.IDEMPREENDIMENTORURALIMOVEL = ERI.IDEMPREENDIMENTORURALIMOVEL

    LEFT JOIN CRE.EMPREENDIMENTORURALCUSTEIO ERC ON ERC.IDEMPREENDIMENTORURAL = ER.IDEMPREENDIMENTORURAL

    JOIN TABLE (
        SELECT RL.IDFASECICLOPRODUCAOBACEN, RL.IDGRAOSEMENTEBACEN, RL.IDTIPOAGROPECUARIABACEN, RL.IDTIPOCULTIVOBACEN, RL.IDTIPOIRRIGACAOBACEN,RL.IDTIPOCONSORCIOBACEN,RL.IDPRODUTOCONSORCIADO, RL.IDTIPOCLIMABACEN
        FROM CRE.EMPREENDIMENTORURALCOMERCIALIZACAOSISTEMAPRODUCAO RL
        WHERE RL.IDEMPREENDIMENTORURAL = ER.IDEMPREENDIMENTORURAL

        UNION ALL
        SELECT RL.IDFASECICLOPRODUCAOBACEN, RL.IDGRAOSEMENTEBACEN, RL.IDTIPOAGROPECUARIABACEN, RL.IDTIPOCULTIVOBACEN, RL.IDTIPOIRRIGACAOBACEN,RL.IDTIPOCONSORCIOBACEN,RL.IDPRODUTOCONSORCIADO, RL.IDTIPOCLIMABACEN
        FROM CRE.EMPREENDIMENTORURALCUSTEIOSISTEMAPRODUCAO RL
        WHERE RL.IDEMPREENDIMENTORURAL = ER.IDEMPREENDIMENTORURAL

        UNION ALL
        SELECT RL.IDFASECICLOPRODUCAOBACEN, RL.IDGRAOSEMENTEBACEN, RL.IDTIPOAGROPECUARIABACEN, RL.IDTIPOCULTIVOBACEN, RL.IDTIPOIRRIGACAOBACEN,RL.IDTIPOCONSORCIOBACEN,RL.IDPRODUTOCONSORCIADO, RL.IDTIPOCLIMABACEN
        FROM CRE.EMPREENDIMENTORURALINVESTIMENTOSISTEMAPRODUCAO RL
        WHERE RL.IDEMPREENDIMENTORURAL = ER.IDEMPREENDIMENTORURAL

    ) ERS 
    ON 1=1 
	)
;
-- COPY-DATABASE-OBJECT: "CRE"."VIW_OPERACAORURALINVESTIMENTOACOMPANHAMENTO"
CREATE OR REPLACE VIEW "CRE"."VIW_OPERACAORURALINVESTIMENTOACOMPANHAMENTO" as (
SELECT 
    ocr.NUMREFBACEN,
    ocr.IDINSTITUICAOOPERACAO,
    ocr.IDUNIDADEINSTITUICAOOPERACAO,
    ocr.DATACONTRATACAO,
    ocr.IDINSTRUMENTOCREDITOBACEN,
    ocr.CODDAP,
    er.IDOPERACAOCREDITORURAL,
    er.IDEMPREENDIMENTORURAL,
    er.IDPESSOAPRODUTORRURAL,
    er.NUMSEQEMPREENDIMENTORURAL, 
    er.IDMUNICIPIO,
    er.IDEMPREENDIMENTOBACEN,
    er.DATAPLANTIOSEMEADURAINICIO,
    er.DATAPLANTIOSEMEADURAFIM,
    er.DATACOLHEITAINICIO,
    er.DATACOLHEITAFIM,
    eig.IDGLEBA,
    eisp.IDTIPOAGROPECUARIABACEN,
    eisp.IDTIPOCONSORCIOBACEN,
    eisp.IDGRAOSEMENTEBACEN,
    eisp.IDTIPOIRRIGACAOBACEN,
    eisp.IDTIPOCULTIVOBACEN,
    eisp.IDFASECICLOPRODUCAOBACEN,
    eisp.IDTIPOCLIMABACEN,
    erin.VALORFINANCIADO,
    erin.VALORRECURSOPROPRIO,
    case when erin.idunidademedidaqtdexplorada = 2 then erin.QTDEXPLORADA else 0 end as QTDEXPLORADA,
    erip.IDPESSOA,
    erip.BOLENVIASICOR,
    eri.IDIMOVEL,
    eri.IDBEMIMOVEL,
    eri.NUMNIRF,
    eri.NUMSNCR,
    eri.NUMREGCAR,
    ers.IDTIPOSEGURORURAL,
    esp.NUMPROPOSTAAPOLICESEGURO,
    esp.IDSEGURADORARURAL,
    esp.IDCORRETORASEGURORURAL,
    esp.IDTIPOSEGUROPRIVADORURAL,
    esp.DATAINICIOVIGENCIA,
    esp.DATAFIMVIGENCIA,
    esp.IDTIPOSUBVENCAOSEGUROPRIVADORURAL,
    esp.VALORSUBVENCAO,
    esp.VALORPREMIOFINANCIADO,
    ocr.IDOPERACAOCREDITO,
    eri.VALORAREAEXPLORADA,
	esp.CODTIPODOCUMENTOSEGUROPRIVADO,
	ers.VALORSEGURO,
	esp.BOLFINANCIADO,
	ers.VALORTOTALSEGURADO,
	esp.IDPESSOASEGURADO,
	esp.IDPESSOABENEFICIARIO,
	erspes.IDEVENTOSEGURO,
	er.PERCENERGIARENOVAVEL, er.CODCERTORGANICA, er.DESCURLCERTORGANICA, er.CODCERTRASTREABILIADADE, er.DESCURLCERTRASTREABILIDADE,
	eri.NUMOUTORGADAGUA, eri.PERCPRESERVACAO 
FROM
    cre.VIW_INTEGRACAOOPERACAORURALEMPREENDIMENTO ocr
JOIN cre.EMPREENDIMENTORURAL er ON
    ocr.IDEMPREENDIMENTORURAL = er.IDEMPREENDIMENTORURAL
JOIN cre.EMPREENDIMENTORURALINVESTIMENTO erin ON
    er.IDEMPREENDIMENTORURAL = erin.IDEMPREENDIMENTORURAL
LEFT JOIN cre.EMPREENDIMENTORURALIMOVEL eri ON
    er.IDEMPREENDIMENTORURAL = eri.IDEMPREENDIMENTORURAL
LEFT JOIN cre.EMPREENDIMENTORURALIMOVELGLEBAGEO eig ON
    eri.IDEMPREENDIMENTORURALIMOVEL = eig.IDEMPREENDIMENTORURALIMOVEL
LEFT JOIN cre.EMPREENDIMENTORURALSEGUROPRIVADO esp ON
    er.IDEMPREENDIMENTORURAL = esp.IDEMPREENDIMENTORURAL
LEFT JOIN cre.EMPREENDIMENTORURALINVESTIMENTOSISTEMAPRODUCAO eisp ON
    er.IDEMPREENDIMENTORURAL = eisp.IDEMPREENDIMENTORURAL
LEFT JOIN cre.EMPREENDIMENTORURALIMOVELPROPRIETARIO erip ON
    eri.IDEMPREENDIMENTORURALIMOVEL = erip.IDEMPREENDIMENTORURALIMOVEL
LEFT JOIN cre.EMPREENDIMENTORURALSEGURO ers ON
    er.IDEMPREENDIMENTORURAL = ers.IDEMPREENDIMENTORURAL 
LEFT JOIN  CRE.EMPREENDIMENTORURALSEGUROPRIVADOEVENTOSEGURO erspes
    on er.IDEMPREENDIMENTORURAL = erspes.IDEMPREENDIMENTORURAL
)
;
