-- COPY-DATABASE-OBJECT: "CRE"."VIW_OPERACAORURALREPASSELIBERADO"
CREATE OR REPLACE VIEW "CRE"."VIW_OPERACAORURALREPASSELIBERADO" AS 
SELECT  oc.IDINSTITUICAOLOCALNEGOCIO, 
        oc.IDOPERACAOCREDITO,
        oc.IDSITUACAOCREDITO,
        oc.DATAOPERACAOCREDITO,
        oc.DATAVENCIMENTOOPERACAO,      
        oc.IDPESSOA,
        oc.NUMPROPOSTA,        
        oc.NUMCONTRATOCREDITO,
        oc.PERCTAXAJUROS,
        oc.VALOROPERACAOCREDITO,
        ocr.DATAREGISTROSICOR,
        ocr.NUMREFBACEN,
        ocm.NUMCONTRATOCREDITOMAE,
        ocm.PERCTAXAJUROS as PERCTAXAJUROSMAE,        
        luo.BOLREGISTRAPENHORCEDULAR, 
        luo.BOLREGISTRACESSAOFIDUCIARIA, 
        luo.BOLREGISTRAINTERVENIENCIACENTRAL, 
        luo.BOLREGISTRAAPLICACAOFINANCEIRA,
        luo.BOLREGISTRAAPLFINANCEIRACENTRAL, 
        luo.PERCACORDOCOMPENSACAO, 
        luo.PERCCONTRAPARTIDA,         
        luo.PERCREMUNERACAOCONTRAPARTIDA, 
        luo.IDINSTITUICAO,
        luo.IDLIMITECCL
        FROM cre.OPERACAOCREDITORURALMAE ocm
                    JOIN cre.OPERACAOCREDITORURAL ocr on ocr.IDOPERACAOCREDITORURAL = ocm.IDOPERACAOCREDITORURAL
                    JOIN cre.OPERACAOCREDITO oc on oc.IDOPERACAOCREDITO = ocr.IDOPERACAOCREDITO AND oc.IDPRODUTO = 6                                        
                    JOIN cre.SITUACAOCREDITO sc ON oc.IDSITUACAOCREDITO = sc.IDSITUACAOCREDITO AND sc.IDFONTEDADO = 2
                    JOIN cre.LIMITEUTILIZADOOPERACAORURAL luo ON luo.IDOPERACAOCREDITORURAL = ocr.IDOPERACAOCREDITORURAL                    
WHERE oc.IDSITUACAOCREDITO in (20,21,22,23,24)
;
