-- COPY-DATABASE-OBJECT: "CRE"."VIW_REPOSITORIOCREDAUTO"
CREATE VIEW "CRE"."VIW_REPOSITORIOCREDAUTO" AS 
SELECT
	IDINSTITUICAO, IDPESSOA, CODMODOPERACAOBACEN, CODSUBMODOPERACAOBACEN, IDPERFILTOMADOR, VALORMARGEMAUTOMATICO, BOLLINHAPREAPROVADA, DATAHORAPROCESSAMENTONPC
	, VALORPARCELAMAX, VALORLIMITENPC, VALORPARCELAMIN, VALORMINLIMITE, VALORPARCELANPC, DATAHORAENDIVIDAMENTOSCR
FROM
	CCL.TMPTOMADORFABRICALIMITE T
WHERE
	CODMODOPERACAOBACEN = 2
AND CODSUBMODOPERACAOBACEN IN (3,15,16)
AND VALORMARGEMAUTOMATICO > 0
AND (
	SELECT COALESCE (
				(SELECT VALORPARAMETROINSTITUICAO FROM  CCL.PARAMETROINSTITUICAO  WHERE IDINSTITUICAO = T.IDINSTITUICAO AND CODPARAMETRO = P.CODPARAMETRO AND VALORPARAMETROINSTITUICAO = 1)
		, VALORPARAMETRO) VALORPAR
	FROM CCL.PARAMETRO P
	WHERE CODPARAMETRO = 36
	) = 1
;
