-- COPY-DATABASE-OBJECT: "CRF"."VIW_EMPRESA"
CREATE OR REPLACE VIEW "CRF"."VIW_EMPRESA" AS

SELECT 
 Empresa.idEmpresaPrestadora       AS IdEmpresa
,Empresa.idInstituicao             AS IdInstituicao
,Empresa.valorAreaMinima           AS ValorAreaMinima
,Empresa.dataInicioContrato        AS dataInicioContrato
,Empresa.dataFimContrato           AS dataFimContrato
,Empresa.descUrlApi                AS descUrlApi
,Empresa.descTokenApi              AS descTokenApi
,Empresa.descDadosAutenticacao     AS descDadosAutenticacao
,Empresa.descEmailMonitoramento    AS descEmailMonitoramento
,Empresa.BolFiscalizacao           AS BolFiscalizacao
,Empresa.BolMonitoramento          AS BolMonitoramento
,Empresa.BolValidarAreaMinimaGleba AS BolValidarAreaMinimaGleba
,Empresa.dataHoraAtualizacao       AS dataHoraAtualizacao
,Empresa.idPessoaJuridica          AS IdPessoaJuridica
,PessoaJuridica.nomePessoa         AS nomePJ
,PessoaJuridica.numCpfCnpj         AS cnpj
,Situacao.codSituacaoEmpresaPrestadora AS codSituacaoEmpresaPrestadora
,Situacao.descSituacaoEmpresaPrestadora AS descSituacaoEmpresaPrestadora
 
,produtos.descricao AS produtos

FROM CRF.EmpresaPrestadora Empresa

    JOIN CRF.SituacaoEmpresaPrestadora Situacao 
        ON Situacao.codSituacaoEmpresaPrestadora = Empresa.codSituacaoEmpresaPrestadora

    JOIN TABLE (
        SELECT PessoaJuridica.numCpfCnpj, LTRIM(RTRIM(PessoaJuridica.nomePessoa)) AS nomePessoa 
        FROM CLI.VIW_PESSOA PessoaJuridica
        WHERE PessoaJuridica.idInstituicao = Empresa.idInstituicao
        AND PessoaJuridica.idPessoa		   = Empresa.idPessoaJuridica
    ) PessoaJuridica ON 1=1
    
    LEFT JOIN TABLE (
        SELECT LISTAGG(idProdutoBacen, ', ') AS descricao
        FROM CRF.EmpresaPrestadoraProdutoBacen RL
        WHERE RL.idEmpresaPrestadora = Empresa.idEmpresaPrestadora
    ) produtos ON 1=1
;
-- COPY-DATABASE-OBJECT: "CRF"."VIW_FISCALIZACAO"
CREATE OR REPLACE VIEW "CRF"."VIW_FISCALIZACAO" AS
SELECT
  Fiscalizacao.IdFiscalizacao
, Fiscalizacao.IdFiscalizacaoREF  
, Fiscalizacao.IdEmpreendimento AS IdEmpreendimentoBacen
, Fiscalizacao.IdLocalidade
, Fiscalizacao.DataHoraAtualizacao
, Fiscalizacao.IdChaveNegocio
, Fiscalizacao.IdInstituicaoOrigem
, Fiscalizacao.IdInstituicaoDestino
, Fiscalizacao.DataInicioExecucao
, Fiscalizacao.DataFimExecucao
, Fiscalizacao.DataNovaFiscalizacao

, ContratoLegado.DataLiberacao + (Fiscalizacao.PrazoConclusao + Fiscalizacao.PrazoAdicionalFiscalizacao) DAY AS DataLimiteConclusao
, Fiscalizacao.DataInicioExecucao + Fiscalizacao.PrazoTecnicoResponsavel + (CASE WHEN Fiscalizacao.PrazoAdicionalProfissional > 0 THEN Fiscalizacao.PrazoAdicionalProfissional ELSE 0 END) DAY AS DataLimiteExecucao
, CASE WHEN Fase.CodFaseFiscalizacao = 2 AND Fiscalizacao.dataInicioExecucao IS NOT NULL THEN DAYS(CURRENT DATE) - DAYS(Fiscalizacao.dataInicioExecucao) ELSE DAYS(CURRENT DATE) - DAYS(DATE(Historico.dataHoraHistorico)) END AS numDiasSituacao
, Fiscalizacao.PrazoConclusao + Fiscalizacao.PrazoAdicionalFiscalizacao AS PrazoConclusao
, Fiscalizacao.PrazoTecnicoResponsavel + (CASE WHEN Fiscalizacao.PrazoAdicionalProfissional > 0 THEN Fiscalizacao.PrazoAdicionalProfissional ELSE 0 END) AS PrazoProfissional

, Historico.IdUsuario AS IdUsuarioHistorico
, Historico.DataHoraHistorico
, Historico.DescJustificativa

, Fase.CodFaseFiscalizacao
, Fase.DescFaseFiscalizacao

, Situacao.CodSituacaoFiscalizacao
, Situacao.DescSituacaoFiscalizacao

, TipoFiscalizacao.CodTipoFiscalizacao
, TipoFiscalizacao.DescTipoFiscalizacao

, TipoFormulario.CodTipoFormulario
, TipoFormulario.DescTipoFormulario

, FormularioVersao.IdFormularioVersao
, FormularioVersao.NumVersao
, FormularioVersao.NomeFormulario

, Profissional.IdTecnicoResponsavel AS IdProfissional
, Profissional.IdUsuario AS IdUsuarioProfissional
, Profissional.IdPessoa AS IdPessoaProfissional

, Empresa.idEmpresaPrestadora AS IdEmpresa
, Empresa.idPessoaJuridica AS IdPessoaEmpresa

, Contrato.IdContratoFiscalizavel
, Contrato.IdOperacaoCredito
, Contrato.IdOperacaoCreditoRural
, Contrato.IdPessoaCliente
, Contrato.BolLiberacaoParcelada

, ContratoLegado.IdProduto
, ContratoLegado.IdModalidadeProduto
, ContratoLegado.NumCliente
, ContratoLegado.NumContratoCredito
, ContratoLegado.NumRefBacen
, ContratoLegado.NumParcelaLiberacao
, ContratoLegado.DataLiberacao
, ContratoLegado.DataVencimento
, ContratoLegado.ValorContratado
, ContratoLegado.ValorLiberado
, ContratoLegado.IdProgramaBndesLegado
, ContratoLegado.IdModalidadeLegado
, ContratoLegado.CodSistematicaOperacional
, ContratoLegado.IdOrigemRecursoOpCred
, ContratoLegado.IdFinalidadeOpCred

, ContratoEmpreendimento.DataInicioColheita
, ContratoEmpreendimento.DescTipoCultivar
, ContratoEmpreendimento.DescTipoSolo
, ContratoEmpreendimento.ValorAreaFinanciada
, ContratoEmpreendimento.ValorFinanciado
, ContratoEmpreendimento.ValorRecursoProprio
, ContratoEmpreendimento.IdGrupoSelecao AS IdGrupoSelecaoEmpreendimento

, ContratoAmostragem.IdProcessoAmostragem
, ContratoAmostragem.IdGrupoSelecao

, ModalidadeLegado.CodCarteira
, ModalidadeLegado.DescModalidadeProduto
	
FROM CRF.Fiscalizacao Fiscalizacao
		        
    JOIN CRF.HistFiscalizacao Historico 
        ON  Historico.idFiscalizacao = Fiscalizacao.idFiscalizacao
        AND Historico.idHistFiscalizacao = (SELECT MAX(H2.idHistFiscalizacao) FROM CRF.HistFiscalizacao H2 WHERE H2.idFiscalizacao = Fiscalizacao.idFiscalizacao) 

    JOIN CRF.SituacaoFiscalizacao Situacao ON Situacao.CodSituacaoFiscalizacao = Fiscalizacao.CodSituacaoFiscalizacao

    JOIN CRF.FaseFiscalizacao Fase ON Fase.CodFaseFiscalizacao = Situacao.CodFaseFiscalizacao

    JOIN CRF.TipoFiscalizacao TipoFiscalizacao ON TipoFiscalizacao.CodTipoFiscalizacao = Fiscalizacao.CodTipoFiscalizacao
    
    JOIN CRF.ContratoFiscalizavel Contrato ON Contrato.IdContratoFiscalizavel = Fiscalizacao.IdContratoFiscalizavel

    JOIN CRF.ContratoFiscalizavelLegado ContratoLegado ON ContratoLegado.IdContratoFiscalizavel = Fiscalizacao.IdContratoFiscalizavel

    LEFT JOIN CRF.ContratoFiscalizavelAmostragem ContratoAmostragem ON ContratoAmostragem.IdContratoFiscalizavel = Fiscalizacao.IdContratoFiscalizavel

    JOIN CRF.ContratoFiscalizavelEmpreendimento ContratoEmpreendimento 
        ON  ContratoEmpreendimento.IdContratoFiscalizavel = Fiscalizacao.IdContratoFiscalizavel
        AND ContratoEmpreendimento.IdEmpreendimento       = Fiscalizacao.IdEmpreendimento
        AND ContratoEmpreendimento.IdLocalidade           = Fiscalizacao.IdLocalidade   
    
    LEFT JOIN CRF.FormularioVersao FormularioVersao ON FormularioVersao.IdFormularioVersao = Fiscalizacao.IdFormularioVersao
    
    LEFT JOIN CRF.TipoFormulario TipoFormulario ON TipoFormulario.CodTipoFormulario = FormularioVersao.CodTipoFormulario

    LEFT JOIN CRF.TecnicoResponsavel Profissional ON Profissional.IdTecnicoResponsavel = Fiscalizacao.IdTecnicoResponsavel

    LEFT JOIN CRF.EmpresaPrestadora Empresa ON Empresa.IdEmpresaPrestadora = Fiscalizacao.IdEmpresaPrestadora

    LEFT JOIN CRF.ModalidadeLegado ModalidadeLegado ON ModalidadeLegado.IdModalidadeLegado = ContratoLegado.IdModalidadeLegado
;
-- COPY-DATABASE-OBJECT: "CRF"."VIW_FISCALIZACAOGLEBA"
CREATE OR REPLACE VIEW "CRF"."VIW_FISCALIZACAOGLEBA" AS
SELECT 
  Fiscalizacao.IdFiscalizacao
, Fiscalizacao.IdChaveNegocio
, Fiscalizacao.IdEmpreendimento AS IdEmpreendimentoBacen

, ContratoFiscalizavel.IdOperacaoCredito
, ContratoFiscalizavelLegado.NumContratoCredito

, FiscalizacaoGleba.IdGleba
, FiscalizacaoGleba.IdGlebaContratada
, FiscalizacaoGleba.DescComentario
, FiscalizacaoGleba.DataHorainclusao
, FiscalizacaoGleba.dataHoraalteracao
, FiscalizacaoGleba.BolAplicativo
, FiscalizacaoGleba.BolAtivo

, DocumentoFiscalizacao.IdDocumentoFiscalizacao
, DocumentoFiscalizacao.DescDocumento
, DocumentoFiscalizacao.DescCoordenadaGeodesica

FROM CRF.FiscalizacaoGleba FiscalizacaoGleba
    JOIN CRF.Fiscalizacao Fiscalizacao ON Fiscalizacao.IdFiscalizacao = FiscalizacaoGleba.IdFiscalizacao
    JOIN CRF.ContratoFiscalizavel ContratoFiscalizavel ON ContratoFiscalizavel.IdContratoFiscalizavel = Fiscalizacao.IdContratoFiscalizavel
    JOIN CRF.ContratoFiscalizavelLegado ContratoFiscalizavelLegado ON ContratoFiscalizavelLegado.IdContratoFiscalizavel = Fiscalizacao.IdContratoFiscalizavel
    LEFT JOIN CRF.DocumentoFiscalizacao DocumentoFiscalizacao ON DocumentoFiscalizacao.IdDocumentoFiscalizacao = FiscalizacaoGleba.IdDocumentoFiscalizacao
;
-- COPY-DATABASE-OBJECT: "CRF"."VIW_FLUXOFISCALIZACAO"
CREATE OR REPLACE VIEW "CRF"."VIW_FLUXOFISCALIZACAO" AS
SELECT
  TipoFiscalizacao.codTipoFiscalizacao
, TipoFiscalizacao.descTipoFiscalizacao

, Situacao.codSituacaoFiscalizacao AS codSituacao
, '('||Fase.descFaseFiscalizacao||') '||Situacao.descSituacaoFiscalizacao AS descSituacao

, Perfil.codPerfilFiscalizacao AS codPerfil
, Perfil.descPerfilFiscalizacao AS descPerfil

, Fluxo.codAcaoFiscalizacao AS codAcao
, '('||FaseAcao.descFaseFiscalizacao||') '||Acao.descAcaoFiscalizacao AS descAcao

FROM CRF.FluxoSituacaoFiscalizacao Fluxo 

    JOIN CRF.TipoFiscalizacao TipoFiscalizacao 
        ON TipoFiscalizacao.codTipoFiscalizacao = Fluxo.codTipoFiscalizacao

    JOIN CRF.SituacaoFiscalizacao Situacao 
        ON Situacao.codSituacaoFiscalizacao = Fluxo.codSituacaoFiscalizacao 

    JOIN CRF.FaseFiscalizacao Fase 
        ON Fase.codFaseFiscalizacao = Situacao.codFaseFiscalizacao 

    JOIN CRF.PerfilFiscalizacao Perfil 
        ON Perfil.codPerfilFiscalizacao = Fluxo.codPerfilFiscalizacao  

    JOIN CRF.SituacaoFiscalizacao Acao 
        ON Acao.codSituacaoFiscalizacao = Fluxo.codAcaoFiscalizacao

    JOIN CRF.FaseFiscalizacao FaseAcao
        ON FaseAcao.codFaseFiscalizacao = Acao.codFaseFiscalizacao
;
-- COPY-DATABASE-OBJECT: "CRF"."VIW_FORMULARIOASSUNTOCAMPOVERSAO"
CREATE OR REPLACE VIEW "CRF"."VIW_FORMULARIOASSUNTOCAMPOVERSAO" AS
SELECT DISTINCT
       FORMULARIOVERSAO.IDFORMULARIOVERSAO 
     , FORMULARIOVERSAO.IDFORMULARIO
     , FORMULARIOVERSAO.NUMVERSAO
     , FORMULARIOVERSAO.DATAHORAINCLUSAO  
     , FORMULARIOVERSAO.IDUSUARIOINCLUSAO
     , FORMULARIOVERSAO.NOMEFORMULARIO
     , FORMULARIOVERSAO.DESCFORMULARIO
     , FORMULARIOVERSAO.DESCTAGXML AS DESCTAGFORMULARIO
     , FORMULARIOVERSAO.BOLNOVACONFIGURACAO 
     , FORMULARIOVERSAO.BOLATIVO 

     , TIPOFORMULARIO.CODTIPOFORMULARIO
     , TIPOFORMULARIO.DESCTIPOFORMULARIO
     
     , ASSUNTOFORMULARIOVERSAO.IDASSUNTOFORMULARIOVERSAO 
     , ASSUNTOFORMULARIOVERSAO.DESCASSUNTOFORMULARIO
     , ASSUNTOFORMULARIOVERSAO.NOMEASSUNTOFORMULARIO
     , ASSUNTOFORMULARIOVERSAO.BOLMULTIPLARESPOSTA
     , ASSUNTOFORMULARIOVERSAO.DESCTAGXML AS DESCTAGASSUNTO
     , ASSUNTOFORMULARIOVERSAO.NUMORDEM AS NUMORDEMASSUNTO
     
     , CAMPOASSUNTOVERSAO.IDCAMPOASSUNTOVERSAO 
     , CAMPOASSUNTOVERSAO.NOMECAMPOASSUNTO
     , CAMPOASSUNTOVERSAO.DESCCAMPOASSUNTO
     , CAMPOASSUNTOVERSAO.BOLPOSSUIITEM 
     , CAMPOASSUNTOVERSAO.BOLGRUPOMULTIPLARESPOSTA 
     , CAMPOASSUNTOVERSAO.BOLOBRIGATORIO 
     , CAMPOASSUNTOVERSAO.DESCTAGXML AS DESCTAGCAMPO
     , CAMPOASSUNTOVERSAO.NUMORDEM AS NUMORDEMCAMPO
     
     , TIPODADO.CODTIPODADO
     , TIPODADO.DESCTIPODADO
     
     , VALORPADRAO.CODVALORPADRAO
     , VALORPADRAO.NOMEVALORPADRAO
     , VALORPADRAO.DESCVALORPADRAO 
     
     , ITEM.ITENS
     
FROM CRF.CAMPOASSUNTOVERSAO CAMPOASSUNTOVERSAO 
    JOIN CRF.ASSUNTOFORMULARIOVERSAO ASSUNTOFORMULARIOVERSAO ON ASSUNTOFORMULARIOVERSAO.IDASSUNTOFORMULARIOVERSAO = CAMPOASSUNTOVERSAO.IDASSUNTOFORMULARIOVERSAO
    JOIN CRF.FORMULARIOVERSAO FORMULARIOVERSAO ON FORMULARIOVERSAO.IDFORMULARIOVERSAO = ASSUNTOFORMULARIOVERSAO.IDFORMULARIOVERSAO
    JOIN CRF.TIPOFORMULARIO TIPOFORMULARIO ON TIPOFORMULARIO.CODTIPOFORMULARIO = FORMULARIOVERSAO.CODTIPOFORMULARIO
    JOIN CRF.TIPODADO TIPODADO ON TIPODADO.CODTIPODADO = CAMPOASSUNTOVERSAO.CODTIPODADO
    LEFT JOIN CRF.VALORPADRAO VALORPADRAO ON VALORPADRAO.CODVALORPADRAO = CAMPOASSUNTOVERSAO.CODVALORPADRAO 
    LEFT JOIN TABLE(
      SELECT ITEM.IDCAMPOASSUNTOVERSAO,
             LISTAGG(
                '{"numero":'||ITEM.NUMITEM
                ||', "descricao":"'||ITEM.DESCITEM||'"'                
                ||CASE WHEN ITEM.DESCTAGXML IS NULL OR ITEM.DESCTAGXML = '' THEN '' ELSE ', "tag":"'||ITEM.DESCTAGXML||'"' END                
                ||', "complemento":'||CASE ITEM.BOLEXIGETEXTOCOMPLEMENTAR WHEN 1 THEN 'true' ELSE 'false' END||'},'
             ) WITHIN GROUP (ORDER BY ITEM.NUMITEM) AS ITENS
      FROM CRF.CAMPOASSUNTOITEMVERSAO ITEM
      WHERE ITEM.IDCAMPOASSUNTOVERSAO = CAMPOASSUNTOVERSAO.IDCAMPOASSUNTOVERSAO
      GROUP BY ITEM.IDCAMPOASSUNTOVERSAO
    ) AS ITEM ON 1=1
;
-- COPY-DATABASE-OBJECT: "CRF"."VIW_FORMULARIOVERSAOXML"
CREATE OR REPLACE VIEW "CRF"."VIW_FORMULARIOVERSAOXML" AS
SELECT  FORMULARIO.IDFORMULARIO
      , FORMULARIO.IDFORMULARIOVERSAO  
      , FORMULARIO.CODTIPOFORMULARIO  
      , FORMULARIO.NUMVERSAO
      , FORMULARIO.BOLATIVO    
      , XMLELEMENT(
          NAME "FORMULARIO", 
          XMLFOREST(
            FORMULARIO.IDFORMULARIOVERSAO      AS "CODIGO",    
            FORMULARIO.NUMVERSAO               AS "VERSAO",   
            FORMULARIO.NOMEFORMULARIO          AS "NOME",   
            FORMULARIO.DESCFORMULARIO          AS "DESCRICAO",
            FORMULARIO.DESCTAGXML              AS "TAG",
            FORMULARIO.BOLNOVACONFIGURACAO     AS "NOVACONFIGURACAO",
            TO_CHAR(FORMULARIO.DATAHORAINCLUSAO, 'DD/MM/YYYY HH24:MI:SS') AS "DATACADASTRO",
            FORMULARIO.IDUSUARIOINCLUSAO       AS "RESPONSAVELCADASTRO",    

            XMLFOREST( 
                TIPOFORMULARIO.CODTIPOFORMULARIO   AS "CODIGO",   
                TIPOFORMULARIO.DESCTIPOFORMULARIO  AS "NOME"
            ) AS "TIPOFORMULARIO",
            ASSUNTOS.LISTASSUNTOS              AS "LISTASSUNTOS"
          )
        ) AS DADOSXML

FROM CRF.FORMULARIOVERSAO FORMULARIO 
    JOIN CRF.TIPOFORMULARIO TIPOFORMULARIO ON TIPOFORMULARIO.CODTIPOFORMULARIO = FORMULARIO.CODTIPOFORMULARIO
 
    JOIN (
        SELECT  ASSUNTO.IDFORMULARIOVERSAO, 
              XMLAGG(
                XMLELEMENT(
                  NAME "ASSUNTO", 
                  XMLFOREST(
                    ASSUNTO.IDASSUNTOFORMULARIOVERSAO AS "CODIGO",  
                    ASSUNTO.NOMEASSUNTOFORMULARIO     AS "NOME",   
                    ASSUNTO.DESCASSUNTOFORMULARIO     AS "DESCRICAO",  
                    ASSUNTO.DESCTAGXML                AS "TAG",
                    ASSUNTO.NUMORDEM                  AS "ORDEM",  
                    CAMPOS.LISTCAMPOS                 AS "LISTACAMPOS"  
                  )
                )   
                ORDER BY ASSUNTO.NUMORDEM
              )  AS LISTASSUNTOS

        FROM CRF.ASSUNTOFORMULARIOVERSAO ASSUNTO 

        JOIN ( 
          SELECT  CAMPO.IDASSUNTOFORMULARIOVERSAO , 
                  XMLAGG(
                    XMLELEMENT(
                      NAME "CAMPO", 
                      XMLFOREST(
                        CAMPO.IDCAMPOASSUNTOVERSAO  AS "CODIGO",  
                        CAMPO.NOMECAMPOASSUNTO      AS "NOME",  
                        CAMPO.DESCCAMPOASSUNTO      AS "DESCRICAO",  
                        CAMPO.DESCTAGXML            AS "TAG",
                        CAMPO.BOLOBRIGATORIO        AS "OBRIGATORIO",  
                        CAMPO.NUMORDEM              AS "ORDEM",   
                        ITEM.ITENS                  AS "LISTAITENS",

                        XMLFOREST(
                            VALORPADRAO.CODVALORPADRAO  AS "CODIGO",   
                            VALORPADRAO.NOMEVALORPADRAO AS "NOME",   
                            VALORPADRAO.DESCVALORPADRAO AS "DESCRICAO"
                        ) AS "VALORPADRAO",

                        XMLFOREST(
                            TIPODADO.CODTIPODADO        AS "CODIGO",   
                            TIPODADO.DESCTIPODADO       AS "NOME" 
                        ) AS "TIPODADO"
 
                      )
                    )   
                    ORDER BY CAMPO.NUMORDEM
                  )  AS LISTCAMPOS
      
          FROM CRF.CAMPOASSUNTOVERSAO CAMPO 
            JOIN CRF.TIPODADO TIPODADO ON TIPODADO.CODTIPODADO = CAMPO.CODTIPODADO
            LEFT JOIN CRF.VALORPADRAO VALORPADRAO ON VALORPADRAO.CODVALORPADRAO = CAMPO.CODVALORPADRAO 
            LEFT JOIN TABLE(
              SELECT ITEM.IDCAMPOASSUNTOVERSAO,
                     XMLAGG( 
                        XMLELEMENT(
                          NAME "ITEM", 
                          XMLFOREST(
                            ITEM.NUMITEM                   AS "NUMERO",   
                            ITEM.DESCITEM                  AS "DESCRICAO",  
                            ITEM.DESCTAGXML                AS "TAG",
                            ITEM.BOLEXIGETEXTOCOMPLEMENTAR AS "COMPLEMENTO"  
                          )
                        )    
                        ORDER BY ITEM.NUMITEM
                     )  AS ITENS 
              FROM CRF.CAMPOASSUNTOITEMVERSAO ITEM
              WHERE ITEM.IDCAMPOASSUNTOVERSAO = CAMPO.IDCAMPOASSUNTOVERSAO
              GROUP BY ITEM.IDCAMPOASSUNTOVERSAO
            ) AS ITEM ON 1=1 
            
          GROUP BY CAMPO.IDASSUNTOFORMULARIOVERSAO 
        ) AS CAMPOS ON CAMPOS.IDASSUNTOFORMULARIOVERSAO = ASSUNTO.IDASSUNTOFORMULARIOVERSAO

      GROUP BY ASSUNTO.IDFORMULARIOVERSAO
      
    ) AS ASSUNTOS ON ASSUNTOS.IDFORMULARIOVERSAO = FORMULARIO.IDFORMULARIOVERSAO
;
-- COPY-DATABASE-OBJECT: "CRF"."VIW_MENSAGEMFISCALIZACAO"
CREATE OR REPLACE VIEW "CRF"."VIW_MENSAGEMFISCALIZACAO" AS
SELECT 
  Mensagem.idMensagemFiscalizacao
, Mensagem.idUsuarioInclusao
, Mensagem.idUsuarioExclusao
, Mensagem.dataHoraInclusao
, Mensagem.dataHoraVisualizacao
, Mensagem.dataHoraExclusao
, Mensagem.descMensagem
, Fiscalizacao.idFiscalizacao 
, Fiscalizacao.idChaveNegocio 
, Fiscalizacao.idInstituicaoDestino
, Fiscalizacao.codSituacaoFiscalizacao 
, Fiscalizacao.codTipoFiscalizacao 
, Contrato.idPessoaCliente
, Contrato.idInstituicao AS idInstituicaoCliente
, PerfilDestinatario.codPerfilFiscalizacao AS codPerfilDestinatario
, PerfilDestinatario.descPerfilFiscalizacao AS descPerfilDestinatario
, Prioridade.codPrioridadeMensagem
, Prioridade.descPrioridadeMensagem
, Profissional.idTecnicoResponsavel AS idProfissional
, Profissional.idPessoa AS idPessoaProfissional
FROM CRF.MensagemFiscalizacao Mensagem
    INNER JOIN CRF.PrioridadeMensagem Prioridade ON Prioridade.codPrioridadeMensagem = Mensagem.codPrioridadeMensagem
    INNER JOIN CRF.PerfilFiscalizacao PerfilDestinatario ON PerfilDestinatario.codPerfilFiscalizacao = Mensagem.codPerfilFiscalizacaoDestinatario
    INNER JOIN CRF.Fiscalizacao Fiscalizacao ON Fiscalizacao.idFiscalizacao = Mensagem.idFiscalizacao
    INNER JOIN CRF.ContratoFiscalizavel Contrato ON Contrato.idContratoFiscalizavel = Fiscalizacao.idContratoFiscalizavel
    LEFT JOIN CRF.TecnicoResponsavel Profissional ON Profissional.idTecnicoResponsavel = Mensagem.idTecnicoResponsavel
;
-- COPY-DATABASE-OBJECT: "CRF"."VIW_PROFISSIONAL"
CREATE OR REPLACE VIEW "CRF"."VIW_PROFISSIONAL" AS
SELECT 
 Profissional.IdTecnicoResponsavel                                        AS IdProfissional
,Profissional.idInstituicao                                               AS IdInstituicaoPessoa
,Profissional.idPessoa                                                    AS IdPessoaFisica
,Profissional.idPessoaJuridica                                            AS IdPessoaJuridica
,Profissional.idUsuario                                                   AS IdUsuario
,Profissional.QtdTempoExperiencia                                         AS QtdTempoExperiencia

,ProfissionalFuncoes.funcoes                                              AS DescFuncoes
,ProfissionalFuncoes.FuncoesHabilitadas                                   AS DescFuncoesHabilitadas

,ProfissionalInstituicoes.InstituicoesHabilitadas                         AS DescInstituicoesHabilitadas
,ProfissionalInstituicoes.InstituicoesDesabilitadas                       AS DescInstituicoesDesabilitadas

,TipoProfissional.codTipoTecnicoResponsavel                               AS CodTipoProfissional 
,TipoProfissional.descTipoTecnicoResponsavel                              AS DescTipoProfissional   

,Profissional.CodConselhoRegional                                         AS CodConselhoRegional
,Profissional.SiglaUfDocProfissional                                      AS SiglaUfDocProfissional

,Profissional.numInscricaoDocProfissional                                 AS NumInscricao 
,Profissional.dataEmissaoDocProfissional                                  AS DataEmissao
,Profissional.dataVencimentoDocProfissional                               AS DataVencimento
 
FROM CRF.TecnicoResponsavel Profissional

    JOIN CRF.TipoTecnicoResponsavel TipoProfissional 
        ON TipoProfissional.codTipoTecnicoResponsavel = Profissional.codTipoTecnicoResponsavel

    LEFT JOIN TABLE (
        SELECT 
          ProfissionalFuncao.IdTecnicoResponsavel 
        , LISTAGG(Funcao.descFuncaoTecnicoResponsavel, ', ')  AS Funcoes
        , LISTAGG(CASE WHEN Funcao.BolExigeHabilitacao = 1 and ProfissionalFuncao.BolHabilitado = 1 THEN Funcao.descFuncaoTecnicoResponsavel ELSE NULL END, ', ') AS FuncoesHabilitadas
        FROM CRF.TecnicoResponsavelFuncaoTecnicoResponsavel ProfissionalFuncao
            JOIN CRF.FuncaoTecnicoResponsavel Funcao 
                ON Funcao.codFuncaoTecnicoResponsavel = ProfissionalFuncao.codFuncaoTecnicoResponsavel 
        WHERE ProfissionalFuncao.IdTecnicoResponsavel = Profissional.IdTecnicoResponsavel
        AND ProfissionalFuncao.BolAtivo = 1
        GROUP BY ProfissionalFuncao.IdTecnicoResponsavel
    ) ProfissionalFuncoes 
        ON 1=1
        
    LEFT JOIN TABLE (
        SELECT 
          ProfissionalInstituicao.IdTecnicoResponsavel  
        , LISTAGG(CASE WHEN ProfissionalInstituicao.codSituacaoTecnicoResponsavel = 4 THEN ProfissionalInstituicao.idInstituicao ELSE NULL END, ', ') AS InstituicoesHabilitadas
        , LISTAGG(CASE WHEN ProfissionalInstituicao.codSituacaoTecnicoResponsavel = 5 THEN ProfissionalInstituicao.idInstituicao ELSE NULL END, ', ') AS InstituicoesDesabilitadas
        FROM CRF.TecnicoResponsavelInstituicao ProfissionalInstituicao
        WHERE ProfissionalInstituicao.IdTecnicoResponsavel = Profissional.IdTecnicoResponsavel
        GROUP BY ProfissionalInstituicao.IdTecnicoResponsavel
    ) ProfissionalInstituicoes 
        ON 1=1
;
-- COPY-DATABASE-OBJECT: "CRF"."VIW_PROFISSIONALINSTITUICAO"
CREATE OR REPLACE VIEW "CRF"."VIW_PROFISSIONALINSTITUICAO" AS
SELECT
 Profissional.IdTecnicoResponsavel           AS IdProfissional
,ProfissionalInstituicao.idInstituicao
,Profissional.idInstituicao                  AS IdInstituicaoPessoa
,Profissional.idPessoa                       AS IdPessoaFisica
,Profissional.idPessoaJuridica               AS IdPessoaJuridica
,Profissional.idUsuario
,Profissional.QtdTempoExperiencia

,Situacao.codSituacaoTecnicoResponsavel      AS CodSituacaoProfissional
,Situacao.descSituacaoTecnicoResponsavel     AS DescSituacaoProfissional


,TipoProfissional.codTipoTecnicoResponsavel  AS codTipoProfissional 
,TipoProfissional.descTipoTecnicoResponsavel AS descTipoProfissional

,ProfissionalFuncoes.funcoes                 AS DescFuncoes
,ProfissionalFuncoes.FuncoesHabilitadas      AS DescFuncoesHabilitadas
,ProfissionalUnidades.Unidades               AS DescUnidades

,Profissional.CodConselhoRegional
,Profissional.SiglaUfDocProfissional

,Profissional.numInscricaoDocProfissional    AS NumInscricao 
,Profissional.dataEmissaoDocProfissional     AS DataEmissao
,Profissional.dataVencimentoDocProfissional  AS DataVencimento

,CriterioPagamento.descCriterioPagamento
,ProfissionalInstituicao.numBanco
,ProfissionalInstituicao.numAgencia
,ProfissionalInstituicao.numConta


FROM  CRF.TecnicoResponsavel Profissional   

    JOIN CRF.TipoTecnicoResponsavel TipoProfissional 
        ON TipoProfissional.codTipoTecnicoResponsavel = Profissional.codTipoTecnicoResponsavel  

    JOIN CRF.TecnicoResponsavelInstituicao ProfissionalInstituicao 
        ON  ProfissionalInstituicao.idTecnicoResponsavel = Profissional.idTecnicoResponsavel 
        
    JOIN CRF.SituacaoTecnicoResponsavel Situacao 
        ON Situacao.codSituacaoTecnicoResponsavel = ProfissionalInstituicao.codSituacaoTecnicoResponsavel 
       
    LEFT JOIN CRF.CriterioPagamento CriterioPagamento 
        ON CriterioPagamento.codCriterioPagamento = ProfissionalInstituicao.codCriterioPagamento
   
    LEFT JOIN TABLE (
        SELECT 
          ProfissionalFuncao.IdTecnicoResponsavel 
        , LISTAGG(Funcao.descFuncaoTecnicoResponsavel, ', ')  AS Funcoes
        , LISTAGG(CASE WHEN Funcao.BolExigeHabilitacao = 1 and ProfissionalFuncao.BolHabilitado = 1 THEN Funcao.descFuncaoTecnicoResponsavel ELSE NULL END, ', ') AS FuncoesHabilitadas
        FROM CRF.TecnicoResponsavelFuncaoTecnicoResponsavel ProfissionalFuncao
            JOIN CRF.FuncaoTecnicoResponsavel Funcao 
                ON Funcao.codFuncaoTecnicoResponsavel = ProfissionalFuncao.codFuncaoTecnicoResponsavel 
        WHERE ProfissionalFuncao.IdTecnicoResponsavel = Profissional.IdTecnicoResponsavel
        AND ProfissionalFuncao.BolAtivo = 1
        GROUP BY ProfissionalFuncao.IdTecnicoResponsavel
    ) ProfissionalFuncoes 
        ON 1=1

    LEFT JOIN TABLE (
        SELECT 
          ProfissionalUnidade.IdTecnicoResponsavel 
        , LISTAGG(ProfissionalUnidade.IdUnidadeInst, ', ') AS Unidades
        FROM CRF.TecnicoResponsavelUnidadeAtuacao ProfissionalUnidade
        WHERE ProfissionalUnidade.IdTecnicoResponsavel = ProfissionalInstituicao.IdTecnicoResponsavel
        AND ProfissionalUnidade.idInstituicao = ProfissionalInstituicao.idInstituicao
        GROUP BY ProfissionalUnidade.IdTecnicoResponsavel
    ) ProfissionalUnidades
        ON 1=1
;
-- COPY-DATABASE-OBJECT: "CRF"."VIW_RESPOSTAFISCALIZACAO"
CREATE OR REPLACE VIEW "CRF"."VIW_RESPOSTAFISCALIZACAO" AS
SELECT
  RESPOSTA.IDFISCALIZACAO
, CAMPO.IDCAMPOASSUNTOVERSAO
, CAMPO.NOMECAMPOASSUNTO
, CAMPO.DESCTAGXML AS DESCTAGCAMPO
, CAMPO.NUMORDEM AS NUMORDEMCAMPO
, RESPOSTA.NUMLINHA
, RESPOSTA.DESCRESPOSTA AS RESPOSTA
FROM CRF.RESPOSTAFISCALIZACAO RESPOSTA
    JOIN CRF.CAMPOASSUNTOVERSAO CAMPO ON CAMPO.IDCAMPOASSUNTOVERSAO = RESPOSTA.IDCAMPOASSUNTOVERSAO
;
-- COPY-DATABASE-OBJECT: "CRF"."VIW_RESPOSTAFISCALIZACAOITEM"
CREATE OR REPLACE VIEW "CRF"."VIW_RESPOSTAFISCALIZACAOITEM" AS
SELECT
  RESPOSTA.IDFISCALIZACAO
, CAMPO.IDCAMPOASSUNTOVERSAO
, CAMPO.NOMECAMPOASSUNTO
, CAMPO.DESCTAGXML AS DESCTAGCAMPO
, CAMPO.NUMORDEM AS NUMORDEMCAMPO
, ITEM.NUMITEM
, ITEM.DESCITEM
, ITEM.DESCTAGXML AS DESCTAGITEM
, ITEM.BOLEXIGETEXTOCOMPLEMENTAR

, RESPOSTA.NUMLINHA

, RESPOSTA.DESCRESPOSTA AS RESPOSTACAMPO
, RESPOSTAITEM.DESCRESPOSTA AS RESPOSTAITEM

FROM CRF.RESPOSTAFISCALIZACAO RESPOSTA

    JOIN CRF.RESPOSTAFISCALIZACAOITEM RESPOSTAITEM
        ON  RESPOSTAITEM.IDFISCALIZACAO       = RESPOSTA.IDFISCALIZACAO
        AND RESPOSTAITEM.IDCAMPOASSUNTOVERSAO = RESPOSTA.IDCAMPOASSUNTOVERSAO
        AND RESPOSTAITEM.NUMLINHA             = RESPOSTA.NUMLINHA

    JOIN CRF.CAMPOASSUNTOVERSAO CAMPO ON CAMPO.IDCAMPOASSUNTOVERSAO = RESPOSTA.IDCAMPOASSUNTOVERSAO 
    
    JOIN CRF.CAMPOASSUNTOITEMVERSAO ITEM 
        ON  ITEM.IDCAMPOASSUNTOVERSAO = RESPOSTAITEM.IDCAMPOASSUNTOVERSAO
        AND ITEM.NUMITEM              = RESPOSTAITEM.NUMITEM
;
-- COPY-DATABASE-OBJECT: "CRL"."VIW_RISCOTOMADOR"
CREATE OR REPLACE VIEW "CRL"."VIW_RISCOTOMADOR" ( IDPESSOA, IDINSTITUICAO, VALORCORTE, RISCOBACEN, VALORPD, IDSITUACAOLIMITE, BOLATIVO, DATAVIGENCIA, DESCORIGEM, DESCSITUACAOLIMITE, RISCOCRL, DESCRISCOLEGADO, DATAAPROVACAO ) AS SELECT T.IDPESSOA, T.IDINSTITUICAO, R.VALORCORTE, R.DESCRISCOBACEN AS RISCOBACEN, R.VALORPD, R.IDSITUACAOLIMITE, COALESCE(R.BOLATIVO, 1) AS BOLATIVO, R.DATAVIGENCIA, R.DESCORIGEM, S.DESCSITUACAOLIMITE, R.DESCRISCOCRL, RM.DESCRISCOLEGADO, R.DATAAPROVACAO FROM (SELECT DISTINCT T1.IDPESSOA, T1.IDINSTITUICAO FROM CRL.TOMADOR T1 ) T LEFT JOIN CRL.RISCOLIMITECONSOLIDADO R ON R.IDPESSOA = T.IDPESSOA AND R.IDINSTITUICAO = T.IDINSTITUICAO LEFT JOIN CRL.RISCOMIGRADO RM ON RM.IDPESSOA = T.IDPESSOA AND RM.IDINSTITUICAO = T.IDINSTITUICAO LEFT JOIN CRL.SITUACAOLIMITE S ON R.IDSITUACAOLIMITE = S.IDSITUACAOLIMITE WHERE R.DESCRISCOCRL IS NOT NULL OR  RM.DESCRISCOLEGADO IS NOT NULL
;
-- COPY-DATABASE-OBJECT: "CRS"."VIW_ATUALIZACAOSICORCONDUCAO"
CREATE OR REPLACE VIEW "CRS"."VIW_ATUALIZACAOSICORCONDUCAO" as (
SELECT hocc.IdInstituicao
       , hocc.NUMCHAVEOPERACAO
       , hocc.NumRefBacen
       , hocc.IdEmpreendRuralLegado
       , MAX(DECODE(hocc.CodCampoOpCruConducao, 1, hocc.DescValorAtu)) AS DataInicioColheita
       , MAX(DECODE(hocc.CodCampoOpCruConducao, 2, hocc.DescValorAtu)) AS DataFimColheita
       , MAX(DECODE(hocc.CodCampoOpCruConducao, 3, hocc.DescValorAtu)) AS DataInicioSemeadura
       , MAX(DECODE(hocc.CodCampoOpCruConducao, 4, hocc.DescValorAtu)) AS DataFimSemeadura
       , MAX(DECODE(hocc.CodCampoOpCruConducao, 5, hocc.DescValorAtu)) AS ValorProdutividade
       , MAX(DECODE(hocc.CodCampoOpCruConducao, 8, hocc.DescValorAtu)) AS DescCar
       , MAX(DECODE(hocc.CodCampoOpCruConducao, 9, hocc.DescValorAtu)) AS DescGlebas
       , MAX(DECODE(hocc.CodCampoOpCruConducao,19, hocc.DescValorAtu)) AS ValorAreaExplorada
       , hocc.IDIMOVEL
  FROM CRE.HistOpCruConducao hocc
  JOIN CRE.ControleMensagem cm 
    ON cm.NumControleIf = hocc.NumControleIf  
 WHERE substring(cm.CodMensagemRetorno,8,1) = 'R' 
   AND hocc.CodCampoOpCruConducao IN(1, 2, 3, 4, 5, 8, 9, 19)  
 GROUP BY hocc.IdInstituicao, hocc.NUMCHAVEOPERACAO, hocc.NumRefBacen, hocc.IdEmpreendRuralLegado, hocc.IDIMOVEL
)
;
-- COPY-DATABASE-OBJECT: "CTF"."VIW_ERROPORTABILIDADE"
CREATE OR REPLACE VIEW "CTF"."VIW_ERROPORTABILIDADE" (IDSOLICITACAOPORTABILIDADE,
                                       IDHISTORICOERROPORTABILIDADE,
                                       IDTIPOHISTORICOPORTABILIDADE,
                                       DESCTIPOHISTORICOPORTABILIDADE,
                                       DESCERRO) AS
       ( SELECT                       sol.IDSOLICITACAOPORTABILIDADE
                                   , hep.IDHISTORICOERROPORTABILIDADE
                                   , tipo.IDTIPOHISTORICOPORTABILIDADE         
                                   , tipo.DESCTIPOHISTORICOPORTABILIDADE
                                   , ec.DESCERROCIPPORTABILIDADE  AS "DESCERRO"
                                
                             FROM ctf.ERROCIPPORTABILIDADE ec
                                    JOIN ctf.HISTORICOERROPORTABILIDADE hep
                                         ON hep.CODERROCIPPORTABILIDADE = ec.CODERROCIPPORTABILIDADE
                                    JOIN ctf.HISTORICOSOLICITACAOPORTABILIDADE hsol
                                         ON hsol.IDHISTORICOSOLICITACAOPORTABILIDADE = hep.IDHISTORICOSOLICITACAOPORTABILIDADE
                                    JOIN ctf.TIPOHISTORICOPORTABILIDADE tipo
                                         ON tipo.IDTIPOHISTORICOPORTABILIDADE = hsol.IDTIPOHISTORICOPORTABILIDADE
                                     JOIN ctf.SOLICITACAOPORTABILIDADE sol
                                         ON sol.IDSOLICITACAOPORTABILIDADE = hsol.IDSOLICITACAOPORTABILIDADE
                                        WHERE tipo.IDVALORDOMINIO = 1
                                    AND tipo.IDTIPOHISTORICOPORTABILIDADE IN (29,31,38)
                                    )
;
-- COPY-DATABASE-OBJECT: "CTF"."VIW_PROPOSTAPORTABILIDADE"
-- Create Views 

CREATE OR REPLACE VIEW "CTF"."VIW_PROPOSTAPORTABILIDADE" (CONTRATO, DESCTIPOCONTRATO, IDTIPOCONTRATO,IDOPERACAOCREDITO, NUMPROPOSTASOLICITACAONPC, IDPROPOSTAPORTABILIDADE, SALDODEVEDORPROPOSTA, QUANTIDADETOTALPARCELASPROPOSTA, VALORPARCELAPROPOSTA, IDINSTITUICAO, ISPBIFPROPONENTE, PERCJUROSNOMINAL, IDSOLICITACAOPORTABILIDADE, NUMPORTABILIDADECTC, IDTIPOHISTORICOPORTABILIDADE, SITUACAOPORTABILIDADE, CONTRATOORIGINAL, ISPBCREDORAORIGINAL, SIGLACOPERATIVA, NUMCONTRATOORIGINALPROPOSTA, NUMCONTRATOAPROVACAO, SALDODEVEDORAPROVACAO, QUANTIDADEPARCELAAVENCER, QUANTIDADETOTALPARCELARESPOSTA, QUANTIDADEPARCELAVENCIDA, VALORPARCELACONTRATORESPOSTA, TAXACETPROPOSTA, 
JUROSEFETIVOPROPOSTA, DATAREFERENCIASALDODEVEDOR, BOLTROCAMODALIDADE, TAXACETAPROVACAO, JUROSEFETIVOAPROVACAO, JUROSNOMINALAPROVACAO, RETENCAO, CANCELAMENTO, DECURSOPRAZO,
 VALORPRIMEIRAPARCELAIRREGULAR) AS 
SELECT 
    DISTINCT 'Consignado' , 
    tpc.DESCTIPOCONTRATO , 
    tpc.IDTIPOCONTRATO , 
    soln.IDOPERACAOCREDITO,
    soln.NUMPROPOSTASOLICITACAONPC , 
    pro.IDPROPOSTAPORTABILIDADE , 
    pro.VALORSALDODEVEDORCONTABIL "SALDODEVEDORPROPOSTA" , 
    mc.QTDTOTALPARCELA "QUANTIDADETOTALPARCELASPROPOSTA" , 
    mc.VALORFACEPARCELACONTRATO "VALORPARCELAPROPOSTA" , 
    sol.IDINSTITUICAO , 
    sol.NUMCNPJIFPROPONENTE "ISPBIFPROPONENTE" , 
    pro.PERCJUROSNOMINAL , 
    pro.IDSOLICITACAOPORTABILIDADE , 
    sol.NUMPORTABILIDADECTC , 
    sol.IDTIPOHISTORICOPORTABILIDADE , 
    thp.DESCTIPOHISTORICOPORTABILIDADE "SITUACAOPORTABILIDADE" , 
    tpm.DESCTIPOMODALIDADEPORTABILIDADE "CONTRATOORIGINAL" , 
    sol.NUMISPBIFCREDORAORIGINAL "ISPBCREDORAORIGINAL" , 
    (   SELECT
            SCI.DESCSIGLACOOP AS "SIGLACOPERATIVA"
        FROM 
            ctf.INSTITUICAOCTC instituicaoCtc
        LEFT JOIN 
            sci.VIW_INSTITUICAO sci
        ON 
            sci.IDINSTITUICAO = instituicaoCtc.IDINSTITUICAO
        AND sci.IDUNIDADEINST = 0
        WHERE 
            SUBSTRING (sci.NUMCNPJ,0,9) = sol.NUMISPBIFCREDORAORIGINAL) , 
    pro.NUMCONTRATOORIGINAL "NUMCONTRATOORIGINALPROPOSTA" , 
    rp.NUMCONTRATOORIGEM "NUMCONTRATOAPROVACAO" , 
    rp.VALORSALDODEVEDORCONTABIL "SALDODEVEDORAPROVACAO " , 
    mccr.QTDTOTALPARCELAVENCER "QUANTIDADEPARCELAAVENCER" , 
    mccr.QTDTOTALPARCELA "QUANTIDADETOTALPARCELARESPOSTA" , 
    mccr.QTDTOTALPARCELAVENCIDA "QUANTIDADEPARCELAVENCIDA" , 
    mccr.VALORFACEPARCELACONTRATO "VALORPARCELACONTRATORESPOSTA" , 
    pro.PERCCET "TAXACETPROPOSTA" , 
    pro.PERCJUROSEFETIVO "JUROSEFETIVOPROPOSTA" , 
    pro.DATAREFERENCIASALDODEVEDOR , 
    pro.BOLTROCAMODALIDADE , 
    rp.PERCCET "TAXACETAPROVACAO" , 
    rp.PERCJUROSEFETIVO "JUROSEFETIVOAPROVACAO" , 
    rp.PERCJUROSNOMINAL "JUROSNOMINALAPROVACAO" , 
    (   SELECT 
            vdd.DESCVALORDOMINIO AS "RETENCAO"
        FROM 
            ctf.SOLICITACAOPORTABILIDADE soll
        INNER JOIN 
            ctf.VALORDOMINIOSOLICITACAOPORTABILIDADE vhh
        ON 
            vhh.IDSOLICITACAOPORTABILIDADE = soll.IDSOLICITACAOPORTABILIDADE
        INNER JOIN 
            ctf.VALORDOMINIO vdd
        ON 
            vdd.IDVALORDOMINIO = vhh.IDVALORDOMINIO
        WHERE 
            vhh.IDDOMINIOCIP = 14
        AND SOLL.IDSOLICITACAOPORTABILIDADE = SOL.IDSOLICITACAOPORTABILIDADE) , 
    (   SELECT 
            vdd.DESCVALORDOMINIO AS "CANCELAMENTO"
        FROM 
            ctf.SOLICITACAOPORTABILIDADE soll
        INNER JOIN 
            ctf.VALORDOMINIOSOLICITACAOPORTABILIDADE vhh
        ON 
            vhh.IDSOLICITACAOPORTABILIDADE = soll.IDSOLICITACAOPORTABILIDADE
        INNER JOIN 
            ctf.VALORDOMINIO vdd
        ON 
            vdd.IDVALORDOMINIO = vhh.IDVALORDOMINIO
        WHERE 
            vhh.IDDOMINIOCIP =11
        AND SOLL.IDSOLICITACAOPORTABILIDADE = SOL.IDSOLICITACAOPORTABILIDADE) , 
    (   SELECT 
            vdd.DESCVALORDOMINIO AS "DECURSOPRAZO"
        FROM 
            ctf.SOLICITACAOPORTABILIDADE soll
        INNER JOIN 
            ctf.VALORDOMINIOSOLICITACAOPORTABILIDADE vhh
        ON 
            vhh.IDSOLICITACAOPORTABILIDADE = soll.IDSOLICITACAOPORTABILIDADE
        INNER JOIN 
            ctf.VALORDOMINIO vdd
        ON 
            vdd.IDVALORDOMINIO = vhh.IDVALORDOMINIO
        WHERE 
            vhh.IDDOMINIOCIP =12
        AND SOLL.IDSOLICITACAOPORTABILIDADE = SOL.IDSOLICITACAOPORTABILIDADE) , 
    (   SELECT 
            pip.VALORPARCELAIRREGULAR AS "VALORPRIMEIRAPARCELAIRREGULAR" 
        FROM 
            CTF.PARCELAIRREGULARPROPOSTAPORTABILIDADE pip
        WHERE 
            pip.IDPARCELAIRREGULAR = 
            (   SELECT 
                    MIN (p.idparcelairregular)
                FROM 
                    ctf.PARCELAIRREGULARPROPOSTAPORTABILIDADE p
                INNER JOIN 
                    ctf.PROPOSTAPORTABILIDADE ppro
                ON 
                    ppro.IDPROPOSTAPORTABILIDADE = p.IDPROPOSTAPORTABILIDADE
                WHERE 
                    ppro.IDPROPOSTAPORTABILIDADE = pro.IDPROPOSTAPORTABILIDADE))
FROM 
    ctf.PROPOSTAPORTABILIDADE pro
LEFT JOIN 
    ctf.SOLICITACAOPORTABILIDADE sol
ON 
    pro.IDSOLICITACAOPORTABILIDADE = sol.IDSOLICITACAOPORTABILIDADE
INNER JOIN 
    ctf.MODALIDADECREDITOCONSIGNADOPROPOSTA mc
ON 
    mc.IDPROPOSTAPORTABILIDADE = pro.IDPROPOSTAPORTABILIDADE
INNER JOIN 
    ctf.TIPOMODALIDADEPORTABILIDADE tpm
ON 
    tpm.IDTIPOMODALIDADEPORTABILIDADE = pro.IDTIPOMODALIDADEPORTABILIDADE
INNER JOIN 
    ctf.TIPOCONTRATO tpc
ON 
    tpc.IDTIPOCONTRATO = tpm.IDTIPOCONTRATO
INNER JOIN 
    ctf.TIPOHISTORICOPORTABILIDADE thp
ON 
    thp.IDTIPOHISTORICOPORTABILIDADE = sol.IDTIPOHISTORICOPORTABILIDADE
LEFT JOIN 
    ctf.RESPOSTAPORTABILIDADE rp
ON 
    rp.IDSOLICITACAOPORTABILIDADE = sol.IDSOLICITACAOPORTABILIDADE
LEFT JOIN 
    ctf.MODALIDADECREDITOCONSIGNADORESPOSTA mccr
ON 
    mccr.IDRESPOSTAPORTABILIDADE = rp.IDRESPOSTAPORTABILIDADE
LEFT JOIN 
    ctf.SOLICITACAOPORTABILIDADENPC soln
ON 
    soln.IDSOLICITACAOPORTABILIDADE = sol.IDSOLICITACAOPORTABILIDADE

UNION ALL

