SELECT CAST(   RPAD(id,        MAX(LENGTH(id))        OVER(), ' ')
            || ' | ' 
            || RPAD(operation, MAX(LENGTH(operation)) OVER(), ' ')
            || ' | ' 
            || LPAD(rows,      MAX(LENGTH(rows))      OVER(), ' ')
            || ' | ' 
            || CASE WHEN COUNT(ActualRows) OVER () > 1
                    THEN LPAD(ActualRows, MAX(LENGTH(ActualRows)) OVER(), ' ') || ' | ' 
                    ELSE ''
               END
            || LPAD(cost,      MAX(LENGTH(cost))      OVER(), ' ')  || ' | ' 
            || LPAD(pcost,     MAX(LENGTH(pcost))     OVER(), ' ')
         AS VARCHAR(100)) EXPLAINPLAN
     , path
  FROM (
SELECT 'ID' ID
     , 'Operation'  Operation
     , 'Rows'       Rows
     , 'ActualRows' ActualRows
     , 'Cost'       Cost
     , 'PCost'      PCost     
     , '0'          Path
FROM SYSIBM.SYSDUMMY1
UNION
SELECT CAST(tree.operator_id as VARCHAR(254)) ID
     , CAST(LPAD(' ', tree.level, ' ')
       || CASE WHEN tree.cycle = 1
               THEN '(cycle) '
               ELSE ''
          END     
       || COALESCE (
             TRIM(O.Operator_Type)
          || COALESCE(' (' || argument || ')', '') 
          || ' '
          || COALESCE(S.Object_Name,'')
          , ''
          )
       AS VARCHAR(254)) AS OPERATION
     , COALESCE(CAST(rows AS VARCHAR(254)), '')                         Rows
     , CAST(ActualRows as VARCHAR(254))                                 ActualRows
     , COALESCE(CAST(CAST(O.Total_Cost AS BIGINT) AS VARCHAR(254)), '') Cost
     , CAST(1000 as VARCHAR(254)) pcost
--     , CASE WHEN O.Operator_Type <> 'RETURN' THEN COALESCE(CAST(CAST(O.Total_Cost*100/sum(case when O.Operator_Type <> 'RETURN' then O.Total_Cost else 0 end) over (partition by o.explain_time) AS BIGINT) AS VARCHAR(254)), '') ELSE ' ' END pCost
     , path
  FROM tree
  LEFT JOIN ( SELECT i.source_id
              , i.target_id
              , CAST(CAST(ROUND(o.stream_count) AS INTEGER) AS VARCHAR(12))
                || ' of '
                || CAST (total_rows AS VARCHAR(12))
                || CASE WHEN total_rows > 0
                         AND ROUND(o.stream_count) <= total_rows THEN
                   ' ('
                   || LPAD(CAST (ROUND(ROUND(o.stream_count)/total_rows*100,2)
                          AS NUMERIC(5,2)), 6, ' ')
                   || '%)'
                   ELSE ''
                   END rows
              , CASE WHEN act.actual_value is not null then
                CAST(CAST(ROUND(act.actual_value) AS INTEGER) AS VARCHAR(12))
                || ' of '
                || CAST (total_rows AS VARCHAR(12))
                || CASE WHEN total_rows > 0 THEN
                   ' ('
                   || LPAD(CAST (ROUND(ROUND(act.actual_value)/total_rows*100,2)
                          AS NUMERIC(5,2)), 6, ' ')
                   || '%)'
                   ELSE NULL
                   END END ActualRows
              , i.object_name
              , i.explain_time
         FROM (SELECT MAX(source_id) source_id
                    , target_id
                    , MIN(CAST(ROUND(stream_count,0) AS BIGINT)) total_rows
                    , CAST(LISTAGG(object_name) AS VARCHAR(50)) object_name
                    , explain_time
                 FROM EXPLAIN_STREAM
                WHERE explain_time = (SELECT MAX(explain_time)
                                      FROM EXPLAIN_OPERATOR
                                     )
                GROUP BY target_id, explain_time
              ) I
         LEFT JOIN EXPLAIN_STREAM O
           ON (    I.target_id=o.source_id
               AND I.explain_time = o.explain_time
              )
         LEFT JOIN EXPLAIN_ACTUALS act
           ON (    act.operator_id  = i.target_id
               AND act.explain_time = i.explain_time
               AND act.ACTUAL_TYPE  like 'CARDINALITY%'
              )
       ) s
    ON (    s.target_id    = tree.operator_id
        AND s.explain_time = tree.explain_time
       )
  LEFT JOIN EXPLAIN_OPERATOR O
    ON (    o.operator_id  = tree.operator_id
        AND o.explain_time = tree.explain_time
       ) 
  LEFT JOIN (SELECT LISTAGG (CASE argument_type
                             WHEN 'UNIQUE' THEN
                                  CASE WHEN argument_value = 'TRUE'
                                       THEN 'UNIQUE'
                                  ELSE NULL
                                  END
                             WHEN 'TRUNCSRT' THEN
                                  CASE WHEN argument_value = 'TRUE'
                                       THEN 'TOP-N'
                                  ELSE NULL
                                  END   
                             WHEN 'SCANDIR' THEN
                                  CASE WHEN argument_value != 'FORWARD'
                                       THEN argument_value
                                  ELSE NULL
                                  END                     
                             ELSE argument_value     
                             END
                           , ' ') argument
                  , operator_id
                  , explain_time
               FROM EXPLAIN_ARGUMENT EA
              WHERE argument_type IN ('AGGMODE'
                                     ,'UNIQUE', 'TRUNCSRT'
                                     ,'SCANDIR' 
                                     ,'OUTERJN' 
                                     ,'OPT_PROF')
              GROUP BY explain_time, operator_id
            ) A
    ON (    a.operator_id  = tree.operator_id
        AND a.explain_time = tree.explain_time
       )
     ) O
UNION ALL
SELECT '', 'A' FROM SYSIBM.SYSDUMMY1
UNION ALL
SELECT '', 'Y' FROM SYSIBM.SYSDUMMY1
UNION ALL
SELECT '', 'Q' FROM SYSIBM.SYSDUMMY1
UNION ALL
SELECT 'Partition information','R' FROM SYSIBM.SYSDUMMY1
UNION ALL
SELECT 
                    CASE argument_type
                             WHEN 'DPESTFLG' THEN
                                '   DPNUMPRT value is based on an estimate? '||argument_value
                             WHEN 'DPLSTPRT' THEN
                                '   Accessed data partitions: '||argument_value
                             WHEN 'DPNUMPRT' THEN
                                '   Actual or estimated number of data partitions accessed: '||argument_value                                
                             ELSE argument_value
                             END
                           argument,'S'
              FROM (SELECT DISTINCT EXPLAIN_TIME FROM tree) a inner join EXPLAIN_ARGUMENT b on a.explain_time = b.explain_time
              WHERE argument_type IN ('DPESTFLG'
                                     ,'DPLSTPRT'
                                     ,'DPNUMPRT')
UNION ALL
SELECT 'Predicate Information', 'AA' FROM SYSIBM.SYSDUMMY1
UNION ALL
SELECT CAST (LPAD(CASE WHEN operator_id = LAG  (operator_id) OVER (PARTITION BY operator_id ORDER BY pred_order)
                       THEN ''
                       ELSE operator_id || ' - '
                  END
                , MAX(LENGTH(operator_id )+4) OVER()
                , ' ')
             || how_applied
             || ' ' 
             || predicate_text
             || CASE WHEN how_applied like '%DPSTART%' or how_applied like '%DPSTOP%' THEN 'Partição: '||TO_CHAR(RANGE_NUM) ELSE '' END
          AS VARCHAR(200)) PredicateInformation
     , 'P' || LPAD(id_order, 5, '0') || pred_order path
  FROM (SELECT CAST(operator_id AS VARCHAR(254)) operator_id
             , LPAD(trim(how_applied)
                  ,  MAX (LENGTH(TRIM(how_applied)))
                    OVER (PARTITION BY operator_id)
                  , ' '
               ) how_applied
             , CAST(substr(predicate_text, 1, 80) AS VARCHAR(80)) predicate_text
             , CASE how_applied WHEN 'START' THEN '1'
                                WHEN 'STOP'  THEN '2'
                                WHEN 'SARG'  THEN '3'
                                ELSE '9'
               END pred_order
             , operator_id id_order
             , RANGE_NUM
          FROM explain_predicate p
         WHERE explain_time = (SELECT MAX(explain_time)
                               FROM EXPLAIN_OPERATOR)
       )
)
ORDER BY path)
;
-- COPY-DATABASE-OBJECT: "DCL"."VIW_DESCLASSIFICACAO"
CREATE OR REPLACE VIEW "DCL"."VIW_DESCLASSIFICACAO" 
        (IDDESCLASSIFICACAOOPERACAO, FLUXO, IDINSTITUICAO, IDPESSOA, NUMCONTRATOCREDITO, NUMREFBACEN, 
        IDCONTRATOCREDITO, IDOPERACAOCREDITO, VALORTOTALDESCLASSIFICACAO, SITUACAO, DATADESCLASSIFICACAO, DATACADASTRODESCLASSIFICACAO, 
        DATAPREVISAOCONCLUSAO, DATACONCLUSAOPROCESSO, TIPODESCLASSIFICACAO, DESCORIGEMDESCLASSIFICACAO, CODMOTIVODESCLASSIFICACAO, 
        DESCMOTIVODESCLASSIFICACAO, DESCMOTIVODESCLASSIFICACAOOUTRO )
AS
SELECT
          Desclassificacao.idDesclassificacaoOperacao
        , Fluxo.DESCFLUXOirregularidade AS fluxo
        , Desclassificacao.idInstituicao
        , Desclassificacao.idPessoa
        , Desclassificacao.numContratoCredito
        , Desclassificacao.numRefBacen
        , Desclassificacao.idContratoCredito
        , Desclassificacao.idOperacaoCredito
        , Desclassificacao.valorTotalDesclassificacao
        , Situacao.DESCSITUACAOFLUXO AS situacao
        , Desclassificacao.dataDesclassificacao -- data do ofício que desclassificou a operação 
        , Desclassificacao.dataCadastroDesclassificacao -- data que a desclassificação teve seu processo iniciado no sistema
        , Desclassificacao.dataPrevisaoConclusao -- data limite para conclusão do processo de desclassificacao 
        , Desclassificacao.dataConclusaoProcesso -- data que o processo de desclassificacao foi concluido
        , DECODE(Desclassificacao.codTipoDesclassificacao, 1,'total', 'parcial') AS tipoDesclassificacao
        , Origem.descOrigemIrregularidade AS DESCORIGEMDESCLASSIFICACAO
        , Motivo.codMotivoirregularidade AS CODMOTIVODESCLASSIFICACAO
        , Motivo.descMotivoirregularidade AS DESCMOTIVODESCLASSIFICACAO
        , Desclassificacao.descMotivoIrregularidadeOutro AS DESCMOTIVODESCLASSIFICACAOOUTRO
     FROM DCL.DesclassificacaoOperacao Desclassificacao
LEFT JOIN DCL.MOTIVOIRREGULARIDADE Motivo 
        ON Motivo.codMotivoIrregularidade = Desclassificacao.codMotivoIrregularidade
LEFT JOIN DCL.ORIGEMIRREGULARIDADE origem 
        ON origem.codOrigemIrregularidade = Desclassificacao.codOrigemIrregularidade
     JOIN DCL.SITUACAOFLUXO situacao
        ON situacao.CODSITUACAOFLUXO = desclassificacao.CODSITUACAOFLUXOATUAL
     JOIN DCL.FLUXOIRREGULARIDADE fluxo
        ON fluxo.CODFLUXOirregularidade = situacao.CODFLUXOirregularidade
    WHERE Desclassificacao.bolativo = 1
;
-- COPY-DATABASE-OBJECT: "FCO"."VIW_FCRURALOPERACOESLIBERADAS"
CREATE OR REPLACE VIEW "FCO"."VIW_FCRURALOPERACOESLIBERADAS" AS 
SELECT
        OP.IDOPERACAOCREDITO,
        OPFC.IDOPERACAOCREDITOFC,
        OP.IDPESSOA,
        PE.NOMEPESSOA,
        OP.NUMCONTRATOCREDITO,
        OP.DATAOPERACAOCREDITO,
        OP.DATAVENCIMENTOOPERACAO,
        OPC.DATAHORAULTIMALIBERACAO,
        OP.VALORCONTRATADO,
        OP.IDINSTITUICAOLOCALNEGOCIO,
        OP.IDUNIDADEINSTLOCALNEGOCIO,
        SICOR.NUMREFBACEN,
        SICOR.DATAHORAGERACAONUMREFBACEN,
        VERI.IDEMPREENDIMENTORURAL,
        VERI.IDEMPREENDIMENTOBACEN,
        VERI.IDMUNICIPIO,
        VERI.NUMREGCARIMOVEL
FROM
        CRE.OPERACAOCREDITO OP
        INNER JOIN CRE.OPERACAOCREDITOCOMPLEMENTO OPC
                ON OP.IDOPERACAOCREDITO = OPC.IDOPERACAOCREDITO
        INNER JOIN FCO.OPERACAOCREDITOFC OPFC
                ON OP.IDOPERACAOCREDITO = OPFC.IDOPERACAOCREDITO
        INNER JOIN CLI.VIW_PESSOA PE
        ON OP.IDPESSOA = PE.IDPESSOA
        AND PE.IDINSTITUICAO = OP.IDINSTITUICAOOPERACAO
    INNER JOIN FCO.EMPREENDIMENTOOPERACAOCREDITOFC EOCFC
        ON EOCFC.IDOPERACAOCREDITOFC =  OPFC.IDOPERACAOCREDITOFC
        INNER JOIN CRE.VIW_EMPREENDIMENTORURALINTEGRACAO VERI
                ON EOCFC.CODEMPREENDIMENTO = VERI.IDEMPREENDIMENTORURALINTEGRACAO
        INNER JOIN CRE.INTEGRACAOSICOROPERACAOCREDITO SICOR
                ON SICOR.IDOPERACAOCREDITO = OP.IDOPERACAOCREDITO
WHERE
        OP.IDPRODUTO = 13
    AND OPC.DATAHORAULTIMALIBERACAO IS NOT NULL
;
-- COPY-DATABASE-OBJECT: "GAR"."VIW_GARANTIA"
CREATE OR REPLACE VIEW "GAR"."VIW_GARANTIA" AS
	SELECT 	g.IDGARANTIA,
		g.VALORGARANTIA,
		g.DATACADASTRO,
		g.BOLATIVO,
		g.IDOPERACAOCREDITO, 
		CASE WHEN g2.CODTIPOGARANTIABACEN = 1 THEN 'Cessão de direitos creditórios'
 			 WHEN g2.CODTIPOGARANTIABACEN = 2 THEN 'Caução'
		     WHEN g2.CODTIPOGARANTIABACEN = 3 THEN 'Penhor'
 		     WHEN g2.CODTIPOGARANTIABACEN = 4 THEN 'Alienação Fiduciária'
			 WHEN g2.CODTIPOGARANTIABACEN = 5 THEN 'Hipoteca'
 			 WHEN g2.CODTIPOGARANTIABACEN = 6 THEN 'Operações garantidas pelo governo'
 			 WHEN g2.CODTIPOGARANTIABACEN = 7 THEN 'Outras garantias não fidejussórias'
 			 WHEN g2.CODTIPOGARANTIABACEN = 8 THEN 'Seguros e assemelhados'
 			 WHEN g2.CODTIPOGARANTIABACEN = 9 THEN 'Garantia fidejussória'
 			 WHEN g2.CODTIPOGARANTIABACEN = 10 THEN 'Bens arrendados'
 	   	     WHEN g2.CODTIPOGARANTIABACEN = 11 THEN 'Garantias internacionais'
 		     WHEN g2.CODTIPOGARANTIABACEN = 12 THEN 'Operações garantidas por outras entidades'
 			 WHEN g2.CODTIPOGARANTIABACEN = 13 THEN 'Acordos de Compensação'
 			 ELSE 'Não Identificado' 
 		END AS DescTipoGarantiaBACEN,
		e.DESCENQUADRAMENTOGARANTIA 		         			 
FROM GAR.GARANTIA g 
JOIN GAR.ENQUADRAMENTOGARANTIA e ON e.IDENQUADRAMENTOGARANTIA = g.IDENQUADRAMENTOGARANTIA 
JOIN GAR.GRUPOGARANTIA g2 ON g2.IDGRUPOGARANTIA = e.IDGRUPOGARANTIA
;
