-- COPY-DATABASE-OBJECT: "GAR"."VIW_GARANTIALIMITECHEQUEESPECIAL"
CREATE OR REPLACE VIEW "GAR"."VIW_GARANTIALIMITECHEQUEESPECIAL" AS
SELECT 	G.IDGARANTIA,
		G.IDINSTITUICAO,
		GR.CODTIPOGARANTIABACEN, 
		GR.CODTIPOENQUADRAMENTOBACEN,
		G.DESCGARANTIA, 
		G.VALORGARANTIA, 
		G.PERCCOBERTURA,
		G.DATACADASTRO, 
		PESSOA_GARANTIDOR.IDPESSOA AS GARANTIDOR_IDPESSOA,
		PESSOA_GARANTIDOR.IDPESSOALEGADO AS GARANTIDOR_IDPESSOALEGADO,
		GARANTIDOR.CODRESPONSABILIDADE AS GARANTIDOR_CODRESPONSABILIDADE,
		PESSOA_TERCEIRO.IDPESSOA AS TERCEIRO_IDPESSOA,
		PESSOA_TERCEIRO.IDPESSOALEGADO AS TERCEIRO_IDPESSOALEGADO,
		TERCEIRO.CODRESPONSABILIDADE AS TERCEIRO_CODRESPONSABILIDADE,
		COALESCE(REGISTRO.BOLREGISTRADA, 0) AS BOLREGISTRADA,
		APL.CODTIPOAPLICACAO,
		CASE WHEN APL.CODTIPOORIGEMAPLICACAO = 1 THEN 1 ELSE 0 END AS CODTIPOVINCULACAOAPLICACAO,
		APL.DATAVENCAPLICACAO,
		C.NUMCONTACORRENTE 
FROM GAR.GARANTIA G
JOIN CRE.OPERACAOCREDITO O 
	ON O.IDOPERACAOCREDITO = G.IDOPERACAOCREDITO 
	AND O.IDPRODUTO = 5
	AND O.IDSITUACAOCREDITO = 21
JOIN CCL.INFORMACAOLIMITE I	
	ON I.IDOPERACAOCREDITO = O.IDOPERACAOCREDITO 
	AND I.CODTIPODOMINIO = 4
	AND I.CODSITUACAOLIMITE = 2
JOIN CCL.INFORMACAOLIMITECONTACORRENTE C 
	ON C.IDINFORMACAOLIMITE  = I.IDINFORMACAOLIMITE 	
LEFT JOIN TABLE (SELECT S.BOLREGISTRADA 
				 FROM GAR.SITUACAOREGISTROGARANTIA S 
				 WHERE S.IDGARANTIA = G.IDGARANTIA 
				 ORDER BY S.DATAHORASITUACAOREGISTRO DESC 
				 FETCH FIRST 1 ROWS ONLY) 
	REGISTRO ON 1 = 1
JOIN GAR.ENQUADRAMENTOGARANTIA E
	ON E.IDENQUADRAMENTOGARANTIA = G.IDENQUADRAMENTOGARANTIA 
JOIN GAR.GRUPOGARANTIA GR 
	ON GR.IDGRUPOGARANTIA = E.IDGRUPOGARANTIA 	
LEFT JOIN GAR.PARTICIPACAO AS GARANTIDOR 
	ON GARANTIDOR.IDGARANTIA = G.IDGARANTIA 
	AND GARANTIDOR.CODRESPONSABILIDADE IN (8, 10) 
LEFT JOIN CLI.VIW_PESSOA PESSOA_GARANTIDOR 
	ON PESSOA_GARANTIDOR.IDPESSOA = GARANTIDOR.IDPESSOA 
	AND PESSOA_GARANTIDOR.IDINSTITUICAO = G.IDINSTITUICAO 	
LEFT JOIN GAR.PARTICIPACAO AS TERCEIRO 
	ON TERCEIRO.IDGARANTIA = G.IDGARANTIA 
	AND TERCEIRO.CODRESPONSABILIDADE = 17
LEFT JOIN CLI.VIW_PESSOA AS PESSOA_TERCEIRO 
	ON PESSOA_TERCEIRO.IDPESSOA = TERCEIRO.IDPESSOA 
	AND PESSOA_TERCEIRO.IDINSTITUICAO = G.IDINSTITUICAO 
LEFT JOIN GAR.ASSOCIACAOEXTERNA A 
	ON A.IDGARANTIA = G.IDGARANTIA 
	AND A.IDMODULO = 1	
LEFT JOIN GAR.APLICACAO APL ON APL.IDAPLICACAO = A.IDNEGOCIO 	
WHERE G.BOLATIVO = 1
;
-- COPY-DATABASE-OBJECT: "GAR"."VIW_GARANTIARECEBIVEISCARTAO"
CREATE OR REPLACE VIEW "GAR"."VIW_GARANTIARECEBIVEISCARTAO" AS
SELECT 
g.IDGARANTIA,
a.IDNEGOCIO,
p.IDPESSOA AS idPessoaTitular,
g.IDINSTITUICAO,
g.IDUNIDADEINST,
s.IDSOLICITACAOGERENCIADOR,
g.VALORGARANTIA,
c.NUMCONTACORRENTE,
g.BOLATIVO AS status,
s.CODSITUACAOSOLICITACAOCARTAO,
ss.DESCSITUACAOSOLICITACAOCARTAO,
h.CODSITUACAOGARANTIA,
sg.DESCSITUACAOGARANTIA,
h.CODTIPOHISTORICO,
t.DESCTIPOHISTORICO
FROM 
gar.GARANTIA g 
JOIN gar.SOLICITACAORECEBIVELCARTAO s ON g.IDGARANTIA = s.IDGARANTIA 
JOIN gar.ASSOCIACAOEXTERNA a ON g.IDGARANTIA = a.IDGARANTIA 
JOIN gar.CONTAVINCULADAGARANTIA c ON g.IDGARANTIA = c.IDGARANTIA 
JOIN gar.PARTICIPACAO p ON g.IDGARANTIA = p.IDGARANTIA AND p.CODRESPONSABILIDADE = 7 
JOIN gar.HISTORICOSITUACAOGARANTIA h ON g.IDGARANTIA = h.IDGARANTIA
JOIN gar.SITUACAOSOLICITACAOCARTAO ss ON s.CODSITUACAOSOLICITACAOCARTAO = ss.CODSITUACAOSOLICITACAOCARTAO 
JOIN gar.TIPOHISTORICO t ON h.CODTIPOHISTORICO = t.CODTIPOHISTORICO
JOIN gar.SITUACAOGARANTIA sg ON h.CODSITUACAOGARANTIA = sg.CODSITUACAOGARANTIA 
WHERE 
s.IDSOLICITACAOGERENCIADOR = (SELECT max(IDSOLICITACAOGERENCIADOR) FROM gar.SOLICITACAORECEBIVELCARTAO WHERE g.IDGARANTIA = IDGARANTIA)
AND h.DATAHORAHISTORICO = (SELECT max(DATAHORAHISTORICO) FROM gar.HISTORICOSITUACAOGARANTIA WHERE g.IDGARANTIA = IDGARANTIA)
;
