-- Create Views 

CREATE OR REPLACE VIEW "LPC"."VIW_VALORLIBERACAOPARCELADA" AS
SELECT
    PL.IDPLANOLIBERACAO,
    PL.BOLMAE,
     (
        SELECT
            COALESCE (SUM(plp.VALORPARCELADEFINITIVO),0)
        FROM
            lpc.PLANOLIBERACAOPARCELA plp
        WHERE
            plp.IDPLANOLIBERACAO = pl.IDPLANOLIBERACAO
            AND plp.IDSITUACAOPARCELA = 3 AND plp.BOLPENDENTEAPROVACAO = 0
    ) AS VALORLIBERADO,
     (
        SELECT
            COALESCE (SUM(plp.VALORPARCELADEFINITIVO),0)
        FROM
            lpc.PLANOLIBERACAOPARCELA plp
        WHERE
            plp.IDPLANOLIBERACAO = pl.IDPLANOLIBERACAO
            AND plp.IDSITUACAOPARCELA = 5 AND plp.BOLPENDENTEAPROVACAO = 0
    ) AS VALORCANCELADO,
    (
        SELECT
            COALESCE (SUM(plp.VALORPARCELADEFINITIVO),0)
        FROM
            lpc.PLANOLIBERACAOPARCELA plp
        WHERE
            plp.IDPLANOLIBERACAO = pl.IDPLANOLIBERACAO
            AND plp.IDSITUACAOPARCELA IN (2,4) AND plp.BOLPENDENTEAPROVACAO = 0
    ) AS VALORALIBERAR
FROM LPC.PLANOLIBERACAO PL
;
