, Configuracao.dataHoraAlteracao
, Configuracao.bolAtivo
FROM MNTCRU.ConfiguracaoEmpreendimentoBacen Configuracao

    JOIN MNTCRU.CulturaEmpreendimento Cultura 
        ON Cultura.codCulturaEmpreendimento = Configuracao.codCulturaEmpreendimento

    JOIN CRE.VIW_EmpreendimentoBacen Empreendimento
        ON Empreendimento.idEmpreendimentoBacen = Configuracao.idEmpreendimentoBacen

    JOIN CRE.VIW_ProdutoBacen Produto
        ON Produto.idProdutoBacen = Empreendimento.idProdutoBacen

    JOIN CRE.VIW_VariedadeBacen Variedade
        ON Variedade.idVariedadeBacen = Empreendimento.idVariedadeBacen

    JOIN CRE.VIW_AtividadeBacen Atividade 
        ON Atividade.idAtividadeBacen = Empreendimento.idAtividadeBacen

    JOIN CRE.VIW_FinalidadeBacen Finalidade
        ON Finalidade.idFinalidadeBacen = Empreendimento.idFinalidadeBacen

    JOIN CRE.VIW_ModalidadeBacen Modalidade
        ON  Modalidade.idAtividadeBacen  = Empreendimento.idAtividadeBacen
        AND Modalidade.idFinalidadeBacen = Empreendimento.idFinalidadeBacen
        AND Modalidade.idModalidadeBacen = Empreendimento.idModalidadeBacen
;
-- COPY-DATABASE-OBJECT: "MNTCRU"."VIW_FLUXOACAOMONITORAMENTO"
CREATE OR REPLACE VIEW "MNTCRU"."VIW_FLUXOACAOMONITORAMENTO" AS
(
SELECT
  Monitoramento.IdMonitoramento
, TipoMonitoramento.CodTipoMonitoramento
, TipoMonitoramento.descTipoMonitoramento

, Situacao.CodSituacaoMonitoramento AS CodSituacao
, '('||Fase.descFaseMonitoramento||') '||Situacao.descSituacaoMonitoramento AS DescSituacao

, Perfil.codPerfilMonitoramento AS CodPerfil
, Perfil.descPerfilMonitoramento AS DescPerfil

, Fluxo.codAcaoMonitoramento AS CodAcao
, '('||FaseAcao.descFaseMonitoramento||') '||Acao.descAcaoMonitoramento AS descAcao

FROM MNTCRU.Monitoramento Monitoramento

    JOIN MNTCRU.FluxoMonitoramento Fluxo 
        ON  Fluxo.CodTipoMonitoramento = Monitoramento.CodTipoMonitoramento
        AND Fluxo.CodSituacaoMonitoramento = Monitoramento.CodSituacaoMonitoramento 

    JOIN MNTCRU.TipoMonitoramento TipoMonitoramento 
        ON TipoMonitoramento.CodTipoMonitoramento = Fluxo.CodTipoMonitoramento

    JOIN MNTCRU.SituacaoMonitoramento Situacao 
        ON Situacao.CodSituacaoMonitoramento = Fluxo.CodSituacaoMonitoramento 

    JOIN MNTCRU.FaseMonitoramento Fase 
        ON Fase.codFaseMonitoramento = Situacao.codFaseMonitoramento 

    JOIN MNTCRU.PerfilMonitoramento Perfil 
        ON Perfil.codPerfilMonitoramento = Fluxo.codPerfilMonitoramento  

    JOIN MNTCRU.SituacaoMonitoramento Acao 
        ON Acao.CodSituacaoMonitoramento = Fluxo.codAcaoMonitoramento

    JOIN MNTCRU.FaseMonitoramento FaseAcao
        ON FaseAcao.codFaseMonitoramento = Acao.codFaseMonitoramento 
)
;
-- COPY-DATABASE-OBJECT: "MNTCRU"."VIW_FLUXOMONITORAMENTO"
CREATE OR REPLACE VIEW "MNTCRU"."VIW_FLUXOMONITORAMENTO" AS
SELECT
  TipoMonitoramento.CodTipoMonitoramento
, TipoMonitoramento.descTipoMonitoramento

, Situacao.CodSituacaoMonitoramento AS codSituacao
, '('||Fase.descFaseMonitoramento||') '||Situacao.descSituacaoMonitoramento AS descSituacao

, Perfil.codPerfilMonitoramento AS codPerfil
, Perfil.descPerfilMonitoramento AS descPerfil

, Fluxo.codAcaoMonitoramento AS codAcao
, '('||FaseAcao.descFaseMonitoramento||') '||Acao.descAcaoMonitoramento AS descAcao

FROM MNTCRU.FluxoMonitoramento Fluxo 

    JOIN MNTCRU.TipoMonitoramento TipoMonitoramento 
        ON TipoMonitoramento.CodTipoMonitoramento = Fluxo.CodTipoMonitoramento

    JOIN MNTCRU.SituacaoMonitoramento Situacao 
        ON Situacao.CodSituacaoMonitoramento = Fluxo.CodSituacaoMonitoramento 

    JOIN MNTCRU.FaseMonitoramento Fase 
        ON Fase.codFaseMonitoramento = Situacao.codFaseMonitoramento 

