    JOIN MNTCRU.SituacaoMonitoramento Acao 
        ON Acao.CodSituacaoMonitoramento = Fluxo.codAcaoMonitoramento

    JOIN MNTCRU.FaseMonitoramento FaseAcao
        ON FaseAcao.codFaseMonitoramento = Acao.codFaseMonitoramento
;
-- COPY-DATABASE-OBJECT: "MNTCRU"."VIW_MESAMONITORAMENTO"
/*:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::
:: VIW_MesaMonitoramento             
:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::*/
CREATE OR REPLACE VIEW "MNTCRU"."VIW_MESAMONITORAMENTO" AS
SELECT
-- Monitoramento
  Monitoramento.idMonitoramento
, Monitoramento.idMonitoramentoRef
, Monitoramento.dataHoraInclusao AS dataInclusao
, Monitoramento.dataHoraAtualizacao AS dataAtualizacao

-- Contrato
, Monitoramento.idContratoCredito
, Monitoramento.idOperacaoCredito
, Monitoramento.idOperacaoCreditoRural
, Monitoramento.numRefBacen
, Monitoramento.numContratoCredito
, Monitoramento.valorContratado
, Monitoramento.bolContratoLegado AS bolLegado

-- Empresa
, Monitoramento.idPessoaEmpresa

-- Cliente 
, Monitoramento.idPessoaCliente
, CASE WHEN Monitoramento.bolContratoLegado = 1 AND Monitoramento.codTipoLiberacao != 0 THEN 1 ELSE Monitoramento.idInstituicao END AS idInstituicaoCliente

-- Cooperativa 
, Monitoramento.idInstituicao
, Monitoramento.idUnidadeInst
, Instituicao.numCoopPai AS numCentral
, DECODE(Monitoramento.idInstituicao, 1,1, Instituicao.numCooperativa) AS numCooperativa

-- Liberacao
, Monitoramento.idPlanoLiberacao
, Monitoramento.numParcela
, Monitoramento.dataLiberacao
, Monitoramento.valorParcela

-- Situacao
, Situacao.codFaseMonitoramento AS codFase
, Situacao.codSituacaoMonitoramento AS codSituacao
, Situacao.descSituacaoMonitoramento AS descSituacao
, Monitoramento.dataPeriodoLimiteConclusao AS dataLimiteConclusao
, DAYS(CURRENT_DATE) - DAYS(Monitoramento.dataHoraInclusao) AS numDiasMonitoramento

-- OUTROS
, Monitoramento.codTipoLiberacao
, TipoMonitoramento.codTipoProcesso
, TipoMonitoramento.codTipoMonitoramento
, TipoMonitoramento.descTipoMonitoramento

FROM MNTCRU.Monitoramento Monitoramento 

    JOIN MNTCRU.SituacaoMonitoramento Situacao 
        ON Situacao.codSituacaoMonitoramento = Monitoramento.codSituacaoMonitoramento
        
    JOIN MNTCRU.TipoMonitoramento TipoMonitoramento 
        ON TipoMonitoramento.codTipoMonitoramento = Monitoramento.codTipoMonitoramento

    JOIN SCI.VIW_Instituicao Instituicao
        ON  Instituicao.idInstituicao = Monitoramento.idInstituicao
        AND Instituicao.idUnidadeInst = 0
;
-- COPY-DATABASE-OBJECT: "MNTCRU"."VIW_MONITORAMENTO"
/*:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::
:: VIW_Monitoramento             
:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::*/
CREATE OR REPLACE VIEW "MNTCRU"."VIW_MONITORAMENTO" AS
SELECT
-- Monitoramento
  Monitoramento.idMonitoramento
, Monitoramento.idMonitoramentoRef
, Monitoramento.dataHoraInclusao AS dataInclusao
, Monitoramento.dataHoraAtualizacao AS dataAtualizacao

-- Contrato
, Monitoramento.idContratoCredito
, Monitoramento.idOperacaoCredito
, Monitoramento.idOperacaoCreditoRural
, Monitoramento.numRefBacen
, Monitoramento.numContratoCredito
, Monitoramento.valorContratado
, Monitoramento.bolContratoLegado AS bolLegado

-- Empresa
, Monitoramento.idPessoaEmpresa
, PessoaEmpresa.nomeEmpresa
, PessoaEmpresa.numCnpjEmpresa

-- Cliente 
, Monitoramento.idPessoaCliente
, CASE WHEN Monitoramento.bolContratoLegado = 1 AND Monitoramento.codTipoLiberacao != 0 THEN 1 ELSE Monitoramento.idInstituicao END AS idInstituicaoCliente
, PessoaCliente.numCpfCnpjCliente
, PessoaCliente.nomeCliente

-- Cooperativa 
, Monitoramento.idInstituicao
, Monitoramento.idUnidadeInst
, TO_CHAR(Instituicao.numCoopPai) AS numCentral
, TO_CHAR(Instituicao.numCooperativa) AS numCooperativa

-- Liberacao
, Monitoramento.idPlanoLiberacao
, Monitoramento.numParcela
, Monitoramento.dataLiberacao
, Monitoramento.valorParcela

-- Situacao
, Fase.codFaseMonitoramento AS codFase
, Fase.descFaseMonitoramento AS descFase
, Situacao.codSituacaoMonitoramento AS codSituacao
, Situacao.descSituacaoMonitoramento AS descSituacao
, Monitoramento.dataPeriodoLimiteConclusao AS dataLimiteConclusao
, DAYS(CURRENT_DATE) - DAYS(Monitoramento.dataHoraInclusao) AS numDiasMonitoramento

-- Historico
, Historico.idUsuario AS idUsuarioHistorico
, Historico.descJustificativa AS descHistorico
, Historico.dataHoraHistorico AS dataHistorico
, DAYS(CURRENT_DATE) - DAYS(Historico.dataHoraHistorico) AS numDiasHoraHistorico
, HistoricoEncerramento.dataHoraHistorico dataEncerramento

-- OUTROS
, TipoLiberacao.codTipoLiberacao
, TipoLiberacao.descTipoLiberacao
, TipoMonitoramento.codTipoProcesso
, TipoMonitoramento.codTipoMonitoramento
, TipoMonitoramento.descTipoMonitoramento
, HistoricoMin.descJustificativa AS descRegra
, Other.monitoramentosVinculados AS descMonitoramentosVinculados

FROM MNTCRU.Monitoramento Monitoramento 

    JOIN MNTCRU.TipoMonitoramento TipoMonitoramento 
        ON TipoMonitoramento.CodTipoMonitoramento = Monitoramento.CodTipoMonitoramento

    JOIN MNTCRU.TipoLiberacao TipoLiberacao 
        ON TipoLiberacao.codTipoLiberacao = Monitoramento.codTipoLiberacao

    JOIN MNTCRU.SituacaoMonitoramento Situacao 
        ON Situacao.CodSituacaoMonitoramento = Monitoramento.CodSituacaoMonitoramento 

    JOIN MNTCRU.FaseMonitoramento Fase 
        ON Fase.codFaseMonitoramento = Situacao.codFaseMonitoramento

    JOIN MNTCRU.HistMonitoramento Historico
        ON  Historico.idMonitoramento = Monitoramento.idMonitoramento
        AND Historico.idHistMonitoramento = (
            SELECT MAX(H2.idHistMonitoramento) 
            FROM MNTCRU.HistMonitoramento H2 
            WHERE H2.idMonitoramento = Monitoramento.idMonitoramento
        )

    JOIN MNTCRU.HistMonitoramento HistoricoMin
        ON  HistoricoMin.idMonitoramento = Monitoramento.idMonitoramento
        AND HistoricoMin.idHistMonitoramento = (
            SELECT MIN(H2.idHistMonitoramento) 
            FROM MNTCRU.HistMonitoramento H2 
            WHERE H2.idMonitoramento = Monitoramento.idMonitoramento
        )

    LEFT JOIN MNTCRU.HistMonitoramento HistoricoEncerramento
        ON  HistoricoEncerramento.idMonitoramento = Monitoramento.idMonitoramento
        AND HistoricoEncerramento.idHistMonitoramento = (
            SELECT MAX(H2.idHistMonitoramento)
            FROM MNTCRU.HistMonitoramento H2 
                JOIN MNTCRU.SituacaoMonitoramento S2 ON S2.codSituacaoMonitoramento = H2.codSituacaoMonitoramento
            WHERE H2.idMonitoramento = Monitoramento.idMonitoramento
            AND S2.codFaseMonitoramento = 5
        )

    JOIN TABLE (
        SELECT LISTAGG(Other.idMonitoramento,',') AS monitoramentosVinculados
        FROM MNTCRU.Monitoramento Other
        WHERE (
            Other.idMonitoramentoRef = NVL(Monitoramento.idMonitoramentoRef, Monitoramento.idMonitoramento)
            OR Other.idMonitoramento = Monitoramento.idMonitoramentoRef
        )
        AND Other.idMonitoramento != Monitoramento.idMonitoramento
    ) Other ON 1=1

    JOIN SCI.VIW_Instituicao Instituicao
        ON  Instituicao.idInstituicao = Monitoramento.idInstituicao
        AND Instituicao.idUnidadeInst = 0

    JOIN TABLE (
        SELECT Pessoa.numCpfCnpj AS numCpfCnpjCliente, LTRIM(RTRIM(Pessoa.nomePessoa)) AS nomeCliente
        FROM CLI.VIW_Pessoa Pessoa
        WHERE Pessoa.idInstituicao = CASE WHEN Monitoramento.bolContratoLegado = 1 AND Monitoramento.codTipoLiberacao != 0 THEN 1 ELSE Monitoramento.idInstituicao END
        AND Pessoa.idPessoa = Monitoramento.idPessoaCliente
    ) PessoaCliente ON 1=1

    LEFT JOIN TABLE (
        SELECT Pessoa.numCpfCnpj AS numCnpjEmpresa, LTRIM(RTRIM(Pessoa.nomePessoa)) AS nomeEmpresa
        FROM CLI.VIW_Pessoa Pessoa
        WHERE Pessoa.idInstituicao = 2
        AND Pessoa.idPessoa = Monitoramento.idPessoaEmpresa
    ) PessoaEmpresa ON 1=1
;
-- COPY-DATABASE-OBJECT: "MNTCRU"."VIW_MONITORAMENTOEMPREENDIMENTO"
CREATE OR REPLACE VIEW "MNTCRU"."VIW_MONITORAMENTOEMPREENDIMENTO" AS

SELECT
-- Monitoramento
  Monitoramento.idMonitoramento
, Monitoramento.idMonitoramentoRef
, Monitoramento.dataHoraInclusao
, Monitoramento.dataHoraAtualizacao

-- Contrato
, Monitoramento.idOperacaoCredito
, Monitoramento.idOperacaoCreditoRural
, Monitoramento.numRefBacen
, Monitoramento.numContratoCredito
, Monitoramento.valorContratado

-- Empresa
, Monitoramento.idPessoaEmpresa

-- Cliente
, Monitoramento.idPessoaCliente

-- Cooperativa 
, Monitoramento.idInstituicao
, Monitoramento.idUnidadeInst

-- Liberacao
, Monitoramento.idPlanoLiberacao
, Monitoramento.numParcela
, Monitoramento.dataLiberacao
, Monitoramento.valorParcela

-- Situacao
, Fase.codFaseMonitoramento AS codFase
, Fase.descFaseMonitoramento AS descFase
, Situacao.codSituacaoMonitoramento AS codSituacao
, Situacao.descSituacaoMonitoramento AS descSituacao
, Monitoramento.dataPeriodoLimiteConclusao AS dataLimiteConclusao

-- Empreendimento
, MonitoramentoEmpreendimentoRural.idEmpreendimentoRural
, MonitoramentoEmpreendimentoRural.idEmpreendimentoBacen
, MonitoramentoEmpreendimentoRural.idMunicipio
, Localidade.codCaf
, MonitoramentoEmpreendimentoRural.descSafra
, MonitoramentoEmpreendimentoRural.codCicloCultivar
, MonitoramentoEmpreendimentoRural.codTipoSolo
, MonitoramentoEmpreendimentoRural.dataPlantioInicio
, MonitoramentoEmpreendimentoRural.dataPlantioFim
, MonitoramentoEmpreendimentoRural.dataColheitaInicio
, MonitoramentoEmpreendimentoRural.dataColheitaFim
, MonitoramentoEmpreendimentoRural.valorAreaInformada
, MonitoramentoEmpreendimentoRural.valorPrevisaoProducao

-- OUTROS
, TipoLiberacao.codTipoLiberacao
, TipoLiberacao.descTipoLiberacao
, DAYS(CURRENT_DATE) - DAYS(Monitoramento.dataHoraAtualizacao) AS numDiasSituacao
, TipoMonitoramento.codTipoMonitoramento
, TipoMonitoramento.descTipoMonitoramento
, Glebas.Glebas
, Fiscalizacoes.Fiscalizacoes
, AnaliseEmpresa.descResultado AS descAnaliseEmpresa

FROM MNTCRU.Monitoramento Monitoramento 

    JOIN MNTCRU.TipoMonitoramento TipoMonitoramento 
        ON TipoMonitoramento.CodTipoMonitoramento = Monitoramento.CodTipoMonitoramento

    JOIN MNTCRU.TipoLiberacao TipoLiberacao 
        ON TipoLiberacao.codTipoLiberacao = Monitoramento.codTipoLiberacao

    JOIN MNTCRU.SituacaoMonitoramento Situacao 
        ON Situacao.CodSituacaoMonitoramento = Monitoramento.CodSituacaoMonitoramento 

    JOIN MNTCRU.FaseMonitoramento Fase 
        ON Fase.codFaseMonitoramento = Situacao.codFaseMonitoramento

    JOIN MNTCRU.MonitoramentoEmpreendimentoRural MonitoramentoEmpreendimentoRural 
        ON MonitoramentoEmpreendimentoRural.idMonitoramento = Monitoramento.idMonitoramento

    JOIN LOC.VIW_Localidade Localidade
        ON Localidade.idLocalidade = MonitoramentoEmpreendimentoRural.idMunicipio

    LEFT JOIN TABLE(
        SELECT LISTAGG(Gleba.idGleba, ', ') AS Glebas
        FROM MNTCRU.MonitoramentoEmpreendimentoRuralGleba Gleba
        WHERE Gleba.idMonitoramentoEmpreendimentoRural = MonitoramentoEmpreendimentoRural.idMonitoramentoEmpreendimentoRural
    ) Glebas ON 1=1

    LEFT JOIN TABLE(
        SELECT LISTAGG(RL.idFiscalizacao, ', ') AS Fiscalizacoes
        FROM MNTCRU.MonitoramentoEmpreendimento RL
        WHERE RL.idMonitoramento = Monitoramento.idMonitoramento
        AND RL.idEmpreendimentoBacen = MonitoramentoEmpreendimentoRural.idEmpreendimentoBacen
        AND RL.idFiscalizacao IS NOT NULL
    ) Fiscalizacoes ON 1=1

    LEFT JOIN TABLE(
        SELECT Historico.idHistMonitoramento, Historico.descHistorico AS descResultado
        FROM MNTCRU.HistMonitoramento Historico 
        WHERE Historico.idMonitoramento = Monitoramento.idMonitoramento
        AND Historico.codSituacaoMonitoramento IN(14,19)
        AND Historico.descComplemento = 'EmpreendimentoResultadoVO'
        ORDER BY 1 DESC
        LIMIT 1 
    ) AnaliseEmpresa ON 1=1

WHERE Monitoramento.CodTipoMonitoramento IN(5,7,8)
;
-- COPY-DATABASE-OBJECT: "MNTCRU"."VIW_PROCESSOAMOSTRAGEM"
CREATE OR REPLACE VIEW "MNTCRU"."VIW_PROCESSOAMOSTRAGEM" AS
SELECT
  ProcessoAmostragem.IdProcessoAmostragem
, ProcessoAmostragem.IdInstituicao
, ProcessoAmostragem.AnoMesCompetencia
, ProcessoAmostragem.CodSituacao
, DECODE(ProcessoAmostragem.CodSituacao, 0,'não iniciado', 1,'iniciado', 2,'finalizado', 'erro') AS DescSituacao
, ProcessoAmostragem.DataHoraAtualizacao
, ProcessoAmostragem.DescParametro
, ProcessoAmostragem.DescResultado
, TipoProcesso.CodTipoProcesso
, TipoProcesso.descTipoProcesso
, TipoLiberacao.CodTipoLiberacao
, TipoLiberacao.DescTipoLiberacao

FROM MNTCRU.ProcessoAmostragem ProcessoAmostragem 

    JOIN MNTCRU.TipoProcesso TipoProcesso 
        ON TipoProcesso.CodTipoProcesso = ProcessoAmostragem.CodTipoProcesso

    LEFT JOIN MNTCRU.TipoLiberacao TipoLiberacao
        ON TipoLiberacao.CodTipoLiberacao = ProcessoAmostragem.CodTipoLiberacao
;
-- COPY-DATABASE-OBJECT: "PGR"."VIW_PROAGROCOORDENADAGEODESICA"
CREATE OR REPLACE VIEW "PGR"."VIW_PROAGROCOORDENADAGEODESICA" AS
SELECT
	CP.IDCOMUNICACAOPERDA,
    PRIMEIRAVISITA.IDFISCALIZACAO,
    PRIMEIRAVISITA.DATAINICIOVISTORIA1,
    PRIMEIRAVISITA.DATAFIMVISTORIA1,
    PRIMEIRAVISITA.DATAHORAACEITE,
    CP.IDINSTITUICAO,
    CP.IDUNIDADEINSTITUICAOOPERACAO ,
    VIW_INST.NUMCOOPERATIVA,
    VIW_INST.DESCSIGLACOOP,
    PP.NUMCPFCNPJ,
    PP.NOMEPESSOA,
    TIMESTAMPDIFF(
    	16,PRIMEIRAVISITA.DATAFIMVISTORIA1 - PRIMEIRAVISITA.DATAHORAACEITE
    ) AS TEMPO_VISTORIA_DIAS ,
    EV.IDEVENTOAGRAVAMENTO
FROM
    PGR.SOLICITACAOFISCALIZACAO SF
INNER JOIN PGR.EVENTOAGRAVAMENTO EV ON
    EV.IDEVENTOAGRAVAMENTO = SF.IDEVENTOAGRAVAMENTO
    AND EV.BOLEVENTOCOMUNICACAOPERDA = 1
INNER JOIN PGR.COMUNICACAOPERDA CP ON
    EV.IDCOMUNICACAOPERDA = CP.IDCOMUNICACAOPERDA
INNER JOIN CRE.OPERACAOCREDITO OP
	ON OP.IDOPERACAOCREDITO = CP.IDOPERACAOCREDITO 
INNER JOIN CRE.OPERACAOCREDITORURAL OPCRER 
	ON OPCRER.IDOPERACAOCREDITO = OP.IDOPERACAOCREDITO
	AND OPCRER.NUMREFBACEN  = CP.NUMREFERENCIABACEN
INNER JOIN CRE.EMPREENDIMENTORURAL ER
	ON ER.IDOPERACAOCREDITORURAL = OPCRER.IDOPERACAOCREDITORURAL
	AND ER.NUMSEQEMPREENDIMENTORURAL = CP.NUMORDEMDESTINACAO
INNER JOIN CRE.SAFRA S 
	ON S.IDSAFRA = OPCRER.IDSAFRA
	AND S.BOLATIVO = 1
INNER JOIN TABLE (
    SELECT
        INST.IDINSTITUICAO ,
        INST.IDUNIDADEINST ,
        INST.NUMPAC ,
        INST.NUMCOOPERATIVA ,
        INST.NUMCNPJ ,
        INST.DESCSIGLACOOP
    FROM
        SCI.VIW_INSTITUICAO INST
    WHERE
        INST.IDINSTITUICAO = CP.IDINSTITUICAO
        AND INST.IDUNIDADEINST = CP.IDUNIDADEINSTITUICAOOPERACAO
    LIMIT 1 ) VIW_INST
ON
    1 = 1
INNER JOIN TABLE (
    SELECT
        PP.IDPESSOA ,
        PP.NUMCPFCNPJ ,
        PP.NOMEPESSOA
    FROM
        CLI.VIW_PESSOA PP
    WHERE 
        PP.IDPESSOA = CP.IDPESSOAPERITO
    LIMIT 1 ) PP
ON
    1 = 1
INNER JOIN TABLE (
    SELECT
        MIN(S1.IDFISCALIZACAO) AS IDFISCALIZACAO,
		S1.DATAINICIOVISTORIA1,
        S1.DATAHORAACEITE, 
        S1.DATAFIMVISTORIA1 
    FROM
        PGR.SOLICITACAOFISCALIZACAO S1 
    WHERE
        S1.IDEVENTOAGRAVAMENTO = EV.IDEVENTOAGRAVAMENTO
    GROUP BY 
    	S1.DATAHORAACEITE, 
        S1.DATAFIMVISTORIA1,
		S1.DATAINICIOVISTORIA1
    LIMIT 1 ) PRIMEIRAVISITA
ON
    PRIMEIRAVISITA.IDFISCALIZACAO = SF.IDFISCALIZACAO 
WHERE
   SF.DATAHORACANCELAMENTO IS NULL
   AND SF.DATAHORAACEITE IS NOT NULL
;
-- COPY-DATABASE-OBJECT: "PGR"."VIW_PROAGRO_COP"
CREATE OR replace VIEW "PGR"."VIW_PROAGRO_COP" as
	select sf.idfiscalizacao,
                       cp.idcomunicacaoperda,
                       sf.datainiciovistoria1,
                       sf.datafimvistoria1,
                       sf.datahoraaceite,
                       cp.idinstituicao,
                       cp.idunidadeinstituicaooperacao ,
                       viw_inst.numcooperativa,
                       viw_inst.descsiglacoop,
                       pp.numcpfcnpj,
                       pp.nomepessoa,
                       timestampdiff
                       (
                            16,
							sf.datahoraaceite - sf.datafimvistoria1
                       )
                       AS tempo_vistoria_dias ,
                       ev.ideventoagravamento
						FROM                   pgr.solicitacaofiscalizacao sf
						INNER JOIN             pgr.eventoagravamento ev
						ON                     ev.ideventoagravamento = sf.ideventoagravamento
						AND                    ev.boleventocomunicacaoperda = 1 INNER
						JOIN                   pgr.comunicacaoperda cp
						ON                     ev.idcomunicacaoperda = cp.idcomunicacaoperda
						INNER JOIN             TABLE
                       (
                              SELECT inst.idinstituicao ,
                                     inst.idunidadeinst ,
                                     inst.numpac ,
                                     inst.numcooperativa ,
                                     inst.numcnpj ,
                                     inst.descsiglacoop
                              FROM   sci.viw_instituicao inst
                              WHERE  inst.idinstituicao = cp.idinstituicao
                              AND    inst.idunidadeinst = cp.idunidadeinstituicaooperacao limit 1
                       )
                       viw_inst
ON                     1 = 1 INNER
JOIN                   TABLE
                       (
                              SELECT pp.idpessoa ,
                                     pp.numcpfcnpj ,
                                     pp.nomepessoa
                              FROM   cli.viw_pessoa pp
                              WHERE  pp.idpessoa = cp.idpessoaperito limit 1
                       )
                       pp
ON                     1 = 1

WHERE sf.datahoracancelamento IS NULL
;
-- COPY-DATABASE-OBJECT: "RAF"."VIW_HISTORICODESTINATARIOPAGAMENTO"
create view "RAF"."VIW_HISTORICODESTINATARIOPAGAMENTO" as select * from RAF.HISTORICODESTINATARIOPAGAMENTO
;
-- COPY-DATABASE-OBJECT: "REM"."VIW_INSTITUICAOCAPREM"
CREATE VIEW "REM"."VIW_INSTITUICAOCAPREM" 
( 
	IDINSTITUICAO, 
	CODCONTAPROPRIACETIP, 
	CODCONTAEMISSOR, 
	CODCONTACLIENTE, 
	CODCONTARESERVATECNICA, 
	CODCONTAGARANTIA, 
	DATAHORAATUALIZACAO, 
	NOMEPARTICIPANTE 
) 
AS 
SELECT 
    I.IDINSTITUICAO , 
