;
-- COPY-DATABASE-OBJECT: "REP"."VIW_CONSULTA_SCORE"
CREATE OR REPLACE VIEW "REP"."VIW_CONSULTA_SCORE" AS
SELECT *
FROM
        (SELECT 
                  NUMSCORE
                , DESCRANGE
                , TAXASCORE
                , NUMPONTUACAORISK
                , DESCPRINAD
                , DESCMENSAGEM
                , NUMCPFCNPJ
                , DATAHORACONSULTA
                , NULL as IDINSTITUICAO
                , NULL as IDUNIDADEINST
                , NULL as IDCONTRATO
                , NULL as DESCRETORNOXML
        FROM FDE.CONSULTASCORE
        UNION ALL
        SELECT 
                  NULL as NUMSCORE
                , NULL as DESCRANGE
                , NULL as TAXASCORE
                , NULL as NUMPONTUACAORISK
                , NULL as DESCPRINAD
                , NULL as DESCMENSAGEM
                , CO.DESCCPFCNPJ
                , CO.DATAHORACONSULTA
                , CO.IDINSTITUICAO
                , CO.IDUNIDADEINST
                , CO.IDCONTRATO
                , XMLCAST(CO.DESCRETORNOXML as VARCHAR(32000)) as DESCRETORNOXML
        FROM FDE.CONSULTA CO
        INNER JOIN FDE.CONTRATO CT ON
              CT.IDCONTRATO = CO.IDCONTRATO
        WHERE CT.IDSERVICOORGAOEXTERNO = 160
) as T
;
