CREATE OR REPLACE VIEW  "REP"."VIW_PESSOA_PERFIL"
   (
      CODCOMPARTILHAMENTOCADASTRO,
      CODTIPOPESSOA,
      IDPESSOA,
      NOMEPESSOA,
      NUMCPFCNPJ,
      NOMECOMPLETO,
      NOMEAPELIDO,
      IDINSTITUICAO,
      IDUNIDADEINST,
      IDPESSOALEGADO,
      IDINSTITUICAORESPONSAVEL,
      CODPERFILCADASTRO,
      BOLAUTORIZACONSULTABACEN,
      DATAALTERACAOPERFILCADASTRO,
      CODTIPOFONTERENDA,
      BOLRENDAFIXA,
      VALORRECEITABRUTAMENSAL,
      DATAHORAINICIO,
      DATAVALIDADERENDA
   ) AS
SELECT
   B.CODCOMPARTILHAMENTOCADASTRO,
   A.CODTIPOPESSOA,
   A.IDPESSOA,
   B.NOMEPESSOA,
   A.NUMCPFCNPJ,
   B.NOMECOMPLETO,
   B.NOMEAPELIDO,
   C.IDINSTITUICAO,
   C.IDUNIDADEINST,
   C.IDPESSOALEGADO,
   D.IDINSTITUICAO IDINSTITUICAORESPONSAVEL,
   B.CODPERFILCADASTRO,
   B.BOLAUTORIZACONSULTABACEN,
   B.DATAALTERACAOPERFILCADASTRO,
   E.CODTIPOFONTERENDA,
   E.BOLRENDAFIXA,
   E.VALORRECEITABRUTAMENSAL,
   E.DATAHORAINICIO,
   E.DATAVALIDADERENDA
FROM   REP.TGPESSOA A
INNER JOIN   REP.TGPESSOACOMPARTILHAMENTO B ON
       A.IDPESSOA = B.IDPESSOA
INNER JOIN   REP.TGTRANSICAOPESSOA C ON
       B.IDPESSOACOMPARTILHAMENTO = C.IDPESSOACOMPARTILHAMENTO
INNER JOIN   REP.TGINSTITUICAORESPONSAVELCADASTRO D ON
       D.IDPESSOACOMPARTILHAMENTO = B.IDPESSOACOMPARTILHAMENTO
LEFT JOIN    REP.TGFONTERENDA E ON
       E.IDPESSOACOMPARTILHAMENTO     = B.IDPESSOACOMPARTILHAMENTO
   AND E.DATAHORAINICIO IS NOT NULL
;
