-- COPY-DATABASE-OBJECT: "USRCAT"."VIW_BLOQUEIO_CREDITO"
CREATE VIEW "USRCAT"."VIW_BLOQUEIO_CREDITO" (
        IDBLOQUEIO
        ,IDREGISTROBLOQUEIO
        ,IDNEGOCIO
        ,NUMCONTRATO
        ,NUMPARCELA
        ,DATAVENCIMENTO
        ,DATAEXPIRACAO
        ,IDUSUARIOEXCLUSAO
        ,DATAHORAEXCLUSAO
        ,NUMCOOPERATIVA
        ,NUMPAC
        ,IDUSUARIOINCLUSAO
        ,DATAHORAINCLUSAO
        )
AS
(
                SELECT RB.IDBLOQUEIO
                        ,RB.IDREGISTROBLOQUEIO
                        ,OC.IDNEGOCIO
                        ,OC.NUMCONTRATO
                        ,RB.NUMPARCELA
                        ,RB.DATAVENCIMENTO
                        ,RB.DATAEXPIRACAO
                        ,RB.IDUSUARIOEXCLUSAO
                        ,RB.DATAHORAEXCLUSAO
                        ,VI.NUMCOOPERATIVA
                        ,VI.NUMPAC
                        ,RB.IDUSUARIOINCLUSAO
                        ,RB.DATAHORAINCLUSAO
                FROM CDM.REGISTROBLOQUEIO RB
                LEFT JOIN CDM.OPERACAOCOBRANCA OC ON (
                                RB.IDOPERACAOCOBRANCA = OC.IDOPERACAOCOBRANCA
                                AND RB.IDINSTITUICAO = OC.IDINSTITUICAO
                                )
                INNER JOIN SCI.VIW_INSTITUICAO VI ON (
                                VI.IDINSTITUICAO = RB.IDINSTITUICAO
                                AND VI.IDUNIDADEINST = RB.IDUNIDADEINST
                                )
                INNER JOIN CDM.BLOQUEIOINST BI ON (
                                RB.IDINSTITUICAO = BI.IDINSTITUICAO
                                AND RB.IDUNIDADEINST = BI.IDUNIDADEINST
                                AND RB.IDBLOQUEIO = BI.IDBLOQUEIOINST
                                )
                )
;
