-- COPY-DATABASE-OBJECT: "CLS"."FN_CONSULTA_SALDOCAMBIO"
CREATE OR REPLACE FUNCTION "CLS"."FN_CONSULTA_SALDOCAMBIO" (
    IN PIDINSTITUICAO INTEGER DEFAULT NULL
)
READS SQL DATA
RETURNS TABLE (
    IDINSTITUICAO INTEGER,
    NUMCOOPCENTRAL DECFLOAT,
    DESCSIGLACENTRAL VARCHAR(60),
    NUMCNPJCENTRAL VARCHAR(14),
    NUMCOOPERATIVA DECFLOAT,
    DESCSIGLACOOP VARCHAR(60),
    NUMCNPJCOOP VARCHAR(14),
    VALORDISPONIVELTOTAL DECIMAL(31,2),
    VALORUTILIZADOTOTAL DECIMAL(31,2),
    VALORMARGEMDISPONIVEL DECIMAL(31,2)
)
SPECIFIC FN_CONSULTA_SALDOCAMBIO
BEGIN
    DECLARE PNUMCOOPCENTRAL DECFLOAT;
    DECLARE PDESCSIGLACENTRAL VARCHAR(60); 
    DECLARE PNUMCNPJCENTRAL VARCHAR(14);
    DECLARE PNUMCOOPERATIVA DECFLOAT;
    DECLARE PDESCSIGLACOOP VARCHAR(60);
    DECLARE PNUMCNPJCOOP VARCHAR(14);
    DECLARE PVALORDISPONIVELTOTAL DECIMAL(31,2);
    DECLARE PVALORUTILIZADOTOTAL DECIMAL(31,2);
    DECLARE PVALORMARGEMDISPONIVEL DECIMAL(31,2);
    DECLARE VSAI BOOLEAN DEFAULT FALSE;
    DECLARE VSQL VARCHAR(15000);   
    DECLARE VSTATEMENT STATEMENT;   
    DECLARE VSTATEMENTCURSOR STATEMENT;
    DECLARE VCURSOR CURSOR FOR VSTATEMENTCURSOR;   
    
    DECLARE CONTINUE HANDLER FOR NOT FOUND   
    BEGIN
        SET VSAI = TRUE;
    END;      

    SET VSQL = '
    SELECT vi.IDINSTITUICAO,
           COALESCE(VIP.NUMCOOPERATIVA, ''0001'') NUMCOOPCENTRAL,
           COALESCE(VIP.DESCSIGLACOOP, ''BANCO SICOOB'') DESCSIGLACENTRAL,
           COALESCE(VIP.NUMCNPJ, ''02038232000164'') NUMCNPJCENTRAL,
           COALESCE(VI.NUMCOOPERATIVA, ''0001'') NUMCOOPERATIVA,
           VI.DESCSIGLACOOP,
           VI.NUMCNPJ NUMCNPJCOOP,
           (SUM(PLT.VALORUTILIZADO) + SUM(PLT.VALORMARGEM)) AS VALORDISPONIVELTOTAL,
           SUM(PLT.VALORUTILIZADO) VALORUTILIZADOTOTAL,
           SUM(PLT.VALORMARGEM) VALORMARGEMDISPONIVEL
    FROM CLS.MAPAPORTFOLIOBACEN M 
    INNER JOIN CLS.REGISTROOPERACAO RO ON M.IDMAPAPORTFOLIOBACEN = RO.IDMAPAPORTFOLIOBACEN
    INNER JOIN CLS.OPERACAOAVAL o ON o.IDREGISTROPRINCIPAL = RO.IDREGISTROOPERACAO 
    INNER JOIN CLS.REGISTROOPERACAO rOval ON rOval.IDREGISTROOPERACAO = o.IDREGISTROAVAL 
    INNER JOIN CLI.VIW_PESSOA vp ON vp.IDPESSOA = rOval.IDPESSOAMENSAGEM AND vp.IDINSTITUICAO = rOval.IDINSTITUICAO 
    INNER JOIN SCI.VIW_INSTITUICAO vi ON vi.NUMCNPJ = vp.NUMCPFCNPJ AND vi.NUMPAC = 0                                      
    INNER JOIN CLS.POSICAOLIMITETOMADOR PLT ON rOval.IDLIMITETOMADOR = PLT.IDLIMITETOMADOR                                                  
    LEFT JOIN SCI.VIW_INSTITUICAO VIP ON VIP.NUMCOOPERATIVA = VI.NUMCOOPPAI AND VIP.NUMPAC = 0 AND VIP.NUMCOOPERATIVA IS NOT NULL
    WHERE 1=1';

    IF PIDINSTITUICAO IS NOT NULL THEN
        SET VSQL = VSQL || ' AND vi.IDINSTITUICAO = ?'; 
    END IF;   

    SET VSQL = VSQL || '
    AND M.BOLATIVO = 1
    AND M.IDDOMINIOORIGEM = 267    
    AND RO.BOLATIVO = 1
    AND RO.IDTIPOREGISTROOPERACAO = 2
    GROUP BY vi.IDINSTITUICAO,
             COALESCE(VIP.NUMCOOPERATIVA, ''0001''),
             COALESCE(VIP.DESCSIGLACOOP, ''BANCO SICOOB''),
             COALESCE(VIP.NUMCNPJ, ''02038232000164''),
             COALESCE(VI.NUMCOOPERATIVA, ''0001''),
             VI.DESCSIGLACOOP,
             VI.NUMCNPJ';

    PREPARE VSTATEMENTCURSOR FROM VSQL;
   
    IF PIDINSTITUICAO IS NOT NULL THEN
        OPEN VCURSOR USING PIDINSTITUICAO;
    ELSE
        OPEN VCURSOR;
    END IF; 

    FETCH VCURSOR INTO 
        PIDINSTITUICAO, PNUMCOOPCENTRAL, PDESCSIGLACENTRAL, PNUMCNPJCENTRAL,
        PNUMCOOPERATIVA, PDESCSIGLACOOP, PNUMCNPJCOOP,
        PVALORDISPONIVELTOTAL, PVALORUTILIZADOTOTAL, PVALORMARGEMDISPONIVEL;

    WHILE NOT VSAI DO
        PIPE (
            PIDINSTITUICAO, PNUMCOOPCENTRAL, PDESCSIGLACENTRAL, PNUMCNPJCENTRAL,
            PNUMCOOPERATIVA, PDESCSIGLACOOP, PNUMCNPJCOOP,
            PVALORDISPONIVELTOTAL, PVALORUTILIZADOTOTAL, PVALORMARGEMDISPONIVEL
        );
        FETCH VCURSOR INTO 
            PIDINSTITUICAO, PNUMCOOPCENTRAL, PDESCSIGLACENTRAL, PNUMCNPJCENTRAL,
            PNUMCOOPERATIVA, PDESCSIGLACOOP, PNUMCNPJCOOP,
            PVALORDISPONIVELTOTAL, PVALORUTILIZADOTOTAL, PVALORMARGEMDISPONIVEL;
    END WHILE;

    CLOSE VCURSOR;
    RETURN;
END
;
-- COPY-DATABASE-OBJECT: "DBSYS"."FNC_QTDREGISTROS"
CREATE OR REPLACE FUNCTION "DBSYS"."FNC_QTDREGISTROS" (PTABSCHEMA VARCHAR(50),PTABNAME VARCHAR(100),PMAXCOUNTREGISTROS BIGINT DEFAULT 1000)
   RETURNS BIGINT
   SPECIFIC FNC_QTDREGISTROS
BEGIN
   DECLARE VSQL  VARCHAR(2000);
   DECLARE VQTD  BIGINT;
   DECLARE VSTMT STATEMENT;
   DECLARE VCUR CURSOR FOR VSTMT;
   DECLARE CONTINUE HANDLER FOR SQLEXCEPTION set VQTD = 0;
   SET VSQL = 'SELECT COUNT(*) DBSYSCOUNT FROM (SELECT 1 FROM '||TRIM(PTABSCHEMA)||'."'||PTABNAME||'" FETCH FIRST '||TO_CHAR(PMAXCOUNTREGISTROS)||' ROWS ONLY)';
   PREPARE VSTMT FROM VSQL;
   OPEN VCUR;
   FETCH VCUR INTO VQTD;
   CLOSE VCUR;
   RETURN VQTD;
END;
;
-- COPY-DATABASE-OBJECT: "DBSYS"."SPLIT"
CREATE OR REPLACE FUNCTION "DBSYS"."SPLIT"(text VARCHAR(32000),
                                       split VARCHAR(10)) RETURNS TABLE(column_values VARCHAR(60))
    RETURN
    WITH rec
        (
            rn,
            column_value,
            pos
        ) AS
        (
            VALUES
            (
                1,
                VARCHAR(SUBSTR(text, 1, DECODE(INSTR(text, split, 1), 0, LENGTH(text), INSTR(text,
                split, 1) - 1)), 255),
                INSTR(text, split, 1) + LENGTH(split)
            )
        UNION ALL
        SELECT rn + 1,
            VARCHAR(SUBSTR(text, pos, DECODE(INSTR(text, split, pos), 0, LENGTH(text) - pos + 1,
            INSTR(text, split, pos) - pos)), 255),
            INSTR(text, split, pos) + LENGTH(split)
        FROM rec
        WHERE rn < 30000
            AND pos > LENGTH(split)
        )
    SELECT column_value
    FROM rec
;
