-- COPY-DATABASE-OBJECT: "USRDB2TUNE"."FNC_RETORNA_NUMCONTRATOCREDITO"
CREATE OR REPLACE FUNCTION "USRDB2TUNE"."FNC_RETORNA_NUMCONTRATOCREDITO" (VQTD INTEGER DEFAULT 500)
  RETURNS INTEGER
  LANGUAGE SQL
  READS SQL DATA
  DETERMINISTIC
BEGIN
   DECLARE VID                 INTEGER;
   DECLARE VNUMCONTRATOCREDITO BIGINT;
   SET VID = INT(RAND() * VQTD) + 1;
   SET VNUMCONTRATOCREDITO = (SELECT NUMCONTRATOCREDITO
                              FROM SESSION.OPERACAOCREDITO
                              WHERE ID = VID);
   RETURN VNUMCONTRATOCREDITO;
END;
;

