-- COPY-DATABASE-OBJECT: "CCL"."SPU_CCL_LIMITEALOCACAO"
CREATE OR REPLACE PROCEDURE "CCL"."SPU_CCL_LIMITEALOCACAO" (PCODPERIODOREFERENCIA SMALLINT,
PIDINSTITUICAOREPASSADORA INTEGER DEFAULT NULL,
PIDINSTITUICAOSOLICITANTE INTEGER DEFAULT NULL,
PIDINSTITUICAO INTEGER DEFAULT NULL,
PNUMCEDULA VARCHAR(50) DEFAULT NULL)
LANGUAGE SQL
DYNAMIC RESULT SETS 1
SPECIFIC SPU_CCL_LIMITEALOCACAO
BEGIN
   DECLARE 
            VSQL VARCHAR(5000);


DECLARE 
    VSTATEMENT STATEMENT;


DECLARE GLOBAL TEMPORARY TABLE 
    SESSION.TMP_LIMITES_UTILIZADOS 
    ( 
        IDCEDULARURAL INTEGER NOT NULL,
IDLIMITECONCESSAO INTEGER NOT NULL,
NUMPROSPECCAORURAL INTEGER
    ) 
    NOT LOGGED 
ON
ROLLBACK
DELETE
   ROWS 
ON
   COMMIT
DELETE
   ROWS WITH REPLACE;


SET VSQL = 
'INSERT INTO SESSION.TMP_LIMITES_UTILIZADOS              
WITH PARAMETROS (CODPERIODOREFERENCIA,IDINSTITUICAOREPASSADORA,IDINSTITUICAOSOLICITANTE,IDINSTITUICAO,NUMCEDULA)                                                                 
AS (VALUES (CAST(? AS SMALLINT),                                                                             
CAST(? AS INTEGER),                                                                             
CAST(? AS INTEGER),                                                                             
CAST(? AS INTEGER),                                                                             
CAST(? AS VARCHAR(50))))              
SELECT DISTINCT c.IDCEDULARURAL, L.IDLIMITECONCESSAO, p2.NUMPROSPECCAORURAL              
FROM ccl.CEDULARURAL c              
INNER JOIN ccl.PROPOSTADISTRIBUICAORURAL p ON p.IDPROPOSTADISTRIBUICAORURAL = c.IDPROPOSTADISTRIBUICAORURAL     
INNER JOIN ccl.INFORMACAOLIMITEALOCACAO i ON c.IDCEDULARURAL = i.IDCEDULARURAL
INNER JOIN ccl.LIMITECONCESSAO l ON l.IDINFORMACAOLIMITE = i.IDINFORMACAOLIMITEALOCACAO 
LEFT JOIN ccl.PROSPECCAORURAL p2 ON c.IDPROSPECCAORURAL = p2.IDPROSPECCAORURAL          
CROSS JOIN PARAMETROS                    p0              
WHERE 1=1' 
;


IF PIDINSTITUICAOREPASSADORA IS NOT NULL THEN
    SET VSQL = VSQL || CHR(10)|| 
    ' AND p.CODPERIODOREFERENCIA = P0.CODPERIODOREFERENCIA AND p.IDINSITTUICAOREPASSADORA = p0.IDINSTITUICAOREPASSADORA' 
    ;

END IF;


IF PIDINSTITUICAOSOLICITANTE IS NOT NULL THEN
    SET VSQL = VSQL || CHR(10)|| 
    ' AND p.CODPERIODOREFERENCIA = P0.CODPERIODOREFERENCIA AND p.IDINSTITUICAOSOLICITANTE = p0.IDINSTITUICAOSOLICITANTE' 
    ;

END IF;


IF PIDINSTITUICAO IS NOT NULL THEN
    SET VSQL = VSQL || CHR(10)|| 
    ' AND c.CODPERIODOREFERENCIA = P0.CODPERIODOREFERENCIA AND c.IDINSTITUICAO            = p0.IDINSTITUICAO' 
    ;

END IF;


IF PNUMCEDULA IS NOT NULL THEN
    SET VSQL = VSQL || CHR(10)|| 
    ' AND c.CODPERIODOREFERENCIA = P0.CODPERIODOREFERENCIA AND c.NUMCEDULA                = p0.NUMCEDULA';

END IF;


IF PIDINSTITUICAOREPASSADORA IS NULL
AND 
    PIDINSTITUICAOSOLICITANTE IS NULL
AND 
    PIDINSTITUICAO IS NULL
AND 
    PNUMCEDULA IS NULL THEN
    SET VSQL = VSQL || CHR(10)|| ' AND p.CODPERIODOREFERENCIA = P0.CODPERIODOREFERENCIA';

END IF;


PREPARE VSTATEMENT
FROM VSQL;


EXECUTE VSTATEMENT
   USING PCODPERIODOREFERENCIA,
PIDINSTITUICAOREPASSADORA,
PIDINSTITUICAOSOLICITANTE,
PIDINSTITUICAO,
PNUMCEDULA;


CALL ADMIN_CMD('RUNSTATS ON TABLE SESSION.TMP_LIMITES_UTILIZADOS WITH DISTRIBUTION AND DETAILED INDEXES ALL');


DECLARE GLOBAL TEMPORARY TABLE 
    SESSION.EVENTO_UTILIZACAO AS 
    (
SELECT
   DISTINCT t.IDLIMITECONCESSAO ,
   t.IDCEDULARURAL ,
   t.NUMPROSPECCAORURAL ,
   e.IDNEGOCIO ,
   e.VALOREVENTOSENSIBILIZACAO
FROM    SESSION.TMP_LIMITES_UTILIZADOS t
LEFT JOIN ccl.EVENTOSENSIBILIZACAO e ON
   e.IDLIMITECONCESSAO = t.IDLIMITECONCESSAO
   AND e.CODTIPOSENSIBILIZACAO = 1
   AND e.BOLESTORNO = 0
    ) 
    WITH DATA NOT LOGGED 
ON
ROLLBACK
DELETE
   ROWS 
ON
   COMMIT
DELETE
   ROWS WITH REPLACE;


CALL ADMIN_CMD('RUNSTATS ON TABLE SESSION.EVENTO_UTILIZACAO WITH DISTRIBUTION AND DETAILED INDEXES ALL');


DECLARE GLOBAL TEMPORARY TABLE 
    SESSION.VALORES_CREDITO AS 
    (
SELECT
   es.IDCEDULARURAL,
   ES.IDLIMITECONCESSAO,
   ES.IDNEGOCIO,
   CASE
       WHEN vo.NOMEATIVIDADEATUALGFT IN ('ESTUDO_E_APROVACAO', 
                                                  'ANALISE_TECNICA' , 
                                                  'APROVACAO') 
                THEN SUM(vo.VALORCONTRATADO)
   END AS LIMITE_UTILIZADO_CREDITO,
   CASE
       WHEN vo.NOMEATIVIDADEATUALGFT IN ('FORMALIZACAO', 
                                                  'LIBERACAO') 
                THEN SUM(vo.VALORCONTRATADO)
   END AS LIMITE_UTILIZADO_SICOR,
   CASE
       WHEN vo.NOMEATIVIDADEATUALGFT = 'CONDUCAO'
           OR vo.IDSITUACAOCREDITO = 22
                THEN SUM(vo.VALORCONTRATADO)
       END AS LIMITE_LIBERADO
   FROM        SESSION.EVENTO_UTILIZACAO ES
   INNER JOIN cre.VIW_OPERACAOCREDITORURAL o ON
       o.IDOPERACAOCREDITORURAL = ES.IDNEGOCIO
   INNER JOIN cre.VIW_OPERACAOCREDITO vo ON
       vo.IDOPERACAOCREDITO = o.IDOPERACAOCREDITO
   GROUP BY
       es.IDCEDULARURAL,
       ES.IDLIMITECONCESSAO,
       ES.IDNEGOCIO,
       vo.NOMEATIVIDADEATUALGFT,
       vo.IDSITUACAOCREDITO
    ) 
    WITH DATA NOT LOGGED 
ON
ROLLBACK
DELETE
   ROWS 
ON
   COMMIT
DELETE
   ROWS WITH REPLACE;


CALL ADMIN_CMD('RUNSTATS ON TABLE SESSION.VALORES_CREDITO WITH DISTRIBUTION AND DETAILED INDEXES ALL');


DECLARE GLOBAL TEMPORARY TABLE 
    SESSION.TOTAL_CCL AS 
    (
SELECT
   ila.IDLIMITECONCESSAO,
   ila.IDCEDULARURAL,
   ila.NUMPROSPECCAORURAL,
   sum(COALESCE(c.LIMITE_UTILIZADO_CREDITO, 0)) AS LIMITE_UTILIZADO_CREDITO,
   sum(COALESCE(c.LIMITE_UTILIZADO_SICOR, 0)) AS LIMITE_UTILIZADO_SICOR,
   sum(COALESCE(c.LIMITE_LIBERADO, 0)) AS LIMITE_LIBERADO,
   sum(COALESCE(ILA.VALOREVENTOSENSIBILIZACAO, 0)) AS UTILIZADO
FROM    SESSION.EVENTO_UTILIZACAO ILA
LEFT JOIN SESSION.VALORES_CREDITO c ON
   ILA.IDLIMITECONCESSAO = c.IDLIMITECONCESSAO
   AND ILA.IDNEGOCIO = C.IDNEGOCIO
GROUP BY
   ila.IDLIMITECONCESSAO,
   ila.IDCEDULARURAL,
   ila.NUMPROSPECCAORURAL
    ) 
    WITH DATA NOT LOGGED 
ON
ROLLBACK
DELETE
   ROWS 
ON
   COMMIT
DELETE
   ROWS WITH REPLACE;


CALL ADMIN_CMD ('RUNSTATS ON TABLE SESSION.TOTAL_CCL WITH DISTRIBUTION AND DETAILED INDEXES ALL');

BEGIN
   DECLARE 
        VCURSOR 
        CURSOR WITH 
            RETURN TO CALLER FOR
SELECT
   CASE
       WHEN vi2.IDINSTITUICAO = 1 
                    THEN 1
       ELSE vi2.NUMCOOPERATIVA
   END AS IFREPASSADORA ,
   vi.NUMCOOPPAI AS NUMCENTRAL ,
   vi.NUMCOOPERATIVA ,
   c.NUMCEDULA ,
   tc.NUMPROSPECCAORURAL,
   ILA.NUMPROPOSTADISTRIBUICAO ,
   ILA.IDFONTERECURSO ,
   ILA.IDPROGRAMAORIGEM ,
   j.DESCPROSPECCAOPROGRAMA ,
   po.IDFINALIDADE ,
   k.DESCTIPORECURSO ,
   po.PRAZOINICIAL ,
   po.PRAZOFINAL ,
   VARCHAR_FORMAT(LC.DATAINICIOVIGENCIA, 'DD/MM/YYYY') DATAINICIOVIGENCIA,
   VARCHAR_FORMAT(LC.DATAFIMVIGENCIA, 'DD/MM/YYYY') DATAFIMVIGENCIA,
   VARCHAR_FORMAT(LC.DATALIMITEOPERACAO, 'DD/MM/YYYY') DATALIMITEOPERACAO,
   CASE
       WHEN tg.NOMETIPOGARANTIAVINCULADA IS NULL 
                    THEN '-'
       ELSE tg.NOMETIPOGARANTIAVINCULADA
   END AS GARANTIA ,
   CASE
       WHEN pg.CODTIPOAPLICACAO IS NULL 
                    THEN '-'
       WHEN pg.CODTIPOAPLICACAO IN (1, 3) 
                    THEN 'NAO'
       ELSE 'SIM'
   END AS "CONTRAPARTIDA" ,
   CASE
       WHEN r.NOMERELACAOTIPOAPLICACAO IS NULL 
                    THEN '-'
       ELSE r.NOMERELACAOTIPOAPLICACAO
   END AS RELACAOTIPOAPLICACAO ,
   CASE
       WHEN pg.BOLACORDOCOMPENSACAO = 0 
                    THEN 'NAO'
       ELSE 'SIM'
   END AS ACORDO_COMPENSACAO ,
   ILA.PERCACORDOCOMPENSACAO ,
   ILA.PERCCONTRAPARTIDA ,
   ILA.PERCREMUNERACAOCONTRAPARTIDA ,
   LC.VALORLIMITETOTAL ,
   (COALESCE(tc.UTILIZADO, 0)) AS UTILIZADO ,
   (COALESCE(tc.LIMITE_UTILIZADO_CREDITO, 0)) AS LIMITE_UTILIZADO_CREDITO ,
   (COALESCE(tc.LIMITE_UTILIZADO_SICOR, 0)) AS LIMITE_UTILIZADO_SICOR ,
   (COALESCE(tc.LIMITE_LIBERADO, 0)) AS LIMITE_LIBERADO,
   CASE
       WHEN ila.BOLLIBERACAOBLOQUEADA = TRUE 
                    THEN 'SIM'
       ELSE 'NAO'
   END AS BLOQUEADA ,
   CASE
       WHEN LC.BOLATIVO = TRUE 
                    THEN 'SIM'
       ELSE 'NAO'
   END AS ATIVO,
   lc.IDLIMITECONCESSAO,
   ILA.IDGRUPOFONTE 
FROM    SESSION.TMP_LIMITES_UTILIZADOS a
INNER JOIN ccl.CEDULARURAL c ON
   c.IDCEDULARURAL = a.IDCEDULARURAL
LEFT JOIN SESSION.TOTAL_CCL tc ON
   a.IDLIMITECONCESSAO = tc.IDLIMITECONCESSAO
LEFT JOIN CCL.LIMITECONCESSAO LC ON
   LC.IDLIMITECONCESSAO = tc.IDLIMITECONCESSAO
LEFT JOIN ccl.INFORMACAOLIMITEALOCACAO ila ON
   ila.IDINFORMACAOLIMITEALOCACAO = lc.IDINFORMACAOLIMITE
INNER JOIN ccl.PROPOSTADISTRIBUICAORURAL p ON
   p.IDPROPOSTADISTRIBUICAORURAL = c.IDPROPOSTADISTRIBUICAORURAL
INNER JOIN SCI.VIW_INSTITUICAO vi ON
   VI.IDINSTITUICAO = c.IDINSTITUICAO
   AND VI.IDUNIDADEINST = 0
INNER JOIN SCI.VIW_INSTITUICAO vi2 ON
   VI2.IDINSTITUICAO = p.IDINSITTUICAOREPASSADORA
   AND VI2.IDUNIDADEINST = 0
LEFT JOIN ccl.PARAMETRIZACAOOPERACIONAL po ON
   po.IDPARAMETRIZACAOOPERACIONAL = ILA.IDPARAMETRIZACAOOPERACIONAL
LEFT JOIN ccl.PROSPECCAOPROGRAMA j ON
   j.CODPROSPECCAOPROGRAMA = po.CODPROSPECCAOPROGRAMA
LEFT JOIN ccl.TIPORECURSO k ON
   k.CODTIPORECURSO = po.CODTIPORECURSO
LEFT JOIN ccl.GARANTIAVINCULADAINFORMACAOLIMITEALOCACAO gv ON
   gv.IDINFORMACAOLIMITEALOCACAO = ILA.IDINFORMACAOLIMITEALOCACAO
LEFT JOIN ccl.TIPOGARANTIAVINCULADA tg ON
   tg.CODTIPOGARANTIAVINCULADA = gv.CODTIPOGARANTIAVINCULADA
LEFT JOIN ccl.PARAMETRIZACAOGARANTIA pg ON
   pg.IDPARAMETRIZACAOGARANTIA = ILA.IDPARAMETRIZACAOGARANTIA
LEFT JOIN ccl.RELACAOTIPOAPLICACAO r ON
   r.CODRELACAOTIPOAPLICACAO = pg.CODRELACAOTIPOAPLICACAO
ORDER BY
   c.NUMCEDULA ,
   vi2.IDINSTITUICAO,
   vi2.NUMCOOPERATIVA,
   vi.NUMCOOPPAI,
   vi.NUMCOOPERATIVA ,
   tc.NUMPROSPECCAORURAL,
   ILA.NUMPROPOSTADISTRIBUICAO ,
   ILA.IDFONTERECURSO ,
   ILA.IDPROGRAMAORIGEM ,
   j.DESCPROSPECCAOPROGRAMA ,
   po.IDFINALIDADE ,
   k.DESCTIPORECURSO ,
   po.PRAZOINICIAL ,
   po.PRAZOFINAL ,
   LC.DATAINICIOVIGENCIA ,
   LC.DATAFIMVIGENCIA ,
   LC.DATALIMITEOPERACAO ,
   tg.NOMETIPOGARANTIAVINCULADA,
   pg.CODTIPOAPLICACAO,
   r.NOMERELACAOTIPOAPLICACAO,
   pg.BOLACORDOCOMPENSACAO,
   ILA.PERCACORDOCOMPENSACAO ,
   ILA.PERCCONTRAPARTIDA ,
   ILA.PERCREMUNERACAOCONTRAPARTIDA ,
   LC.VALORLIMITETOTAL ,
   ila.BOLLIBERACAOBLOQUEADA,
   LC.BOLATIVO,
   lc.IDLIMITECONCESSAO,
   ILA.IDGRUPOFONTE;


OPEN VCURSOR;

END;

END
;
-- COPY-DATABASE-OBJECT: "CCL"."SPU_CCL_LIMITECCBS"
CREATE OR REPLACE PROCEDURE "CCL"."SPU_CCL_LIMITECCBS"
                                            (PCODANOSAFRA SMALLINT,
PCODPERIODOREFERENCIA SMALLINT,
PIDINSTITUICAOREPASSADORA INTEGER DEFAULT NULL,
PIDINSTITUICAOSOLICITANTE INTEGER DEFAULT NULL,
PIDINSTITUICAO INTEGER DEFAULT NULL,
PNUMCEDULA VARCHAR(50) DEFAULT NULL)
  
LANGUAGE SQL
  
DYNAMIC RESULT SETS 1
  
SPECIFIC SPU_CCL_LIMITECCBS
BEGIN
   DECLARE VSQL VARCHAR(5000);


DECLARE VSTATEMENT STATEMENT;


DECLARE GLOBAL TEMPORARY TABLE SESSION.CEDULA (IDINSTITUICAOREPASSADORA INTEGER NOT NULL,
IDINSTITUICAOSOLICITANTE INTEGER NOT NULL,
IDINSTITUICAO INTEGER NOT NULL,
NUMCEDULA VARCHAR(50),
IDCEDULARURAL INTEGER NOT NULL,
DESCANOSAFRA VARCHAR(10) NOT NULL,
DESCPERIODOREFERENCIA VARCHAR(50) NOT NULL,
NUMPROSPECCAORURAL INTEGER,
CODFASEALTERACAO SMALLINT,
VALORAPROVADO DECIMAL(31,
2),
UTILIZADO DECIMAL(31,
2)) NOT LOGGED ON
ROLLBACK
DELETE
   ROWS ON
   COMMIT
DELETE
   ROWS WITH REPLACE;


SET VSQL = 'INSERT INTO SESSION.CEDULA
               WITH PARAMETROS (CODANOSAFRA,CODPERIODOREFERENCIA,IDINSTITUICAOREPASSADORA,IDINSTITUICAOSOLICITANTE,IDINSTITUICAO,NUMCEDULA)
                                                                  AS (VALUES (CAST(? AS SMALLINT),
                                                                              CAST(? AS SMALLINT),
                                                                              CAST(? AS INTEGER),
                                                                              CAST(? AS INTEGER),
                                                                              CAST(? AS INTEGER),
                                                                              CAST(? AS VARCHAR(50))))
                SELECT p.IDINSITTUICAOREPASSADORA , 
                     p.IDINSTITUICAOSOLICITANTE , 
                     c.IDINSTITUICAO ,
                     c.NUMCEDULA , 
                     c.IDCEDULARURAL , 
                     a.DESCANOSAFRA ,  
                     p2.DESCPERIODOREFERENCIA , 
                     p3.NUMPROSPECCAORURAL ,
                     c.CODFASEALTERACAO ,
                     c.VALORAPROVADO,
                     sum(l.VALORLIMITETOTAL) UTILIZADO
                FROM ccl.ANOSAFRARURAL a INNER JOIN ccl.PERIODOREFERENCIA         p2 ON a.CODANOSAFRA                 = p2.CODANOSAFRA
                                         INNER JOIN ccl.PROPOSTADISTRIBUICAORURAL p  ON p2.CODPERIODOREFERENCIA       = p.CODPERIODOREFERENCIA
                                         INNER JOIN ccl.CEDULARURAL               c  ON p.IDPROPOSTADISTRIBUICAORURAL = c.IDPROPOSTADISTRIBUICAORURAL
                                         LEFT JOIN ccl.INFORMACAOLIMITEALOCACAO  i  ON i.IDCEDULARURAL                = c.IDCEDULARURAL
                                         LEFT JOIN ccl.INFORMACAOLIMITE           i2 ON i2.IDINFORMACAOLIMITE         = i.IDINFORMACAOLIMITEALOCACAO
                                         LEFT JOIN ccl.LIMITECONCESSAO        l  ON l.IDINFORMACAOLIMITE          = i2.IDINFORMACAOLIMITE
                                         LEFT JOIN ccl.PROSPECCAORURAL            p3 ON c.IDPROSPECCAORURAL           = p3.IDPROSPECCAORURAL
                                         CROSS JOIN PARAMETROS                    p0
                WHERE a.CODANOSAFRA              = p0.CODANOSAFRA
                  AND p2.CODPERIODOREFERENCIA    = p0.CODPERIODOREFERENCIA';


IF PIDINSTITUICAOREPASSADORA IS NOT NULL THEN 
      SET VSQL = VSQL || CHR(10)|| '  AND p.IDINSITTUICAOREPASSADORA = p0.IDINSTITUICAOREPASSADORA';

END IF;


IF PIDINSTITUICAOSOLICITANTE IS NOT NULL THEN
      SET VSQL = VSQL || CHR(10)|| '  AND p.IDINSTITUICAOSOLICITANTE = p0.IDINSTITUICAOSOLICITANTE';

END IF;


IF PIDINSTITUICAO IS NOT NULL THEN
      SET VSQL = VSQL || CHR(10)|| '  AND c.IDINSTITUICAO            = p0.IDINSTITUICAO';

END IF;


IF PNUMCEDULA IS NOT NULL THEN
      SET VSQL = VSQL || CHR(10)|| '  AND c.NUMCEDULA                = p0.NUMCEDULA';

END IF;


SET VSQL = VSQL || CHR(10)|| 'GROUP BY  p.IDINSITTUICAOREPASSADORA , p.IDINSTITUICAOSOLICITANTE , c.IDINSTITUICAO ,c.NUMCEDULA , c.IDCEDULARURAL , a.DESCANOSAFRA ,  p2.DESCPERIODOREFERENCIA, p3.NUMPROSPECCAORURAL, c.CODFASEALTERACAO, c.VALORAPROVADO';


PREPARE VSTATEMENT
FROM VSQL;


EXECUTE VSTATEMENT
   USING PCODANOSAFRA,
PCODPERIODOREFERENCIA,
PIDINSTITUICAOREPASSADORA,
PIDINSTITUICAOSOLICITANTE,
PIDINSTITUICAO,
PNUMCEDULA;


CALL ADMIN_CMD ('RUNSTATS ON TABLE SESSION.CEDULA WITH DISTRIBUTION AND DETAILED INDEXES ALL');


DECLARE GLOBAL TEMPORARY TABLE SESSION.EVENTO_UTILIZACAO AS (
SELECT
   i.IDCEDULARURAL ,
   e.VALORTICKET ,
   e.IDNEGOCIO ,
   e.VALOREVENTOSENSIBILIZACAO
FROM    ccl.INFORMACAOLIMITEALOCACAO i
INNER JOIN ccl.LIMITECONCESSAO l ON
   l.IDINFORMACAOLIMITE = i.IDINFORMACAOLIMITEALOCACAO
INNER JOIN ccl.EVENTOSENSIBILIZACAO e ON
   e.IDLIMITECONCESSAO = l.IDLIMITECONCESSAO
   AND e.CODTIPOSENSIBILIZACAO = 1
   AND e.BOLESTORNO = 0
WHERE    i.IDCEDULARURAL IN (
   SELECT
       IDCEDULARURAL
   FROM        SESSION.CEDULA)
GROUP BY
   i.IDCEDULARURAL ,
   e.VALORTICKET ,
   e.VALOREVENTOSENSIBILIZACAO,
   e.IDNEGOCIO) WITH DATA NOT LOGGED ON
ROLLBACK
DELETE
   ROWS ON
   COMMIT PRESERVE ROWS WITH REPLACE;


CALL ADMIN_CMD ('RUNSTATS ON TABLE SESSION.EVENTO_UTILIZACAO WITH DISTRIBUTION AND DETAILED INDEXES ALL');


DECLARE GLOBAL TEMPORARY TABLE SESSION.VALORES_CREDITO AS (
SELECT
   ES.IDCEDULARURAL,
   CASE
       WHEN vo.NOMEATIVIDADEATUALGFT IN ('ESTUDO_E_APROVACAO', 'ANALISE_TECNICA' , 'APROVACAO') THEN sum(vo.VALORCONTRATADO)
   END AS LIMITE_UTILIZADO_CREDITO,
   CASE
       WHEN vo.NOMEATIVIDADEATUALGFT IN ('FORMALIZACAO', 'LIBERACAO') THEN sum(vo.VALORCONTRATADO)
   END AS LIMITE_UTILIZADO_SICOR,
   CASE
       WHEN vo.NOMEATIVIDADEATUALGFT = 'CONDUCAO' OR vo.IDSITUACAOCREDITO = 22 THEN sum(vo.VALORCONTRATADO)
   END AS LIMITE_LIBERADO
FROM    SESSION.EVENTO_UTILIZACAO ES
INNER JOIN cre.VIW_OPERACAOCREDITORURAL o ON
   o.IDOPERACAOCREDITORURAL = ES.IDNEGOCIO
INNER JOIN cre.VIW_OPERACAOCREDITO vo ON
   vo.IDOPERACAOCREDITO = o.IDOPERACAOCREDITO
GROUP BY
   ES.IDCEDULARURAL,
   vo.NOMEATIVIDADEATUALGFT, 
   vo.IDSITUACAOCREDITO) WITH DATA NOT LOGGED ON
ROLLBACK
DELETE
   ROWS ON
   COMMIT PRESERVE ROWS WITH REPLACE;


CALL ADMIN_CMD ('RUNSTATS ON TABLE SESSION.VALORES_CREDITO WITH DISTRIBUTION AND DETAILED INDEXES ALL');


DECLARE GLOBAL TEMPORARY TABLE SESSION.TOTAL_CCL AS (
SELECT
   c.IDINSTITUICAOREPASSADORA ,
   c.IDINSTITUICAOSOLICITANTE ,
   c.IDINSTITUICAO ,
   c.NUMCEDULA ,
   c.DESCANOSAFRA ,
   c.DESCPERIODOREFERENCIA,
   c.VALORAPROVADO ,
   c.UTILIZADO,
   c.IDCEDULARURAL,
   c.NUMPROSPECCAORURAL,
   c.CODFASEALTERACAO ,
   CASE
       WHEN c.CODFASEALTERACAO IN (7) THEN 'Proposta'
       WHEN c.CODFASEALTERACAO IN (8, 20, 21) THEN 'Análise'
       WHEN c.CODFASEALTERACAO = 9 THEN 'Formalização'
       WHEN c.CODFASEALTERACAO = 10 THEN 'Documentação'
       WHEN c.CODFASEALTERACAO = 11 THEN 'Alocação'
       WHEN c.CODFASEALTERACAO IN (12, 13) THEN 'Propostas Canceladas'
   END AS DESCFASEALTERACAO,
   (c.VALORAPROVADO - c.UTILIZADO) DISPONIVEL
FROM    SESSION.CEDULA c
LEFT JOIN SESSION.EVENTO_UTILIZACAO ILA ON
   ILA.IDCEDULARURAL = c.IDCEDULARURAL
GROUP BY
   c.IDINSTITUICAOREPASSADORA ,
   c.IDINSTITUICAOSOLICITANTE ,
   c.IDINSTITUICAO ,
   c.NUMCEDULA ,
   c.DESCANOSAFRA ,
   c.VALORAPROVADO,
   c.UTILIZADO ,
   c.DESCPERIODOREFERENCIA,
   c.IDCEDULARURAL,
   c.NUMPROSPECCAORURAL,
   c.CODFASEALTERACAO) WITH DATA NOT LOGGED ON
ROLLBACK
DELETE
   ROWS ON
   COMMIT PRESERVE ROWS WITH REPLACE;


CALL ADMIN_CMD ('RUNSTATS ON TABLE SESSION.TOTAL_CCL WITH DISTRIBUTION AND DETAILED INDEXES ALL');

BEGIN
   DECLARE VCURSOR CURSOR WITH RETURN TO CALLER FOR
SELECT
   CASE
       WHEN c.IDINSTITUICAOREPASSADORA = 1 THEN 1
       ELSE vi.NUMCOOPERATIVA
   END AS IFREPASSADORA,
   vi2.NUMCOOPERATIVA AS CENTRAL,
   vi3.NUMCOOPERATIVA AS COOPERATIVA,
   c.NUMCEDULA ,
   c.DESCANOSAFRA ,
   COALESCE(c.VALORAPROVADO, 0) VALORAPROVADO ,
   COALESCE(C.UTILIZADO, 0) UTILIZADO,
   COALESCE(C.DISPONIVEL, 0) DISPONIVEL,
   SUM(COALESCE(ILC.LIMITE_UTILIZADO_CREDITO, 0) ) LIMITE_UTILIZADO_CREDITO,
   SUM(COALESCE(ILC.LIMITE_UTILIZADO_SICOR, 0)) LIMITE_UTILIZADO_SICOR,
   SUM(COALESCE(ILC.LIMITE_LIBERADO, 0)) LIMITE_LIBERADO,
   c.NUMPROSPECCAORURAL,
   c.DESCFASEALTERACAO
FROM    SESSION.TOTAl_CCL c
LEFT JOIN SESSION.VALORES_CREDITO ILC ON
   ILC.IDCEDULARURAL = c.IDCEDULARURAL
INNER JOIN SCI.VIW_INSTITUICAO vi ON
   vi.IDINSTITUICAO = c.IDINSTITUICAOREPASSADORA
   AND vi.NUMPAC = 0
INNER JOIN SCI.VIW_INSTITUICAO vi2 ON
   vi2.IDINSTITUICAO = c.IDINSTITUICAOSOLICITANTE
   AND vi2.NUMPAC = 0
INNER JOIN SCI.VIW_INSTITUICAO vi3 ON
   vi3.IDINSTITUICAO = c.IDINSTITUICAO
   AND vi3.NUMPAC = 0
GROUP BY
   c.IDINSTITUICAOREPASSADORA,
   vi.NUMCOOPERATIVA,
   vi2.NUMCOOPERATIVA,
   vi3.NUMCOOPERATIVA,
   c.NUMCEDULA,
   c.DESCANOSAFRA,
   c.VALORAPROVADO,
   c.DESCPERIODOREFERENCIA,
   c.IDCEDULARURAL,
   C.UTILIZADO,
   C.DISPONIVEL,
   c.NUMPROSPECCAORURAL,
   c.DESCFASEALTERACAO;


OPEN VCURSOR;

END;

END
;
-- COPY-DATABASE-OBJECT: "CRE"."ESPECIALIZARLINHA"
CREATE PROCEDURE "CRE"."ESPECIALIZARLINHA"(
    ConfederacaoID   INTEGER,    -- ID DA ISNTITUICAO DA CONFEDERACAO
    CentralID        INTEGER,    -- ID DA INSTITUICAO CENTRAL
    InstituicaoID    INTEGER,    -- ID DA INSTITUICAO COOPERATIVA, SE A ESPECIALIZACAO FOR FEITA PELA CENTRAL ESTE CAMPO DEVE SER NULO
    UsuarioID        varchar(40),
    LinhaCreditoID   INTEGER,
    LinhaCreditoMae   INTEGER,
    DataLinhaMae     DATE)
LANGUAGE SQL
MODIFIES SQL DATA
DYNAMIC RESULT SETS 1
BEGIN

--===============================================
--error handling
--===============================================

        DECLARE SQLSTATE        CHAR(5) DEFAULT '00000';
        DECLARE l_error         CHAR(5) DEFAULT '00000';
        DECLARE intError        INT;

        DECLARE CONTINUE HANDLER FOR NOT FOUND
        SET l_error = '00000';

        DECLARE CONTINUE HANDLER FOR SQLEXCEPTION, SQLWARNING

        BEGIN
                SET l_error = SQLSTATE;
                IF SUBSTR(l_error, 1, 1) >= '5' AND SUBSTR(l_error, 1, 1) <= '9' THEN
                        RESIGNAL;
                END IF;
        END;

--===============================================
-- business logic
--===============================================
        

        MERGE INTO cre.LinhaCredito PR
        USING (
                SELECT  LinhaCreditoID as IDLinhaCredito, CURRENT DATE DATACADASTROLINHA, 
                         a.IDLINHACREDITO as IDLINHACREDITOMAE, a.DATACADASTROLINHA as DATACADASTROLINHAMAE,
                         a.IDLINHACREDITOCONFEDERACAO, a.IDLINHAPASSIVA, a.IDTIPOOPERACAO, 
                         left(a.SIGLALINHACREDITO,7) || b.Sequencial as SIGLALINHACREDITO,
                         a.IDPRODUTO, a.CODCOBRANCAIOF, a.IDALIQUOTAIOF, 
                         a.IDINDICADORCALCULO, a.CODOBRIGFINANCIAIOF, a.CODSUBDIVISAOCONTABIL, a.CODCARTEIRA, a.CODPASSIVO, a.IDORIGEMRECURSO, a.CODENQUADRAMENTO,
                         a.CODCRITERIOJUROS, a.DATAINICIOVIGENCIA, a.DATAFIMVIGENCIA, a.DESCLINHACREDITO, a.NOMECOMERCIAL,
                         InstituicaoID AS IDINSTITUICAOCRIACAO, 
                         UsuarioID AS IDUSUARIOCRIACAO, UsuarioID AS IDUSUARIOALTERACAO,
                         CURRENT TIMESTAMP AS DATAHORAULTIMAALTERACAO, a.IDSISTEMACOOPERATIVO, a.PERCSPREADCALCULO, a.DATACADASTROLINHAPASSIVA,
                         CURRENT DATE DATACRIACAOLINHA, 
                         a.IDMODELOINSTRUMENTOCREDITO, a.BOLOPERADAPLATAFORMA, a.SIGLAASSUNTO, a.BOLLINHABANCO, a.CODFINALIDADE, a.CODOBRIGDESCBEM, a.DESCRESUMOLINHACREDITO, 
                         a.IDGRUPOFORMALIZACAO, a.CODGRUPOHISTORICOLANCAMENTO, a.CODGRUPOANOTACAO, a.CODANTECFORMALIZACAO
                 FROM cre.LinhaCredito as a 
                        join (
                                SELECT IDLINHACREDITOMAE,datacadastrolinhaMAE ,RIGHT(REPEAT('0',3) || CAST(MAX(SIGLALINHACREDITO) + 1  AS VARCHAR(3)),3) as Sequencial
                                FROM 
                                (
                                        SELECT  a.IDLINHACREDITOMAE,a.datacadastrolinhaMAE,
                                                CAST(right(a.SIGLALINHACREDITO,3) AS INTEGER) SIGLALINHACREDITO
                                        FROM cre.LinhaCredito as a 
                                        where a.IDLINHACREDITOMAE = LinhaCreditoMae AND a.datacadastrolinhaMAE = DataLinhaMae
                                        union all
                                        SELECT  a.IDLINHACREDITO as IDLINHACREDITOMAE,a.datacadastrolinha as datacadastrolinhaMAE,
                                                CAST(right(a.SIGLALINHACREDITO,3) AS INTEGER) SIGLALINHACREDITO
                                        FROM cre.LinhaCredito as a 
                                        where (a.IDLINHACREDITO = LinhaCreditoMae AND a.datacadastrolinha = DataLinhaMae)
                                 ) T
                                 GROUP BY IDLINHACREDITOMAE,datacadastrolinhaMAE                                 
                             ) as b on
                             a.idlinhacredito = b.IDLINHACREDITOMAE
                             and a.datacadastrolinha = b.datacadastrolinhaMAE
                where a.IDLINHACREDITO = LinhaCreditoMae AND a.datacadastrolinha = DataLinhaMae
                ) TX 
                        ON PR.IDLinhaCredito = TX.IDLinhaCredito and
                           PR.DATACADASTROLINHA = TX.DATACADASTROLINHA
        WHEN NOT MATCHED THEN
                INSERT(IDLINHACREDITO, DATACADASTROLINHA, IDLINHACREDITOMAE, DATACADASTROLINHAMAE, IDLINHACREDITOCONFEDERACAO, IDLINHAPASSIVA, IDTIPOOPERACAO, SIGLALINHACREDITO, IDPRODUTO, CODCOBRANCAIOF, IDALIQUOTAIOF, IDINDICADORCALCULO, CODOBRIGFINANCIAIOF, CODSUBDIVISAOCONTABIL, CODCARTEIRA, CODPASSIVO, IDORIGEMRECURSO, CODENQUADRAMENTO, CODCRITERIOJUROS, DATAINICIOVIGENCIA, DATAFIMVIGENCIA, DESCLINHACREDITO, NOMECOMERCIAL, IDINSTITUICAOCRIACAO, IDUSUARIOCRIACAO, IDUSUARIOALTERACAO, DATAHORAULTIMAALTERACAO, IDSISTEMACOOPERATIVO, PERCSPREADCALCULO, DATACADASTROLINHAPASSIVA, DATACRIACAOLINHA, IDMODELOINSTRUMENTOCREDITO, BOLOPERADAPLATAFORMA, SIGLAASSUNTO, BOLLINHABANCO, CODFINALIDADE, CODOBRIGDESCBEM, DESCRESUMOLINHACREDITO, IDGRUPOFORMALIZACAO, CODGRUPOHISTORICOLANCAMENTO, CODGRUPOANOTACAO, CODANTECFORMALIZACAO)
                VALUES(TX.IDLinhaCredito, TX.DATACADASTROLINHA, TX.IDLINHACREDITOMAE, TX.DATACADASTROLINHAMAE, TX.IDLINHACREDITOCONFEDERACAO, TX.IDLINHAPASSIVA, TX.IDTIPOOPERACAO, TX.SIGLALINHACREDITO, TX.IDPRODUTO, TX.CODCOBRANCAIOF, TX.IDALIQUOTAIOF, TX.IDINDICADORCALCULO, TX.CODOBRIGFINANCIAIOF, TX.CODSUBDIVISAOCONTABIL, TX.CODCARTEIRA, TX.CODPASSIVO, TX.IDORIGEMRECURSO, TX.CODENQUADRAMENTO, TX.CODCRITERIOJUROS, TX.DATAINICIOVIGENCIA, TX.DATAFIMVIGENCIA, TX.DESCLINHACREDITO, TX.NOMECOMERCIAL, TX.IDINSTITUICAOCRIACAO, TX.IDUSUARIOCRIACAO, TX.IDUSUARIOALTERACAO, TX.DATAHORAULTIMAALTERACAO,TX.IDSISTEMACOOPERATIVO, TX.PERCSPREADCALCULO, TX.DATACADASTROLINHAPASSIVA, TX.DATACRIACAOLINHA, TX.IDMODELOINSTRUMENTOCREDITO, TX.BOLOPERADAPLATAFORMA, TX.SIGLAASSUNTO, TX.BOLLINHABANCO, TX.CODFINALIDADE, TX.CODOBRIGDESCBEM, TX.DESCRESUMOLINHACREDITO, TX.IDGRUPOFORMALIZACAO, TX.CODGRUPOHISTORICOLANCAMENTO, TX.CODGRUPOANOTACAO, TX.CODANTECFORMALIZACAO);

        SET l_error = SQLSTATE ;

        IF LEFT(l_error, 2 ) > '02' THEN
               SET intError = intError + 1 ;
        END IF;

        MERGE INTO cre.VALORMINMAXPARCELALINHA PR
        USING (
                SELECT 
                        LinhaCreditoID as IDLinhaCredito, CURRENT DATE DATACADASTROLINHA, 
                        a.CODPERIODICIDADEPAGAMENTO, a.QTDMINPRESTACAO, a.QTDMAXPRESTACAO
                FROM cre.VALORMINMAXPARCELALINHA as a 
                where a.IDLINHACREDITO = LinhaCreditoMae AND a.datacadastrolinha = DataLinhaMae
                ) TX 
                        ON PR.IDLinhaCredito = TX.IDLinhaCredito and
                           PR.DATACADASTROLINHA = TX.DATACADASTROLINHA
        WHEN NOT MATCHED THEN
                INSERT(IDLINHACREDITO, DATACADASTROLINHA, CODPERIODICIDADEPAGAMENTO, QTDMINPRESTACAO, QTDMAXPRESTACAO)
                VALUES(TX.IDLinhaCredito, TX.DATACADASTROLINHA, TX.CODPERIODICIDADEPAGAMENTO, TX.QTDMINPRESTACAO, TX.QTDMAXPRESTACAO);
        
        SET l_error = SQLSTATE ;

        IF LEFT(l_error, 2 ) > '02' THEN
               SET intError = intError + 1 ;
        END IF;

        MERGE INTO cre.VALORMINMAXLINHA PR
        USING (
                select LinhaCreditoID as IDLinhaCredito, CURRENT DATE DATACADASTROLINHA, 
                        a.CODTIPOALTERACAOTAXA, a.PERCTAXAJUROSMIN, a.PERCTAXAJUROSMAX, a.PERCMINMULTA,
                        a.PERCMAXMULTA, a.PERCTAXAMORAMAX, a.PERCTAXAMORAMIN, a.VALORMINOPERACAO, 
                        a.VALORMAXOPERACAO, a.QTDMAXDIAOPERACAO, a.QTDMAXEMITENTE, a.CODAJUSTEFERIADO, 
                        a.QTDMAXOPERACAOCLIENTE, a.VALORMAXOPERACAOCLIENTE, a.CODCONDICAOVALORMAXCLIENTE, 
                        a.QTDMINIDADE, a.QTDMAXIDADE, a.QTDMINDIAOPERACAO 
                FROM cre.VALORMINMAXLINHA as a 
                where a.IDLINHACREDITO = LinhaCreditoMae AND a.datacadastrolinha = DataLinhaMae
                ) TX 
                        ON PR.IDLinhaCredito = TX.IDLinhaCredito and
                           PR.DATACADASTROLINHA = TX.DATACADASTROLINHA
        WHEN NOT MATCHED THEN
                INSERT(IDLINHACREDITO, DATACADASTROLINHA, CODTIPOALTERACAOTAXA, PERCTAXAJUROSMIN, PERCTAXAJUROSMAX, PERCMINMULTA, PERCMAXMULTA, PERCTAXAMORAMAX, PERCTAXAMORAMIN, VALORMINOPERACAO, VALORMAXOPERACAO, QTDMAXDIAOPERACAO, QTDMAXEMITENTE, CODAJUSTEFERIADO, QTDMAXOPERACAOCLIENTE, VALORMAXOPERACAOCLIENTE, CODCONDICAOVALORMAXCLIENTE, QTDMINIDADE, QTDMAXIDADE, QTDMINDIAOPERACAO) 
                VALUES(TX.IDLinhaCredito, TX.DATACADASTROLINHA, TX.CODTIPOALTERACAOTAXA, TX.PERCTAXAJUROSMIN, TX.PERCTAXAJUROSMAX, TX.PERCMINMULTA, TX.PERCMAXMULTA, TX.PERCTAXAMORAMAX, TX.PERCTAXAMORAMIN, TX.VALORMINOPERACAO, TX.VALORMAXOPERACAO, TX.QTDMAXDIAOPERACAO, TX.QTDMAXEMITENTE, TX.CODAJUSTEFERIADO, TX.QTDMAXOPERACAOCLIENTE, TX.VALORMAXOPERACAOCLIENTE, TX.CODCONDICAOVALORMAXCLIENTE, TX.QTDMINIDADE, TX.QTDMAXIDADE, TX.QTDMINDIAOPERACAO);

        SET l_error = SQLSTATE ;

        IF LEFT(l_error, 2 ) > '02' THEN
               SET intError = intError + 1 ;
        END IF;

        MERGE INTO cre.REGRAESPECIALIZACAO PR
        USING (
                select  LinhaCreditoID as IDLinhaCredito, CURRENT DATE DATACADASTROLINHA, 
                        a.CODPARAMETROLINHA, a.BOLCOOPCENTRALALTERA, a.BOLCOOPSINGULARALTERA, a.BOLREGRAEMCONFLITO
                FROM cre.REGRAESPECIALIZACAO as a
                where a.IDLINHACREDITO = LinhaCreditoMae AND a.datacadastrolinha = DataLinhaMae
                ) TX 
                        ON PR.IDLinhaCredito = TX.IDLinhaCredito and
                           PR.DATACADASTROLINHA = TX.DATACADASTROLINHA

        WHEN NOT MATCHED THEN
                INSERT(IDLINHACREDITO, DATACADASTROLINHA, CODPARAMETROLINHA, BOLCOOPCENTRALALTERA, BOLCOOPSINGULARALTERA, BOLREGRAEMCONFLITO)
                VALUES(TX.IDLinhaCredito, TX.DATACADASTROLINHA, TX.CODPARAMETROLINHA, TX.BOLCOOPCENTRALALTERA, TX.BOLCOOPSINGULARALTERA, TX.BOLREGRAEMCONFLITO);


        SET l_error = SQLSTATE ;

        IF LEFT(l_error, 2 ) > '02' THEN
               SET intError = intError + 1 ;
        END IF;

        MERGE INTO cre.PERFILCONTABILLINHA PR
        USING (
                select  LinhaCreditoID as IDLinhaCredito, CURRENT DATE DATACADASTROLINHA, a.CODPERFILCONTABIL
                FROM cre.PERFILCONTABILLINHA as a
                where a.IDLINHACREDITO = LinhaCreditoMae AND a.datacadastrolinha = DataLinhaMae
                ) TX 
                        ON PR.IDLinhaCredito = TX.IDLinhaCredito and
                           PR.DATACADASTROLINHA = TX.DATACADASTROLINHA
        WHEN NOT MATCHED THEN
                INSERT(CODPERFILCONTABIL, IDLINHACREDITO, DATACADASTROLINHA)
                VALUES(TX.CODPERFILCONTABIL, TX.IDLinhaCredito, TX.DATACADASTROLINHA);

        SET l_error = SQLSTATE ;

        IF LEFT(l_error, 2 ) > '02' THEN
               SET intError = intError + 1 ;
        END IF;


        MERGE INTO cre.PARAMETROLINHARURAL PR
        USING (
                select  LinhaCreditoID as IDLinhaCredito, CURRENT DATE DATACADASTROLINHA,
                        a.CODOBRIGEXIGEORIENTACAOTECNICA, a.CODOBRIGARMAZEMCERTIFICADO, a.CODOBRIGEXIGEORCAMENTO, a.CODOBRIGEXIGEPROJETO, 
                        a.IDATIVIDADEBACEN, a.IDFINALIDADEBACEN, a.BOLEQUALIZAVEL, a.BOLREBATEJUROS, a.BOLPGPAF, a.BOLEXIGECEDULAMAE, 
                        a.BOLFINANCIAORIENTACAOTECNICA, a.PERCMAXFINANCIADOOPERACAO, a.QTDEMAXEMPRE, a.IDFONTERECURSOBACEN, a.CODOBRIGATORIEDADEPGPAF 
                FROM cre.PARAMETROLINHARURAL as a 
                where a.IDLINHACREDITO = LinhaCreditoMae AND a.datacadastrolinha = DataLinhaMae
                ) TX 
                        ON PR.IDLinhaCredito = TX.IDLinhaCredito and
                           PR.DATACADASTROLINHA = TX.DATACADASTROLINHA
        WHEN NOT MATCHED THEN
                INSERT(IDLINHACREDITO, DATACADASTROLINHA, CODOBRIGEXIGEORIENTACAOTECNICA, CODOBRIGARMAZEMCERTIFICADO, CODOBRIGEXIGEORCAMENTO, CODOBRIGEXIGEPROJETO, IDATIVIDADEBACEN, IDFINALIDADEBACEN, BOLEQUALIZAVEL, BOLREBATEJUROS, BOLPGPAF, BOLEXIGECEDULAMAE, BOLFINANCIAORIENTACAOTECNICA, PERCMAXFINANCIADOOPERACAO, QTDEMAXEMPRE, IDFONTERECURSOBACEN, CODOBRIGATORIEDADEPGPAF)
                VALUES(TX.IDLinhaCredito, TX.DATACADASTROLINHA, TX.CODOBRIGEXIGEORIENTACAOTECNICA, TX.CODOBRIGARMAZEMCERTIFICADO, TX.CODOBRIGEXIGEORCAMENTO, TX.CODOBRIGEXIGEPROJETO, TX.IDATIVIDADEBACEN, TX.IDFINALIDADEBACEN, TX.BOLEQUALIZAVEL, TX.BOLREBATEJUROS, TX.BOLPGPAF, TX.BOLEXIGECEDULAMAE, TX.BOLFINANCIAORIENTACAOTECNICA, TX.PERCMAXFINANCIADOOPERACAO, TX.QTDEMAXEMPRE, TX.IDFONTERECURSOBACEN, TX.CODOBRIGATORIEDADEPGPAF);
        
        SET l_error = SQLSTATE ;

        IF LEFT(l_error, 2 ) > '02' THEN
               SET intError = intError + 1 ;
        END IF;

        MERGE INTO cre.PARAMETROLINHARURALPROGRAMABACEN PR
