-- COPY-DATABASE-OBJECT: "CRE"."SPU_CONSULTA_GRUPO_ECONOMICO"
CREATE OR REPLACE PROCEDURE "CRE"."SPU_CONSULTA_GRUPO_ECONOMICO" (PIDINSTITUICAO INTEGER,
                                                                  PNUMCPFCNPJ    VARCHAR(14))
  LANGUAGE SQL
  DYNAMIC RESULT SETS 1
  SPECIFIC SPU_CONSULTA_GRUPO_ECONOMICO
BEGIN

   DELETE FROM CRE.GTTGRUPOECONOMICO;

   INSERT INTO CRE.GTTGRUPOECONOMICO (IDGRUPOECONOMICO)
   SELECT IDGRUPOECONOMICO
   FROM CLI.VIW_GRUPO_ECONOMICO 
    WHERE IDINSTITUICAO = PIDINSTITUICAO
      AND NUMCPFCNPJ    = PNUMCPFCNPJ;

   CALL ADMIN_CMD ('RUNSTATS ON TABLE CRE.GTTGRUPOECONOMICO WITH DISTRIBUTION AND DETAILED INDEXES ALL');       
  
   BEGIN
      DECLARE VCURSOR CURSOR WITH RETURN FOR SELECT B.IDPESSOA, 
                                                    B.NUMCPFCNPJ, 
                                                    B.IDGRUPOECONOMICO, 
                                                    B.DESCGRUPOECONOMICO 
                                             FROM CRE.GTTGRUPOECONOMICO A INNER JOIN TABLE (SELECT B.IDPESSOA, 
                                                                                                   B.NUMCPFCNPJ, 
                                                                                                   B.IDGRUPOECONOMICO, 
                                                                                                   B.DESCGRUPOECONOMICO 
                                                                                             FROM CLI.VIW_GRUPO_ECONOMICO B --CLI.VIW_GRUPO_ECONOMICO  GE 
                                                                                             WHERE B.IDGRUPOECONOMICO = A.IDGRUPOECONOMICO
                                                                                               AND B.IDINSTITUICAO    = PIDINSTITUICAO
                                                                                             FETCH FIRST 99999 ROWS ONLY) B ON 1=1;
      OPEN VCURSOR;   
   END;
END;
;
-- COPY-DATABASE-OBJECT: "CRE"."SPU_CONSULTA_LINHAS_REPACTUACAO"
--SPU_CONSULTA_LINHAS_REPACTUACAO ;

CREATE OR REPLACE PROCEDURE "CRE"."SPU_CONSULTA_LINHAS_REPACTUACAO" (PIDINSTITUICAO INTEGER,PIDUNIDADEINST INTEGER,PIDSITUACAOCREDITO SMALLINT,PIDPRODUTO SMALLINT,PCODTIPOPESSOA SMALLINT,PCODGRUPOOPERACAO XML,PIDGRUPOS XML)
  LANGUAGE SQL
  DYNAMIC RESULT SETS 1
SPECIFIC SQL201126095258546
BEGIN
   DECLARE VQTD SMALLINT;
   DECLARE GLOBAL TEMPORARY TABLE SESSION.TEMP   (IDLINHAATUAL INTEGER,IDLINHACREDITO INTEGER, DATACADASTROLINHA TIMESTAMP) NOT LOGGED ON ROLLBACK DELETE ROWS ON COMMIT PRESERVE ROWS WITH REPLACE;
   FOR REG AS CUR1 CURSOR FOR SELECT DISTINCT LINHAATUAL.* 
                              FROM CRE.LINHAVERSAOATUAL LINHAATUAL 
                               INNER JOIN CRE.LINHACREDITO LINHACRED ON 
                                    LINHAATUAL.IDLINHACREDITO = LINHACRED.IDLINHACREDITO 
                                        AND LINHAATUAL.DATACADASTROLINHA = LINHACRED.DATACADASTROLINHA 
                               INNER JOIN CRE.LINHATIPOPESSOA LINHAPESSOA ON
                                    LINHAPESSOA.IDLINHACREDITO = LINHACRED.IDLINHACREDITO 
                                        AND LINHAPESSOA.DATACADASTROLINHA = LINHACRED.DATACADASTROLINHA 
                               INNER JOIN CRE.LINHAGRUPOOPERACAO GRUPOOPLINHA ON
                                    GRUPOOPLINHA.IDLINHACREDITO = LINHACRED.IDLINHACREDITO 
                                        AND GRUPOOPLINHA.DATACADASTROLINHA = LINHACRED.DATACADASTROLINHA 
                               INNER JOIN CRE.INSTITUICAOLINHA INSTLINHA ON
                                    INSTLINHA.IDLINHAATUAL = LINHAATUAL.IDLINHAATUAL 
                              WHERE LINHACRED.IDPRODUTO = PIDPRODUTO 
                                AND GRUPOOPLINHA.CODGRUPOOPERACAO IN (SELECT CODGRUPOOPERACAO FROM XMLTABLE('$c/rs/r' passing PCODGRUPOOPERACAO AS "c" COLUMNS CODGRUPOOPERACAO SMALLINT PATH '.'))
                                AND LINHAPESSOA.CODTIPOPESSOA     = PCODTIPOPESSOA 
                                AND INSTLINHA.IDSITUACAOCREDITO   = PIDSITUACAOCREDITO 
                                AND INSTLINHA.IDINSTITUICAO       = PIDINSTITUICAO
   DO 
      SET VQTD = 0;
      SET VQTD = (SELECT COUNT(*) QTD
                  FROM XMLTABLE('$c/rs/r' passing PIDGRUPOS AS "c" COLUMNS IDGRUPO INTEGER PATH '.') G
                  WHERE EXISTS (SELECT 1
                                FROM CRE.LINHAGRUPOLIBERACAO LINHAGRUPO 
                                   INNER JOIN CRE.LINHAGRUPOLIBERACAODETALHE GRUPODETALHE ON 
                                       LINHAGRUPO.IDGRUPOLINHALIBERACAO = GRUPODETALHE.IDGRUPOLINHALIBERACAO 
                                   INNER JOIN CRE.LINHAGRUPOVINCULOLIBERACAO GRUPOVINCULO ON 
                                       GRUPOVINCULO.IDGRUPOLINHALIBERACAO = LINHAGRUPO.IDGRUPOLINHALIBERACAO 
                                WHERE LINHAGRUPO.BOLATIVO = 1 
                                  AND LINHAGRUPO.IDINSTITUICAO   = PIDINSTITUICAO
                                  AND GRUPODETALHE.IDUNIDADEINST = PIDUNIDADEINST 				
                                  AND GRUPOVINCULO.IDLINHAATUAL  = REG.IDLINHAATUAL
                                  AND GRUPODETALHE.IDGRUPO       = G.IDGRUPO
                                UNION 
                                SELECT 1
                                FROM CRE.UNIDADEINSTITUICAOLINHA UNIDINSTLINHA 
                                WHERE UNIDINSTLINHA.IDINSTITUICAO = PIDINSTITUICAO
                                  AND UNIDINSTLINHA.IDUNIDADEINST = PIDUNIDADEINST 
                                  AND UNIDINSTLINHA.IDLINHAATUAL  = REG.IDLINHAATUAL
                                  AND UNIDINSTLINHA.IDGRUPO       = G.IDGRUPO));

      IF VQTD > 0 THEN
         INSERT INTO SESSION.TEMP (IDLINHAATUAL,IDLINHACREDITO, DATACADASTROLINHA)
         VALUES (REG.IDLINHAATUAL,REG.IDLINHACREDITO,REG.DATACADASTROLINHA);
      END IF;
   END FOR;
   BEGIN
      DECLARE VCURSOR1 CURSOR WITH RETURN FOR SELECT *
                                              FROM SESSION.TEMP;       
   
      OPEN VCURSOR1;
   END;
END
;
