                                                                       (8, 3, ''Aguardando Retorno SICOR'', ''APROVACAO'', ''SICOR_INFO'', ''SICOR_INFO'', ''access_alarms'', NULL) ,
                                                                       (9, 3, ''Erro no SICOR'',''APROVACAO'',''SICOR_ERRO'', ''SICOR_ERRO'', ''block'', NULL),
                                                                       --Na fase de AprovaÃ§Ã£o, envio a instituiÃ§Ã£o externa (BASA ou BNB),
                                                                       (10, 3, ''Aguardando Protocolo BNB'',''APROVACAO'',''BNB_AGUARDANDO_INCLUSAO'', ''BNB_AGUARDANDO_INCLUSAO'', ''add_alarm'', NULL) ,
                                                                       (11, 3, ''Erro Protocolo BNB'',''APROVACAO'',''BNB_INCLUSAO_ERRO'', ''BNB_INCLUSAO_ERRO'', ''block'', NULL)  ,
                                                                       (12, 2, ''Erro Protocolo BASA'',''APROVACAO'',''BASA_INCLUSAO_ERRO'', ''BASA_INCLUSAO_ERRO'', ''block'', NULL),
                                                                       --Na fase de LiberaÃ§Ã£o,
                                                                       (13, 2, ''Analisar liberaÃ§Ã£o no CCS'',''LIBERACAO'',''CCS_LIBERACAO_PENDENTE'', ''CCS_LIBERACAO_PENDENTE'', ''playlist_add_check'', NULL),
                                                                       (14, 2, ''Aguardando PL BASA'',''LIBERACAO'', ''BASA_LIBERACAO_PENDENTE'', ''BASA_LIBERACAO_ERRO'', ''alarm_on'', NULL),
                                                                       (15, 2, ''Aguardando Recurso BASA'',''LIBERACAO'',''BASA_LIBERACAO_APROVADA'', ''BASA_LIBERACAO_APROVADA'', ''local_atm'', NULL),
                                                                       (16, 1, ''Analisar liberaÃ§Ã£o no CCS'',''LIBERACAO'','''', '''', ''playlist_add_check'', NULL),
                                                                       (17, 1, ''Aguardando PL BB'',''LIBERACAO'',''BB_LIBERACAO_PENDENTE'', ''BB_LIBERACAO_PENDENTE'', ''alarm_on'', NULL),
                                                                       (18, 1, ''Aguardando Recurso BB'',''LIBERACAO'',''BB_LIBERACAO_APROVADA'', ''BB_LIBERACAO_APROVADA'', ''local_atm'', NULL),
                                                                       (19, 2, ''Aguardando Recurso BB'',''ESTUDO_E_APROVACAO'',''BNDES_SUCESSO'', ''BNDES_SUCESSO'', ''local_atm'', NULL))
                          
                          --total.tipoFundo AS fundoOrigem,                                                                                             
                   SELECT REL_MESA.FUNDOPERMITIDO AS fundoOrigem,
                          COALESCE(total.total, 0) AS total,
                          REL_MESA.ORDEM AS ordem,
                          --total,
                          REL_MESA.NOMEFASE AS nomeFase,
                          REL_MESA.NOMEATIVIDADEATUALGFT AS nomeAtividadeAtualGft,
                          REL_MESA.NOMESUBATIVIDADEATUALGFT AS subAtividadeGft,   
                          REL_MESA.NOMEICONESTATUS AS icone,
                          CASE WHEN total.tipoFundo = 3 THEN TRUE ELSE FALSE END AS isPropostaBNB,
                          CASE WHEN total.tipoFundo = 2 THEN TRUE ELSE FALSE END AS isPropostaBASA,
                          CASE WHEN REL_MESA.NOMESUBATIVIDADEATUALGFT = ''BASA_INCLUSAO_ERRO'' THEN TRUE ELSE FALSE END AS isPropostaErroBASA
                    FROM RELATORIO_MESAOPERACOES REL_MESA CROSS JOIN PARAMETROS P
                                      LEFT JOIN (SELECT PROFC.NUMTIPOFUNDOCONSTITUCIONAL AS tipoFundo,
                                                        COALESCE( COUNT(DISTINCT OPCRE.NUMPROPOSTA), 0 ) AS TOTAL,
                                                        OPCRE.NOMEATIVIDADEATUALGFT,
                                                        OPCRE.NOMESUBATIVIDADEATUALGFT         
                                                 FROM PARAMETROS P CROSS JOIN CRE.OPERACAOCREDITO OPCRE INNER JOIN FCO.OPERACAOCREDITOFC OPFC  ON OPFC.IDOPERACAOCREDITO = OPCRE.IDOPERACAOCREDITO
                                                                                                        INNER JOIN FCO.LINHAFC           LINFC ON LINFC.IDLINHAFC        = OPFC.IDLINHAFC
                                                                                                        INNER JOIN FCO.PROGRAMAFC        PROFC ON PROFC.IDPROGRAMAFC     = LINFC.IDPROGRAMAFC';
   IF PNUMCPFCNPJ IS NOT NULL THEN
      SET VSQL = VSQL || '                                                   INNER JOIN TABLE (SELECT VP.IDPESSOA,
                                                                                                      VP.IDINSTITUICAO
                                                                                               FROM CLI.VIW_PESSOA VP
                                                                                               WHERE VP.NUMCPFCNPJ = P.NUMCPFCNPJ) TOMADOROP ON TOMADOROP.IDPESSOA      = OPFC.IDPESSOA
                                                                                                                                            AND TOMADOROP.IDINSTITUICAO = OPFC.IDINSTITUICAOOPERACAO';
   END IF;
   IF PNUMCOOPERATIVA IS NOT NULL AND PNUMCOOPERATIVA <> 1 THEN
      SET VSQL = VSQL || '                                                   INNER JOIN SCI.VIW_INSTITUICAO INSTLOCAL ON OPCRE.IDINSTITUICAOLOCALNEGOCIO = INSTLOCAL.IDINSTITUICAO
                                                                                                                     AND OPCRE.IDUNIDADEINSTLOCALNEGOCIO = INSTLOCAL.IDUNIDADEINST';
   END IF;                                                                                                                     
   SET VSQL = VSQL || '                                                   WHERE 1=1 ';
   IF PTIPOHIERARQUIAINSTITUICAOENUM <> PTIPOHIERARQUIAINSTITUICAOBANCOOB THEN
      SET VSQL = VSQL || '                                                   AND OPCRE.IDINSTITUICAOLOCALNEGOCIO = P.IDINSTITUICAOUSUARIOLOGADO';
      IF PIDUNIDADEINSTITUICAOUSUARIOLOGADO <> 0 THEN
         SET VSQL = VSQL || '                                                   AND OPCRE.IDUNIDADEINSTLOCALNEGOCIO = P.IDUNIDADEINSTITUICAOUSUARIOLOGADO';
      END IF;
      IF PLISTAINSTITUICOES IS NOT NULL THEN
         SET VSQL = VSQL || '                                                   AND OPCRE.IDINSTITUICAOLOCALNEGOCIO IN (SELECT IDINSTITUICAO
                                                                                                                        FROM XMLTABLE(''$c/rs/r'' passing cast (P.LISTAINSTITUICOES as xml) AS "c" COLUMNS IDINSTITUICAO INTEGER PATH ''.''))';
      END IF;
   END IF;   
/*FILTROS DE PESQUISA*/
        --      AND PROFC.NUMTIPOFUNDOCONSTITUCIONAL = :numTipoFundoConstitucional
   IF PNUMCONTRATOCREDITO IS NOT NULL THEN
      SET VSQL = VSQL || '                                                   AND OPFC.NUMCONTRATOCREDITO = P.NUMCONTRATOCREDITO';
   END IF;
   IF PNUMCOOPERATIVA IS NOT NULL THEN
      IF PNUMCOOPERATIVA = 1 THEN
      --AQUI
         SET VSQL = VSQL || '                                                   AND OPFC.IDINSTITUICAOLOCALNEGOCIO  = 1';
      ELSE            
         SET VSQL = VSQL || '                                                   AND INSTLOCAL.NUMCOOPERATIVA = P.NUMCOOPERATIVA';         
      END IF;
   END IF;
   IF PNUMPROPOSTA IS NOT NULL THEN
      SET VSQL = VSQL || '                                                   AND OPCRE.NUMPROPOSTA = P.NUMPROPOSTA';
   END IF;
   IF PSITUACAOCONTRATO IS NULL THEN
      SET VSQL = VSQL || '                                                   AND OPCRE.IDSITUACAOCREDITO IN (20, 25, 26, 96)';
   ELSEIF PSITUACAOCONTRATO THEN
          SET VSQL = VSQL || '                                                   AND OPCRE.IDSITUACAOCREDITO IN (20, 96)';
       ELSE
          SET VSQL = VSQL || '                                                   AND OPCRE.IDSITUACAOCREDITO IN (25, 26)';
   END IF;
   
   SET VSQL = VSQL || '                                                 GROUP BY PROFC.NUMTIPOFUNDOCONSTITUCIONAL,               
                                                                                 OPCRE.NOMEATIVIDADEATUALGFT,
                                                                                 OPCRE.NOMESUBATIVIDADEATUALGFT) AS TOTAL ON TOTAL.TIPOFUNDO = REL_MESA.FUNDOPERMITIDO
                                                                                                                         AND TOTAL.NOMEATIVIDADEATUALGFT = REL_MESA.NOMEATIVIDADEATUALGFT
                                                                                                                         AND (COALESCE(TOTAL.NOMESUBATIVIDADEATUALGFT, '''') = COALESCE(REL_MESA.NOMESUBATIVIDADEATUALGFT, '''')
                                                                                                                           OR COALESCE(total.NOMESUBATIVIDADEATUALGFT, '''') = COALESCE(REL_MESA.NOMESUBATIVIDADEATUALSECGFT, ''''))
                WHERE P.NUMTIPOFUNDOCONSTITUCIONAL IS NULL OR TOTAL.TIPOFUNDO = P.NUMTIPOFUNDOCONSTITUCIONAL
   ORDER BY 1,5';
    
   CALL DBMS_OUTPUT.PUT_LINE (VSQL);
               
   PREPARE VSTATEMENTCURSOR FROM VSQL;
   
   OPEN VCURSOR USING PTIPOHIERARQUIAINSTITUICAOENUM,PTIPOHIERARQUIAINSTITUICAOBANCOOB,PIDINSTITUICAOUSUARIOLOGADO,PLISTAINSTITUICOES,PIDUNIDADEINSTITUICAOUSUARIOLOGADO,PNUMCONTRATOCREDITO,PNUMCOOPERATIVA,PNUMCPFCNPJ,PNUMPROPOSTA,PSITUACAOCONTRATO,PNUMTIPOFUNDOCONSTITUCIONAL;

END;
;
-- COPY-DATABASE-OBJECT: "CRE"."SPU_LIMPA_CRITERIOREGRAPESQUISA"
CREATE OR REPLACE PROCEDURE "CRE"."SPU_LIMPA_CRITERIOREGRAPESQUISA"
   LANGUAGE SQL
   AUTONOMOUS
SPECIFIC SPU_LIMPA_CRITERIOREGRAPESQUISA
BEGIN
   DECLARE VQTD INTEGER DEFAULT 0;
   DECLARE VERROTRUNCATE BOOLEAN DEFAULT FALSE;
   DECLARE CONTINUE HANDLER FOR SQLEXCEPTION 
   BEGIN 
      SET VERROTRUNCATE = TRUE;
   END;
   SET CURRENT LOCK TIMEOUT 30;--NOT WAIT;   
   COMMIT;
   TRUNCATE TABLE CRE.CRITERIOREGRAPESQUISA REUSE STORAGE IMMEDIATE; --VAI ESPERAR 30 SEGUNDOS
   COMMIT;
   IF VERROTRUNCATE THEN
       SET CURRENT MDC ROLLOUT MODE IMMEDIATE;
       SET CURRENT LOCK TIMEOUT NOT WAIT; 
ins_loop:
       FOR V_LISTA AS CUR1 CURSOR WITH HOLD FOR SELECT DISTINCT IDINSTITUICAO
                                                FROM CRE.CRITERIOREGRAPESQUISA
                                                WITH UR 
       DO
          SET VQTD = VQTD + 1;
          DELETE FROM CRE.CRITERIOREGRAPESQUISA
          WHERE IDINSTITUICAO = V_LISTA.IDINSTITUICAO;
          COMMIT;
          IF VQTD > 3000 THEN --POR SEGURANÃ‡A
             LEAVE ins_loop;
          END IF;          
      END FOR;
   END IF;
   BEGIN   
      CALL ADMIN_CMD ('RUNSTATS ON TABLE CRE.CRITERIOREGRAPESQUISA ON ALL COLUMNS WITH DISTRIBUTION DEFAULT NUM_FREQVALUES 200 NUM_QUANTILES 200 AND DETAILED INDEXES ALL ALLOW WRITE ACCESS TABLESAMPLE SYSTEM(1) INDEXSAMPLE SYSTEM(1)');
   END;             
END;
;
