-- COPY-DATABASE-OBJECT: "DBSYS"."PRC_TUNING_AMBIENTE"
--/
CREATE OR REPLACE PROCEDURE "DBSYS"."PRC_TUNING_AMBIENTE" ()
   RESULT SETS 1
   LANGUAGE SQL
   SPECIFIC PRC_TUNING_AMBIENTE
BEGIN
   DECLARE VCURSOR CURSOR WITH RETURN FOR 
      SELECT RPAD(TO_CHAR(CURRENT TIMESTAMP,'DD/MM/YYYY HH24:MI'),18,' ') "Data",
             CURRENT SERVER    "Banco de Dados",
             CASE WHEN A.HOST_NAME LIKE '%db2d%' THEN 'Desenvolvimento'
                  WHEN A.HOST_NAME LIKE '%db2t%' THEN 'Teste Integrado'
                  WHEN A.HOST_NAME LIKE '%db2h%' THEN 'Homologacao'
                  WHEN A.HOST_NAME LIKE '%db2p%' THEN 'Producao'
             END               "Ambiente",
             A.HOST_NAME       "Equipamento Servidor",
             CURRENT USER      "Usuirio corrente", 
             CLIENT WRKSTNNAME "Equipamento usuirio corrente",
             B.SERVICE_LEVEL   "Versao do Banco de Dados"
      FROM TABLE(SYSPROC.ENV_GET_SYS_INFO()) A CROSS JOIN TABLE (SYSPROC.ENV_GET_INST_INFO()) B;
   OPEN VCURSOR;
END;
;
-- COPY-DATABASE-OBJECT: "DBSYS"."PRC_TUNING_BIND_VARIABLES"
CREATE OR REPLACE PROCEDURE "DBSYS"."PRC_TUNING_BIND_VARIABLES" (PTABSCHEMA VARCHAR(10) DEFAULT NULL)
   RESULT SETS 1
   LANGUAGE SQL
   SPECIFIC PRC_TUNING_BIND_VARIABLES
BEGIN
   DECLARE VCURSOR CURSOR WITH RETURN FOR 
      SELECT ROW_NUMBER()             OVER (ORDER BY QTD DESC) "Numero",
             STMTID                            "Valor Hash SQL",
             CASE WHEN EDESISTEMA = 1 THEN 'Verificar problema de Bind Variable' ELSE 'Ignorar! O SQL não é de Sistema' END "Diagnostico",
             QTD                               "Qtd. instancias do comando SQL no cache",
             NUM_EXECUTIONS                    "Qtd. Execucoes",
             IO_READS_RATIO                    "Qt. Media de blocos lidos",
             ROWS_READ_RATIO                   "Qt. Media de registros lidos",
             (SELECT CAST(STMT_TEXT AS VARCHAR(32000)) FROM TABLE(MON_GET_PKG_CACHE_STMT (null, O.EXECUTABLE_ID, null, -2)))
                                               "Texto do comando SQL",
             ' '                               "Comentarios do Analista"
      FROM (SELECT VARCHAR(STMTID) STMTID,
                   C.QUERY_COST_ESTIMATE                                              QUERY_COST_ESTIMATE,
                   SUM(NUM_EXECUTIONS)     OVER (PARTITION BY STMTID,SEMANTIC_ENV_ID) NUM_EXECUTIONS,
                   SUM(POOL_DATA_P_READS+POOL_TEMP_DATA_P_READS+POOL_XDA_P_READS+POOL_TEMP_XDA_P_READS+POOL_INDEX_P_READS+POOL_TEMP_INDEX_P_READS+POOL_DATA_GBP_P_READS+POOL_INDEX_GBP_P_READS+POOL_XDA_GBP_P_READS+POOL_COL_P_READS+POOL_TEMP_COL_P_READS+POOL_COL_GBP_P_READS+POOL_DATA_L_READS+POOL_TEMP_DATA_L_READS+POOL_XDA_L_READS+POOL_TEMP_XDA_L_READS+POOL_INDEX_L_READS+POOL_TEMP_INDEX_L_READS+POOL_DATA_GBP_L_READS+POOL_INDEX_GBP_L_READS+POOL_XDA_GBP_L_READS+POOL_COL_L_READS+POOL_TEMP_COL_L_READS+POOL_COL_GBP_L_READS) OVER (PARTITION BY STMTID,SEMANTIC_ENV_ID)
                  /SUM(NUM_EXECUTIONS)     OVER (PARTITION BY STMTID,SEMANTIC_ENV_ID) IO_READS_RATIO,
                   SUM(ROWS_READ)          OVER (PARTITION BY STMTID,SEMANTIC_ENV_ID) 
                  /SUM(NUM_EXECUTIONS)     OVER (PARTITION BY STMTID,SEMANTIC_ENV_ID) ROWS_READ_RATIO,
                   ROW_NUMBER()            OVER (PARTITION BY STMTID,SEMANTIC_ENV_ID ORDER BY 1) SEQ,
                   COUNT(*)                OVER (PARTITION BY STMTID,SEMANTIC_ENV_ID)            QTD,
                   C.EXECUTABLE_ID,
                   CASE WHEN A.SESSION_AUTH_ID             LIKE 'USR%' 
                         AND A.SESSION_AUTH_ID         NOT IN ('USRCAT') 
                         AND UPPER(A.APPL_NAME)        NOT LIKE 'ASN%'
                         AND UPPER(A.TPMON_CLIENT_APP) NOT LIKE '%DBEAVER%'
                         AND UPPER(A.APPL_NAME)        NOT LIKE '%DBVIS%' THEN 1 
                                                                          ELSE 0 
                   END EDESISTEMA
            FROM TABLE(SYSPROC.MON_GET_PKG_CACHE_STMT ( NULL, NULL, NULL, -2)) C LEFT OUTER JOIN TABLE (SELECT B.APPL_ID,B.ACTIVITY_ID,B.UOW_ID
                                                                                                        FROM DBSYS.TB_TUNING_ATIVIDADES_STMT B 
                                                                                                        WHERE C.EXECUTABLE_ID = B.EXECUTABLE_ID
                                                                                                        FETCH FIRST 1 ROW ONLY) B ON 1=1
                                                                                 LEFT OUTER JOIN TABLE (SELECT A.SESSION_AUTH_ID,A.APPL_NAME,A.TPMON_CLIENT_APP
                                                                                                        FROM DBSYS.TB_TUNING_ATIVIDADES      A 
                                                                                                        WHERE A.APPL_ID     = B.APPL_ID 
                                                                                                          AND A.ACTIVITY_ID = B.ACTIVITY_ID 
                                                                                                           AND A.UOW_ID     = B.UOW_ID
                                                                                                        FETCH FIRST 1 ROW ONLY) A ON 1=1
--            
            WHERE NUM_EXECUTIONS > 0
              AND (PTABSCHEMA IS NULL OR UPPER(CAST(STMT_TEXT AS VARCHAR(32000))) LIKE '%'||PTABSCHEMA||'.%')
              AND UPPER(CAST(STMT_TEXT AS VARCHAR(32000))) NOT LIKE '%DBSYS%'
              AND UPPER(CAST(STMT_TEXT AS VARCHAR(32000))) NOT LIKE '%SYSIBM%'
              AND UPPER(CAST(STMT_TEXT AS VARCHAR(32000))) NOT LIKE '%CREATE %'              
              AND UPPER(CAST(STMT_TEXT AS VARCHAR(32000))) NOT LIKE '%ALTER %'
              AND UPPER(CAST(STMT_TEXT AS VARCHAR(32000))) NOT LIKE '%TRUNCATE %'              
              AND UPPER(CAST(STMT_TEXT AS VARCHAR(32000))) NOT LIKE '%DROP %'
              AND UPPER(CAST(STMT_TEXT AS VARCHAR(32000))) NOT LIKE '%CONSTRAINT%'
              AND UPPER(CAST(STMT_TEXT AS VARCHAR(32000))) NOT LIKE '%EXPLAIN %'
              AND UPPER(CAST(STMT_TEXT AS VARCHAR(32000))) NOT LIKE '%RUNSTATS %') O
              --AND NOT ( INSTR(VARCHAR(STMT_TEXT,32000),'?') > 0 OR INSTR(VARCHAR(STMT_TEXT,32000),':') > 0))
      WHERE SEQ = 1
        AND QTD > 2
      ORDER BY QTD DESC;
--   IF PTABSCHEMA IS NULL THEN
--      SIGNAL SQLSTATE '75001'
--           SET MESSAGE_TEXT = 'Ex: CALL DBSYS.PRC_TUNING_BIND_VARIABLES (''CRE'')';
--   END IF;               
   OPEN VCURSOR;
END;
;
-- COPY-DATABASE-OBJECT: "DBSYS"."PRC_TUNING_BIND_VARIABLES_AJUDA"
CREATE OR REPLACE PROCEDURE "DBSYS"."PRC_TUNING_BIND_VARIABLES_AJUDA" ()
   RESULT SETS 1
   LANGUAGE SQL
   SPECIFIC PRC_TUNING_BIND_VARIABLES_AJUDA
BEGIN
   DECLARE VCURSOR CURSOR WITH RETURN FOR 
      WITH AJUDA ("Texto") AS (VALUES 
'PRC_TUNING_BIND_VARIABLES

   Descricao:
                                       
      Informa quais SQLs presentes no cache do DB2 nao estsao utilizando Bind Variables
      
   Parametros:
      
       . PTABSCHEMA: obrigatorio, o nome do esquema
      
   informacoes:     
   
       . Numero                                      número sequencial para identificacao
       . Valor Hash SQL                              número Hash gerado pelo IBM DB2, que identifica o SQL
       . Qtd. instancias do comando SQL no cache     a quantidade de copias do mesmo SQL encontradas no cache (pode haver falsos positivos)
       . Qtd. Execucoes:                             a quantidade de vezes que todas as copias do mesmo SQl foram executadas
       . Qt. Media de blocos lidos:                  a quantidade Media de blocos lidos
       . Qt. Media de registros lidos:               a quantidade Media de registros lidos
       . Comentarios do Analista                     justificativas do analista                
       . Texto do comando SQL:                       o texto do comando SQL        
       
   Observacoes:
   
       . e possivel a presenca de falsos positivos no relatorio. 
       
   Verificar:
    
       . verificar se a tecnica de Bind Vairables esta sendo corretamente aplicada.
           
      
   Bind Variables:
                                       
      Os Bancos de Dados necessitam de uma plano de acao para atender a uma requisicao SQL. Para isso eles necessitam de uma serie de informacoes:
      
         . quais sao as tabelas envolvidas no comando SQL.
         . qual e a quantidade de registros de cada tabela utilizada no comando SQL. 
         . qual e a cardinalidade (quantidade de valores distintos) das colunas que sao utilizadas nas clausulas de selecao, juncao e etc.
         . qual e a distribuicao estatistica dos valores das colunas (Ex: Sexo -> 50% M, 50% F) que sao utilizadas nas clausulas de selecao, juncao e etc.         
         . quais sao os indices disponiveis.
         . se as tabelas possuem algum tipo de particionamento.
            
         Baseados nessas em em outras informacoes, o Banco de Dados cria um Plano de Execucao, que e o guia que o Banco ira utilizar para atender a consulta. 
         
            Exemplo:
         
               SELECT I.Nome
               FROM PESSOA P INNER JOIN INSTITUICAO I ON P.IDINSTITUICAO = I.IDINSTITUICAO
               WHERE P.CPF = ''123456678901''
         
               Plano
               ------------------------------------------------------------------------------------------------------------------------------------------------
               Com o valor do CPF, acessar o indice por CPF da tabela PESSOA e recuperar o RID (Record Identified) do registro da tabela PESSOA
                  Com o RID obtido, acessar a Tabela PESSOA e buscar o valor da coluna IDINSTITUICAO
                     Com o valor de IDINSTITUICAO, acessar o indice por IDINSTITUICAO da tabela Instituicao e recuperar o RID do registro da tabela INSTITUICAO
                        Com o RID obtido, acessar a Tabela INSTITUICAO e recuperar o valor da coluna Nome
                           Retornar o resultado para o solicitante
                       
         A geracao do Plano de Execucao SQL e um processo caro. Ele envolve ler os dados estatisticos das tabelas, colunas e indices, e realizar diversos calculos 
      complexos para gerar o melhor Plano de Execucao possivel, em um tempo aceitavel (tempo heuristico). 
      
         Para evitar o custo da geracao do Plano para cada comando SQL, os Bancos de Dados armazenam os Planos de Execucao em um cache de memoria. Um codigo Hash e gerado, 
      e partir do texto do comando SQL, e esse codigo Hash serve como identificador do Plano de Execucao.
      
         Para cada SQL cujo texto gere o mesmo codigo Hash, o Banco de Dados recupera seu Plano de Execucao do cache. 
         
            Um comando SQL do tipo:
      
              SELECT NOME FROM PESSOA WHERE NOME = ''MARIA''
         
            gera um codigo Hash diferente do comando:
       
               SELECT NOME FROM PESSOA WHERE NOME = ''JOSE''   
         
         Os comandos são idênticos, com excessao do parametro de consulta, mas como o Hash gerado pelo DB2 sera diferente para cada comando, Banco ira ter o trabalho de 
      gerar o Plano de Execução duas vezes.
             
   O processo de parsing: 
      
      O Banco de Dados, ao receber uma requisicao de execucao de um comando SQL realiza as seguintes acoes (parsing):
      
         . verifica se o comando SQL esta com a sintaxe correta.
         . vefifica se o solicitante tem os acessos necessarios.
         . a partir do texto do comando SQL, gera um codigo Hash, utilizando uma formula matematica.
         . procura no seu cache de comandos SQL, algum registro que possua o mesmo codigo Hash.
         
            . caso encontre o registro, recupera o Plano armazenado e executa o comando SQL utilizando o Plano recuperado.
            . caso nao encontre, cria o Plano de Execucao, armazena o Plano no cache com o codigo Hash calculado, e executa o comando SQL utilizando o novo Plano
              gerado.

   A tecnica de Bind Variables
 
      Entendendo como os bancos geram os Planos de Execucao SQL, fica claro que deve ser utilizado uma tecnica para evitar que o Banco de Dados tenha que gerar planos 
   iguais para comando SQL semelhantes em tudo, menos no valor das colunas utilizadas como filtro. Essa tecnica consiste na utilizacao de "Bind Variables".

      A tecnica de utilizacao de Bind Variables consiste em utilizar "placeholders" nos comandos SQL da seguinte maneira:
  
         SELECT NOME FROM PESSOA WHERE NOME = ?
     
      O "?" (ou algo semelhante) e utilizado pelas ferramentas cliente (Java, C, COBOL, e etc), e funciona da seguinte maneira: O Comando SQL e passado para o Banco de Dados 
      em sua maneira "pura", sem os valores das variaveis, o valor real das variaveis sendo passado separadamente. Dessa maneira, o Banco de Dados conseguira reaproveitar
      os Planos de Execucao SQL e, substituindo em tempo de execucao os "placeholders" pelos valores reais.

   A excecao a tecnica de Bind Variables   

      Como vimos, a utilizacao da tecnica de Bind Variables e um importante fator para o desempenho do Banco de Dados, pela grande economia que gera ao evitar uma das tarefas mais complexas
   e caras do Banco de Dados, que e a geracao do Plano de Execucao.

      A tecnica de Bind Variables funciona bem em quase todos os casos onde a distribuicao dos valores de uma tabela e equilibrada. 
      
         Exemplo:
  
            SELECT NOME FROM PESSOA WHERE CPF = ?
     
         ou
  
            SELECT * FROM NOTAFISCAL WHERE IDNOTA = ?
     
      A excecao ocorre quando os valores de um determinado atributo possuem uma distribuicao desigual. Exemplo:
  
         SELECT * FROM LOTE WHERE SITUACAOLOTE = ''PENDENTE''
     
      no caso da tabela LOTE, os registros, apos serem processados, passarao a ficar com a situacao "nao PENDENTE". Dessa maneira, 
   podemos considerar que 99% dos registros da tabela terao o valor "nao PENDENTE", e 1% tera o valor "PENDENTE". Isso sigfica que, caso haja um indice
   pela coluna SITUACAOLOTE na tabela LOTE, o Banco de Dados podera, consultando seus dados estatisticos, perceber que ao consultar os registros com 
   situacao "PENDENTE", valera a pena utilizar o indice para realizar a consulta, ja que a consulta retorna uma pequena quantidade de registros 
   (Obs: a utilizacao de indices em uma consulta, e uma tarefa cara e o Banco de Dados geralmente so a utiliza quando calcula que apenas um pequeno 
   percentual de registros sera recuperado).

     Nesse unico caso, a tecnica de Bind Variables nao deve ser utilizada. A consulta devera utilizar o valor da coluna de maneira explicita, permitindo
   ao banco "enxergar" o valor real passado. Consultando seus dados estatisticos, o Banco ira tomar a melhor decisao: utilizar indice quando a consulta 
   for por pelo valor "PENDENTE" e nao utilizar indice quando a consulta for pelo valor "nao PENDENTE" (nesse caso fazendo uma varredura completa 
   da tabela - um TBSCAN).')
      SELECT *
      FROM AJUDA;
   OPEN VCURSOR;
END;
;
-- COPY-DATABASE-OBJECT: "DBSYS"."PRC_TUNING_BOAS_PRATICAS"
CREATE OR REPLACE PROCEDURE "DBSYS"."PRC_TUNING_BOAS_PRATICAS" ()
   RESULT SETS 1
   LANGUAGE SQL
   SPECIFIC PRC_TUNING_BOAS_PRATICAS
BEGIN
   DECLARE VCURSOR CURSOR WITH RETURN FOR 
      WITH DICAS ("Item", "Descricao", "Resposta          ") AS (VALUES 
       ('010','As tabelas nos ambientes de testes foram populadas com um volume significativo de registros, e com a distribuicao dos valores das colunas compativel com a realidade de producao?','_______'),
       ('030','Todas as consultas ou juncoes de tabelas estao cobertas por indices, atendendo o Mapa de Acesso logico?','_______'),
       ('050','Os Planos de Execucao SQL para os consultas contendo tabelas pontencialmente volumosas foram gerados, analisados e documentados?','_______'),
       ('070','A tecnica de Bind Variables em consultas em atributos com distribuicao equilibrada (Ex: CPF em tabela Pessoa) foi seguida?','_______'),
       ('090','A tecnica de Bind Variables em consultas em atributos com distribuicao desigual    (Ex: SituacaoProcessamento em tabela Lote) foi seguida?','_______'),
       ('110','As estatisticas de execucao das consultas foram geradas e analisadas?','_______'),
       ('800','Data:','__________'),              
       ('900','Analista Responsavel:','_______________________________'))
/*      WITH DICAS ("Descricao") AS (VALUES        
       ('As tabelas nos ambientes de testes devem ser populadas com um volume significativo de registros, e com a distribuicao dos valores das colunas compativel com a realidade de producao!'),
       ('Todas as consultas ou juncoes de tabelas devem estar cobertas por indices, atendendo o Mapa de Acesso logico"'),
       ('Os Planos de Execucao SQL para os consultas contendo tabelas pontencialmente volumosas devem ser gerados, analisados e documentados!'),
       ('As estatisticas de execucao das consultas devem ser analisadas!'),       
       ('A tecnica de Bind Variables em consultas em atributos com distribuicao equilibrada (Ex: CPF em tabela Pessoa) deve ser utilizada!'),
       ('A tecnica de Bind Variables em consultas em atributos com distribuicao desigual    (Ex: SituacaoProcessamento em tabela Lote) deve ser seguida!'))*/
       SELECT *
       FROM DICAS
       ORDER BY 1;
   OPEN VCURSOR;
END;
;
-- COPY-DATABASE-OBJECT: "DBSYS"."PRC_TUNING_EXPLAIN"
CREATE OR REPLACE PROCEDURE "DBSYS"."PRC_TUNING_EXPLAIN" (PTABSCHEMA VARCHAR(50) DEFAULT NULL,PIO_READS_RATIO INTEGER DEFAULT 500,PROWS_READS_RATIO INTEGER DEFAULT 500,PSTREAM_COUNT INTEGER DEFAULT NULL,PIO_READS_RATIOALERTA1 INTEGER DEFAULT 1500,PIO_READS_RATIOALERTA2 INTEGER DEFAULT 500,PROWS_READS_RATIOALERTA1 INTEGER DEFAULT 5000,PROWS_READS_RATIOALERTA2 INTEGER DEFAULT 2500,PROWS_TABSCAN INTEGER DEFAULT 500,PROWS_IXSCAN INTEGER DEFAULT 500,PEXPLAIN_ALL INTEGER DEFAULT 0,PAPENASSQLSSISTEMA BOOLEAN DEFAULT TRUE)
   DYNAMIC RESULT SETS 1
   LANGUAGE SQL
   SPECIFIC PRC_TUNING_EXPLAIN
BEGIN
   DECLARE VMOSTRADIAGNOSTICO     CHAR;
   DECLARE VAPENASSQLSSISTEMA     SMALLINT DEFAULT 1;
   DECLARE VDUMMY                 SMALLINT;
   DECLARE VMENSAGEM              VARCHAR(1000);
   DECLARE VEOF                   SMALLINT;
   DECLARE VSQLCACHE              CLOB(2097152);
   DECLARE VSTMTID                BIGINT;
   DECLARE VSQLOBSERVACOES        VARCHAR(32000);
   DECLARE VQTDTBSCANS            BIGINT;
   DECLARE VQTDIXSCANS            BIGINT;
   DECLARE VSQLEXPLAIN            CLOB(2097152);   
   DECLARE VOBSERVACOES           VARCHAR(32000);      
   DECLARE VQTD                   BIGINT;
   DECLARE VSQL                   CLOB(2097152); 
   DECLARE VNUM_EXECUTIONS        BIGINT;
   DECLARE VQUERY_COST_ESTIMATE   BIGINT;
   DECLARE VTOTAL_ACT_TIME_RATIO  BIGINT;
   DECLARE VIO_READS_RATIO        BIGINT;
   DECLARE VROWS_READS_RATIO      INTEGER;
   DECLARE VROWS_RETURNED_RATIO   INTEGER;
   DECLARE VAVG_IO_READS_RATIO1   INTEGER;
   DECLARE VAVG_IO_READS_RATIO2   INTEGER;   
   DECLARE VINSERT_TIMESTAMP      VARCHAR(19);
   DECLARE VLAST_METRICS_UPDATE   VARCHAR(19);
   DECLARE VIOREADSRATIO1         INTEGER;
   DECLARE VROWSREADRATIO1        INTEGER;
   DECLARE VIOREADSRATIO2         INTEGER;  
   DECLARE VROWSREADRATIO2        INTEGER;     
   DECLARE VQUERYNO               INTEGER;    
   DECLARE VTABLENF               CONDITION FOR SQLSTATE '42704';
   DECLARE VTABLEF                CONDITION FOR SQLSTATE '42710';
   DECLARE VLISTAGG               CONDITION FOR SQLSTATE '54006';
   DECLARE VNAOSEI1               CONDITION FOR SQLSTATE '42610';
   DECLARE VNAOSEI2               CONDITION FOR SQLSTATE '56098';
   DECLARE VNAOSEI3               CONDITION FOR SQLSTATE '42501';
   DECLARE VNAOSEI4               CONDITION FOR SQLSTATE '22001';
   DECLARE VNAOSEI5               CONDITION FOR SQLSTATE '42884';
   DECLARE VNAOSEI6               CONDITION FOR SQLSTATE '42703';    
   DECLARE VNAOSEI7               CONDITION FOR SQLSTATE '428F5';  
   DECLARE VNAOSEI8               CONDITION FOR SQLSTATE '42509';  
   DECLARE VNAOSEI9               CONDITION FOR SQLSTATE '22004'; 
   DECLARE VNAOSEI10              CONDITION FOR SQLSTATE '22003';    
   DECLARE VNAOSEI11              CONDITION FOR SQLSTATE '24501';
   DECLARE VNAOSEI12              CONDITION FOR SQLSTATE '07003';   
   DECLARE VSTMT                  STATEMENT;
   DECLARE VSTMTOBSERVACOES       STATEMENT; 
   DECLARE VRETORNO               STATEMENT;  
   DECLARE VCURSOROBSERVACOES     CURSOR FOR VSTMTOBSERVACOES;   
   DECLARE VCURSORRETORNO CURSOR WITH HOLD WITH RETURN TO CLIENT FOR VRETORNO;
   DECLARE VCURCACHE CURSOR FOR SELECT (SELECT STMT_TEXT FROM TABLE(MON_GET_PKG_CACHE_STMT (NULL, O.EXECUTABLE_ID, NULL, -2)))
                                                            "Texto do comando SQL",
                                       STMTID               "Valor Hash SQL",
                                       NUM_EXECUTIONS       "Qtd. Execucoes",
                                       QUERY_COST_ESTIMATE  "Custo",
                                       TIME_RATIO           "Tempo Medio(ms)",
                                       IO_READS_RATIO       "Qt. Media de blocos lidos",
                                       ROWS_READS_RATIO     "Qt. Media de registros lidos",
                                       ROWS_RETURNED_RATIO  "Qt. Media de registros retornados",
                                       AVG_IO_READS_RATIO1,
                                       AVG_IO_READS_RATIO2,
                                       TO_CHAR(INSERT_TIMESTAMP   ,'DD/MM/YYYY HH24:MI:SS') "Horario de entrada do SQL no cache",
                                       TO_CHAR(LAST_METRICS_UPDATE,'DD/MM/YYYY HH24:MI:SS') "Horario da ultima execucao",                                       
                                       CASE WHEN MINRATIO = 1 AND ((IO_READS_RATIO > (10 * AVG_IO_READS_RATIO1)) OR (IO_READS_RATIO > (10 * AVG_IO_READS_RATIO2))) THEN 1 ELSE 0 END IOREADSRATIO1,
                                       CASE WHEN MINRATIO = 1 AND ((IO_READS_RATIO >= PIO_READS_RATIOALERTA1) OR (ROWS_READS_RATIO >= PROWS_READS_RATIOALERTA1))   THEN 1 ELSE 0 END ROWSREADRATIO1,
                                       CASE WHEN MINRATIO = 1 AND ((IO_READS_RATIO > (5  * AVG_IO_READS_RATIO1)) OR (IO_READS_RATIO > (5  * AVG_IO_READS_RATIO2))) THEN 1 ELSE 0 END IOREADSRATIO2,
                                       CASE WHEN MINRATIO = 1 AND ((IO_READS_RATIO >= PIO_READS_RATIOALERTA2) OR (ROWS_READS_RATIO >= PROWS_READS_RATIOALERTA2))   THEN 1 ELSE 0 END ROWSREADRATIO2,
                                       MOSTRADIAGNOSTICO
                                FROM (SELECT VARCHAR(STMTID) STMTID,
                                             NUM_EXECUTIONS,
                                             QUERY_COST_ESTIMATE,
--                                             TOTAL_TIME,
                                             TIME_RATIO,
--                                             TOTAL_IO_READS,
                                             IO_READS_RATIO,
                                             CASE WHEN ((PIO_READS_RATIO   IS NULL OR IO_READS_RATIO   >= PIO_READS_RATIO) OR
                                                        (PROWS_READS_RATIO IS NULL OR ROWS_READS_RATIO >= PROWS_READS_RATIO)) THEN 1 ELSE 0
                                             END MINRATIO,                                                        
                                             AVG(IO_READS_RATIO) OVER (ORDER BY NUM_EXECUTIONS DESC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)   AVG_IO_READS_RATIO1,
                                             AVG(IO_READS_RATIO) OVER (ORDER BY NUM_EXECUTIONS DESC ROWS BETWEEN 4 PRECEDING AND 4 FOLLOWING)           AVG_IO_READS_RATIO2,                   
--                                             TOTAL_ROWS_READ,
                                             ROWS_READS_RATIO,
--                                             TOTAL_ROWS_RETURNED,
                                             ROWS_RETURNED_RATIO,
--                                             TOTAL_IO_WRITES,
                                             IO_WRITES_RATIO,
--                                             TOTAL_ROWS_MODIFIED,
                                             ROWS_MODIFIED_RATIO,
                                             INSERT_TIMESTAMP,
                                             LAST_METRICS_UPDATE,
                                             EFFECTIVE_ISOLATION,
                                             EXECUTABLE_ID,
                                             MOSTRADIAGNOSTICO
                                      FROM (SELECT ROW_NUMBER()             OVER (PARTITION BY C.STMTID,C.SEMANTIC_ENV_ID ORDER BY 1) SEQ,
                                                   C.STMTID                                                               STMTID,
                                                   SUM(C.NUM_EXECUTIONS)      OVER (PARTITION BY C.STMTID,C.SEMANTIC_ENV_ID)  NUM_EXECUTIONS,
                                                   C.QUERY_COST_ESTIMATE                                                  QUERY_COST_ESTIMATE,
--                                             SUM(TOTAL_ACT_TIME)      OVER (PARTITION BY C.STMTID,C.SEMANTIC_ENV_ID)  TOTAL_TIME,
                                                   SUM(C.TOTAL_ACT_TIME)      OVER (PARTITION BY C.STMTID,C.SEMANTIC_ENV_ID)
                                                  /SUM(C.NUM_EXECUTIONS)      OVER (PARTITION BY C.STMTID,C.SEMANTIC_ENV_ID)  TIME_RATIO,
--                                                   SUM(POOL_DATA_P_READS+POOL_TEMP_DATA_P_READS+POOL_XDA_P_READS+POOL_TEMP_XDA_P_READS+POOL_INDEX_P_READS+POOL_TEMP_INDEX_P_READS+POOL_DATA_GBP_P_READS+POOL_INDEX_GBP_P_READS+POOL_XDA_GBP_P_READS+POOL_COL_P_READS+POOL_TEMP_COL_P_READS+POOL_COL_GBP_P_READS+POOL_DATA_L_READS+POOL_TEMP_DATA_L_READS+POOL_XDA_L_READS+POOL_TEMP_XDA_L_READS+POOL_INDEX_L_READS+POOL_TEMP_INDEX_L_READS+POOL_DATA_GBP_L_READS+POOL_INDEX_GBP_L_READS+POOL_XDA_GBP_L_READS+POOL_COL_L_READS+POOL_TEMP_COL_L_READS+POOL_COL_GBP_L_READS) OVER (PARTITION BY C.STMTID,C.SEMANTIC_ENV_ID)
--                                                                                                                        TOTAL_IO_READS,
                                                   SUM(C.POOL_DATA_P_READS+C.POOL_TEMP_DATA_P_READS+C.POOL_XDA_P_READS+C.POOL_TEMP_XDA_P_READS+C.POOL_INDEX_P_READS+C.POOL_TEMP_INDEX_P_READS+C.POOL_DATA_GBP_P_READS+C.POOL_INDEX_GBP_P_READS+C.POOL_XDA_GBP_P_READS+C.POOL_COL_P_READS+C.POOL_TEMP_COL_P_READS+C.POOL_COL_GBP_P_READS+C.POOL_DATA_L_READS+C.POOL_TEMP_DATA_L_READS+C.POOL_XDA_L_READS+C.POOL_TEMP_XDA_L_READS+C.POOL_INDEX_L_READS+C.POOL_TEMP_INDEX_L_READS+C.POOL_DATA_GBP_L_READS+C.POOL_INDEX_GBP_L_READS+C.POOL_XDA_GBP_L_READS+C.POOL_COL_L_READS+C.POOL_TEMP_COL_L_READS+C.POOL_COL_GBP_L_READS) OVER (PARTITION BY C.STMTID,C.SEMANTIC_ENV_ID)
                                                  /SUM(C.NUM_EXECUTIONS)      OVER (PARTITION BY C.STMTID,C.SEMANTIC_ENV_ID)  IO_READS_RATIO,
--                                           SUM(ROWS_READ)           OVER (PARTITION BY C.STMTID,C.SEMANTIC_ENV_ID)  TOTAL_ROWS_READ,
                                                   SUM(C.ROWS_READ)           OVER (PARTITION BY C.STMTID,C.SEMANTIC_ENV_ID)
                                                  /SUM(C.NUM_EXECUTIONS)      OVER (PARTITION BY C.STMTID,C.SEMANTIC_ENV_ID)  ROWS_READS_RATIO,
--                                           SUM(ROWS_RETURNED)       OVER (PARTITION BY C.STMTID,C.SEMANTIC_ENV_ID)  TOTAL_ROWS_RETURNED,
                                                   SUM(C.ROWS_RETURNED)       OVER (PARTITION BY C.STMTID,C.SEMANTIC_ENV_ID)
                                                  /SUM(C.NUM_EXECUTIONS)      OVER (PARTITION BY C.STMTID,C.SEMANTIC_ENV_ID)  ROWS_RETURNED_RATIO,
--                                                   SUM(POOL_DATA_WRITES+C.POOL_XDA_WRITES) OVER (PARTITION BY C.STMTID,C.SEMANTIC_ENV_ID) 
--                                                                                                                TOTAL_IO_WRITES,
                                                   SUM(C.POOL_DATA_WRITES+C.POOL_XDA_WRITES) OVER (PARTITION BY C.STMTID,C.SEMANTIC_ENV_ID) 
                                                  /SUM(C.NUM_EXECUTIONS)      OVER (PARTITION BY C.STMTID,C.SEMANTIC_ENV_ID)  IO_WRITES_RATIO,
--                                           SUM(ROWS_MODIFIED)       OVER (PARTITION BY C.STMTID,C.SEMANTIC_ENV_ID)  TOTAL_ROWS_MODIFIED,
                                                   SUM(C.ROWS_MODIFIED)       OVER (PARTITION BY C.STMTID,C.SEMANTIC_ENV_ID)
                                                  /SUM(C.NUM_EXECUTIONS)      OVER (PARTITION BY C.STMTID,C.SEMANTIC_ENV_ID)  ROWS_MODIFIED_RATIO,
                                                   MIN(C.INSERT_TIMESTAMP)    OVER (PARTITION BY C.STMTID,C.SEMANTIC_ENV_ID)  INSERT_TIMESTAMP,
                                                   MAX(C.LAST_METRICS_UPDATE) OVER (PARTITION BY C.STMTID,C.SEMANTIC_ENV_ID)  LAST_METRICS_UPDATE,
                                                   C.EFFECTIVE_ISOLATION                                                  EFFECTIVE_ISOLATION,
                                                   C.EXECUTABLE_ID                                                        EXECUTABLE_ID,
                                                   CASE WHEN (VAPENASSQLSSISTEMA = 0 
                                                          OR (VAPENASSQLSSISTEMA = 1 
                                                          AND A.SESSION_AUTH_ID             LIKE 'USR%' 
                                                          AND A.SESSION_AUTH_ID         NOT IN ('USRCAT') 
                                                          AND UPPER(A.APPL_NAME)        NOT LIKE 'ASN%'
                                                          AND UPPER(A.TPMON_CLIENT_APP) NOT LIKE '%DBEAVER%'
                                                          AND UPPER(A.APPL_NAME)        NOT LIKE '%DBVIS%')) THEN 'S' ELSE 'N' END MOSTRADIAGNOSTICO 
                                            FROM TABLE(SYSPROC.MON_GET_PKG_CACHE_STMT ( NULL, NULL, NULL, -2)) C LEFT OUTER JOIN TABLE (SELECT B.APPL_ID,B.ACTIVITY_ID,B.UOW_ID
                                                                                                                                        FROM DBSYS.TB_TUNING_ATIVIDADES_STMT B 
                                                                                                                                        WHERE C.EXECUTABLE_ID = B.EXECUTABLE_ID
                                                                                                                                        FETCH FIRST 1 ROW ONLY) B ON 1=1
                                                                                                                 LEFT OUTER JOIN TABLE (SELECT A.SESSION_AUTH_ID,A.APPL_NAME,A.TPMON_CLIENT_APP
                                                                                                                                        FROM DBSYS.TB_TUNING_ATIVIDADES      A 
                                                                                                                                        WHERE A.APPL_ID     = B.APPL_ID 
                                                                                                                                          AND A.ACTIVITY_ID = B.ACTIVITY_ID 
                                                                                                                                           AND A.UOW_ID     = B.UOW_ID
                                                                                                                                        FETCH FIRST 1 ROW ONLY) A ON 1=1
                                            WHERE C.NUM_EXECUTIONS > 0
                                              AND C.STMT_TEXT IS NOT NULL                                              
                                              AND UPPER(CAST(C.STMT_TEXT AS VARCHAR(32000))) LIKE '%'||PTABSCHEMA||'.%'
                                              AND UPPER(CAST(C.STMT_TEXT AS VARCHAR(32000))) NOT LIKE '%NUM_EXECUTIONS%'
                                              AND UPPER(CAST(C.STMT_TEXT AS VARCHAR(32000))) NOT LIKE '%DBSYS%'
                                              AND UPPER(CAST(C.STMT_TEXT AS VARCHAR(32000))) NOT LIKE '%SYSIBM%'                                  
                                              AND UPPER(CAST(C.STMT_TEXT AS VARCHAR(32000))) NOT LIKE '%CREATE %'
                                              AND UPPER(CAST(C.STMT_TEXT AS VARCHAR(32000))) NOT LIKE '%ALTER %'
                                              AND UPPER(CAST(C.STMT_TEXT AS VARCHAR(32000))) NOT LIKE '%DROP %'
                                              AND UPPER(CAST(C.STMT_TEXT AS VARCHAR(32000))) NOT LIKE '%GRANT%'                                  
                                              AND UPPER(CAST(C.STMT_TEXT AS VARCHAR(32000))) NOT LIKE '%CONSTRAINT%'
                                              AND UPPER(CAST(C.STMT_TEXT AS VARCHAR(32000))) NOT LIKE '%EXPLAIN %'
                                              AND UPPER(CAST(C.STMT_TEXT AS VARCHAR(32000))) NOT LIKE '%TRUNCATE %'
                                              AND UPPER(CAST(C.STMT_TEXT AS VARCHAR(32000))) NOT LIKE '%COMMENT %'
                                              AND UPPER(CAST(C.STMT_TEXT AS VARCHAR(32000))) NOT LIKE '%DECLATE %'                                              
                                              AND UPPER(CAST(C.STMT_TEXT AS VARCHAR(32000))) NOT LIKE '%RUNSTATS %'
                                              AND UPPER(CAST(C.STMT_TEXT AS VARCHAR(32000))) NOT LIKE '%RENAME %'                                              
                                              AND UPPER(CAST(C.STMT_TEXT AS VARCHAR(32000))) NOT LIKE '%GLOBAL TEMPORARY%') O
                                        WHERE SEQ = 1
                                         --AND (PIO_READS_RATIO   IS NULL OR IO_READS_RATIO   >= PIO_READS_RATIO)
                                         --AND (PROWS_READS_RATIO IS NULL OR ROWS_READS_RATIO >= PROWS_READS_RATIO)
                                         ) O
                                ORDER BY NUM_EXECUTIONS DESC;
   DECLARE CONTINUE HANDLER FOR NOT FOUND
      SET VEOF = 1;
   DECLARE CONTINUE HANDLER FOR VTABLENF 
      SET VDUMMY = 0;  
   DECLARE CONTINUE HANDLER FOR VTABLEF 
      SET VDUMMY = 0;        
   DECLARE CONTINUE HANDLER FOR VLISTAGG 
      SET VDUMMY = 0;              
   DECLARE CONTINUE HANDLER FOR VNAOSEI1
      SET VDUMMY = 0;                    
   DECLARE CONTINUE HANDLER FOR VNAOSEI2
      SET VDUMMY = 0;    
   DECLARE CONTINUE HANDLER FOR VNAOSEI3
      SET VDUMMY = 0;          
   DECLARE CONTINUE HANDLER FOR VNAOSEI4
      SET VDUMMY = 0;          
   DECLARE CONTINUE HANDLER FOR VNAOSEI5
      SET VDUMMY = 0;                
   DECLARE CONTINUE HANDLER FOR VNAOSEI6
      SET VDUMMY = 0;
   DECLARE CONTINUE HANDLER FOR VNAOSEI7
      SET VDUMMY = 0;      
   DECLARE CONTINUE HANDLER FOR VNAOSEI8
      SET VDUMMY = 0;            
   DECLARE CONTINUE HANDLER FOR VNAOSEI9
      SET VDUMMY = 0;       
   DECLARE CONTINUE HANDLER FOR VNAOSEI10
      SET VDUMMY = 0;             
   DECLARE CONTINUE HANDLER FOR VNAOSEI11
      SET VDUMMY = 0;                   
   DECLARE CONTINUE HANDLER FOR VNAOSEI12
      SET VDUMMY = 0;                         

   DECLARE GLOBAL TEMPORARY TABLE SESSION.EXPLAIN (STMTID BIGINT,NUM_EXECUTIONS BIGINT,QUERY_COST_ESTIMATE BIGINT,TOTAL_ACT_TIME_RATIO BIGINT,IO_READS_RATIO BIGINT,ROWS_READS_RATIO BIGINT,ROWS_RETURNED_RATIO BIGINT,AVG_IO_READS_RATIO1 BIGINT,AVG_IO_READS_RATIO2 BIGINT,INSERT_TIMESTAMP VARCHAR(19),LAST_METRICS_UPDATE VARCHAR(19),SQL CLOB(2097152),PLANO CLOB(2097152),OBSERVACOES VARCHAR(5000),QTDTBSCANS BIGINT,QTDIXSCANS BIGINT,IOREADSRATIO1 INTEGER,ROWSREADRATIO1 INTEGER,IOREADSRATIO2 INTEGER,ROWSREADRATIO2 INTEGER,MOSTRADIAGNOSTICO CHAR) NOT LOGGED ON ROLLBACK DELETE ROWS ON COMMIT PRESERVE ROWS WITH REPLACE;
   
   IF NOT PAPENASSQLSSISTEMA THEN
      SET VAPENASSQLSSISTEMA = 0;
   END IF;
   
   IF PTABSCHEMA IS NULL THEN
      SIGNAL SQLSTATE '75001'
           SET MESSAGE_TEXT = 'Ex: CALL DBSYS.PRC_TUNING_EXPLAIN (''CRE'')';
   END IF; 
   SET VSQLOBSERVACOES = 'SET (?,?,?) =  (SELECT ''Operador  Esquema  Tabela                                                   Nr. Regs. Retornados  Qtd. Regs. Tabela''||CHR(10)||
                                           ''--------  -------  ------------------------------------------------------   --------------------  -----------------''||CHR(10)||
                    LISTAGG(CAST(RPAD(OPERATOR_TYPE,8,'' '')||''  ''||RPAD(TRIM(OBJECT_SCHEMA),7,'' '')||''  ''||RPAD(OBJECT_NAME,55,'' '')||''  ''||RPAD(INTEGER(STREAM_COUNT),20,'' '')||''  ''||RPAD(CARD,15,'' '') AS VARCHAR(32000)),CHR(10)),
                    COUNT(CASE WHEN TBSCANS = 1 AND SEQ = 1 THEN 1 ELSE NULL END) QTDTBSCANS,
                    COUNT(CASE WHEN IXSCANS = 1 AND SEQ = 1 THEN 1 ELSE NULL END) QTDIXSCANS                    
                    FROM (SELECT OPER.OPERATOR_TYPE,
                                 OBJ.OBJECT_SCHEMA,
                                 OBJ.OBJECT_NAME,
                                 OBJ.COLUMN_COUNT,
                                 STR.STREAM_COUNT,
                                 COALESCE(TAB1.CARD,TAB2.CARD) CARD,
                                 COUNT(CASE WHEN OPER.OPERATOR_TYPE = ''TBSCAN'' AND STR.STREAM_COUNT >= ? THEN 1 ELSE NULL END) OVER() TBSCANS,
                                 COUNT(CASE WHEN OPER.OPERATOR_TYPE = ''IXSCAN'' AND STR.STREAM_COUNT >= ? THEN 1 ELSE NULL END) OVER() IXSCANS,
                                 ROW_NUMBER() OVER () SEQ                                 
                          FROM EXPLAIN_OPERATOR OPER INNER JOIN EXPLAIN_STATEMENT STMT ON OPER.EXPLAIN_REQUESTER = STMT.EXPLAIN_REQUESTER
                                                                                      AND OPER.EXPLAIN_TIME      = STMT.EXPLAIN_TIME
                                                                                      AND OPER.SOURCE_NAME       = STMT.SOURCE_NAME
                                                                                      AND OPER.SOURCE_SCHEMA     = STMT.SOURCE_SCHEMA
                                                                                      AND OPER.EXPLAIN_LEVEL     = STMT.EXPLAIN_LEVEL
                                                                                      AND OPER.STMTNO            = STMT.STMTNO
                                                                                      AND OPER.SECTNO            = STMT.SECTNO
                                                                                      AND STMT.EXPLAIN_LEVEL = ''P''
                                                LEFT OUTER JOIN EXPLAIN_STREAM    STR  ON OPER.OPERATOR_ID       = STR.SOURCE_ID
                                                                                      AND OPER.EXPLAIN_REQUESTER = STR.EXPLAIN_REQUESTER
                                                                                      AND OPER.EXPLAIN_TIME      = STR.EXPLAIN_TIME
                                                                                      AND OPER.SOURCE_NAME       = STR.SOURCE_NAME
                                                                                      AND OPER.SOURCE_SCHEMA     = STR.SOURCE_SCHEMA
                                                                                      AND OPER.EXPLAIN_LEVEL     = STR.EXPLAIN_LEVEL
                                                                                      AND OPER.STMTNO            = STR.STMTNO
                                                                                      AND OPER.SECTNO            = STR.SECTNO
                                                LEFT OUTER JOIN EXPLAIN_STREAM    OBJ  ON STR.SOURCE_ID = OBJ.TARGET_ID
                                                                                      AND OBJ.SOURCE_ID = -1
                                                                                      AND STR.EXPLAIN_REQUESTER = OBJ.EXPLAIN_REQUESTER
                                                                                      AND STR.EXPLAIN_TIME      = OBJ.EXPLAIN_TIME
                                                                                      AND STR.SOURCE_NAME       = OBJ.SOURCE_NAME
                                                                                      AND STR.SOURCE_SCHEMA     = OBJ.SOURCE_SCHEMA
                                                                                      AND STR.EXPLAIN_LEVEL     = OBJ.EXPLAIN_LEVEL
                                                                                      AND STR.STMTNO            = OBJ.STMTNO
                                                                                      AND STR.SECTNO            = OBJ.SECTNO
                                                LEFT OUTER JOIN SYSCAT.TABLES    TAB1  ON OBJ.OBJECT_SCHEMA = TAB1.TABSCHEMA
                                                                                      AND OBJ.OBJECT_NAME   = TAB1.TABNAME
                                                LEFT OUTER JOIN SYSCAT.INDEXES   IND   ON OBJ.OBJECT_SCHEMA = IND.INDSCHEMA
                                                                                      AND OBJ.OBJECT_NAME   = IND.INDNAME
                                                LEFT OUTER JOIN SYSCAT.TABLES    TAB2  ON IND.TABSCHEMA     = TAB2.TABSCHEMA
                                                                                      AND IND.TABNAME       = TAB2.TABNAME                                                                                      
                    WHERE OBJ.OBJECT_SCHEMA IS NOT NULL
                        AND STMT.QUERYNO       = ?
                        AND (? IS NULL OR STR.STREAM_COUNT >= ?)
                    GROUP BY OPER.OPERATOR_TYPE,
                             OBJ.OBJECT_SCHEMA,
                             OBJ.OBJECT_NAME,
                             OBJ.COLUMN_COUNT,
                             STR.STREAM_COUNT,
                             COALESCE(TAB1.CARD,TAB2.CARD)))';
   DELETE FROM SESSION.EXPLAIN;
   
   SET VEOF = 0;   
   OPEN VCURCACHE;
   FETCH VCURCACHE INTO VSQLCACHE,VSTMTID,VNUM_EXECUTIONS,VQUERY_COST_ESTIMATE,VTOTAL_ACT_TIME_RATIO,VIO_READS_RATIO,VROWS_READS_RATIO,VROWS_RETURNED_RATIO,VAVG_IO_READS_RATIO1,VAVG_IO_READS_RATIO2,VINSERT_TIMESTAMP,VLAST_METRICS_UPDATE,VIOREADSRATIO1,VROWSREADRATIO1,VIOREADSRATIO2,VROWSREADRATIO2,VMOSTRADIAGNOSTICO;
   SET VSQLEXPLAIN = '';
   WHILE VEOF = 0 DO      
      IF VSQLCACHE IS NOT NULL THEN
      
/*
         IF PEXPLAIN_ALL = 1 OR (VMOSTRADIAGNOSTICO = 'S' AND (VIOREADSRATIO1 = 1 OR VROWSREADRATIO1 = 1 OR VIOREADSRATIO2 = 1 OR VROWSREADRATIO2 = 1)) THEN

            SET VQUERYNO = NEXT VALUE FOR DBSYS.SEQ_TUNING_EXPLAIN;
            SET VSQL = 'EXPLAIN PLAN SET QUERYNO = ' ||TO_CHAR(VQUERYNO)||' FOR ' ||VSQLCACHE;
      
            PREPARE VSTMT FROM VSQL;  
            EXECUTE VSTMT;        
            FOR V_LISTA AS CUR1 CURSOR FOR SELECT EXPLAINPLAN 
                                           FROM DBSYS.VIW_TUNING_EXPLAIN
            DO
               SET VSQLEXPLAIN = VSQLEXPLAIN||V_LISTA.EXPLAINPLAN||CHR(10);
            END FOR;
--            SET VSQLEXPLAIN = 'SET ? = (SELECT CAST(LISTAGG(CAST(TRIM(EXPLAINPLAN) AS VARCHAR(32000)),CHR(10)) AS VARCHAR(32000)) "Texto do comando SQL" FROM DBSYS.VIW_TUNING_EXPLAIN)';
--            PREPARE VSTMT FROM VSQLEXPLAIN;
--            EXECUTE VSTMT INTO VSQLEXPLAIN;
            PREPARE VSTMT FROM VSQLOBSERVACOES;
            EXECUTE VSTMT INTO VOBSERVACOES,VQTDTBSCANS,VQTDIXSCANS USING PROWS_TABSCAN,PROWS_IXSCAN,VQUERYNO,PSTREAM_COUNT,PSTREAM_COUNT;
            
         END IF;  
*/         
         
         INSERT INTO SESSION.EXPLAIN (STMTID,NUM_EXECUTIONS,QUERY_COST_ESTIMATE,TOTAL_ACT_TIME_RATIO,IO_READS_RATIO,ROWS_READS_RATIO,ROWS_RETURNED_RATIO,AVG_IO_READS_RATIO1,AVG_IO_READS_RATIO2,INSERT_TIMESTAMP,LAST_METRICS_UPDATE,SQL,PLANO,OBSERVACOES,QTDTBSCANS,QTDIXSCANS,IOREADSRATIO1,ROWSREADRATIO1,IOREADSRATIO2,ROWSREADRATIO2,MOSTRADIAGNOSTICO) VALUES (VSTMTID,VNUM_EXECUTIONS,VQUERY_COST_ESTIMATE,VTOTAL_ACT_TIME_RATIO,VIO_READS_RATIO,VROWS_READS_RATIO,VROWS_RETURNED_RATIO,VAVG_IO_READS_RATIO1,VAVG_IO_READS_RATIO2,VINSERT_TIMESTAMP,VLAST_METRICS_UPDATE,VSQLCACHE,VSQLEXPLAIN,NVL(VOBSERVACOES,''),VQTDTBSCANS,VQTDIXSCANS,VIOREADSRATIO1,VROWSREADRATIO1,VIOREADSRATIO2,VROWSREADRATIO2,VMOSTRADIAGNOSTICO);
         SET VNUM_EXECUTIONS = 0;
         SET VQUERY_COST_ESTIMATE = 0;
         SET VTOTAL_ACT_TIME_RATIO = 0;
         SET VIO_READS_RATIO = 0;
         SET VROWS_READS_RATIO = 0;
         SET VROWS_RETURNED_RATIO = 0;
         SET VAVG_IO_READS_RATIO1 = 0;
         SET VAVG_IO_READS_RATIO2 = 0;
         SET VINSERT_TIMESTAMP = NULL;
         SET VLAST_METRICS_UPDATE = NULL;
         SET VSQLCACHE = '';
         SET VSQLEXPLAIN = '';
         SET VOBSERVACOES = '';
         SET VQTDTBSCANS = 0;
         SET VQTDIXSCANS = 0;
  
  /*
         DELETE FROM EXPLAIN_STATEMENT       WHERE QUERYNO = VQUERYNO;
         DELETE FROM EXPLAIN_ARGUMENT        WHERE (EXPLAIN_REQUESTER,EXPLAIN_TIME,SOURCE_NAME,SOURCE_SCHEMA,SOURCE_VERSION,EXPLAIN_LEVEL,STMTNO,SECTNO) IN (SELECT EXPLAIN_REQUESTER,EXPLAIN_TIME,SOURCE_NAME,SOURCE_SCHEMA,SOURCE_VERSION,EXPLAIN_LEVEL,STMTNO,SECTNO FROM EXPLAIN_STATEMENT WHERE QUERYNO = VQUERYNO);
         DELETE FROM EXPLAIN_OBJECT          WHERE (EXPLAIN_REQUESTER,EXPLAIN_TIME,SOURCE_NAME,SOURCE_SCHEMA,SOURCE_VERSION,EXPLAIN_LEVEL,STMTNO,SECTNO) IN (SELECT EXPLAIN_REQUESTER,EXPLAIN_TIME,SOURCE_NAME,SOURCE_SCHEMA,SOURCE_VERSION,EXPLAIN_LEVEL,STMTNO,SECTNO FROM EXPLAIN_STATEMENT WHERE QUERYNO = VQUERYNO);
         DELETE FROM EXPLAIN_OPERATOR        WHERE (EXPLAIN_REQUESTER,EXPLAIN_TIME,SOURCE_NAME,SOURCE_SCHEMA,SOURCE_VERSION,EXPLAIN_LEVEL,STMTNO,SECTNO) IN (SELECT EXPLAIN_REQUESTER,EXPLAIN_TIME,SOURCE_NAME,SOURCE_SCHEMA,SOURCE_VERSION,EXPLAIN_LEVEL,STMTNO,SECTNO FROM EXPLAIN_STATEMENT WHERE QUERYNO = VQUERYNO);
         DELETE FROM EXPLAIN_ACTUALS         WHERE (EXPLAIN_REQUESTER,EXPLAIN_TIME,SOURCE_NAME,SOURCE_SCHEMA,SOURCE_VERSION,EXPLAIN_LEVEL,STMTNO,SECTNO,OPERATOR_ID) IN (SELECT EXPLAIN_REQUESTER,EXPLAIN_TIME,SOURCE_NAME,SOURCE_SCHEMA,SOURCE_VERSION,EXPLAIN_LEVEL,STMTNO,SECTNO,OPERATOR_ID FROM EXPLAIN_OPERATOR WHERE (EXPLAIN_REQUESTER,EXPLAIN_TIME,SOURCE_NAME,SOURCE_SCHEMA,SOURCE_VERSION,EXPLAIN_LEVEL,STMTNO,SECTNO) IN (SELECT EXPLAIN_REQUESTER,EXPLAIN_TIME,SOURCE_NAME,SOURCE_SCHEMA,SOURCE_VERSION,EXPLAIN_LEVEL,STMTNO,SECTNO FROM EXPLAIN_STATEMENT WHERE QUERYNO = VQUERYNO));          
         DELETE FROM EXPLAIN_PREDICATE       WHERE (EXPLAIN_REQUESTER,EXPLAIN_TIME,SOURCE_NAME,SOURCE_SCHEMA,SOURCE_VERSION,EXPLAIN_LEVEL,STMTNO,SECTNO) IN (SELECT EXPLAIN_REQUESTER,EXPLAIN_TIME,SOURCE_NAME,SOURCE_SCHEMA,SOURCE_VERSION,EXPLAIN_LEVEL,STMTNO,SECTNO FROM EXPLAIN_STATEMENT WHERE QUERYNO = VQUERYNO);   
         DELETE FROM EXPLAIN_STREAM          WHERE (EXPLAIN_REQUESTER,EXPLAIN_TIME,SOURCE_NAME,SOURCE_SCHEMA,SOURCE_VERSION,EXPLAIN_LEVEL,STMTNO,SECTNO) IN (SELECT EXPLAIN_REQUESTER,EXPLAIN_TIME,SOURCE_NAME,SOURCE_SCHEMA,SOURCE_VERSION,EXPLAIN_LEVEL,STMTNO,SECTNO FROM EXPLAIN_STATEMENT WHERE QUERYNO = VQUERYNO);  
         DELETE FROM EXPLAIN_DIAGNOSTIC      WHERE (EXPLAIN_REQUESTER,EXPLAIN_TIME,SOURCE_NAME,SOURCE_SCHEMA,SOURCE_VERSION,EXPLAIN_LEVEL,STMTNO,SECTNO) IN (SELECT EXPLAIN_REQUESTER,EXPLAIN_TIME,SOURCE_NAME,SOURCE_SCHEMA,SOURCE_VERSION,EXPLAIN_LEVEL,STMTNO,SECTNO FROM EXPLAIN_STATEMENT WHERE QUERYNO = VQUERYNO);                            
         DELETE FROM EXPLAIN_DIAGNOSTIC_DATA WHERE (EXPLAIN_REQUESTER,EXPLAIN_TIME,SOURCE_NAME,SOURCE_SCHEMA,SOURCE_VERSION,EXPLAIN_LEVEL,STMTNO,SECTNO,DIAGNOSTIC_ID) IN (SELECT EXPLAIN_REQUESTER,EXPLAIN_TIME,SOURCE_NAME,SOURCE_SCHEMA,SOURCE_VERSION,EXPLAIN_LEVEL,STMTNO,SECTNO,DIAGNOSTIC_ID FROM EXPLAIN_DIAGNOSTIC WHERE (EXPLAIN_REQUESTER,EXPLAIN_TIME,SOURCE_NAME,SOURCE_SCHEMA,SOURCE_VERSION,EXPLAIN_LEVEL,STMTNO,SECTNO) IN (SELECT EXPLAIN_REQUESTER,EXPLAIN_TIME,SOURCE_NAME,SOURCE_SCHEMA,SOURCE_VERSION,EXPLAIN_LEVEL,STMTNO,SECTNO FROM EXPLAIN_STATEMENT WHERE QUERYNO = VQUERYNO));
  */         
         SET VEOF = 0;      
      END IF;         
      FETCH VCURCACHE INTO VSQLCACHE,VSTMTID,VNUM_EXECUTIONS,VQUERY_COST_ESTIMATE,VTOTAL_ACT_TIME_RATIO,VIO_READS_RATIO,VROWS_READS_RATIO,VROWS_RETURNED_RATIO,VAVG_IO_READS_RATIO1,VAVG_IO_READS_RATIO2,VINSERT_TIMESTAMP,VLAST_METRICS_UPDATE,VIOREADSRATIO1,VROWSREADRATIO1,VIOREADSRATIO2,VROWSREADRATIO2,VMOSTRADIAGNOSTICO;
   END WHILE;
              
   CLOSE VCURCACHE;
   
   SET VSQL = 'SELECT "Numero",
                      "Valor Hash SQL",
                      CASE WHEN "Diagnostico" <> '''' THEN CASE WHEN MOSTRADIAGNOSTICO = ''S'' THEN "Diagnostico" ELSE ''Ignorar o alto consumo! O SQL não é de Sistema'' END ELSE '''' END "Diagnostico",
--                      "Diagnostico",
                      "Comentarios do Analista",
                      "Qtd. Execucoes",
                      "Qt. Media de blocos lidos",
                      "Qt. Media de registros lidos",
                      "Texto do comando SQL",
                      "Sistema",
                      "Pacote",
                      "Custo",
                      "Tempo Medio(ms)",
                      "Horario de entrada do SQL no cache",
                      "Horario da ultima execucao",
                      "Plano de Execucao",
                      "Observacoes"
               FROM (SELECT ROW_NUMBER() OVER (ORDER BY NUM_EXECUTIONS DESC) "Numero",
                            VARCHAR(STMTID)                 "Valor Hash SQL",
                            CASE WHEN IOREADSRATIO1 = 1 OR ROWSREADRATIO1 = 1 OR TBSCANIXSCAN = 1 THEN ''Verificar SQL com urgencia!''||CHR(10)||CASE WHEN IOREADSRATIO1  = 1 THEN CHR(10)||CHR(9)||'' Qt. Media de blocos lidos alta!''                             ELSE '''' END||
                                                                                                                                           CASE WHEN ROWSREADRATIO1 = 1 THEN CHR(10)||CHR(9)||'' Qt. Media de registros alta!''                                ELSE '''' END||
                                                                                                                                           CASE WHEN TBSCANIXSCAN   = 1 THEN CHR(10)||CHR(9)||'' TBSCAN ou IXSCAN com muitos registros! Olhar em Observacoes'' ELSE '''' END
                                 WHEN IOREADSRATIO2 = 1 OR ROWSREADRATIO2 = 1                     THEN ''Verificar O SQL!''           ||CHR(10)||CASE WHEN IOREADSRATIO2  = 1 THEN CHR(10)||CHR(9)||'' Qt. Media de blocos lidos alta!''                             ELSE '''' END||
                                                                                                                                           CASE WHEN ROWSREADRATIO2 = 1 THEN CHR(10)||CHR(9)||'' Qt. Media de registros alta!''                                ELSE '''' END
                                 ELSE ''''       END       "Diagnostico",   
                            LPAD('' '',40,'' '')           "Comentarios do Analista",
                            NUM_EXECUTIONS                 "Qtd. Execucoes",
                            IO_READS_RATIO                 "Qt. Media de blocos lidos",   
                            ROWS_READS_RATIO               "Qt. Media de registros lidos",
                            CAST(SQL   AS VARCHAR(32000))  "Texto do comando SQL",
                            COALESCE(JSON_VALUE(JSON,''strict $.BIBLIOTECASQLS.SISTEMA'' RETURNING VARCHAR(200)),'''') "Sistema",
                            COALESCE(JSON_VALUE(JSON,''strict $.BIBLIOTECASQLS.PACKAGE'' RETURNING VARCHAR(200)),'''') "Pacote",                      
                            QUERY_COST_ESTIMATE            "Custo",
                            TOTAL_ACT_TIME_RATIO           "Tempo Medio(ms)",                      
                            INSERT_TIMESTAMP               "Horario de entrada do SQL no cache",
                            LAST_METRICS_UPDATE            "Horario da ultima execucao",
                            CAST(PLANO AS VARCHAR(32000))  "Plano de Execucao",
                            OBSERVACOES                    "Observacoes",
                            MOSTRADIAGNOSTICO
                      FROM (SELECT IOREADSRATIO1,
                                   ROWSREADRATIO1,
                                   CASE WHEN (QTDTBSCANS > 0 OR QTDIXSCANS > 0) THEN 1 ELSE 0 END TBSCANIXSCAN,
                                   IOREADSRATIO2,
                                   ROWSREADRATIO2,
                                   NUM_EXECUTIONS,
                                   STMTID,
                                   QUERY_COST_ESTIMATE,
                                   TOTAL_ACT_TIME_RATIO,
                                   IO_READS_RATIO, 
                                   ROWS_READS_RATIO,
                                   INSERT_TIMESTAMP,
                                   LAST_METRICS_UPDATE,
                                   SQL,
                                   SYSTOOLS.JSON2BSON(CASE WHEN INSTR(SQL,''{"BIBLIOTECASQLS"'') <> 0 THEN SYSTOOLS.BSON2JSON(SYSTOOLS.JSON2BSON(SUBSTR(SQL,INSTR(SQL,''{"BIBLIOTECASQLS"''),INSTR(SQL,''}}'')-INSTR(SQL,''{"BIBLIOTECASQLS"'')+2)))
                                                           WHEN SQL LIKE ''/* load%'' THEN ''{"BIBLIOTECASQLS":{"PACKAGE": "''||SUBSTR(SQL,INSTR(SQL,''/* load'')+8,INSTR(SQL,''*/'')-(INSTR(SQL,''/* load'')+9))||''"}}''
                                   ELSE NULL END) JSON,
                                   '''' PLANO,
                                   OBSERVACOES,
                                   MOSTRADIAGNOSTICO
                             FROM SESSION.EXPLAIN))';
   PREPARE VRETORNO FROM VSQL;
   OPEN VCURSORRETORNO;
END;
;
-- COPY-DATABASE-OBJECT: "DBSYS"."PRC_TUNING_EXPLAIN_AJUDA"
CREATE OR REPLACE PROCEDURE "DBSYS"."PRC_TUNING_EXPLAIN_AJUDA" ()
   RESULT SETS 1
   LANGUAGE SQL
   SPECIFIC PRC_TUNING_EXPLAIN_AJUDA
BEGIN
   DECLARE VCURSOR CURSOR WITH RETURN FOR 
      WITH AJUDA ("Texto") AS (VALUES '   Descricao:
                                       
      Descricao informa as estatisticas de execucao, o texto do comando SQL, o Plano de Execucao e observacoes sobre a utilizacao dos operadores utilizados pelo banco sobre as tabelas e indices. Por Default, o Plano de execucao e as observacoes so serao gerados para os comandos SQL com indicacao de problemas de desempenho.
      
   Parametros:      
      
       . PTABSCHEMA:                obrigatorio, o nome do esquema  
       . PIO_READS_RATIO:           opcional, a quantidade Media minima de blocos lidos para utilizar como filtro - valor default NULL
       . PROWS_READS_RATIO:         opcional, a quantidade Media minima de registros lidos para utilizar como filtro - default NULL
       . PSTREAM_COUNT:             opcional, informa a quantidade minima de registros utilizadas por um operador - valor default NULL
       . PIO_READS_RATIOALERTA1:    opcional, a quantidade Media minima de blocos lidos para gerar um alerta de urgencia - valor default 1500
       . PIO_READS_RATIOALERTA2:    opcional, a quantidade Media minima de blocos lidos para gerar um alerta - valor default 500       
       . PROWS_READS_RATIOALERTA1:  opcional, a quantidade Media minima de registros lidos para gerar um alerta de urgencia - valor default  1500
       . PROWS_READS_RATIOALERTA2:  opcional, a quantidade Media minima de registros lidos para gerar um alerta - valor default 500              
       . PEXPLAIN_ALL            :  opcional, se setado para 1, irá gerar os planos de execucao e as observacoes para todos os comandos SQL

   informacoes:  
   
       . Numero                               sequencial para ajudar na referencia a um comando SQL
       . Valor Hash SQL                       número Hash gerado pelo IBM DB2, que identifica o SQL
       . Diagnostico:                         mensagem sobre as estatisticas de execucao   
       . Comentarios do Analista              observacao sobre o problema indicado no diagnostico. Exemplos:
	       . SQL com problemas, mas antigo, nao pertencente a demanda atual. O Tuning ja estiver no BackLog
	       . O DBA aprovou o SQL. O alto consumo e devido a caracteristicas do negocio
	       . O DBA aprovou o SQL com as seguintes ressalvas: ...       
       . Qtd. Execucoes:                      a quantidade de Execucoes do mesmo comando SQL
       . Custo:                               o custo do SQL estimado pelo Banco de Dados       
       . Tempo Medio(ms)                      o tempo medio de execucao para cada comando SQL em milisegundos
       . Qt. Media de blocos lidos:           a quantidade Qt. Media de blocos lidos
       . Qt. Media de registros lidos:        a quantidade Media de registros lidos   
       . Qt. Media de registros retornados:   a quantidade Media de registros retornados
       . Horario de entrada do SQL no cache:  a data/hora de entrada do comando SQL no cache
       . Horario da ultima execucao:          a data/hora da ultima execucao do comando SQL           
       . Texto do comando SQL:                o texto do comando SQL                      
       . Plano de Execucao SQL:               o texto do Plano de Execucao SQL                             
       . Observacoes:                         mensagens de alerta em referencia ao Plano de Execucao SQL
    
   Exemplo de utilizacao:         

      Gera as estatisticas para todos os comandos SQLs do esquema "CRE". Os Planos de execução e observações serão gerados apenas para os SQLs com indicações de problemas de desempenho.

         CALL DBSYS.PRC_TUNING_EXPLAIN (''CRE'')

      Gera as estatisticas, Planos de Execucao e Observacoes para todos os comandos SQLs do Esquema "CRE".

         CALL DBSYS.PRC_TUNING_EXPLAIN (PTABSCHEMA => ''CRE'', PEXPLAIN_ALL => 1)       
       
       
   Observacoes:
   
       . e possivel limpar o cache do DB2 antes dos testes, utilizando o comando "FLUSH PACKAGE CACHE DYNAMIC" (solicitar a execucao a um dos DBAs).
       . para ver o Plano de Execucao para um comando individual, utilizar a clausula "EXPLAIN PLAN FOR", seguido do comando SQL, e depois consultar a View
         DBSYS.VIW_TUNING_EXPLAIN:
       
         Exemplo:
         
            EXPLAIN PLAN FOR SELECT * FROM CRE.AGENDAREGISTRO;
            
            SELECT * FROM DBSYS.VIW_TUNING_EXPLAIN;         
         
       
   Planos de Execucao
   
      Os Planos de Execucao sao os guias que os Bancos de Dados utilizam para executar os comandos SQL. No DB2, os seguintes comandos necessitam de Planos de Execucao:
      
         . comandos XQuery 
         . CALL
         . Compound SQL (Dynamic)
         . DELETE
         . INSERT
         . MERGE
         . REFRESH
         . SELECT
         . SELECT INTO
         . SET INTEGRITY
         . UPDATE
         . VALUES
         . VALUES INTO
      
      Os Bancos de Dados persistem os seus dados em dispositivos fisicos (Discos SAS ou SSD, memiria RAM e etc). 
      
      O IBM DB2 organiza suas informacoes em "Containers", que sao arquivos fisicos armazenados nos dispositivos. Os "Containers" sao agrupados logicamente 
   em "Tablespaces". Uma Tablespace e composta por um ou mais Containers, e seu espaco e organizado em unidades contiguas menores chamadas Extensoes, ("Extents"). 
   As Extensoes sao compostas por Blocos de "N" KBytes (4/8/16/32 KBytes por exemplo). Os registros das tabelas e indice sao armazenados nos Blocos.
   
     Exemplo: 
     
              CREATE LARGE TABLESPACE FLXTBS08K PAGESIZE 8K EXTENTSIZE 4;
   
                 Tablespace FLXTBS08K cuja unidade de amazenamento e de 4 extensoes de 8KBytes cada uma.
              
              CREATE TABLE FLX.SITUACAO (ID INTEGER NOT NULL PRIMARY KEY,NOME VARCHAR(50) NOT NULL) IN FLXTBS08K
              
                 Tabela criada na tablespace FLXTBS08K.
   
      Os principais objetos de um Banco de Dados sao as Tabelas e os indices, ambos criados em Tablespaces. Quando um registro e inserido em uma tabela, o Banco de Dados
   verifica se existe alguma extensao na Tablespace que ainda tenha espaco disponivel. Caso nao exista, ou seja o primeiro registro, o Banco de Dados cria uma extensao  
   de "N" Blocos de "N" KBytes (de acordo com a definicao da Tablespace) contiguos na unidade de armazenamento (no Container), e armazena o registro. 
      
      
   Tabelas
         
      As tabelas sao compostas por registros que podem ou estar armazenadas sem nenhuma ordem especifica, ou podem ser seguir alguma regra de alocacao. 
      
      Por exemplo, uma tabela pode ser criada com um metodo de organizacao chamado "particionamento range". Ele cria "subtabelas", dentro da tabela, separando os registros
   de acordo com algum criterio, por exemplo, a data de criacao.
   
      Exemplo: 
      
         CREATE TABLE ORIGINAL  (ID   INTEGER NOT NULL GENERATED ALWAYS AS IDENTITY PRIMARY KEY, 
                                 DATA DATE    NOT NULL) 
         PARTITION BY RANGE(DATA)
           (PART PART001 STARTING(''2012-01-01'') INCLUSIVE ENDING(''2012-02-01'') EXCLUSIVE,
            PART PART002 STARTING(''2012-02-01'') INCLUSIVE ENDING(''2012-03-01'') EXCLUSIVE);
            
          o particionamento range e util por permitir ao Banco de Dados, restringir as consultas a uma determinada particao da tabela. 
       
          Exemplo:
       
              SELECT * FROM ORIGINAL WHERE DATA BETWEEN ''2012-01-01'' AND ''2012-01-31''
           
          ele tambem e util por permitir incluir ("Attach"), excluir ("Detach") ou criar novas particoes ("Add"), que propiciam metodos muito mais rapidos
       de incluir ou excluir um grande conjunto de dados em uma tabela.
    
          Observacao: O particionamento range exige que as particoes sejam criadas antes que os registros sejam incluidos. No exemplo acima, o Banco de Dados daria um erro
       se houvesse a tentativa de incluir um registro com a valor para o atributo DATA igual a ''2012-03-01'', ja que nao existe particao criada para esse mes.
    
    Outra forma de particionamento existente no DB2 e o particionamento MDC (Multidimensional Clustering). O DB2 ira manter juntos, nas mesmas extensoes, os registros com 
 os mesmos valores das "dimensoes" declaradas na criacao da tabela. O DB2 ira manter indices de bloco, que irao aponter  para "extensoes", ao contrario dos indices BTree 
 convencionais que apontam para registros.
 
       Exemplo: 
      
         CREATE TABLE ORIGINAL  (ID          INTEGER NOT NULL GENERATED ALWAYS AS IDENTITY PRIMARY KEY, 
                                 INSTITUICAO INTEGER NOT NULL,
                                 DATA        DATE    NOT NULL) 
         ORGANIZE BY (IDINSTITUICAO,DATA);
 
       essa forma de particionamento e automatica. O DB2, ao receber uma demanda de inclusao ou alteracao, verifica no indice de Bloco se ja existe alguma extensao 
    reservada para aquele valor (ou valores) da dimensao (ou dimensoes). Se nao houver, ele cria a extensao (N blocos de N KBytes, como vimos), e armazena o registro
    nesssa extensao. O DB2 fara isso para cada combinacao dos valores das dimensoes. Quando uma determinada extensao, criada para uma determinada combinacao de valores
    das dimensoes estiver sem espaco, o DB2 cria uma nova extensao, e atualiza o indice de bloco, incluindo a informacao da nova extensao da lista de extensoes que 
    armazenam os valores para aquela combinacao.
    
       O Particionamento MDC traz a vantagem de manter dados com os mesmos valores dos atributos das dimensoes em locais contiguos nas unidades de armazenamento 
    (os dados estsao "clusterizados"). Isso acelera o desempenho em pesquisas feitas pelas dimensoes MDC, que retornam um grande nimero de registros,  principalmente 
    nos dispositivos fisicos do tipo Disco rigido, por evitar que a cabeia de leitura do disco tenha que se deslocar aleatoriamente no dispositivo.
    
   indices
   
      Os indices no DB2, que sao do tipo BTree, sao estruturas semelhantes aos indices remissivos de um livro. Eles permitem o acesso direto aos registros, baseados em buscas
   pelos atributos que compiem o indice.
   
   Exemplo:
   
            CREATE TABLE ORIGINAL  (ID          INTEGER      NOT NULL GENERATED ALWAYS AS IDENTITY, 
                                    NOME        VARCHAR(100) NOT NULL,
                                    CPF         VARCHAR(11)  NOT NULL) 
   
               supondo que a tabela ORIGINAL tenha 100.000 registros, uma pesquisa do tipo:
               
                  SELECT CPF FROM ORIGINAL WHERE NOME = ?
                  
               faria com que o DB2 fizesse um TBSCAN na tabela (acesso a todos os registros) para descobrir quais registros atendem o criterio de pesquisa.
               
               plano de execucao gerado pelo DB2:
               
                  Operation                   Node Cost Cost              CPU Cost I/O Cost Stream Count      Column Count 
                  --------------------------- --------- ----------------- -------- -------- ----------------- ------------ 
                  RETURN                      0,0 %     7.581757545471191 115158.0 1.0                                     
                    USRGEDAD.ORIGINAL  TBSCAN 100,0 %   7.581757545471191 115158.0 1.0      1.159999966621399 1            
               
               
               Criando o indice:
               
                  CREATE INDEX IDX_ORIGINAL_01 ON ORIGINAL (NOME)
                  
               agora, o DB2 constrii e mantim a estrutura do indice, que e atualizada sempre que um registro e incluido, alterado ou excluido. 
               
               O Db2 ira realizar, para a consulta acima, uma operacao de varredura do indice (operador IXSCAN) IDX_ORIGINAL_01, ira recuperar no indice o RID (Record Identified), 
            e ira acessar a tabela (operador Fetch) para recuperar o valor do atributo CPF.
            
               plano de execucao gerado pelo DB2:            
            
                  Operation                            Node Cost Cost              CPU Cost      I/O Cost           Stream Count       Column Count 
                  ------------------------------------ --------- ----------------- ------------- ------------------ ------------------ ------------ 
                  RETURN                               0,0 %     42.06038284301758 181099.375    5.559016704559326                                  
                    USRGEDAD.ORIGINAL  FETCH           62,6 %    42.06038284301758 181099.375    5.559016704559326  24.119998931884766 1            
                      USRGEDAD.IDX_ORIGINAL_01  IXSCAN 37,4 %    15.7461519241333  113012.953125 2.0799999237060547 24.119998931884766 1            
            
            
               caso o indice fosse criado da seguinte maneira:
               
                   CREATE INDEX IDX_ORIGINAL_01 ON ORIGINAL (NOME,CPF)
               
               o DB2 nao teria que fazer o acesso a tabela, ja que todas os atributos necessarios estao presentes no indice (NOME e CPF)
               
               plano de execucao gerado pelo DB2:                           
               
                  Operation                          Node Cost Cost               CPU Cost       I/O Cost          Stream Count       Column Count 
                  ---------------------------------- --------- ------------------ -------------- ----------------- ------------------ ------------ 
                  RETURN                             0,0 %     16.956146240234375 115087.7421875 2.240000009536743                                 
                    USRGEDAD.IDX_ORIGINAL_01  IXSCAN 100,0 %   16.956146240234375 115087.7421875 2.240000009536743 24.119998931884766 1   
                    
   
      Os indices tem um formato logico parecido com uma arvore invertida. Eles possuem um nivel Root, niveis  intermediarios e o nivel folha. No nivel folha fica
   o RID (Record Identified), que e um identificador que aponta para a localizacao do registro na tabela.
   
   
     Exemplo: Estrutura de um indice BTree
  
               +-------------------------------------------+ 
               !        c         j    l         z         !     / root 
               +--------+---------+----+---------+---------+
                        !         !    !         !
           +------------+     +---+    ---+      -----+     
        +--!---+      +-------!---+    +--!---+    +--!---+      
        !      !      !  d  f  J  !    !      !    !      !       / nis intermediirios
        +------+      +--+--+--+--+    +------+    +------+
                         !  !  !
                         !  !  !-----------------
                         !  !                   !
           +-------------+  +-------+           !
           !                        !           !  
        +--!-------+        +-------!---+    +--!---+
        !(''d'',rid) !        ! (''e'',rid) !    !      !  
        !          !        ! (''f'',rid) !    !      !             / nis folha
        +----------+        +-----------+    +------+
        

      A utilizacao de indices BTree e indicada para consultas por atributos com valores unicos, ou que retornem uma pequena quantidade de registros, em geral nao mais que 8%
   do total de registros de uma tabela.   


   Operadores 
   
      Os operadores utilizados pelo DB2 para acessar os dados, e que sao expostos no Plano de Execucao SQL sao:

      
         . HSJOIN       Hash Join           
         . INSERT       Insert
         . IXAND        Dynamic Bitmap Index ANDing
         . IXSCAN       Relational index scan
         . MSJOIN       Merge Scan Join
         . NLJOIN       Nested loop Join
         . RETURN       Result
         . RIDSCN       Row Identifier (RID) Scan
         . RPD          Remote PushDown
         . SHIP         Ship query to remote system
         . SORT         Sort
         . TBSCAN       Table Scan
         . TEMP         Temporary Table Construction
         . TQ           Table Queue
         . UNION        Union
         . UNIQUE       Duplicate Elimination
         . UPDATE       Update
         . XISCAN       Index scan over XML data
         . XSCAN        XML document navigation scan
         . XANDOR       Index ANDing and ORing over XML data 

         
         HSJOIN - Forma de juncao de dois conjuntos de registros, onde uma dos membros do conjunto e lido completamente, e uma tabela Hash e construida a partir 
                  do atributo (ou atributos) utilizados na juncao; depois o outro conjunto de registros e lido, o valor Hash do(s) atributo(s) e calculado, e a tabela Hash 
                  gerada no primeiro e acessada, juntando assim os registros.
                  
         IXAND  - Quando dois indices BTree sao acessados, e seus RIDs sao combinados.
         
         IXSCAN - Um indice e acessado.
         
         MSJOIN - Uma forma de juncao entre dois conjuntos de registros, utilizado apenas quando o sinal de igualdade e utilizado na juncao, e que sorteia os dois 
                  conjuntos de registros pelos atributos utilizados na juncao, e depois faz um balance line entre os dois conjuntos de registros.

         NLJOIN - Uma forma de juncao entre dois conjuntos de registros, aonde um dos conjuntos e lido um a um, e para cada registro retornado, os registros no segundo
                  conjunto de registros e recuperado, geralmente utilizando um indice.

         SORT   - Operacao que organiza um conjunto de registros baseado em algum criterio.

         TBSCAN - Informa que uma varredura completa sera feita em uma tabela. So e aceitavel no caso de tabelas pequenas, ou quanto uma grande quantidade de 
                  registros de uma grande tabela devera ser retornada.
               
         TEMP   - Constrii uma tabela temporiria para armazenar resultados intermediarios.

         UNION  - Une dois conjuntos de registros.
         
         UNIQUE - Elimina os registros duplicados.

         UPDATE - Altera um registro.
         
         XISCAN - Faz uma pesquisa por um indice baseado em uma Tag XML.
         
         XSCAN  - Percorre todo um documento XML.
         
         XANDOR - Fax um ANDing e ORing sobre dados XML.            
                 ')
      SELECT *
      FROM AJUDA;
   OPEN VCURSOR;
END;
;
