-- COPY-DATABASE-OBJECT: "DBSYS"."PRC_TUNING_INDICES"
CREATE OR REPLACE PROCEDURE "DBSYS"."PRC_TUNING_INDICES" (PTABSCHEMA VARCHAR(10) DEFAULT NULL,PTABNAME VARCHAR(100) DEFAULT NULL)
   RESULT SETS 1
   LANGUAGE SQL
   SPECIFIC PRC_TUNING_INDICES
BEGIN
   DECLARE VCURSOR CURSOR WITH RETURN FOR 
      SELECT CASE WHEN I.FULLKEYCARD = -1 AND I.INDEXTYPE <> 'XVIL' THEN 'estatisticas nao geradas!' 
                  --WHEN FULLKEYCARD < 10 THEN 'Cardinalidade < 10. Verificar a utilidade do indice!'
                  ELSE '' END "Diagnostico",
             ' '               "Comentarios do Analista",                  
             CASE WHEN I.INDEXTYPE <> 'XVIL' THEN TO_CHAR(I.STATS_TIME,'DD/MM/YYYY HH24:MI:SS') ELSE TO_CHAR(I2.STATS_TIME,'DD/MM/YYYY HH24:MI:SS') END "Dt. Estats.",
             TRIM(I.TABSCHEMA)             "Esquema",
             I.TABNAME                     "Tabela",
             I.INDNAME                     "Indice",
             CASE WHEN I.INDEXTYPE = 'REG'           THEN 'BTree'
                  WHEN I.INDEXTYPE IN ('DIM','BLOK') THEN 'MDC'
                  WHEN I.INDEXTYPE = 'RTC'           THEN 'RTC'
                  WHEN I.INDEXTYPE LIKE 'X%'         THEN 'XML'
             END             "Tipo",
             CASE WHEN I.INDEXTYPE <> 'XVIL' THEN I.COLNAMES       ELSE I.COLNAMES ||' ('||CAST(IP.PATTERN AS VARCHAR(200))||')' END    "Colunas",
             CASE WHEN I.INDEXTYPE <> 'XVIL' THEN I.FIRSTKEYCARD   ELSE I2.FIRSTKEYCARD  END FIRSTKEYCARD,
             CASE WHEN I.INDEXTYPE <> 'XVIL' THEN I.FIRST2KEYCARD  ELSE I2.FIRST2KEYCARD END FIRST2KEYCARD,
             CASE WHEN I.INDEXTYPE <> 'XVIL' THEN I.FIRST3KEYCARD  ELSE I2.FIRST3KEYCARD END FIRST3KEYCARD,
             CASE WHEN I.INDEXTYPE <> 'XVIL' THEN I.FIRST4KEYCARD  ELSE I2.FIRST4KEYCARD END FIRST4KEYCARD,
             CASE WHEN I.INDEXTYPE <> 'XVIL' THEN I.FULLKEYCARD    ELSE I2.FULLKEYCARD   END FULLKEYCARD 
      FROM SYSCAT.INDEXES I LEFT OUTER JOIN SYSCAT.INDEXXMLPATTERNS IP ON I.INDSCHEMA  = IP.INDSCHEMA AND I.INDNAME   = IP.INDNAME
                            LEFT OUTER JOIN SYSCAT.INDEXES          I2 ON I2.INDSCHEMA = 'SYSIBM'     AND IP.PINDNAME = I2.INDNAME
                                 INNER JOIN SYSCAT.TABLES           T  ON I.TABSCHEMA = T.TABSCHEMA   AND I.TABNAME   = T.TABNAME
      WHERE I.TABSCHEMA = UPPER(PTABSCHEMA)
        AND (PTABNAME IS NULL OR I.TABNAME = UPPER(PTABNAME))
        AND T.TYPE = 'T'
        AND I.INDEXTYPE <> 'TEXT'
      ORDER BY I.TABNAME,I.INDNAME;
   IF PTABSCHEMA IS NULL THEN
      SIGNAL SQLSTATE '75001'
           SET MESSAGE_TEXT = 'Ex: CALL DBSYS.PRC_TUNING_INDICES (''CRE'')';
   END IF;            
   OPEN VCURSOR;
END;
;
-- COPY-DATABASE-OBJECT: "DBSYS"."PRC_TUNING_INDICES_AJUDA"
CREATE OR REPLACE PROCEDURE "DBSYS"."PRC_TUNING_INDICES_AJUDA" ()
   RESULT SETS 1
   LANGUAGE SQL
   SPECIFIC PRC_TUNING_INDICES_AJUDA
BEGIN
   DECLARE VCURSOR CURSOR WITH RETURN FOR 
      WITH AJUDA ("Texto") AS (VALUES 
'PRC_TUNING_INDICES

   Descricao:
      
      informacoes sobre os indices das tabelas.       
      
   Parametros:
      
       . PTABSCHEMA: obrigatorio, o nome do esquema
       . PTABNAME:   opcional, nome de uma tabela

   informacoes:
      
       . Diagnostico:               mensagem 
       . Comentarios do Analista    justificativas do analista
       . Dt. Estats.                a data da ultima geracao de estatisticas
       . Esquema:                   o nome do esquema	
       . Tabela:                    o nome da tabela	
       . Indice:                    o nome do indice
       . Tipo                       o tipo do indice (BTree, MDC-Multidimensional Clustering, RTC-Range Clustered Tables ou XML)
       . Colunas                    as colunas pertencentes ao indice
       . FIRSTKEYCARD               a cardinalidade da primeira coluna do indice
       . FIRST2KEYCARD              a cardinalidade combinada da primeira e da segunda colunas do indice
       . FIRST3KEYCARD              a cardinalidade combinada da primeira, da segunda e da terceira colunas do indice
       . FIRST4KEYCARD              a cardinalidade combinada da primeira, da segunda, da terceira e da quarta colunas do indice
       . FULLKEYCARD                a cardinalidade combinada de todas as colunas do indice
       . Qt. Estats. Regs.:         a quantidade de registros obtida na ultima geracao de estattisticas
       . Dt. Estats.:               a data da ultima geracao de estatisticas
       . Qt. Calc. Regs.:           a quantidade atual registros, calculada ate o limite do parametro PQTDMAXREGISTROS (default 100.000).  

   Verificar:
    
       . as mensagens de advertencia do relatorio.
       . as datas de geracao de estatisticas.
       . indices em atributos com baixa cardinalidade e com distribuicao equilibrada (indices em atributos que sao chave estrangeira para tabelas de dominio) so 
          devem ser mantidos no caso da possibilidade de exclusao de registros na tabela de dominio.
       . indices em atributos com baixa cardinalidade, e com distribuicao nao equilibrada (Ex: atributo "SituacaoLote" em uma tabela de "LotesaProcessar") sao uteis
         (ver ajuda sobre Bind Variables).

   Observacao:
       
       . se necessario executar a procedure DBSYS.PRC_TUNING_RUNSTATS para atualizar as estatisticas.
          
   Sobre os indices:
                                       
       . devem ser criados para atender os criterios de consulta, e juncoes entre tabelas.
       . os indices deverao estar com suas estatisticas atualizadas.')                                             
      SELECT *
      FROM AJUDA;
   OPEN VCURSOR;
END;
;
-- COPY-DATABASE-OBJECT: "DBSYS"."PRC_TUNING_INDICES_PARTICIONADOS"
CREATE OR REPLACE PROCEDURE "DBSYS"."PRC_TUNING_INDICES_PARTICIONADOS" (PTABSCHEMA VARCHAR(10) DEFAULT NULL,PTABNAME VARCHAR(100) DEFAULT NULL)
   RESULT SETS 1
   LANGUAGE SQL
   SPECIFIC PRC_TUNING_INDICES_PARTICIONADOS
BEGIN
   DECLARE VCURSOR CURSOR WITH RETURN FOR 
      SELECT DISTINCT TRIM(IP.TABSCHEMA) "Esquema",
                      IP.TABNAME         "Tabela",
                      IP.INDNAME         "Indice"
      FROM SYSCAT.INDEXPARTITIONS IP INNER JOIN SYSCAT.INDEXES I ON IP.INDSCHEMA = I.INDSCHEMA AND IP.INDNAME = I.INDNAME
      WHERE IP.TABSCHEMA = PTABSCHEMA
       AND (PTABNAME IS NULL OR IP.TABNAME = PTABNAME)      
       AND I.INDEXTYPE = 'REG'
      ORDER BY TRIM(IP.TABSCHEMA),IP.TABNAME,IP.INDNAME;
   IF PTABSCHEMA IS NULL THEN
      SIGNAL SQLSTATE '75001'
           SET MESSAGE_TEXT = 'Ex: CALL DBSYS.PRC_TUNING_INDICES_PARTICIONADOS (''CRE'')';
   END IF;             
   OPEN VCURSOR;
END;
;
