-- COPY-DATABASE-OBJECT: "DBSYS"."PRC_TUNING_KILL"
CREATE OR REPLACE PROCEDURE "DBSYS"."PRC_TUNING_KILL" (VAPPLICATION_HANDLER BIGINT)
   LANGUAGE SQL
   SPECIFIC PRC_TUNING_KILL
BEGIN 
   DECLARE VMSGERRO VARCHAR(300);
   DECLARE VCOMANDO VARCHAR(100); 
   DECLARE CONTINUE HANDLER FOR SQLEXCEPTION, SQLWARNING, NOT FOUND 
   BEGIN
         GET DIAGNOSTICS EXCEPTION 1 VMSGERRO=MESSAGE_TEXT;        
         SIGNAL SQLSTATE '75003'
            SET MESSAGE_TEXT = VMSGERRO; 
   END;      
   SET VCOMANDO = 'CALL ADMIN_CMD ('||''''||'FORCE APPLICATION ('||VAPPLICATION_HANDLER||')'||''''||')';
   EXECUTE IMMEDIATE VCOMANDO;
END;
;
-- COPY-DATABASE-OBJECT: "DBSYS"."PRC_TUNING_KILL_BLOCKERS"
CREATE OR REPLACE PROCEDURE "DBSYS"."PRC_TUNING_KILL_BLOCKERS" ()
   LANGUAGE SQL
   SPECIFIC PRC_TUNING_KILL_BLOCKERS
BEGIN 
   FOR V_LISTA AS CUR1 CURSOR WITH HOLD FOR SELECT 'CALL ADMIN_CMD ('||''''||'FORCE APPLICATION ('||HLD_APPLICATION_HANDLE||')'||''''||')' COMANDO
                                            FROM SYSIBMADM.MON_LOCKWAITS
   DO
      EXECUTE IMMEDIATE V_LISTA.COMANDO;
   END FOR;
END;
;
