-- COPY-DATABASE-OBJECT: "DBSYS"."PRC_TUNING_RUNSTATS"
CREATE OR REPLACE PROCEDURE "DBSYS"."PRC_TUNING_RUNSTATS" (PTABSCHEMA VARCHAR(50),PTABNAME VARCHAR(50) DEFAULT NULL,PMETODO CHAR DEFAULT 'A')
   LANGUAGE SQL
   SPECIFIC PRC_TUNING_RUNSTATS
BEGIN
   DECLARE VEOF    SMALLINT;
   DECLARE VSQL  VARCHAR(2000);
   DECLARE VTABNAME VARCHAR(100);
   DECLARE VSTMT STATEMENT;
      DECLARE VCURSOR CURSOR WITH HOLD WITH RETURN FOR
      SELECT TABNAME
      FROM SYSCAT.TABLES
      WHERE TABSCHEMA = UPPER(PTABSCHEMA)
        AND (PTABNAME IS NULL OR TABNAME = UPPER(PTABNAME))
        AND TYPE = 'T'
      ORDER BY TABNAME;
   DECLARE CONTINUE HANDLER FOR SQLEXCEPTION SET VEOF = 0;      
   DECLARE CONTINUE HANDLER FOR NOT FOUND
      SET VEOF = 1;
   IF PMETODO NOT IN ('C','A') THEN
      SIGNAL SQLSTATE '75001'
         SET MESSAGE_TEXT = 'Favor entrar com C-Completa ou A-Amostragem';
   END IF;
   SET VEOF = 0;
   OPEN VCURSOR;
   FETCH VCURSOR INTO VTABNAME;
   WHILE VEOF = 0 DO
      --IF PMETODO = 'C' THEN
         --SET VSQL = 'CALL ADMIN_CMD (''RUNSTATS ON TABLE '||PTABSCHEMA||'."'||VTABNAME||'" WITH DISTRIBUTION AND DETAILED INDEXES ALL'')';
      --ELSE
         SET VSQL = 'CALL ADMIN_CMD (''RUNSTATS ON TABLE '||PTABSCHEMA||'."'||VTABNAME||'" ON ALL COLUMNS WITH DISTRIBUTION DEFAULT NUM_FREQVALUES 200 NUM_QUANTILES 200 AND DETAILED INDEXES ALL ALLOW WRITE ACCESS TABLESAMPLE SYSTEM(1) INDEXSAMPLE SYSTEM(1)'')';
      --END IF;
      PREPARE VSTMT FROM VSQL;
      EXECUTE VSTMT;
      FETCH VCURSOR INTO VTABNAME;
   COMMIT;
   END WHILE;
   CLOSE VCURSOR;
   COMMIT;
END;
;
-- COPY-DATABASE-OBJECT: "DBSYS"."PRC_TUNING_RUNSTATS_AJUDA"
CREATE OR REPLACE PROCEDURE "DBSYS"."PRC_TUNING_RUNSTATS_AJUDA" ()
   RESULT SETS 1
   LANGUAGE SQL
   SPECIFIC PRC_TUNING_RUNSTATS_AJUDA
BEGIN
   DECLARE VCURSOR CURSOR WITH RETURN FOR 
      WITH AJUDA ("Texto") AS (VALUES 
'DBSYS.PRC_TUNING_RUNSTATS
      
   Descricao:
      
      Gerar estatisticas de todas as tabelas de um esquema, ou de uma unica tabela, de maneira completa ou por amostragem.
      
   Parametros:

       . PTABSCHEMA:       obrigatorio, o nome do esquema
       . PTABNAME:         opcional, o nome de uma da tabela                                  
       . PMETODO:          opcional, o tipo de geracao de estatisticas, ''C'' - geracao completa de estatisticas, ''A'' - geracao de estatisticas 
                           por amostragem (default ''C'')  
      
   Exemplo de utilizacao:
    
      para a geracao completa de estatisticas de dodas as tabelas de um esquema 
          
         CALL DBSYS.PRC_TUNING_RUNSTATS (''CRE'')

      para a geracao por amostragem das estatisticas de dodas as tabelas de um esquema 
  
         CALL DBSYS.PRC_TUNING_RUNSTATS (''CRE'',NULL,''A'') 
                
      para a geracao completa de estatisticas de dodas de uma tabela de um esquema
            
         CALL DBSYS.PRC_TUNING_RUNSTATS (''CRE'',''TIPOCREDITO'')
                
      para a geracao por amostragem das estatisticas de uma tabela de um esquema
             
         CALL DBSYS.PRC_TUNING_RUNSTATS (''CRE'',''TIPOCREDITO'',''A''))')
      SELECT *
      FROM AJUDA;
   OPEN VCURSOR;
END;
;
-- COPY-DATABASE-OBJECT: "DBSYS"."PRC_TUNING_SQLS"
CREATE OR REPLACE PROCEDURE "DBSYS"."PRC_TUNING_SQLS" (PTABSCHEMA VARCHAR(10) DEFAULT NULL,PIO_READS_RATIO INTEGER DEFAULT 500,PROWS_READS_RATIO INTEGER DEFAULT 500,PIO_READS_RATIOALERTA1 INTEGER DEFAULT 1000,PIO_READS_RATIOALERTA2 INTEGER DEFAULT 500,PROWS_READS_RATIOALERTA1 INTEGER DEFAULT 5000,PROWS_READS_RATIOALERTA2 INTEGER DEFAULT 2500)
   RESULT SETS 1
   LANGUAGE SQL
   SPECIFIC PRC_TUNING_SQLS
BEGIN
   DECLARE VCURSOR CURSOR WITH RETURN FOR
      SELECT ROW_NUMBER() OVER (ORDER BY NUM_EXECUTIONS DESC) "Numero",
             STMTID                            "Valor Hash SQL",
             CASE WHEN ((PIO_READS_RATIO   IS NULL OR IO_READS_RATIO   >= PIO_READS_RATIO) OR
                        (PROWS_READS_RATIO IS NULL OR ROWS_READS_RATIO >= PROWS_READS_RATIO)) THEN
                CASE WHEN (IO_READS_RATIO > (10 * AVG_IO_READS_RATIO1)) OR (IO_READS_RATIO > (10 * AVG_IO_READS_RATIO2)) OR (IO_READS_RATIO >= PIO_READS_RATIOALERTA1) OR (ROWS_READS_RATIO >= PROWS_READS_RATIOALERTA1) THEN 'Verificar SQL com urgencia!'
                     WHEN (IO_READS_RATIO > (5  * AVG_IO_READS_RATIO1)) OR (IO_READS_RATIO > (5  * AVG_IO_READS_RATIO2)) OR (IO_READS_RATIO >= PIO_READS_RATIOALERTA2) OR (ROWS_READS_RATIO >= PROWS_READS_RATIOALERTA2) THEN 'Verificar o SQL!'
                     ELSE ''
                END
                   ELSE ''
              END "Diagnostico",
             LPAD(' ',40,' ')                  "Comentarios do Analista",
             NUM_EXECUTIONS                    "Qtd. Execucoes",
             TIME_RATIO                        "Tempo Medio(ms)",
             TOTAL_CPU_TIME_RATIO              "Tempo Medio de CPU(ms)",
             IO_READS_RATIO                    "Qt. Media de blocos lidos",
             ROWS_READS_RATIO                  "Qt. Media de registros lidos",
             IO_WRITES_RATIO                   "Qt. Media de blocos gravados",
             ROWS_RETURNED_RATIO               "Qt. Media de registros retornados",
             IO_WRITES_RATIO                   "Qt. Media de registros gravados",
             ROWS_MODIFIED_RATIO               "Qt. Media de registros modificados",
             QUERY_COST_ESTIMATE               "Custo",
             TO_CHAR(INSERT_TIMESTAMP,'DD/MM/YYYY HH24:MI:SS')    "Horario de entrada do SQL no cache",
             TO_CHAR(LAST_METRICS_UPDATE,'DD/MM/YYYY HH24:MI:SS') "Horario da ultima execucao",
             EFFECTIVE_ISOLATION               "Nivel de Isolamento",
             XMLCAST(XMLQUERY('fn:translate($c,"ÁÇÉÍÓÚÀÈÌÒÙÂÊÔÛÃÕËÜáçéíóúààìòùãêôûãõ","ACEIOUAEIOUAEOUAOEUaceiouaaiouaeouao")' passing (SELECT TRIM(CAST(STMT_TEXT AS VARCHAR(32000))) FROM TABLE(MON_GET_PKG_CACHE_STMT (NULL, O.EXECUTABLE_ID, NULL, -2))) AS "c") AS VARCHAR(32000)) "Texto do comando SQL"--,
             --(SELECT TRIM(CAST(STMT_TEXT AS VARCHAR(32000))) FROM TABLE(MON_GET_PKG_CACHE_STMT (NULL, O.EXECUTABLE_ID, NULL, -2)))
                                              -- "Texto do comando SQL"
      FROM (SELECT VARCHAR(STMTID) STMTID,
                   NUM_EXECUTIONS,
                   QUERY_COST_ESTIMATE,
                   TIME_RATIO,
                   TOTAL_CPU_TIME_RATIO,
                   TOTAL_IO_READS,
                   IO_READS_RATIO,
                   AVG(IO_READS_RATIO) OVER (ORDER BY NUM_EXECUTIONS DESC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)   AVG_IO_READS_RATIO1,
                   AVG(IO_READS_RATIO) OVER (ORDER BY NUM_EXECUTIONS DESC ROWS BETWEEN 4 PRECEDING AND 4 FOLLOWING)           AVG_IO_READS_RATIO2,
                   TOTAL_ROWS_READ,
                   ROWS_READS_RATIO,
                   TOTAL_ROWS_RETURNED,
                   ROWS_RETURNED_RATIO,
                   TOTAL_IO_WRITES,
                   IO_WRITES_RATIO,
                   TOTAL_ROWS_MODIFIED,
                   ROWS_MODIFIED_RATIO,
                   INSERT_TIMESTAMP,
                   LAST_METRICS_UPDATE,
                   EFFECTIVE_ISOLATION,
                   EXECUTABLE_ID
            FROM (SELECT ROW_NUMBER()             OVER (PARTITION BY STMTID,SEMANTIC_ENV_ID ORDER BY 1)
                                                                                              SEQ,
                         VARCHAR(STMTID)                                                      STMTID,
                         SUM(NUM_EXECUTIONS)      OVER (PARTITION BY STMTID,SEMANTIC_ENV_ID)  NUM_EXECUTIONS,
                         QUERY_COST_ESTIMATE                                                  QUERY_COST_ESTIMATE,
                         SUM(TOTAL_ACT_TIME)      OVER (PARTITION BY STMTID,SEMANTIC_ENV_ID)  TOTAL_TIME,
                         SUM(TOTAL_ACT_TIME)      OVER (PARTITION BY STMTID,SEMANTIC_ENV_ID)
                        /SUM(NUM_EXECUTIONS)      OVER (PARTITION BY STMTID,SEMANTIC_ENV_ID)  TIME_RATIO,
                         SUM(TOTAL_CPU_TIME)      OVER (PARTITION BY STMTID,SEMANTIC_ENV_ID)
                        /CASE WHEN SUM(NUM_EXECUTIONS) OVER (PARTITION BY STMTID,SEMANTIC_ENV_ID) = 0 THEN 1 ELSE SUM(NUM_EXECUTIONS) OVER (PARTITION BY STMTID,SEMANTIC_ENV_ID) END
                                                                                              TOTAL_CPU_TIME_RATIO,
                         SUM(POOL_DATA_P_READS+POOL_TEMP_DATA_P_READS+POOL_XDA_P_READS+POOL_TEMP_XDA_P_READS+POOL_INDEX_P_READS+POOL_TEMP_INDEX_P_READS+POOL_DATA_GBP_P_READS+POOL_INDEX_GBP_P_READS+POOL_XDA_GBP_P_READS+POOL_COL_P_READS+POOL_TEMP_COL_P_READS+POOL_COL_GBP_P_READS+POOL_DATA_L_READS+POOL_TEMP_DATA_L_READS+POOL_XDA_L_READS+POOL_TEMP_XDA_L_READS+POOL_INDEX_L_READS+POOL_TEMP_INDEX_L_READS+POOL_DATA_GBP_L_READS+POOL_INDEX_GBP_L_READS+POOL_XDA_GBP_L_READS+POOL_COL_L_READS+POOL_TEMP_COL_L_READS+POOL_COL_GBP_L_READS) OVER (PARTITION BY STMTID,SEMANTIC_ENV_ID) TOTAL_IO_READS,
                         SUM(POOL_DATA_P_READS+POOL_TEMP_DATA_P_READS+POOL_XDA_P_READS+POOL_TEMP_XDA_P_READS+POOL_INDEX_P_READS+POOL_TEMP_INDEX_P_READS+POOL_DATA_GBP_P_READS+POOL_INDEX_GBP_P_READS+POOL_XDA_GBP_P_READS+POOL_COL_P_READS+POOL_TEMP_COL_P_READS+POOL_COL_GBP_P_READS+POOL_DATA_L_READS+POOL_TEMP_DATA_L_READS+POOL_XDA_L_READS+POOL_TEMP_XDA_L_READS+POOL_INDEX_L_READS+POOL_TEMP_INDEX_L_READS+POOL_DATA_GBP_L_READS+POOL_INDEX_GBP_L_READS+POOL_XDA_GBP_L_READS+POOL_COL_L_READS+POOL_TEMP_COL_L_READS+POOL_COL_GBP_L_READS) OVER (PARTITION BY STMTID,SEMANTIC_ENV_ID)
                        /SUM(NUM_EXECUTIONS)      OVER (PARTITION BY STMTID,SEMANTIC_ENV_ID)  IO_READS_RATIO,
                         SUM(ROWS_READ)           OVER (PARTITION BY STMTID,SEMANTIC_ENV_ID)  TOTAL_ROWS_READ,
                         SUM(ROWS_READ)           OVER (PARTITION BY STMTID,SEMANTIC_ENV_ID)
                        /SUM(NUM_EXECUTIONS)      OVER (PARTITION BY STMTID,SEMANTIC_ENV_ID)  ROWS_READS_RATIO,
                         SUM(ROWS_RETURNED)       OVER (PARTITION BY STMTID,SEMANTIC_ENV_ID)  TOTAL_ROWS_RETURNED,
                         SUM(ROWS_RETURNED)       OVER (PARTITION BY STMTID,SEMANTIC_ENV_ID)
                        /SUM(NUM_EXECUTIONS)      OVER (PARTITION BY STMTID,SEMANTIC_ENV_ID)  ROWS_RETURNED_RATIO,
                         SUM(POOL_DATA_WRITES+POOL_XDA_WRITES) OVER (PARTITION BY STMTID,SEMANTIC_ENV_ID)
                                                                                              TOTAL_IO_WRITES,
                         SUM(POOL_DATA_WRITES+POOL_XDA_WRITES) OVER (PARTITION BY STMTID,SEMANTIC_ENV_ID)
                        /SUM(NUM_EXECUTIONS)      OVER (PARTITION BY STMTID,SEMANTIC_ENV_ID)  IO_WRITES_RATIO,
                         SUM(ROWS_MODIFIED)       OVER (PARTITION BY STMTID,SEMANTIC_ENV_ID)  TOTAL_ROWS_MODIFIED,
                         SUM(ROWS_MODIFIED)       OVER (PARTITION BY STMTID,SEMANTIC_ENV_ID)
                        /SUM(NUM_EXECUTIONS)      OVER (PARTITION BY STMTID,SEMANTIC_ENV_ID)  ROWS_MODIFIED_RATIO,
                         MIN(INSERT_TIMESTAMP)    OVER (PARTITION BY STMTID,SEMANTIC_ENV_ID)  INSERT_TIMESTAMP,
                         MAX(LAST_METRICS_UPDATE) OVER (PARTITION BY STMTID,SEMANTIC_ENV_ID)  LAST_METRICS_UPDATE,
                         EFFECTIVE_ISOLATION                                                  EFFECTIVE_ISOLATION,
                         EXECUTABLE_ID                                                        EXECUTABLE_ID
                  FROM TABLE(SYSPROC.MON_GET_PKG_CACHE_STMT ( NULL, NULL, NULL, -2))
                  WHERE NUM_EXECUTIONS > 0
                    AND UPPER(CAST(STMT_TEXT AS VARCHAR(32000))) NOT LIKE '%NUM_EXECUTIONS%'
                    AND UPPER(CAST(STMT_TEXT AS VARCHAR(32000))) NOT LIKE '%DBSYS%'
                    --AND UPPER(CAST(STMT_TEXT AS VARCHAR(32000))) NOT LIKE '%SYSIBM%'
                    AND UPPER(CAST(STMT_TEXT AS VARCHAR(32000))) NOT LIKE '%CREATE %'
                    AND UPPER(CAST(STMT_TEXT AS VARCHAR(32000))) NOT LIKE '%ALTER %'
                    AND UPPER(CAST(STMT_TEXT AS VARCHAR(32000))) NOT LIKE '%DROP %'
                    AND UPPER(CAST(STMT_TEXT AS VARCHAR(32000))) NOT LIKE '%GRANT %'
                    AND UPPER(CAST(STMT_TEXT AS VARCHAR(32000))) NOT LIKE '%CONSTRAINT%'
                    --AND UPPER(CAST(STMT_TEXT AS VARCHAR(32000))) NOT LIKE '%EXPLAIN %'
                    AND UPPER(CAST(STMT_TEXT AS VARCHAR(32000))) NOT LIKE '%TRUNCATE %'
                    AND UPPER(CAST(STMT_TEXT AS VARCHAR(32000))) NOT LIKE '%COMMENT %'
                    --AND UPPER(CAST(STMT_TEXT AS VARCHAR(32000))) NOT LIKE '%RUNSTATS%'
                    AND (PTABSCHEMA IS NULL OR UPPER(CAST(STMT_TEXT AS VARCHAR(32000))) LIKE '%'||PTABSCHEMA||'.%')) O
            WHERE SEQ = 1
              --AND (PIO_READS_RATIO   IS NULL OR IO_READS_RATIO   >= PIO_READS_RATIO)
              --AND (PROWS_READS_RATIO IS NULL OR ROWS_READS_RATIO >= PROWS_READS_RATIO)
              ) O
            ORDER BY NUM_EXECUTIONS DESC;
   OPEN VCURSOR;
END;
;
-- COPY-DATABASE-OBJECT: "DBSYS"."PRC_TUNING_SQLS_AJUDA"
CREATE OR REPLACE PROCEDURE "DBSYS"."PRC_TUNING_SQLS_AJUDA" ()
   RESULT SETS 1
   LANGUAGE SQL
   SPECIFIC PRC_TUNING_SQLS_AJUDA
BEGIN
   DECLARE VCURSOR CURSOR WITH RETURN FOR 
      WITH AJUDA ("Texto") AS (VALUES 
'PRC_TUNING_SQLS

   Descricao:
                                       
      Informa estatisticas dos comandos SQLs no cache do DB2
      
   Parametros:
      
       . PTABSCHEMA:                obrigatirio, o nome do esquema
       . PIO_READS_RATIO:           opcional, a quantidade Media minima de blocos lidos para utilizar como filtro - valor default 500
       . PROWS_READS_RATIO:         opcional, a quantidade Media minima de registros lidos para utilizar como filtro - default null
       . PIO_READS_RATIOALERTA1:    opcional, a quantidade Media minima de blocos lidos para gerar um alerta de urgencia - valor default  1500
       . PIO_READS_RATIOALERTA2:    opcional, a quantidade Media minima de blocos lidos para gerar um alerta - valor default 500
       . PROWS_READS_RATIOALERTA1:  opcional, a quantidade Media minima de registros lidos para gerar um alerta de urgencia - valor default  1500
       . PROWS_READS_RATIOALERTA2:  opcional, a quantidade Media minima de registros lidos para gerar um alerta - valor default 500       
      
   informacoes:  
   
       . Numero                               sequencial para ajudar na referencia a um comando SQL
       . Valor Hash SQL                       número Hash gerado pelo IBM DB2, que identifica o SQL
       . Diagnostico:                         mensagens de sobre as estatisticas
       . Comentarios do Analista              observacao sobre o problema indicado no diagnostico. Exemplos:
	       . SQL com problemas, mas e antigo, nao pertencente a demanda atual. O Tuning ja esta no BackLog
	       . O DBA aprovou o SQL. O alto consumo e devido a caracteristicas do negocio
	       . O DBA aprovou o SQL com as seguintes ressalvas: ...
       . Qtd. Execucoes:                      a quantidade de Execucoes do mesmo comando SQL
       . Custo:                               o custo do SQL estimado pelo Banco de Dados
       . Tempo Medio(ms)                      o tempo medio de execucao para cada comando SQL em milisegundos       
       . Qt. Media de blocos lidos:           a quantidade Media de blocos lidos
       . Qt. Media de registros retornados:   a quantidade Media de registros retornados
       . Qt. Media de registros lidos:        a quantidade Media de registros lidos       
       . Qt. Media de registros gravados:     a quantidade Media de registros gravados
       . Qt. Media de registros modificados:  a quantidade Media de registros modificados
       . Horario de entrada do SQL no cache:  a data/hora de entrada do coamndo SQL no cache
       . Horario da ultima execucao           a data/hora da ultima execucao do comando SQL
       . Texto do comando SQL:                o texto do comando SQL 
       
   Observacoes:
   
       . e possivel limpar o cache do DB2 antes dos testes, utilizar o comando "FLUSH PACKAGE CACHE DYNAMIC" (verificar com os DBAs a disponibilidade no seu ambiente)             
       
   Interpretacao das informacoes:
   
      Um comando SQL e eficiente quando age sobre tabelas bem desenhadas, contendo particionamentos range, MDC, e indices desenhados para atender as diferentes
   maneiras que os registros irao ser acessados.
   
      Exemplos:
      
         . Uma tabela PESSOA, que contem o atributo CPF, que e unico, isto i, nao existe dois registros como o mesmo CPF, deve ter um indice 
           que possua o atributo CPF, para atender uma consulta do tipo: SELECT * FROM PESSOA WHERE CPF = ? 
           
           Exemplo:
           
              CREATE TABLE PESSOA (ID   BIGINT      NOT NULL GENERATED ALWAYS AS IDENTITY,
                                   CPF  VARCHAR(11) NOT NULL,
                                   NOME VARCHAR(80) NOT NULL)
                                   
              CREATE INDEX IDX_PESSOA ON PESSOA (CPF)
              
              lembrar que um indice com o formato
              
                 CREATE INDEX IDX_PESSOA ON PESSOA (NOME,CPF)
                 
              que e um indice composto, nao seri utilizado (ou nao seri utilizado de maneira eficiente), ja que a utilizacao de um indice e feita
           da esquerda para a direita. O indice acima poderi ser utilizado por consultas por NOME, ou por NOME e CPF, mas nao por CPF.
              
         . Uma tabela ITEMNOTA, que contem o atributo IDNOTA, deve ter um indice pelo atributo IDNOTA, e uma tabela NOTA deve, por exemplo, ter 
           um indice por DATAEMcao, para atender ao SQL:  SELECT N.ID,N.VALOR FROM NOTA N INNER JOIN ITEMNOTA IN ON N.IDNOTA = IT.IDNOTA WHERE DATAEMcao = ?
           
         . Uma tabela LOTE, e acessada pela coluna DATALOTE, e em media a tabela possui 100.000 registros por cada valor de DATALOTE. Nesse caso, e aconselhavel
           particionar a tabela LOTE pelo metodo MDC (Multidimensional Clustering), que faz com que os registros com o mesmo valor de uma dimensao, 
           que seria o atributo DATALOTE, fiquem armazenados juntos no dispositivo de armazenamento. Para criar o particionamento MDC, utiliza-se a clausula
           ORGANIZE BY no comando de criacao da tabela. O DB2, para as tabelas MDC, cria um indice especial chamado indice de bloco. Esse indice aponta para
           extensoes, ao inves de apontar para registros, como os indices BTree comuns. Uma tabela MDC, alem de ter indices de bloco (pelo menos um), tambem 
           pode ter indices BTree, alim de tambem poder ser particionada por outro tipo de particionamento chamado particionamento range.
           
           Exemplo:
           
              CREATE TABLE LOTE (ID            BIGINT      NOT NULL GENERATED ALWAYS AS IDENTITY,
                                 IDINSTITUICAO INTEGER NOT NULL
                                 DATALOTE      DATE         NOT NULL,
                                 VALOR         DECIMAL(8,2) NOT NULL) ORGANIZE BY (DATALOTE);
                                 
              no caso da tabela ser acessada por IDINSTITUICAO+DATALOTE, pode-se organizar a tabela pelos dois atributos da seguinte maneira:
              
              CREATE TABLE LOTE (ID            BIGINT      NOT NULL GENERATED ALWAYS AS IDENTITY,
                                 IDINSTITUICAO INTEGER NOT NULL
                                 DATALOTE      DATE         NOT NULL,
                                 VALOR         DECIMAL(8,2) NOT NULL) ORGANIZE BY (IDINSTITUICAO,DATALOTE);
                                 
              Uma tabela MDC pode ser imaginada como um cubo, cheio de pequenos cubos dentro. Cada cubo interno teri os registro de cada combinacao
           das dimensoes: IDINSTITUICAO=1 e DATALOTE=2018-01-01 ficaria em um cubo, 
                          IDINSTITUICAO=1 e DATALOTE=2018-01-02 ficaria em um outro cubo, e
                          IDINSTITUICAO=2 e DATALOTE=2018-01-01 ficaria ainda em outro cubo
                          
              O grao de armazenamento sempre e sobre todas as dimensoes, mas podemos, seguindo o padrao de consultas que serao feitas, mudar 
           a clausula ORGANIZE para que o DB2 crie os indices de bloco apenas para as consultas que serao feitas.
           
           Exemplo:  
           
              ORGANIZE BY (IDINSTITUICAO,DATALOTE),   significa que o DB2 ira criar tres indices de Bloco: um por IDINSTITUICAO, um por DATALOTE, e outro por IDINSTITUICAO + DATALOTE
              ORGANIZE BY ((IDINSTITUICAO),DATALOTE), significa que o DB2 ira criar dois indices de Bloco: um por IDINSTITUICAO, e outro por IDINSTITUICAO + DATALOTE
              ORGANIZE BY ((IDINSTITUICAO,DATALOTE)), significa que o DB2 ira criar um indices de Bloco por IDINSTITUICAO + DATALOTE
              
           dessa maneira, se as consultas irao ser feitas sempre por IDINSTITUIACAO+DATALOTE, iremos utilizar a ultima forma do comando ORGANIZE.   
           
      Se a tabela for criada com a estrutura correta (indices e/ou particionamentos), e se fizermos a criacao das tabelas nos ambientes de testes com uma 
   quantidade minima de registros, digamos 1000 registros para as tabelas que irao ter um volume crescente em producao, o que se espera e que um SQL
   bem construido gere um Plano de Execucao SQL eficiente.
   
      Um Plano eficiente, e o que utiliza, dependendo dos filtros passados pelo SQL, os indices, ou as particoes MDC ou range esperados. Se uma pesquisa
   foi feita pelo atributo CPF, deve utilizar um indice que contenha o atributo CPF. Se for uma pesquisa por um mes inteiro de dados, o plano deve indicar
   que uma particao inteira da tabela foi lida, caso essa tenha sido particionada pelo campo DATE correspondente. Se um unico dia e passado como filtro
   de pesquisa, e caso essa tabela contenha milhares de registros para esse dia, o plano deve indicar que um indice de bloco deve ser utilizado, caso um particionamento MDC tenha sido 
   criado pelo campo DATE correspondente.
   
      Casa vez que o DB2 necessita acessar um registro, ele primeiro verifica se o bloco aonde o registro esti ja esti no seu cache. O cache do DB2 e 
   composto de blocos de registros. Caso nao encontre o Bloco no cache, o DB2 li o bloco no disco, e o transfere para o cache.
   
      SQLs que sao muito executados, geralmente devem consumir poucos Blocos. Uma das informacoes mais valiosas para descobrir SQLs problematicos e verificar
   quais dos comandos SQLs  muito executados consomem uma quantidade muito maior de blocos que outros SQLs muito executados.
   
      Em geral, a tecnica de Tuning de comandos SQL consiste em olhar o Plano de Execucao SQL, e verificar se o Plano gerado faz o esperado. Se utiliza os
   indices e particionamentos, se nao faz TBSCANS em tabelas com muitos registros, e etc. E fundamental olhar as estatisticas de execucao dos comandos SQL, 
   junto com as estatisticas de execucao, para detectar o quanto antes problemas de desempenho.   
      
   Tuning em ambientes de Banco de Dados:
   
      1) Projeto Fisico das tabelas
      
         O Projeto Fisico do Banco de Dados e construido a partir do Projeto logico e deve levar em conta:
         
         . as informacoes contidas no mapa de acesso logico das tabelas (que informa quais as colunas serao serao utilizadas como filtro de consultas). 
         . o relacionamento entre as tabelas, que informa como as tabelas serao juntadas
         . as necessidades de ILM (Information life-cycle Management): expurgos, aposentadoria dos dados e etc.
         
         A partir dessas informacoes sao projetados as tabelas e os indices.         

      2) Criacao dos Bancos de Dados de Desenvolvimento, Teste Integrado e Homologacao
      
         Os Bancos de Dados de pre-producao deverao ser criados com as seguintes caracteristicas:
         
         . as tabelas devem ser criadas ja com suas caracteristicas fisicas: particionamento, indices e etc.
         . as tabelas devem ser populadas com registros, de maneira proporcional e equivalente as que irao ter em producao, da seguinte maneira:
         
            . as tabelas que nao sao de dominio, e que com o tempo terao grande volume, deverao ser populadas com o minimo de 1.000 registros.
            . a distribuicao dos valores das colunas deverao simular a situacao real das tabelas em producao.
            
         . as estatisticas das tabelas deverao ser mantidas atualizadas. nao deverao existir tabelas sem estatisticas geradas e tabelas com significativo incremento ou decremento do volume de registros devem ter suas estatisticas atualizadas.
            
      3) Desenvolvimento de comandos SQL
      
         Os comandos SQL deverao ser criados:
         
         . de maneira legivel.
         . com Comentarios explicando seu funcionamento, se necessario.
         . seguindo as boas praticas de desenvolvimento SQL:
         
            . todas as consultas devem estar cobertas por indices,  seguindo o mapa de acesso logico.
            . as colunas utilizadas em filtros ou juncoes  entre tabelas, e que fazem parte de indices, nao devem ser aplicados calculos matematicos, operadores, ou 
              funcoes de banco de dados. O Banco de Dados pode nao utilizar um indice, ou nao o utilizar com eficiencia, caso isso ocorra!
            
               Ex: Tabela "CONTRATOS", coluna "DATACONTRATO". indice "IDX_CONTRATOS_DATACONTRATO (DATACONTRATO)"
               
                  consulta errada: SELECT * FROM CONTRATOS WHERE DATACONTRATO + 1 DAY = CURRENT DATE
              
                  consulta certa : SELECT * FROM CONTRATOS WHERE DATACONTRATO = CURRENT DATE - 1 DAY
                  
               Ex: Tabela "PESSOA", coluna "NOME". indice "IDX_PESSOA_NOME (NOME)" - dados de nome armazenados sempre em letras MAIUSCULAS
                  
                  consulta errada: SELECT * FROM PESSOA WHERE LOWER(NOME) = ?
              
                  consulta certa : SELECT * FROM PESSOA WHERE NOME = UPPER(?)
            
            . a tecnica de Bind Variables deve ser aplicada para todas as consultas por colunas que tiverem seus valores distribuidos de forma equilibrada.
            
               Exemplos: CPF na tabela PESSOA
                         IDNOTA na tabela NOTAFISCAL
                         
            . a tecnica de Bind Variables nao deve ser aplicada para as consultas por colunas que tiverem seus valores distribuidos de forma desigual.
           
               Exemplos: SITUACAOLOTE na tabela LOTES.
               
         . os Planos de Execucao SQL devem ser gerados, analisados e armazenados. 
         
            A analise do Plano de Execucao deve levar em conta:
            
               . quais foram os indices utilizados.
               . como os indices foram utilizados:
                  . quais colunas do indice foram utilizados como ponto de inicio e parada (START/STOP).
                  . quais colunas do indice foram utilizadas como argumentos do tipo SARGABLE (acesso sargable em um indice significa que o 
                    Banco de Dados utilizou a coluna no indice para filtrar os dados mas nao a utilizou para chegar a um ponto preciso na arvore do indice).
                  . se alguma tabela que possuir uma grande quantidade de registros estiver sendo acessada sem a utilizacao de um indice (TBSCAN).
                     . TBSCAN em tabelas grandes nao e aceitavel para aplicacoes OLTP (aplicacoes ON-LINE), sendo aceitavel em alguns cenarios
                       de aplicacoes Batch.
                       
         . que relatorios sobre a saide dos Bancos de Dados pre-producao sejam gerados periodicamente.
         
            . para verificar se as estatisticas das Tabelas estsao atualizadas.
            . para verificar os indices existentes.
            . para verificar se a estrutura dos diferentes Bancos de Dados estsao com estruturas equivalentes.
            . antes de subir uma "release" das aplicacoes. Nesse caso os relatorios deverao er armazenados como artefato.')
      SELECT *
      FROM AJUDA;
   OPEN VCURSOR;
END;
;
-- COPY-DATABASE-OBJECT: "DBSYS"."PRC_TUNING_SQLS_RUNNING"
CREATE OR REPLACE PROCEDURE "DBSYS"."PRC_TUNING_SQLS_RUNNING" (PESTADO CHAR DEFAULT 'E')
   RESULT SETS 1
   LANGUAGE SQL
   SPECIFIC PRC_TUNING_SQLS_RUNNING
BEGIN
   DECLARE VCURSOR CURSOR WITH RETURN FOR SELECT *
                                          FROM (SELECT SESSION_AUTH_ID                               "Usuario",
                                                       CLIENT_HOSTNAME,
                                                       CASE ACTIVITY_STATE WHEN 'EXECUTING' THEN 'Em execucao'
                                                                           WHEN 'IDLE'      THEN 'Em espera'
                                                       END                                           "Status do comando",
                                                       TO_CHAR(START_TIME,'DD/MM/YYYY HH24:MI:SS')   "Inicio da execucao",
                                                       ELAPSED_TIME_SEC                              "Tempo de execucao(s)",
                                                       QUERY_COST_ESTIMATE                           "Custo estimado",
                                                       ROWS_READ                                     "Qtd. registros lidos",
                                                       CAST(STMT_TEXT AS VARCHAR(500))               "Texto resumido do comando SQL",
                                                       APPLICATION_HANDLE                            "Application Handle",
                                                       APPLICATION_NAME                              "Nome da aplicacao",
                                                       ROWS_RETURNED                                 "Qtd. registros retornados",
                                                       CAST(STMT_TEXT AS VARCHAR(4000))              "Texto do comando SQL",
                                                       APPLICATION_ID                                "Id da aplicacao",
--                                                       TOTAL_CPU_TIME                    "Tempo total de CPU",
                                                       ACTIVITY_TYPE                                 "Tipo de comando",
                                                       BANCO                                         "Banco",
                                                       TO_CHAR(DATA_CAPTURA,'DD/MM/YYYY HH24:MI:SS') "Data da captura"
                                                FROM (
                                                SELECT CURRENT SERVER                               BANCO,
                                                       X.ACTIVITY_STATE,
                                                       Y.CLIENT_HOSTNAME,
                                                       CURRENT TIMESTAMP                            DATA_CAPTURA,
                                                       CURRENT TIMESTAMP - X.ELAPSED_TIME_SEC SECONDS START_TIME,
                                                       X.ELAPSED_TIME_SEC,
                                                       X.ROWS_READ,
                                                       STMT_TEXT,
                                                       X.SESSION_AUTH_ID,
                                                       X.APPLICATION_ID,
                                                       X.APPLICATION_HANDLE,
                                                       X.TOTAL_CPU_TIME,
                                                       X.ROWS_RETURNED,
                                                       X.QUERY_COST_ESTIMATE,
                                                       X.APPLICATION_NAME,
                                                       X.ACTIVITY_TYPE,
                                                       COUNT(*) OVER() QTD
                                                FROM SYSIBMADM.MON_CURRENT_SQL X INNER JOIN TABLE (SYSPROC.MON_GET_CONNECTION(CAST(NULL AS BIGINT), -2)) Y ON X.APPLICATION_HANDLE = Y.APPLICATION_HANDLE
                                                WHERE ((UPPER(PESTADO) = 'T' AND X.ACTIVITY_STATE IN ('IDLE','EXECUTING')
                                                    OR (UPPER(PESTADO) = 'E' AND X.ACTIVITY_STATE = 'EXECUTING')
                                                    OR (UPPER(PESTADO) = 'I' AND X.ACTIVITY_STATE = 'IDLE'))
                                                  AND X.STMT_TEXT NOT LIKE '%MON_CURRENT_SQL%')));
   IF UPPER(PESTADO) NOT IN ('T','E','I') THEN
      SIGNAL SQLSTATE '75001'
           SET MESSAGE_TEXT = 'Favor entrar com ''E ou I ou T'' para ''Em execucao/Em espera/Todos'' Ex: CALL DBSYS.PRC_TUNING_SQLS_RUNNING (''T'')';
   END IF;
   OPEN VCURSOR;
END;
;
