-- COPY-DATABASE-OBJECT: "DBSYS"."PRC_TUNING_TABELAS"
CREATE OR REPLACE PROCEDURE "DBSYS"."PRC_TUNING_TABELAS" (PTABSCHEMA VARCHAR(10) DEFAULT NULL,PTABNAME VARCHAR(100) DEFAULT NULL,PQTDMAXREGISTROS BIGINT DEFAULT 10000,PMULTIPLICADOR DECIMAL DEFAULT 1.2,PQTMINREGISTROS SMALLINT DEFAULT 500)
   RESULT SETS 1
   LANGUAGE SQL
   SPECIFIC PRC_TUNING_TABELAS
BEGIN
   
   IF PTABSCHEMA IS NULL THEN
      SIGNAL SQLSTATE '75001'
           SET MESSAGE_TEXT = 'Ex: CALL DBSYS.PRC_TUNING_TABELAS (''CRE'')';
   END IF;         

   DECLARE GLOBAL TEMPORARY TABLE SESSION.TABELASDOMINIO        (BANCO VARCHAR(20) NOT NULL,ESQUEMA VARCHAR(50) NOT NULL,TABELA VARCHAR(100)) NOT LOGGED ON ROLLBACK DELETE ROWS ON COMMIT PRESERVE ROWS WITH REPLACE;
   DECLARE GLOBAL TEMPORARY TABLE SESSION.TABELASSEMCRESCIMENTO (BANCO VARCHAR(20) NOT NULL,ESQUEMA VARCHAR(50) NOT NULL,TABELA VARCHAR(100)) NOT LOGGED ON ROLLBACK DELETE ROWS ON COMMIT PRESERVE ROWS WITH REPLACE;  
   
   CREATE INDEX SESSION.IX_TABELASDOMINIO_01        ON SESSION.TABELASDOMINIO        (BANCO,ESQUEMA,TABELA);
   CREATE INDEX SESSION.IX_TABELASSEMCRESCIMENTO_01 ON SESSION.TABELASSEMCRESCIMENTO (BANCO,ESQUEMA,TABELA);
   
   INSERT INTO SESSION.TABELASDOMINIO 
   SELECT BANCO,ESQUEMA,TABELA
   FROM DBSYS.NICKTABELASDOMINIO;
   
   INSERT INTO SESSION.TABELASSEMCRESCIMENTO 
   SELECT BANCO,ESQUEMA,TABELA
   FROM DBSYS.NICKTABELASSEMCRESCIMENTO;
   
   CALL ADMIN_CMD ('RUNSTATS ON TABLE SESSION.TABELASDOMINIO        WITH DISTRIBUTION AND DETAILED INDEXES ALL');
   CALL ADMIN_CMD ('RUNSTATS ON TABLE SESSION.TABELASSEMCRESCIMENTO WITH DISTRIBUTION AND DETAILED INDEXES ALL');   
   
   BEGIN   
   
      DECLARE VCURSOR CURSOR WITH RETURN FOR 
         SELECT TRIM(TABSCHEMA)       "Esquema",
                TABNAME               "Tabela",             
                CARD                  "Qt. Estats. Regs.",
                QTDREGISTROS          "Qt. Calc. Regs.",
                TO_CHAR(STATS_TIME,'DD/MM/YYYY HH24:MI:SS')            "Dt. Estats.",             
                CASE WHEN CARD = -1                    THEN 'estatisticas nao geradas'
                     WHEN QTDREGISTROS <> PQTDMAXREGISTROS AND QTDREGISTROS >= 0 AND CARD >= 0 AND ABS(GREATEST(QTDREGISTROS,CARD)/LEAST(CASE WHEN QTDREGISTROS = 0 THEN 1 ELSE QTDREGISTROS END,CASE WHEN CARD = 0 THEN 1 ELSE CARD END)) > PMULTIPLICADOR 
                                                       THEN 'estatisticas devem ser atualizadas'
                     WHEN QTDREGISTROS = PQTDMAXREGISTROS 
                                                       THEN 'estatisticas OK. Quantidade real de registros >= '||PQTDMAXREGISTROS                                                    
                                                       ELSE '' 
                END                "Diagnostico Estats.",
                CASE WHEN ETABELADOMINIO        = 1 THEN 'Ok - Tabela de Dominio'
                     WHEN ETABELASEMCRESCIMENTO = 1 THEN 'Ok - Tabela sem Crescimento'
                     WHEN QTDREGISTROS <= PQTMINREGISTROS AND ETABELADOMINIO = 0 THEN 'Menos que '||TO_CHAR(PQTMINREGISTROS)||' de registros! Tabela de Dominio?' ELSE '' 
                END                 "Diagnostico Qtd. Regs.",
                ' '                 "Comentarios do Analista"--,
   --             QTDCOLUNAS                  "Qt. Colunas"
         FROM (SELECT TABSCHEMA,
                      TABNAME,
                      CARD,
                      STATS_TIME,
                      (SELECT COUNT(*) FROM SYSCAT.COLUMNS C WHERE T.TABSCHEMA = C.TABSCHEMA AND T.TABNAME   = C.TABNAME) QTDCOLUNAS,
                      DBSYS.FNC_QTDREGISTROS (TABSCHEMA,TABNAME,PQTDMAXREGISTROS)  QTDREGISTROS,
                      CASE WHEN TD.TABELA IS NOT NULL THEN 1 ELSE 0 END ETABELADOMINIO,
                      CASE WHEN TS.TABELA IS NOT NULL THEN 1 ELSE 0 END ETABELASEMCRESCIMENTO
               FROM SYSCAT.TABLES T LEFT OUTER JOIN SESSION.TABELASDOMINIO        TD ON TD.BANCO = CURRENT SERVER AND T.TABSCHEMA = TD.ESQUEMA AND T.TABNAME = TD.TABELA
                                    LEFT OUTER JOIN SESSION.TABELASSEMCRESCIMENTO TS ON TS.BANCO = CURRENT SERVER AND T.TABSCHEMA = TS.ESQUEMA AND T.TABNAME = TS.TABELA
               WHERE TABSCHEMA = UPPER(PTABSCHEMA)
                AND (PTABNAME IS NULL OR TABNAME = UPPER(PTABNAME))
                AND UPPER(TABNAME) NOT LIKE '%FLYWAY%'
                AND TYPE = 'T')
         ORDER BY TABSCHEMA,TABNAME ASC;

      OPEN VCURSOR;
   END;    
END;
;
-- COPY-DATABASE-OBJECT: "DBSYS"."PRC_TUNING_TABELASDOMINIO"
CREATE OR REPLACE PROCEDURE "DBSYS"."PRC_TUNING_TABELASDOMINIO" (PDATABASE VARCHAR(20),PTABSCHEMA VARCHAR(100),PTABNAME VARCHAR(50),POPERACAO CHAR DEFAULT 'I',PSENHA VARCHAR(10) DEFAULT NULL)
   LANGUAGE SQL
   SPECIFIC PRC_TUNING_TABELASDOMINIO
BEGIN 
   DECLARE DUP_VAL CONDITION FOR SQLSTATE '23505';
   DECLARE EXIT HANDLER FOR DUP_VAL 
   BEGIN
     SIGNAL SQLSTATE '75003'
         SET MESSAGE_TEXT = 'Tabela ja cadastrada';   
   END;
   IF POPERACAO NOT IN ('I','E') THEN
      SIGNAL SQLSTATE '75001'
         SET MESSAGE_TEXT = 'Favor entrar com I-Inclusao ou E-Exclusao';
   END IF;
   IF (POPERACAO = 'I' 
  AND (PTABSCHEMA IS NULL OR PTABNAME IS NULL OR PDATABASE IS NULL))
   OR (POPERACAO = 'E' 
  AND ((PTABSCHEMA IS NULL OR PTABNAME IS NULL)
   AND (PSENHA IS NULL OR PSENHA NOT IN ('CHEFAOTABELA','CHEFAOESQUEMA','CHEFAOTUDO')))) THEN
      SIGNAL SQLSTATE '75002'
         SET MESSAGE_TEXT = 'Favor entrar com o Esquema e a Tabela';
   END IF;   
   IF POPERACAO = 'I' THEN
      IF EXISTS (SELECT 1 FROM DBSYS.NICKTABELASSEMCRESCIMENTO WHERE BANCO = PDATABASE AND ESQUEMA = PTABSCHEMA AND TABELA = PTABNAME) THEN
         SIGNAL SQLSTATE '75003'
            SET MESSAGE_TEXT = 'Tabela ja cadastrada como tabela sem crescimento!';
      END IF;   
      INSERT INTO DBSYS.NICKTABELASDOMINIO VALUES (PDATABASE,PTABSCHEMA,PTABNAME,CURRENT USER,CURRENT TIMESTAMP);
   ELSE
      DELETE FROM DBSYS.NICKTABELASDOMINIO
      WHERE BANCO = PDATABASE
        AND (ESQUEMA = PTABSCHEMA OR (PTABSCHEMA IS NULL AND PSENHA IN ('CHEFAOESQUEMA','CHEFAOTUDO')))
        AND (TABELA  = PTABNAME   OR (PTABNAME   IS NULL AND PSENHA IN ('CHEFAOTABELA','CHEFAOESQUEMA','CHEFAOTUDO')));
   END IF;
END;
;
-- COPY-DATABASE-OBJECT: "DBSYS"."PRC_TUNING_TABELASDOMINIO_AJUDA"
CREATE OR REPLACE PROCEDURE "DBSYS"."PRC_TUNING_TABELASDOMINIO_AJUDA" ()
   RESULT SETS 1
   LANGUAGE SQL
   SPECIFIC PRC_TUNING_TABELASDOMINIO_AJUDA
BEGIN
   DECLARE VCURSOR CURSOR WITH RETURN FOR 
      WITH AJUDA ("Texto") AS (VALUES 
'DBSYS.PRC_TUNING_TABELASDOMINIO
      
   Descricao:      
      
      Cadastra as tabelas de domínio. Essa informação será utilizada na procedure DBSYS.PRC_TUNING_TABELA, impedindo que um mensagem alertando sobre a 
      baixa quantidade de registros seja emitida.  
      
      Para ver uma listagem das tabelas de dominio, executar o comando:
      
         SELECT * FROM TABELASDOMINIO           
      
   Observacao:
   
      As tabelas devem ser cadastradas em cada um dos ambientes, Desenvolvimento, TI e Homologacao, já que os ambientes não se comunicam, 
   impedindo a existencia de uma base centralizada geral.            
      
   Parametros:

       . PDATABASE:        obrigatorio, o nome do banco de dados DB2 (Ex: CRE_TBP)
       . PTABSCHEMA:       obrigatorio, o nome do esquema
       . PTABNAME:         obrigatorio, o nome da tabela                                  
       . POPERACAO:        opcional: ''I'' para inclusao (default) ou ''E'' para exclusao
      
   Exemplo de utilizacao:         
         
         inclusao
          
            CALL DBSYS.PRC_TUNING_TABELASDOMINIO (''CLI_TBP'',''CLI'',''TIPOABRANGENCIACERTIDAO'')
         
         exclusao
         
            CALL DBSYS.PRC_TUNING_TABELASDOMINIO (''CLI_TBP'',''CLI'',''TIPOABRANGENCIACERTIDAO'',''E''))')

      SELECT *
      FROM AJUDA;
   OPEN VCURSOR;
END;
;
