-- COPY-DATABASE-OBJECT: "DBSYS"."SETIDENTITYALWAYS"
CREATE OR REPLACE PROCEDURE "DBSYS"."SETIDENTITYALWAYS" (IN schemaname VARCHAR(128),IN tablename VARCHAR(128), IN columnname VARCHAR(128))
SPECIFIC SETIDENTITYALWAYS
LANGUAGE SQL
BEGIN
	DECLARE generate BIGINT DEFAULT 0;
	DECLARE gennull BIGINT DEFAULT 0;
	DECLARE colvalue BIGINT DEFAULT 0;
	DECLARE maxid BIGINT DEFAULT 0;
	DECLARE stmttxt1 VARCHAR(10000);
	DECLARE stmttxt VARCHAR(10000);
	DECLARE s STATEMENT;
	DECLARE cur CURSOR FOR s;
	
	-- Changing the parameters to upper case:
	set schemaname = trim( upper(schemaname) );
	set tablename  = upper(tablename);
	set columnname = upper(columnname);

	-- Checking if the column is generated by default:
	SELECT 1 INTO generate FROM SYSCAT.COLUMNS WHERE TABSCHEMA = schemaname and TABNAME = tablename and COLNAME = columnname and GENERATED = 'D';
	-- If the column is generated by default, drop the identity:
	IF generate = 1 THEN
	  SET stmttxt = 'ALTER TABLE "' || schemaname || '"."' || tablename ||
	  '" ALTER COLUMN "' || columnname ||
	  '" DROP IDENTITY';
	  EXECUTE IMMEDIATE stmttxt;
	END IF;
	
	-- Checking if the column is generated always:
	SET generate = 0;
	SELECT 1 INTO generate FROM SYSCAT.COLUMNS WHERE TABSCHEMA = schemaname and TABNAME = tablename and COLNAME = columnname and GENERATED = 'A';
	-- If the column is generated always, drop the identity:
	IF generate = 1 THEN
	  SET stmttxt = 'ALTER TABLE "' || schemaname || '"."' || tablename ||
	  '" ALTER COLUMN "' || columnname ||
	  '" DROP IDENTITY';
	  EXECUTE IMMEDIATE stmttxt;
	END IF;
	
	-- Checking if the column is nullable:
	SELECT 1 INTO gennull FROM SYSCAT.COLUMNS WHERE TABSCHEMA = schemaname and TABNAME = tablename and COLNAME = columnname and NULLS = 'Y';
	-- If the column is nullable (Y), set it to a NOT NULL column:
	IF gennull = 1 THEN
	  SET stmttxt = 'ALTER TABLE "' || schemaname || '"."' || tablename ||
	  '" ALTER COLUMN "' || columnname ||
	  '" SET NOT NULL';
	  SET stmttxt1 = 'REORG TABLE "' || schemaname || '"."' || tablename || '"';
	  EXECUTE IMMEDIATE stmttxt;
	  CALL SYSPROC.ADMIN_CMD( stmttxt1 );
	END IF;

	-- Check the max column's value and set it to a generated always as identity column:
	--SELECT COUNT ( IDCENTRALRISCO ) FROM (SELECT IDCENTRALRISCO FROM CRO.CENTRALRISCO FETCH FIRST 1 ROW ONLY WITH UR)
	--VersÃ§ao antiga com COUNT (2016-02-22)
	--SET stmttxt = 'SELECT COUNT(' || columnname || ') FROM ' || '(SELECT '||columnname||' FROM '||TRIM(schemaname) || '.' || tablename || ' FETCH FIRST 1 ROW ONLY WITH UR)';
	SET stmttxt = 'SELECT COALESCE( MAX(' || columnname || '), 0) FROM ' || trim(schemaname) || '.' || tablename;

	PREPARE s FROM stmttxt;
	SET maxid = 0;
	OPEN cur;
	FETCH cur INTO maxid;
	CLOSE cur;

	SET stmttxt = 'ALTER TABLE "' || schemaname || '"."' || tablename ||
	  '" ALTER COLUMN "' || columnname ||
	  '" SET GENERATED ALWAYS AS IDENTITY (START WITH ' || CHAR(maxid + 1) || ')';
	EXECUTE IMMEDIATE stmttxt;

END
;
-- COPY-DATABASE-OBJECT: "DBSYS"."SPU_VERIFICA_TSM_HADR"
CREATE OR REPLACE PROCEDURE "DBSYS"."SPU_VERIFICA_TSM_HADR"()
RESULT SETS 1
LANGUAGE SQL
SPECIFIC SPU_VERIFICA_TSM_HADR
BEGIN NOT ATOMIC
	DECLARE V_DTH TIMESTAMP;
	DECLARE V_CONTA_HADR SMALLINT;
	DECLARE V_CONTA_TSM SMALLINT;

	-- Verifica se o HADR está sincronizado
	SET V_DTH = CURRENT_TIMESTAMP;
	SELECT  COALESCE(INT(STANDBY_SPOOL_PERCENT), 0)
	INTO V_CONTA_HADR               
	from table(MON_GET_HADR(NULL))
	where STANDBY_SPOOL_PERCENT  <> '0.0'
	or PRIMARY_LOG_FILE <> STANDBY_REPLAY_LOG_FILE;
	insert into load.loadlog (SCHEMA, table, datahorainiciocarga, datahorafimcarga, ROWS_DELETED) 
	values ('MON_GET', 'HADR', V_DTH, current_timestamp, V_CONTA_HADR);
	COMMIT;
							
	-- Enquanto houver arquivos de log para sincronizar não libera a demanda
	WHILE V_CONTA_HADR > 10 DO

			SET V_DTH = CURRENT_TIMESTAMP;
			SELECT  COALESCE(INT(STANDBY_SPOOL_PERCENT), 0)
			INTO V_CONTA_HADR               
			from table(MON_GET_HADR(NULL))
			where STANDBY_SPOOL_PERCENT  <> '0.0'
			or PRIMARY_LOG_FILE <> STANDBY_REPLAY_LOG_FILE;
			insert into load.loadlog (SCHEMA, table, datahorainiciocarga, datahorafimcarga, ROWS_READ) 
			values ('MON_GET', 'HADR - WHILE', V_DTH, current_timestamp, V_CONTA_HADR);
			COMMIT;
			
			CALL dbms_lock.sleep(5);

	END WHILE;

	-- Verifica se os logs foram arquivados pelo TSM
	SET V_DTH = CURRENT_TIMESTAMP;
	SELECT  count(1)
	INTO V_CONTA_TSM
	FROM SYSIBMADM.DB_HISTORY 
	WHERE OPERATION = 'X'
	AND DEVICETYPE = 'D'
	AND TIMESTAMP(START_TIME) >= CURRENT DATE - 1
	WITH UR;
	insert into load.loadlog (SCHEMA, table, datahorainiciocarga, datahorafimcarga, ROWS_READ) 
	values ('SYSIBMADM', 'DB_HISTORY', V_DTH, current_timestamp, V_CONTA_TSM);
	COMMIT;
	
	-- Se houver mais de 100 arquivos de log aguardando, interrompe a execução
	-- até que só tenham 5 na fila do TSM
	IF V_CONTA_TSM > 100 THEN
			
		-- Enquanto houver mais de 5 arquivos de log para sincronizar não libera a demanda
		SET V_DTH = CURRENT_TIMESTAMP;
		WHILE V_CONTA_TSM > 5 DO

				SET V_DTH = CURRENT_TIMESTAMP;
				SELECT  count(1)
				into V_CONTA_TSM
				FROM SYSIBMADM.DB_HISTORY 
				WHERE OPERATION = 'X'
				AND DEVICETYPE = 'D'
				AND TIMESTAMP(START_TIME) >= CURRENT DATE - 1
				WITH UR;
				insert into load.loadlog (SCHEMA, table, datahorainiciocarga, datahorafimcarga, ROWS_READ) 
				values ('MON_GET', 'DB_HISTORY - WHILE', V_DTH, current_timestamp, V_CONTA_TSM);
				COMMIT;
				
				CALL dbms_lock.sleep(5);
		
		END WHILE;
			
		SET V_DTH = CURRENT_TIMESTAMP;
		insert into load.loadlog (SCHEMA, table, datahorainiciocarga, datahorafimcarga, ROWS_READ) 
		values ('SYSIBMADM', 'DB_HISTORY - APOS WHILE', V_DTH, current_timestamp, V_CONTA_TSM);
		COMMIT;
	
	END IF;

END
;
-- COPY-DATABASE-OBJECT: "FCO"."SPU_POPULA_TOTALIZADOR"
CREATE OR REPLACE PROCEDURE "FCO"."SPU_POPULA_TOTALIZADOR"
   LANGUAGE SQL
   SPECIFIC SPU_POPULA_TOTALIZADOR
BEGIN
   MERGE INTO FCO.TOTALIZADORDASHBOARDFC D
   USING (WITH ORIGEM AS (SELECT *
                          FROM OLD TABLE (DELETE FROM FCO.FILAEVENTOSITUACAOMESAFC)),
               NOVO AS (SELECT IDINSTITUICAO,
                               NUMTIPOFUNDOCONSTITUCIONAL,
                               SUM(CASE WHEN QTDEMAPROVACAO                IS NOT NULL THEN QTDEMAPROVACAO ELSE 0 END)               QTDEMAPROVACAO,
                               SUM(CASE WHEN QTDAGUARDANDOSICOR            IS NOT NULL THEN QTDAGUARDANDOSICOR ELSE 0 END)           QTDAGUARDANDOSICOR,
                               SUM(CASE WHEN QTDERROSICORAPROVACAO         IS NOT NULL THEN QTDERROSICORAPROVACAO ELSE 0 END)        QTDERROSICORAPROVACAO,
                               SUM(CASE WHEN QTDAGUARDANDOPL               IS NOT NULL THEN QTDAGUARDANDOPL ELSE 0 END)              QTDAGUARDANDOPL,
                               SUM(CASE WHEN QTDANALISELIBCCS              IS NOT NULL THEN QTDANALISELIBCCS ELSE 0 END)             QTDANALISELIBCCS,
                               SUM(CASE WHEN QTDAGUARDANDORECURSO          IS NOT NULL THEN QTDAGUARDANDORECURSO ELSE 0 END)         QTDAGUARDANDORECURSO,
                               SUM(CASE WHEN QTDAGUARDANDOPROTOCOLO        IS NOT NULL THEN QTDAGUARDANDOPROTOCOLO ELSE 0 END)       QTDAGUARDANDOPROTOCOLO,
                               SUM(CASE WHEN QTDAGUARDANDORETORNOSICORLIB  IS NOT NULL THEN QTDAGUARDANDORETORNOSICORLIB ELSE 0 END) QTDAGUARDANDORETORNOSICORLIB, 
                               SUM(CASE WHEN QTDERROPROTOCOLO              IS NOT NULL THEN QTDERROPROTOCOLO ELSE 0 END)             QTDERROPROTOCOLO,
                               SUM(CASE WHEN QTDERROSICORLIBERACAO         IS NOT NULL THEN QTDERROSICORLIBERACAO ELSE 0 END)        QTDERROSICORLIBERACAO  
                           FROM ORIGEM
                           GROUP BY IDINSTITUICAO,
                                    NUMTIPOFUNDOCONSTITUCIONAL)
   SELECT *
   FROM NOVO) O
   ON D.IDINSTITUICAO              = O.IDINSTITUICAO
  AND D.NUMTIPOFUNDOCONSTITUCIONAL = O.NUMTIPOFUNDOCONSTITUCIONAL
   WHEN MATCHED THEN UPDATE SET D.QTDEMAPROVACAO               = D.QTDEMAPROVACAO               + O.QTDEMAPROVACAO,
                                D.QTDAGUARDANDOSICOR           = D.QTDAGUARDANDOSICOR           + O.QTDAGUARDANDOSICOR,
                                D.QTDERROSICORAPROVACAO        = D.QTDERROSICORAPROVACAO        + O.QTDERROSICORAPROVACAO,
                                D.QTDAGUARDANDOPL              = D.QTDAGUARDANDOPL              + O.QTDAGUARDANDOPL,
                                D.QTDANALISELIBCCS             = D.QTDANALISELIBCCS             + O.QTDANALISELIBCCS,
                                D.QTDAGUARDANDORECURSO         = D.QTDAGUARDANDORECURSO         + O.QTDAGUARDANDORECURSO,
                                D.QTDAGUARDANDOPROTOCOLO       = D.QTDAGUARDANDOPROTOCOLO       + O.QTDAGUARDANDOPROTOCOLO,
                                D.QTDAGUARDANDORETORNOSICORLIB = D.QTDAGUARDANDORETORNOSICORLIB + O.QTDAGUARDANDORETORNOSICORLIB,
                                D.QTDERROPROTOCOLO             = D.QTDERROPROTOCOLO             + O.QTDERROPROTOCOLO,
                                D.QTDERROSICORLIBERACAO        = D.QTDERROSICORLIBERACAO        + O.QTDERROSICORLIBERACAO
    WHEN NOT MATCHED THEN INSERT (IDINSTITUICAO,
                                  NUMTIPOFUNDOCONSTITUCIONAL,
                                  QTDEMAPROVACAO,
                                  QTDAGUARDANDOSICOR,
                                  QTDERROSICORAPROVACAO,
                                  QTDAGUARDANDOPL,
                                  QTDANALISELIBCCS,
                                  QTDAGUARDANDORECURSO,
                                  QTDAGUARDANDOPROTOCOLO,
                                  QTDAGUARDANDORETORNOSICORLIB,
                                  QTDERROPROTOCOLO,
                                  QTDERROSICORLIBERACAO)
                          VALUES (O.IDINSTITUICAO,
                                  O.NUMTIPOFUNDOCONSTITUCIONAL,
                                  O.QTDEMAPROVACAO,
                                  O.QTDAGUARDANDOSICOR,
                                  O.QTDERROSICORAPROVACAO,
                                  O.QTDAGUARDANDOPL,
                                  O.QTDANALISELIBCCS,
                                  O.QTDAGUARDANDORECURSO,
                                  O.QTDAGUARDANDOPROTOCOLO,
                                  O.QTDAGUARDANDORETORNOSICORLIB,
                                  O.QTDERROPROTOCOLO,
                                  O.QTDERROSICORLIBERACAO);
END;
;
-- COPY-DATABASE-OBJECT: "GEO"."PRC_DESVINCULAR_GLEBA"
CREATE   OR REPLACE PROCEDURE "GEO"."PRC_DESVINCULAR_GLEBA"(
       IN v_IDGLEBA INTEGER,
       IN v_IDPARAMETROSISTEMA INTEGER,
       IN v_IDNEGOCIO BIGINT
   )
LANGUAGE SQL
SPECIFIC PRC_DESVINCULAR_GLEBA
DYNAMIC RESULT SETS 1
BEGIN
DECLARE P_cur1 VARCHAR(5000);


DECLARE F_IDGLEBA INTEGER;


DECLARE VEOF INT DEFAULT 0;


DECLARE v_cur1 CURSOR FOR s_cur1;


DECLARE CONTINUE HANDLER FOR NOT FOUND
SET VEOF = 1;


--CALL DBMS_OUTPUT.PUT_LINE('PARAMENTROS: ' || v_IDGLEBA || ' - ' || v_IDPARAMETROSISTEMA );

IF COALESCE(
   v_IDGLEBA,
   0
)<= 0 THEN SIGNAL SQLSTATE '75001'
SET MESSAGE_TEXT = 'Gleba deve ser informada';

END IF;


IF COALESCE(
   v_IDPARAMETROSISTEMA,
   0
)<= 0 THEN SIGNAL SQLSTATE '75001'
SET MESSAGE_TEXT = 'v_IDPARAMETROSISTEMA deve ser informada';

END IF;


IF COALESCE(
   v_IDNEGOCIO,
   0
)<= 0 THEN SIGNAL SQLSTATE '75001'
SET MESSAGE_TEXT = 'v_IDNEGOCIO deve ser informada';

END IF;

SET P_cur1 = 'SELECT GPS.IDGLEBA, GPS.IDPARAMETROSISTEMA,GPS.DATAHORAINCLUSAO,GPS.IDNEGOCIO
                    FROM GEO.GLEBAPARAMETROSISTEMA GPS
                    WHERE GPS.IDGLEBA = ' || v_IDGLEBA || ' AND GPS.IDPARAMETROSISTEMA = ' || v_IDPARAMETROSISTEMA || ' AND GPS.IDNEGOCIO = ' || v_IDNEGOCIO;


--CALL DBMS_OUTPUT.PUT_LINE('SQL: ' || P_cur1 );

PREPARE s_cur1
FROM P_cur1;

SET VEOF = 0;


OPEN v_cur1;


FETCH v_cur1 INTO    F_IDGLEBA;


--CALL DBMS_OUTPUT.PUT_LINE( F_IDGLEBA );

-- SE EXISTE NA TABELA GEO.GLEBAPARAMETROSISTEMA
IF VEOF = 0 THEN DELETE
FROM    GEO.GLEBAPARAMETROSISTEMA GPS
WHERE    GPS.IDGLEBA = v_IDGLEBA
   AND GPS.IDPARAMETROSISTEMA = v_IDPARAMETROSISTEMA
   AND GPS.IDNEGOCIO = v_IDNEGOCIO;


--CALL DBMS_OUTPUT.PUT_LINE( 'iNSERE' );

ELSE SIGNAL SQLSTATE '75002'
SET MESSAGE_TEXT = 'Gleba selecionada nÃ£o possui vÃ­nculo com o sistema.';

END IF;


CLOSE v_cur1;

END
;
-- COPY-DATABASE-OBJECT: "GEO"."PRC_PESQUISAR_GLEBA"
CREATE   OR REPLACE PROCEDURE "GEO"."PRC_PESQUISAR_GLEBA"(
       IN v_IDBEMPESSOAIMOVEL INTEGER,
       IN v_NUMCPFCNPJ VARCHAR(14),
       IN v_INSTITUICAO SMALLINT,
       IN v_DATAINICIAL DATE,
       IN v_DATAFINAL DATE,
       IN v_IDPARAMETROSISTEMA INTEGER,
       IN v_IDNEGOCIO BIGINT
   )
LANGUAGE SQL
SPECIFIC PRC_PESQUISAR_GLEBA
DYNAMIC RESULT SETS 1
BEGIN
DECLARE v_cur1 CURSOR WITH RETURN TO CALLER FOR SELECT
       G.IDGLEBA,
       G.IDINSTITUICAO,
       G.VALORAREAINFORMADA,
       G.VALORAREACALCULADA,
       G.VALORAREANAOCULTIVADA,
       G.DESCGLEBA,
       G.IDBEMPESSOAIMOVEL,
       BP.NUMCPFCNPJ,
       CG.VALORLATITUDE,
       CG.VALORLONGITUDE,
       CG.VALORALTITUDE
   FROM        CLI.VIW_BEMPESSOA BP
   INNER JOIN GEO.GLEBA G ON
       (
           G.IDPESSOAPRODUTORRURAL = BP.IDPESSOA
           AND G.IDINSTITUICAO = BP.IDINSTITUICAO
       )
       OR(
           G.IDPESSOAREMETENTE = BP.IDPESSOA
           AND G.IDINSTITUICAO = BP.IDINSTITUICAO
       )
   INNER JOIN GEO.COORDENADAGEODESICA CG ON
       CG.IDGLEBA = G.IDGLEBA
   LEFT JOIN GEO.GLEBAPARAMETROSISTEMA GP ON
       GP.IDGLEBA = G.IDGLEBA
   WHERE        BP.IDINSTITUICAO = v_INSTITUICAO
       AND BP.NUMCPFCNPJ = v_NUMCPFCNPJ
       AND G.IDBEMPESSOAIMOVEL = v_IDBEMPESSOAIMOVEL
       AND G.BOLATIVO = 1
       AND G.DATAVINCULOU BETWEEN TO_TIMESTAMP(
           TO_CHAR(
               v_DATAINICIAL,
               'YYYY-MM-DD'
           )|| ' 00:00:00 000000',
           'YYYY-MM-DD HH24:MI:SS NNNNNN'
       ) AND TO_TIMESTAMP(
           TO_CHAR(
               v_DATAFINAL,
               'YYYY-MM-DD'
           )|| ' 23:59:59 999998',
           'YYYY-MM-DD HH24:MI:SS NNNNNN'
       )
       AND(
           GP.IDGLEBA IS NULL
           OR(
               GP.IDPARAMETROSISTEMA = v_IDPARAMETROSISTEMA
               AND GP.IDNEGOCIO = v_IDNEGOCIO
           )
       );


IF v_NUMCPFCNPJ IS NULL THEN SIGNAL SQLSTATE '75002'
SET MESSAGE_TEXT = 'PRODUTOR RURAL(CPF/CNPJ) NÃƒO ENCONTRADO.';

END IF;


OPEN v_cur1;

END
;
-- COPY-DATABASE-OBJECT: "GEO"."PRC_PESQUISA_GLEBA"
CREATE OR REPLACE PROCEDURE "GEO"."PRC_PESQUISA_GLEBA" (IN v_IDBEMPESSOAIMOVEL  INTEGER,
	                                            IN v_NUMCPFCNPJ	    VARCHAR(14),
	                                            IN v_INSTITUICAO        SMALLINT,
	                                            IN v_DATAINICIAL        DATE,
	                                            IN v_DATAFINAL          DATE,
	                                            IN v_IDPARAMETROSISTEMA INTEGER,
	                                            IN v_IDNEGOCIO          BIGINT)
LANGUAGE SQL SPECIFIC PRC_PESQUISA_GLEBA
DYNAMIC RESULT SETS 1 
BEGIN   
   DECLARE v_cur1 CURSOR WITH RETURN TO CALLER FOR SELECT G.IDGLEBA,
                                                          G.IDINSTITUICAO, 
                                                          G.VALORAREAINFORMADA, 
                                                          G.VALORAREACALCULADA, 
                                                          G.VALORAREANAOCULTIVADA, 
                                                          G.DESCGLEBA, 
                                                          G.IDBEMPESSOAIMOVEL, 
                                                          BP.NUMCPFCNPJ, 
			                                  CG.VALORLATITUDE, 
			                                  CG.VALORLONGITUDE, 
			                                  CG.VALORALTITUDE
                                                   FROM CLI.VIW_BEMPESSOA BP INNER JOIN GEO.GLEBA                 G  ON (G.IDPESSOAPRODUTORRURAL = BP.IDPESSOA AND G.IDINSTITUICAO = BP.IDINSTITUICAO) OR (G.IDPESSOAREMETENTE = BP.IDPESSOA AND G.IDINSTITUICAO = BP.IDINSTITUICAO)
                                                                             INNER JOIN GEO.COORDENADAGEODESICA   CG ON CG.IDGLEBA = G.IDGLEBA
                                                                             LEFT JOIN GEO.GLEBAPARAMETROSISTEMA GP ON GP.IDGLEBA = G.IDGLEBA
                                                   WHERE BP.IDINSTITUICAO    = v_INSTITUICAO
                                                     AND BP.NUMCPFCNPJ       =   v_NUMCPFCNPJ
                                                     AND G.IDBEMPESSOAIMOVEL = v_IDBEMPESSOAIMOVEL
                                                     AND G.BOLATIVO          = 1
                                                     AND G.DATAVINCULOU BETWEEN TO_TIMESTAMP(TO_CHAR(v_DATAINICIAL,'YYYY-MM-DD')||' 00:00:00 000000','YYYY-MM-DD HH24:MI:SS NNNNNN') AND TO_TIMESTAMP(TO_CHAR(v_DATAFINAL,'YYYY-MM-DD')||' 23:59:59 999998','YYYY-MM-DD HH24:MI:SS NNNNNN')  
                                                   AND (GP.IDGLEBA IS NULL 			                              
                                                    OR (GP.IDPARAMETROSISTEMA = v_IDPARAMETROSISTEMA AND GP.IDNEGOCIO = v_IDNEGOCIO));
   IF v_NUMCPFCNPJ IS NULL THEN
               SIGNAL SQLSTATE '75002'
           SET MESSAGE_TEXT = 'PORRA FODA-SE';
   END IF;                                                               
   OPEN v_cur1; 
END
;
