-- COPY-DATABASE-OBJECT: "LOAD"."LOADDATA"
CREATE OR REPLACE PROCEDURE "LOAD"."LOADDATA" (VSCHEMA VARCHAR(20),VTABELA VARCHAR(100),VCOMANDO VARCHAR(32000))
MODIFIES SQL DATA
NOT DETERMINISTIC
LANGUAGE SQL
SPECIFIC SQL170203105321473
BEGIN
   DECLARE RETCODE                    INTEGER DEFAULT 0;
   DECLARE SQLCODE                    INTEGER DEFAULT 0;
   DECLARE ROWS_READ                  INTEGER;
   DECLARE ROWS_SKIPPED               INTEGER;
   DECLARE ROWS_LOADED                INTEGER;
   DECLARE ROWS_REJECTED              INTEGER;
   DECLARE ROWS_DELETED               INTEGER;
   DECLARE ROWS_COMMITTED             INTEGER;
   DECLARE ROWS_PARTITIONED           INTEGER;
   DECLARE NUM_AGENTINFO_ENTRIES      INTEGER;
   DECLARE MSG_RETRIEVAL              VARCHAR(500);
   DECLARE MSG_REMOVAL                VARCHAR(500);
   DECLARE DATAHORAINICIOCARGA        TIMESTAMP;
   DECLARE RESULT1 RESULT_SET_LOCATOR VARYING; 
--   DECLARE CONTINUE HANDLER FOR SQLEXCEPTION,SQLWARNING
--      BEGIN
--         SET RETCODE = SQLCODE;
--      END;   
   SET DATAHORAINICIOCARGA = CURRENT TIMESTAMP;
   CALL SYSPROC.ADMIN_CMD (VCOMANDO);
   ASSOCIATE RESULT SET LOCATORS (RESULT1) WITH PROCEDURE SYSPROC.ADMIN_CMD;
   ALLOCATE RSCUR CURSOR FOR RESULT SET RESULT1;
   FETCH RSCUR INTO ROWS_READ,ROWS_SKIPPED,ROWS_LOADED,ROWS_REJECTED,ROWS_DELETED,ROWS_COMMITTED,ROWS_PARTITIONED,NUM_AGENTINFO_ENTRIES,MSG_RETRIEVAL,MSG_REMOVAL;
   CLOSE RSCUR WITH RELEASE;
   INSERT INTO LOAD.LOADLOG VALUES (VSCHEMA,VTABELA,DATAHORAINICIOCARGA,CURRENT TIMESTAMP,ROWS_READ,ROWS_SKIPPED,ROWS_LOADED,ROWS_REJECTED,ROWS_DELETED,ROWS_COMMITTED,ROWS_PARTITIONED,NUM_AGENTINFO_ENTRIES,MSG_RETRIEVAL,MSG_REMOVAL);
END
;
