-- COPY-DATABASE-OBJECT: "RCR"."SPUCRECOPIAROPERACAOCREDITORURAL"
CREATE OR REPLACE PROCEDURE "RCR"."SPUCRECOPIAROPERACAOCREDITORURAL"
(
    IN  P_IDOPERACAO       BIGINT,
    OUT P_CODIGO           BIGINT,
    OUT P_MENSAGEM         VARCHAR(200),
    OUT P_ID_OPERACAORURAL_NEW  BIGINT
)
LANGUAGE SQL
BEGIN
 
    -- VARIAVEIS
    DECLARE V_ID_OPERACAO_RURAL_ORIGEM BIGINT;
    DECLARE V_ID_OPERACAO_RURAL_NEW   BIGINT;
    DECLARE V_ID_EMPREENDIMENTORURAL_NEW BIGINT;
    DECLARE V_ID_PROAGROMAISOPERACAO_NEW BIGINT;
    DECLARE V_ID_EMPREENDIMENTORURALIMOVEL_NEW BIGINT;

    -- HANDLER DE ERRO
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
 
        SET P_CODIGO = 0;
        SET P_MENSAGEM = 'ERRO AO COPIAR OPERACAO CREDITO RURAL';
        SET P_ID_OPERACAORURAL_NEW = NULL;
    END;

--    DECLARE EXIT HANDLER FOR NOT FOUND
--    BEGIN
--        ROLLBACK;
--
--        SET P_CODIGO = 0;
--        --SET P_MENSAGEM = 'OPERACAO DE CREDITO ORIGEM NAO ENCONTRADA';
--        SET P_ID_OPERACAORURAL_NEW = NULL;
--    END;

    BEGIN
        DECLARE CONTINUE HANDLER FOR SQLSTATE '42710'
        BEGIN
        END;

        DECLARE GLOBAL TEMPORARY TABLE SESSION.TB_EMPREENDIMENTORURAL_MAPA (
            IDEMPREENDIMENTORURAL_ORIGEM INTEGER NOT NULL,
            IDEMPREENDIMENTORURAL_NEW INTEGER NOT NULL
        ) ON COMMIT PRESERVE ROWS NOT LOGGED;

        DECLARE GLOBAL TEMPORARY TABLE SESSION.TB_PROAGROMAISOPERACAO_MAPA (
            IDPROAGROMAISOPERACAO_ORIGEM INTEGER NOT NULL,
            IDPROAGROMAISOPERACAO_NEW INTEGER NOT NULL
        ) ON COMMIT PRESERVE ROWS NOT LOGGED;

        DECLARE GLOBAL TEMPORARY TABLE SESSION.TB_EMPREENDIMENTORURALIMOVEL_MAPA (
            IDEMPREENDIMENTORURALIMOVEL_ORIGEM INTEGER NOT NULL,
            IDEMPREENDIMENTORURALIMOVEL_NEW INTEGER NOT NULL
        ) ON COMMIT PRESERVE ROWS NOT LOGGED;
    END;

    DELETE FROM SESSION.TB_EMPREENDIMENTORURAL_MAPA WHERE 1=1;
    DELETE FROM SESSION.TB_PROAGROMAISOPERACAO_MAPA WHERE 1=1;
    DELETE FROM SESSION.TB_EMPREENDIMENTORURALIMOVEL_MAPA WHERE 1=1;
         SET P_MENSAGEM = 'ANTES DO INICIO TRANSACAO';
    ----------------------------------------------------------------
    -- INICIO TRANSACAO
    -- BUSCA OPERACAO DE ORIGEM NA OPERACAOCREDITORURAL
    ----------------------------------------------------------------
    SELECT IDOPERACAOCREDITORURAL
      INTO V_ID_OPERACAO_RURAL_ORIGEM
      FROM CRE.OPERACAOCREDITORURAL o
    WHERE IDOPERACAOCREDITO = P_IDOPERACAO
      FETCH FIRST 1 ROW ONLY;
        SET P_MENSAGEM = 'INICIO TRANSACAO';
    ----------------------------------------------------------------
    -- COPIA REGISTRO DA OPERACAOCREDITORURAL
    ----------------------------------------------------------------
    
    SELECT IDOPERACAOCREDITORURAL
        INTO V_ID_OPERACAO_RURAL_NEW
        FROM FINAL TABLE
        (
            INSERT INTO CRE.OPERACAOCREDITORURAL (
                        VALORTOTALORCADO,
                        VALORRECURSOPROPRIO,
                        PERCFINANCIADO,
                        BOLORIENTACAOTECNICAFINANC,
                        VALORORIENTACAOTECNICA,
                        PERCORIENTACAOTECNICA,
                        PERCCAPITALIZACAOREPESSA,
                        IDPRESTADORORIENTACAOTECNICA,
                        IDOPERACAOCREDITO,
                        IDLINHACREDITO,
                        DATACADASTROLINHA,
                        IDPROGRAMABACEN,
                        IDSAFRA,
                        QTDEEMPREENDIMENTOS,
                        VALORTOTALSEGURORURAL,
                        DATAOPERACAO,
                        DATACONTRATACAO,
                        IDPESSOAPRODUTORRURAL,
                        VALORTOTALFINANCIADO,
                        VALORTOTALRECURSOPROPRIO,
                        BOLASSISTENCIATECNICAGRATUITA,
                        IDINSTITUICAOOPERACAO,
                        IDUNIDADEINSTITUICAOOPERACAO,
                        IDINSTITUICAOLOCALNEGOCIO ,
                        IDUNIDADEINSTITUICAOLOCALNEGOCIO,
                        IDTIPOCEDULABACEN,
                        NUMREFBACEN,
                        IDEMPREENDIMENTOBACENPGPAF,
                        BOLEXIGEALTERACAOSICOR,
                        IDSUBPROGRAMABACEN,
                        IDINSTRUMENTOCREDITOBACEN ,
                        CODDAP,
                        NUMCONTRATOFUNCAFE,
                        IDSEQPROPREN,
                        DATAREGISTROSICOR ,
                        DATAEXCLUSAOAUTOMATICASICOR,
                        IDPLANOLIBERACAO,
                        DATAHORAALTERACAO,
                        CODSTN,
                        BOLREDUCAOTAXA,
                        IDCONDICAOANALISECAR,
                        IDGRUPOFONTERECURSO,
                        BOLCONSULTAPGT
                )
                SELECT
                  --NULL IDOPERACAOCREDITORURAL, --PK da tabela (informacao sera gravada na PROPOSTARENOVACAO)
                  VALORTOTALORCADO,
                  VALORRECURSOPROPRIO,
                  PERCFINANCIADO,
                  BOLORIENTACAOTECNICAFINANC,
                  VALORORIENTACAOTECNICA,
                  PERCORIENTACAOTECNICA,
                  PERCCAPITALIZACAOREPESSA,
                  IDPRESTADORORIENTACAOTECNICA,
                  NULL IDOPERACAOCREDITO, --NAO VINCULAR OPERACAO ANTERIOR
                  IDLINHACREDITO,
                  DATACADASTROLINHA,
                  IDPROGRAMABACEN,
                  IDSAFRA,
                  QTDEEMPREENDIMENTOS,
                  VALORTOTALSEGURORURAL,
                  DATAOPERACAO,
                  DATACONTRATACAO,
                  IDPESSOAPRODUTORRURAL,
                  VALORTOTALFINANCIADO,
                  VALORTOTALRECURSOPROPRIO,
                  BOLASSISTENCIATECNICAGRATUITA,
                  IDINSTITUICAOOPERACAO,
                  IDUNIDADEINSTITUICAOOPERACAO,
                  IDINSTITUICAOLOCALNEGOCIO,
                  IDUNIDADEINSTITUICAOLOCALNEGOCIO,
                  IDTIPOCEDULABACEN,
                  NUMREFBACEN,
                  IDEMPREENDIMENTOBACENPGPAF,
                  BOLEXIGEALTERACAOSICOR,
                  IDSUBPROGRAMABACEN,
                  IDINSTRUMENTOCREDITOBACEN,
                  CODDAP,
                  NUMCONTRATOFUNCAFE,
                  IDSEQPROPREN,
                  DATAREGISTROSICOR,
                  DATAEXCLUSAOAUTOMATICASICOR,
                  NULL IDPLANOLIBERACAO, ---NAO VINCULAR PLANO ANTERIOR
                  NOW() DATAHORAALTERACAO,
                  CODSTN,
                  BOLREDUCAOTAXA,
                  IDCONDICAOANALISECAR,
                  IDGRUPOFONTERECURSO,
                  BOLCONSULTAPGT
                FROM
                    CRE.OPERACAOCREDITORURAL
            WHERE IDOPERACAOCREDITORURAL = V_ID_OPERACAO_RURAL_ORIGEM
        );
            
        IF V_ID_OPERACAO_RURAL_NEW IS NULL THEN
            SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'FALHA AO GERAR NOVA OPERACAO RURAL';
                SET P_CODIGO = 0;
                SET P_MENSAGEM = 'FALHA AO GERAR NOVA OPERACAO RURAL';
        END IF;

        
