    -- RECUPERA NOVO ID GERADO
    ----------------------------------------------------------------
    SET P_CODIGO = 1;
    SET P_MENSAGEM = 'SUCESSO';
    SET P_ID_OPERACAORURAL_NEW = V_ID_OPERACAO_RURAL_NEW;  
        
