            ,BOLEXIGEMONITORAMENTO
        FROM CRE.EMPREENDIMENTORURAL
        WHERE IDOPERACAOCREDITORURAL = V_ID_OPERACAO_RURAL_ORIGEM
        ORDER BY IDEMPREENDIMENTORURAL
    DO
        BEGIN
        INSERT INTO CRE.EMPREENDIMENTORURAL (
             IDOPERACAOCREDITORURAL
            ,IDINSTITUICAOCADASTRO
            ,IDPESSOAPRODUTORRURAL
            ,IDEMPREENDIMENTOBACEN
            ,IDSAFRA
            ,IDMUNICIPIO
            ,IDIMOVEL
            ,IDSITUACAOCREDITO
            ,IDUSUARIO
            ,DATAHORAALTERACAO
            ,DESCMOTIVOPERDA
            ,BOLMIGRADOCAPES
            ,IDPESSOAPRODUTIVIDADECAPES
            ,DATAPLANTIOSEMEADURAINICIO
            ,DATACOLHEITAINICIO
            ,DATAPLANTIOSEMEADURAFIM
            ,DATACOLHEITAFIM
            ,NUMSEQEMPREENDIMENTORURAL
            ,BOLEMPREENDIMENTORURALCORPORATIVO
            ,BOLEMPREENDIMENTOSEMIMOVEL
            ,PERCENERGIARENOVAVEL
            ,CODCERTORGANICA
            ,DESCURLCERTORGANICA
            ,CODCERTRASTREABILIADADE
            ,DESCURLCERTRASTREABILIDADE
            ,CODSTN
            ,BOLANALISEAMBIENTAL
            ,BOLEXIGEMONITORAMENTO
        )
        VALUES (
             V_ID_OPERACAO_RURAL_NEW
            ,V_EMPREENDIMENTO.IDINSTITUICAOCADASTRO
            ,V_EMPREENDIMENTO.IDPESSOAPRODUTORRURAL
            ,V_EMPREENDIMENTO.IDEMPREENDIMENTOBACEN
            ,V_EMPREENDIMENTO.IDSAFRA
            ,V_EMPREENDIMENTO.IDMUNICIPIO
            ,V_EMPREENDIMENTO.IDIMOVEL
            ,V_EMPREENDIMENTO.IDSITUACAOCREDITO
            ,V_EMPREENDIMENTO.IDUSUARIO
            ,V_EMPREENDIMENTO.DATAHORAALTERACAO
            ,V_EMPREENDIMENTO.DESCMOTIVOPERDA
            ,V_EMPREENDIMENTO.BOLMIGRADOCAPES
            ,V_EMPREENDIMENTO.IDPESSOAPRODUTIVIDADECAPES
            ,V_EMPREENDIMENTO.DATAPLANTIOSEMEADURAINICIO
            ,V_EMPREENDIMENTO.DATACOLHEITAINICIO
            ,V_EMPREENDIMENTO.DATAPLANTIOSEMEADURAFIM
            ,V_EMPREENDIMENTO.DATACOLHEITAFIM
            ,V_EMPREENDIMENTO.NUMSEQEMPREENDIMENTORURAL
            ,V_EMPREENDIMENTO.BOLEMPREENDIMENTORURALCORPORATIVO
            ,V_EMPREENDIMENTO.BOLEMPREENDIMENTOSEMIMOVEL
            ,V_EMPREENDIMENTO.PERCENERGIARENOVAVEL
            ,V_EMPREENDIMENTO.CODCERTORGANICA
            ,V_EMPREENDIMENTO.DESCURLCERTORGANICA
            ,V_EMPREENDIMENTO.CODCERTRASTREABILIADADE
            ,V_EMPREENDIMENTO.DESCURLCERTRASTREABILIDADE
            ,V_EMPREENDIMENTO.CODSTN
            ,V_EMPREENDIMENTO.BOLANALISEAMBIENTAL
            ,V_EMPREENDIMENTO.BOLEXIGEMONITORAMENTO
        );

        SET V_ID_EMPREENDIMENTORURAL_NEW = IDENTITY_VAL_LOCAL();

        INSERT INTO SESSION.TB_EMPREENDIMENTORURAL_MAPA (
             IDEMPREENDIMENTORURAL_ORIGEM
            ,IDEMPREENDIMENTORURAL_NEW
        )
        VALUES (
             V_EMPREENDIMENTO.IDEMPREENDIMENTORURAL
            ,V_ID_EMPREENDIMENTORURAL_NEW
        );
        END;
    END FOR;
 
