-- COPY-DATABASE-OBJECT: "RCR"."SPU_COPIAROPERACAOCREDITORURAL"
CREATE OR REPLACE PROCEDURE "RCR"."SPU_COPIAROPERACAOCREDITORURAL"
(
    IN  P_IDOPERACAO       BIGINT,
    OUT P_CODIGO           BIGINT,
    OUT P_MENSAGEM         VARCHAR(200),
    OUT P_ID_OPERACAORURAL_NEW  BIGINT
)
LANGUAGE SQL
BEGIN
 
    -- VARIAVEIS
    DECLARE V_ID_OPERACAO_RURAL_ORIGEM BIGINT;
    DECLARE V_ID_OPERACAO_RURAL_NEW   BIGINT;
    DECLARE V_ID_EMPREENDIMENTORURAL_NEW BIGINT;
    DECLARE V_ID_PROAGROMAISOPERACAO_NEW BIGINT;
    DECLARE V_ID_EMPREENDIMENTORURALIMOVEL_NEW BIGINT;

    -- HANDLER DE ERRO
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        --ROLLBACK;
 
        SET P_CODIGO = 0;
        SET P_MENSAGEM = 'ERRO AO COPIAR OPERACAO CREDITO RURAL';
        SET P_ID_OPERACAORURAL_NEW = NULL;
    END;

--    DECLARE EXIT HANDLER FOR NOT FOUND
--    BEGIN
--        ROLLBACK;
--
--        SET P_CODIGO = 0;
--        --SET P_MENSAGEM = 'OPERACAO DE CREDITO ORIGEM NAO ENCONTRADA';
--        SET P_ID_OPERACAORURAL_NEW = NULL;
--    END;

    BEGIN
        DECLARE CONTINUE HANDLER FOR SQLSTATE '42710'
        BEGIN
        END;

        DECLARE GLOBAL TEMPORARY TABLE SESSION.TB_EMPREENDIMENTORURAL_MAPA (
            IDEMPREENDIMENTORURAL_ORIGEM INTEGER NOT NULL,
            IDEMPREENDIMENTORURAL_NEW INTEGER NOT NULL
        ) ON COMMIT PRESERVE ROWS NOT LOGGED;

        DECLARE GLOBAL TEMPORARY TABLE SESSION.TB_PROAGROMAISOPERACAO_MAPA (
            IDPROAGROMAISOPERACAO_ORIGEM INTEGER NOT NULL,
            IDPROAGROMAISOPERACAO_NEW INTEGER NOT NULL
        ) ON COMMIT PRESERVE ROWS NOT LOGGED;

        DECLARE GLOBAL TEMPORARY TABLE SESSION.TB_EMPREENDIMENTORURALIMOVEL_MAPA (
            IDEMPREENDIMENTORURALIMOVEL_ORIGEM INTEGER NOT NULL,
            IDEMPREENDIMENTORURALIMOVEL_NEW INTEGER NOT NULL
        ) ON COMMIT PRESERVE ROWS NOT LOGGED;
    END;

    DELETE FROM SESSION.TB_EMPREENDIMENTORURAL_MAPA WHERE 1=1;
    DELETE FROM SESSION.TB_PROAGROMAISOPERACAO_MAPA WHERE 1=1;
    DELETE FROM SESSION.TB_EMPREENDIMENTORURALIMOVEL_MAPA WHERE 1=1;
         SET P_MENSAGEM = 'ANTES DO INICIO TRANSACAO';
    ----------------------------------------------------------------
    -- INICIO TRANSACAO
    -- BUSCA OPERACAO DE ORIGEM NA OPERACAOCREDITORURAL
    ----------------------------------------------------------------
    SELECT IDOPERACAOCREDITORURAL
      INTO V_ID_OPERACAO_RURAL_ORIGEM
      FROM CRE.OPERACAOCREDITORURAL o
    WHERE IDOPERACAOCREDITO = P_IDOPERACAO
      FETCH FIRST 1 ROW ONLY;
        SET P_MENSAGEM = 'INICIO TRANSACAO';
    ----------------------------------------------------------------
    -- COPIA REGISTRO DA OPERACAOCREDITORURAL
    ----------------------------------------------------------------
    
    SELECT IDOPERACAOCREDITORURAL
        INTO V_ID_OPERACAO_RURAL_NEW
        FROM FINAL TABLE
        (
            INSERT INTO CRE.OPERACAOCREDITORURAL (
                        VALORTOTALORCADO,
                        VALORRECURSOPROPRIO,
                        PERCFINANCIADO,
                        BOLORIENTACAOTECNICAFINANC,
                        VALORORIENTACAOTECNICA,
                        PERCORIENTACAOTECNICA,
                        PERCCAPITALIZACAOREPESSA,
                        IDPRESTADORORIENTACAOTECNICA,
                        IDOPERACAOCREDITO,
                        IDLINHACREDITO,
                        DATACADASTROLINHA,
                        IDPROGRAMABACEN,
                        IDSAFRA,
                        QTDEEMPREENDIMENTOS,
                        VALORTOTALSEGURORURAL,
                        DATAOPERACAO,
                        DATACONTRATACAO,
                        IDPESSOAPRODUTORRURAL,
                        VALORTOTALFINANCIADO,
                        VALORTOTALRECURSOPROPRIO,
                        BOLASSISTENCIATECNICAGRATUITA,
                        IDINSTITUICAOOPERACAO,
                        IDUNIDADEINSTITUICAOOPERACAO,
                        IDINSTITUICAOLOCALNEGOCIO ,
                        IDUNIDADEINSTITUICAOLOCALNEGOCIO,
                        IDTIPOCEDULABACEN,
                        NUMREFBACEN,
                        IDEMPREENDIMENTOBACENPGPAF,
                        BOLEXIGEALTERACAOSICOR,
                        IDSUBPROGRAMABACEN,
                        IDINSTRUMENTOCREDITOBACEN ,
                        CODDAP,
                        NUMCONTRATOFUNCAFE,
                        IDSEQPROPREN,
                        DATAREGISTROSICOR ,
                        DATAEXCLUSAOAUTOMATICASICOR,
                        IDPLANOLIBERACAO,
                        DATAHORAALTERACAO,
                        CODSTN,
                        BOLREDUCAOTAXA,
                        IDCONDICAOANALISECAR,
                        IDGRUPOFONTERECURSO,
                        BOLCONSULTAPGT
                )
                SELECT
                  --NULL IDOPERACAOCREDITORURAL, --PK da tabela (informacao sera gravada na PROPOSTARENOVACAO)
                  VALORTOTALORCADO,
                  VALORRECURSOPROPRIO,
                  PERCFINANCIADO,
                  BOLORIENTACAOTECNICAFINANC,
                  VALORORIENTACAOTECNICA,
                  PERCORIENTACAOTECNICA,
                  PERCCAPITALIZACAOREPESSA,
                  IDPRESTADORORIENTACAOTECNICA,
                  NULL IDOPERACAOCREDITO, --NAO VINCULAR OPERACAO ANTERIOR
                  IDLINHACREDITO,
                  DATACADASTROLINHA,
                  IDPROGRAMABACEN,
                  IDSAFRA,
                  QTDEEMPREENDIMENTOS,
                  VALORTOTALSEGURORURAL,
                  DATAOPERACAO,
                  DATACONTRATACAO,
                  IDPESSOAPRODUTORRURAL,
                  VALORTOTALFINANCIADO,
                  VALORTOTALRECURSOPROPRIO,
                  BOLASSISTENCIATECNICAGRATUITA,
                  IDINSTITUICAOOPERACAO,
                  IDUNIDADEINSTITUICAOOPERACAO,
                  IDINSTITUICAOLOCALNEGOCIO,
                  IDUNIDADEINSTITUICAOLOCALNEGOCIO,
                  IDTIPOCEDULABACEN,
                  NUMREFBACEN,
                  IDEMPREENDIMENTOBACENPGPAF,
                  BOLEXIGEALTERACAOSICOR,
                  IDSUBPROGRAMABACEN,
                  IDINSTRUMENTOCREDITOBACEN,
                  CODDAP,
                  NUMCONTRATOFUNCAFE,
                  IDSEQPROPREN,
                  DATAREGISTROSICOR,
                  DATAEXCLUSAOAUTOMATICASICOR,
                  NULL IDPLANOLIBERACAO, ---NAO VINCULAR PLANO ANTERIOR
                  NOW() DATAHORAALTERACAO,
                  CODSTN,
                  BOLREDUCAOTAXA,
                  IDCONDICAOANALISECAR,
                  IDGRUPOFONTERECURSO,
                  BOLCONSULTAPGT
                FROM
                    CRE.OPERACAOCREDITORURAL
            WHERE IDOPERACAOCREDITORURAL = V_ID_OPERACAO_RURAL_ORIGEM
        );
            
        IF V_ID_OPERACAO_RURAL_NEW IS NULL THEN
            SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'FALHA AO GERAR NOVA OPERACAO RURAL';
                SET P_CODIGO = 0;
                SET P_MENSAGEM = 'FALHA AO GERAR NOVA OPERACAO RURAL';
        END IF;

        
    ----------------------------------------------------------------
    -- RECUPERA NOVO ID GERADO
    ----------------------------------------------------------------
    SET P_CODIGO = 1;
    SET P_MENSAGEM = 'SUCESSO';
    SET P_ID_OPERACAORURAL_NEW = V_ID_OPERACAO_RURAL_NEW;  
        
    ----------------------------------------------------------------
    -- COPIA REGISTROS CRE.EMPREENDIMENTORURAL A PARTIR DO: V_ID_OPERACAO_RURAL_ORIGEM
    -- MANTENDO RELACIONAMENTO COM NOVO IDENTIFICADOR: V_ID_OPERACAO_RURAL_NEW
    ----------------------------------------------------------------
    FOR V_EMPREENDIMENTO AS CUR_EMPREENDIMENTO CURSOR FOR
        SELECT
             IDEMPREENDIMENTORURAL
            ,IDINSTITUICAOCADASTRO
            ,IDPESSOAPRODUTORRURAL
            ,IDEMPREENDIMENTOBACEN
            ,IDSAFRA
            ,IDMUNICIPIO
            ,IDIMOVEL
            ,IDSITUACAOCREDITO
            ,IDUSUARIO
            ,DATAHORAALTERACAO
            ,DESCMOTIVOPERDA
            ,BOLMIGRADOCAPES
            ,IDPESSOAPRODUTIVIDADECAPES
            ,DATAPLANTIOSEMEADURAINICIO
            ,DATACOLHEITAINICIO
            ,DATAPLANTIOSEMEADURAFIM
            ,DATACOLHEITAFIM
            ,NUMSEQEMPREENDIMENTORURAL
            ,BOLEMPREENDIMENTORURALCORPORATIVO
            ,BOLEMPREENDIMENTOSEMIMOVEL
            ,PERCENERGIARENOVAVEL
            ,CODCERTORGANICA
            ,DESCURLCERTORGANICA
            ,CODCERTRASTREABILIADADE
            ,DESCURLCERTRASTREABILIDADE
            ,CODSTN
            ,BOLANALISEAMBIENTAL
            ,BOLEXIGEMONITORAMENTO
        FROM CRE.EMPREENDIMENTORURAL
        WHERE IDOPERACAOCREDITORURAL = V_ID_OPERACAO_RURAL_ORIGEM
        ORDER BY IDEMPREENDIMENTORURAL
    DO
        BEGIN
        INSERT INTO CRE.EMPREENDIMENTORURAL (
             IDOPERACAOCREDITORURAL
            ,IDINSTITUICAOCADASTRO
            ,IDPESSOAPRODUTORRURAL
            ,IDEMPREENDIMENTOBACEN
            ,IDSAFRA
            ,IDMUNICIPIO
            ,IDIMOVEL
            ,IDSITUACAOCREDITO
            ,IDUSUARIO
            ,DATAHORAALTERACAO
            ,DESCMOTIVOPERDA
            ,BOLMIGRADOCAPES
            ,IDPESSOAPRODUTIVIDADECAPES
            ,DATAPLANTIOSEMEADURAINICIO
            ,DATACOLHEITAINICIO
            ,DATAPLANTIOSEMEADURAFIM
            ,DATACOLHEITAFIM
            ,NUMSEQEMPREENDIMENTORURAL
            ,BOLEMPREENDIMENTORURALCORPORATIVO
            ,BOLEMPREENDIMENTOSEMIMOVEL
            ,PERCENERGIARENOVAVEL
            ,CODCERTORGANICA
            ,DESCURLCERTORGANICA
            ,CODCERTRASTREABILIADADE
            ,DESCURLCERTRASTREABILIDADE
            ,CODSTN
            ,BOLANALISEAMBIENTAL
            ,BOLEXIGEMONITORAMENTO
        )
        VALUES (
             V_ID_OPERACAO_RURAL_NEW
            ,V_EMPREENDIMENTO.IDINSTITUICAOCADASTRO
            ,V_EMPREENDIMENTO.IDPESSOAPRODUTORRURAL
            ,V_EMPREENDIMENTO.IDEMPREENDIMENTOBACEN
            ,V_EMPREENDIMENTO.IDSAFRA
            ,V_EMPREENDIMENTO.IDMUNICIPIO
            ,V_EMPREENDIMENTO.IDIMOVEL
            ,V_EMPREENDIMENTO.IDSITUACAOCREDITO
            ,V_EMPREENDIMENTO.IDUSUARIO
            ,V_EMPREENDIMENTO.DATAHORAALTERACAO
            ,V_EMPREENDIMENTO.DESCMOTIVOPERDA
            ,V_EMPREENDIMENTO.BOLMIGRADOCAPES
            ,V_EMPREENDIMENTO.IDPESSOAPRODUTIVIDADECAPES
            ,V_EMPREENDIMENTO.DATAPLANTIOSEMEADURAINICIO
            ,V_EMPREENDIMENTO.DATACOLHEITAINICIO
            ,V_EMPREENDIMENTO.DATAPLANTIOSEMEADURAFIM
            ,V_EMPREENDIMENTO.DATACOLHEITAFIM
            ,V_EMPREENDIMENTO.NUMSEQEMPREENDIMENTORURAL
            ,V_EMPREENDIMENTO.BOLEMPREENDIMENTORURALCORPORATIVO
            ,V_EMPREENDIMENTO.BOLEMPREENDIMENTOSEMIMOVEL
            ,V_EMPREENDIMENTO.PERCENERGIARENOVAVEL
            ,V_EMPREENDIMENTO.CODCERTORGANICA
            ,V_EMPREENDIMENTO.DESCURLCERTORGANICA
            ,V_EMPREENDIMENTO.CODCERTRASTREABILIADADE
            ,V_EMPREENDIMENTO.DESCURLCERTRASTREABILIDADE
            ,V_EMPREENDIMENTO.CODSTN
            ,V_EMPREENDIMENTO.BOLANALISEAMBIENTAL
            ,V_EMPREENDIMENTO.BOLEXIGEMONITORAMENTO
        );

        SET V_ID_EMPREENDIMENTORURAL_NEW = IDENTITY_VAL_LOCAL();

        INSERT INTO SESSION.TB_EMPREENDIMENTORURAL_MAPA (
             IDEMPREENDIMENTORURAL_ORIGEM
            ,IDEMPREENDIMENTORURAL_NEW
        )
        VALUES (
             V_EMPREENDIMENTO.IDEMPREENDIMENTORURAL
            ,V_ID_EMPREENDIMENTORURAL_NEW
        );
        END;
    END FOR;
 
        ----------------------------------------------------------------
    -- COPIA REGISTROS CRE.EMPREENDIMENTORURALSEGURO
    ----------------------------------------------------------------
    INSERT INTO CRE.EMPREENDIMENTORURALSEGURO (
         IDEMPREENDIMENTORURAL
        ,IDTIPOSEGURORURAL
        ,VALORSEGURO
        ,VALORTOTALSEGURADO
        ,PERCALIQUOTASEGURO
        ,BOLSEGUROFINANCIADO
        ,IDINSTITUICAOPROAGROMAISINVESTIMENTO
        ,NUMREFBACENOPERACAOPROAGROMAISINVEST
        ,DATACONTRATACAOOPERACAOPROAGROMAISINVEST
        ,VALORENQUADRADOPROAGROMAISINVEST
        ,PERCPROAGROMAISINVEST
        ,VALORSEGUROPROAGROMAISINVEST
        ,BOLINCLUIRRECURSOPROPRIO
        ,VALORRECURSOPROPRIOSERVICO
        ,VALORRECURSOPROPRIOENQUADRADO
        ,VALORTOTALENQUADRADO
        ,PERCBONUSMALUS
        ,PERCALICOTAPREDEFINIDA
        ,DESCPARAMETROSCALCULOSEGURO
        ,DATAHORACALCULO
        ,BOLALIQUOTAMANUAL
        ,IDUSUARIOALIQUOTAMANUAL
        --,DATAHORAINICIOSISTEMATPL
        --,DATAHORAFIMSISTEMATPL
        --,DATAHORAINICIOTRANSACAOTPL
    )
    SELECT
         M.IDEMPREENDIMENTORURAL_NEW
        ,S.IDTIPOSEGURORURAL
        ,S.VALORSEGURO
        ,S.VALORTOTALSEGURADO
        ,S.PERCALIQUOTASEGURO
        ,S.BOLSEGUROFINANCIADO
        ,S.IDINSTITUICAOPROAGROMAISINVESTIMENTO
        ,S.NUMREFBACENOPERACAOPROAGROMAISINVEST
        ,S.DATACONTRATACAOOPERACAOPROAGROMAISINVEST
        ,S.VALORENQUADRADOPROAGROMAISINVEST
        ,S.PERCPROAGROMAISINVEST
        ,S.VALORSEGUROPROAGROMAISINVEST
        ,S.BOLINCLUIRRECURSOPROPRIO
        ,S.VALORRECURSOPROPRIOSERVICO
        ,S.VALORRECURSOPROPRIOENQUADRADO
        ,S.VALORTOTALENQUADRADO
        ,S.PERCBONUSMALUS
        ,S.PERCALICOTAPREDEFINIDA
        ,S.DESCPARAMETROSCALCULOSEGURO
        ,S.DATAHORACALCULO
        ,S.BOLALIQUOTAMANUAL
        ,S.IDUSUARIOALIQUOTAMANUAL
        --,S.DATAHORAINICIOSISTEMATPL
        --,S.DATAHORAFIMSISTEMATPL
        --,S.DATAHORAINICIOTRANSACAOTPL
    FROM CRE.EMPREENDIMENTORURALSEGURO S
    INNER JOIN SESSION.TB_EMPREENDIMENTORURAL_MAPA M
        ON M.IDEMPREENDIMENTORURAL_ORIGEM = S.IDEMPREENDIMENTORURAL;


        ----------------------------------------------------------------
    -- COPIA REGISTROS CRE.EMPREENDIMENTORURALSEGUROPRIVADO
    ----------------------------------------------------------------
    INSERT INTO CRE.EMPREENDIMENTORURALSEGUROPRIVADO (
         IDEMPREENDIMENTORURAL
        ,NUMPROPOSTAAPOLICESEGURO
        ,IDSEGURADORARURAL
        ,IDCORRETORASEGURORURAL
        ,IDTIPOSEGUROPRIVADORURAL
        ,DATAINICIOVIGENCIA
        ,DATAFIMVIGENCIA
        ,BOLFINANCIADO
        ,BOLSUBVENCAO
        ,IDTIPOSUBVENCAOSEGUROPRIVADORURAL
        ,VALORSUBVENCAO
        ,BOLSUBVENCAOFINANCIADA
        ,VALORPREMIOFINANCIADO
        ,CODTIPODOCUMENTOSEGUROPRIVADO
        ,IDPESSOASEGURADO
        ,IDPESSOABENEFICIARIO
    )
    SELECT
         M.IDEMPREENDIMENTORURAL_NEW
        ,S.NUMPROPOSTAAPOLICESEGURO
        ,S.IDSEGURADORARURAL
        ,S.IDCORRETORASEGURORURAL
        ,S.IDTIPOSEGUROPRIVADORURAL
        ,S.DATAINICIOVIGENCIA
        ,S.DATAFIMVIGENCIA
        ,S.BOLFINANCIADO
        ,S.BOLSUBVENCAO
        ,S.IDTIPOSUBVENCAOSEGUROPRIVADORURAL
        ,S.VALORSUBVENCAO
        ,S.BOLSUBVENCAOFINANCIADA
        ,S.VALORPREMIOFINANCIADO
        ,S.CODTIPODOCUMENTOSEGUROPRIVADO
        ,S.IDPESSOASEGURADO
        ,S.IDPESSOABENEFICIARIO
    FROM CRE.EMPREENDIMENTORURALSEGUROPRIVADO S
    INNER JOIN SESSION.TB_EMPREENDIMENTORURAL_MAPA M
        ON M.IDEMPREENDIMENTORURAL_ORIGEM = S.IDEMPREENDIMENTORURAL;


        ----------------------------------------------------------------
    -- COPIA REGISTROS CRE.EMPREENDIMENTOORCAMENTOITEM
    ----------------------------------------------------------------
    INSERT INTO CRE.EMPREENDIMENTOORCAMENTOITEM (
         IDEMPREENDIMENTORURAL
        ,IDORCAMENTOEMPREENDBACEN
        ,IDITEM
        ,IDTIPOTECNOLOGIA
        ,DATADESEMBOLSO
        ,VALORITEMEMPREEND
    )
    SELECT
         M.IDEMPREENDIMENTORURAL_NEW
        ,S.IDORCAMENTOEMPREENDBACEN
        ,S.IDITEM
        ,S.IDTIPOTECNOLOGIA
        ,S.DATADESEMBOLSO
        ,S.VALORITEMEMPREEND
    FROM CRE.EMPREENDIMENTOORCAMENTOITEM S
    INNER JOIN SESSION.TB_EMPREENDIMENTORURAL_MAPA M
        ON M.IDEMPREENDIMENTORURAL_ORIGEM = S.IDEMPREENDIMENTORURAL;


        ----------------------------------------------------------------
    -- COPIA REGISTROS CRE.EMPREENDIMENTORURALCUSTEIO
    ----------------------------------------------------------------
    INSERT INTO CRE.EMPREENDIMENTORURALCUSTEIO (
         IDEMPREENDIMENTORURAL
        ,VALORRECURSOPROPRIO
        ,VALORFINANCIADO
        ,VALORTOTALEMPREENDIMENTO
        ,VALORPREVISAOPRODUCAO
        ,IDUNIDADEMEDIDAPREVISAOPRODUCAO
        ,VALOREXPLORACAO
        ,IDUNIDADEMEDIDAEXPLORADA
        ,VALORPRECOMEDIO
        ,VALORRBE
        ,IDTIPOTECNOLOGIA
        ,QTDPRODUTIVIDADE
        ,PERCFINANCIADO
        ,VALORTOTALORCAMENTO
        ,DESCEXPLORACAO
        --,DATAHORAINICIOSISTEMATPL
        --,DATAHORAFIMSISTEMATPL
        --,DATAHORAINICIOTRANSACAOTPL
    )
    SELECT
         M.IDEMPREENDIMENTORURAL_NEW
        ,S.VALORRECURSOPROPRIO
        ,S.VALORFINANCIADO
        ,S.VALORTOTALEMPREENDIMENTO
        ,S.VALORPREVISAOPRODUCAO
        ,S.IDUNIDADEMEDIDAPREVISAOPRODUCAO
        ,S.VALOREXPLORACAO
        ,S.IDUNIDADEMEDIDAEXPLORADA
        ,S.VALORPRECOMEDIO
        ,S.VALORRBE
        ,S.IDTIPOTECNOLOGIA
        ,S.QTDPRODUTIVIDADE
        ,S.PERCFINANCIADO
        ,S.VALORTOTALORCAMENTO
        ,S.DESCEXPLORACAO
        --,S.DATAHORAINICIOSISTEMATPL
        --,S.DATAHORAFIMSISTEMATPL
        --,S.DATAHORAINICIOTRANSACAOTPL
    FROM CRE.EMPREENDIMENTORURALCUSTEIO S
    INNER JOIN SESSION.TB_EMPREENDIMENTORURAL_MAPA M
        ON M.IDEMPREENDIMENTORURAL_ORIGEM = S.IDEMPREENDIMENTORURAL;


        ----------------------------------------------------------------
    -- COPIA REGISTROS CRE.EMPREENDIMENTORURALCUSTEIOSISTEMAPRODUCAO
    ----------------------------------------------------------------
    INSERT INTO CRE.EMPREENDIMENTORURALCUSTEIOSISTEMAPRODUCAO (
         IDEMPREENDIMENTORURAL
        ,IDEMPREENDIMENTOBACEN
        ,IDTIPOAGROPECUARIABACEN
        ,IDTIPOCULTIVOBACEN
        ,IDGRAOSEMENTEBACEN
        ,IDFASECICLOPRODUCAOBACEN
        ,IDTIPOIRRIGACAOBACEN
        ,IDTIPOCONSORCIOBACEN
        ,IDSISTEMAPRODUCAOANTIGO
        ,IDPRODUTOCONSORCIADO
        ,IDTIPOCLIMABACEN
        ,IDOUTRAPRATICAMANEJOBACEN
    )
    SELECT
         M.IDEMPREENDIMENTORURAL_NEW
        ,S.IDEMPREENDIMENTOBACEN
        ,S.IDTIPOAGROPECUARIABACEN
        ,S.IDTIPOCULTIVOBACEN
        ,S.IDGRAOSEMENTEBACEN
        ,S.IDFASECICLOPRODUCAOBACEN
        ,S.IDTIPOIRRIGACAOBACEN
        ,S.IDTIPOCONSORCIOBACEN
        ,S.IDSISTEMAPRODUCAOANTIGO
        ,S.IDPRODUTOCONSORCIADO
        ,S.IDTIPOCLIMABACEN
        ,S.IDOUTRAPRATICAMANEJOBACEN
    FROM CRE.EMPREENDIMENTORURALCUSTEIOSISTEMAPRODUCAO S
    INNER JOIN SESSION.TB_EMPREENDIMENTORURAL_MAPA M
        ON M.IDEMPREENDIMENTORURAL_ORIGEM = S.IDEMPREENDIMENTORURAL;

        ----------------------------------------------------------------
    -- COPIA REGISTROS CRE.EMPREENDIMENTORURALCOOPERADO
    ----------------------------------------------------------------
    INSERT INTO CRE.EMPREENDIMENTORURALCOOPERADO (
         IDEMPREENDIMENTORURAL
        ,CODTIPOPESSOA
        ,NUMCPFCNPJ
        ,VALORPARCELACREDITO
    )
    SELECT
         M.IDEMPREENDIMENTORURAL_NEW
        ,S.CODTIPOPESSOA
        ,S.NUMCPFCNPJ
        ,S.VALORPARCELACREDITO
    FROM CRE.EMPREENDIMENTORURALCOOPERADO S
    INNER JOIN SESSION.TB_EMPREENDIMENTORURAL_MAPA M
        ON M.IDEMPREENDIMENTORURAL_ORIGEM = S.IDEMPREENDIMENTORURAL;

        ----------------------------------------------------------------
    -- COPIA REGISTROS CRE.EMPREENDIMENTORURALINFOZARC
    ----------------------------------------------------------------
    INSERT INTO CRE.EMPREENDIMENTORURALINFOZARC (
         IDEMPREENDIMENTORURAL
        ,CODTIPOMANEJO
        ,CODTIPOSOLO
        ,CODCICLOCULTIVAR
    )
    SELECT
         M.IDEMPREENDIMENTORURAL_NEW
        ,S.CODTIPOMANEJO
        ,S.CODTIPOSOLO
        ,S.CODCICLOCULTIVAR
    FROM CRE.EMPREENDIMENTORURALINFOZARC S
    INNER JOIN SESSION.TB_EMPREENDIMENTORURAL_MAPA M
        ON M.IDEMPREENDIMENTORURAL_ORIGEM = S.IDEMPREENDIMENTORURAL;

        ----------------------------------------------------------------
    -- COPIA REGISTROS CRE.PROAGROMAISOPERACAO
    ----------------------------------------------------------------
    FOR V_PROAGRO AS CUR_PROAGRO CURSOR FOR
        SELECT
             IDPROAGROMAISOPERACAO
            ,M.IDEMPREENDIMENTORURAL_NEW
            ,IDOPERACAOORIGEMLEGADO
            ,IDINSTITUCAOOPERACAOLEGADO
            ,IDCONTRATOCREDITOLEGADO
            ,NUMREFERENCIASICOR
        FROM CRE.PROAGROMAISOPERACAO S
        INNER JOIN SESSION.TB_EMPREENDIMENTORURAL_MAPA M
            ON M.IDEMPREENDIMENTORURAL_ORIGEM = S.IDEMPREENDIMENTORURAL
    DO
        INSERT INTO CRE.PROAGROMAISOPERACAO (
             IDEMPREENDIMENTORURAL
            ,IDOPERACAOORIGEMLEGADO
            ,IDINSTITUCAOOPERACAOLEGADO
            ,IDCONTRATOCREDITOLEGADO
            ,NUMREFERENCIASICOR
        )
        VALUES (
             V_PROAGRO.IDEMPREENDIMENTORURAL_NEW
            ,V_PROAGRO.IDOPERACAOORIGEMLEGADO
            ,V_PROAGRO.IDINSTITUCAOOPERACAOLEGADO
            ,V_PROAGRO.IDCONTRATOCREDITOLEGADO
            ,V_PROAGRO.NUMREFERENCIASICOR
        );

        SET V_ID_PROAGROMAISOPERACAO_NEW = IDENTITY_VAL_LOCAL();

        INSERT INTO SESSION.TB_PROAGROMAISOPERACAO_MAPA (
             IDPROAGROMAISOPERACAO_ORIGEM
            ,IDPROAGROMAISOPERACAO_NEW
        )
        VALUES (
             V_PROAGRO.IDPROAGROMAISOPERACAO
            ,V_ID_PROAGROMAISOPERACAO_NEW
        );
    END FOR;

        ----------------------------------------------------------------
    -- COPIA REGISTROS CRE.PROAGROMAISPARCELA
    ----------------------------------------------------------------    
    INSERT INTO CRE.PROAGROMAISPARCELA (
         IDPROAGROMAISOPERACAO
        ,VALORPARCELA
        ,NUMPARCELA
        ,DATAVENCIMENTO
    )
    SELECT
         M.IDPROAGROMAISOPERACAO_NEW
        ,S.VALORPARCELA
        ,S.NUMPARCELA
        ,S.DATAVENCIMENTO
    FROM CRE.PROAGROMAISPARCELA S
    INNER JOIN SESSION.TB_PROAGROMAISOPERACAO_MAPA M
        ON M.IDPROAGROMAISOPERACAO_ORIGEM = S.IDPROAGROMAISOPERACAO;


        ----------------------------------------------------------------
    -- COPIA REGISTROS CRE.EMPREENDIMENTORURALIMOVEL
    ----------------------------------------------------------------    
    FOR V_IMOVEL AS CUR_IMOVEL CURSOR FOR
        SELECT
             IDEMPREENDIMENTORURALIMOVEL
            ,M.IDEMPREENDIMENTORURAL_NEW
            ,IDIMOVEL
            ,VALORAREAEXPLORADA
            ,NUMNIRF
            ,NUMSNCR
            ,NUMREGCAR
            ,IDBEMIMOVEL
            --,DATAHORAINICIOSISTEMATPL
            --,DATAHORAFIMSISTEMATPL
            --,DATAHORAINICIOTRANSACAOTPL
            ,NUMOUTORGADAGUA
            ,PERCPRESERVACAO
            ,BOLPOSSUIGLEBA
            ,BOLINDCONFORMIDADEIMOVEL
            ,VALORUNIDADEANIMAL
        FROM CRE.EMPREENDIMENTORURALIMOVEL S
        INNER JOIN SESSION.TB_EMPREENDIMENTORURAL_MAPA M
            ON M.IDEMPREENDIMENTORURAL_ORIGEM = S.IDEMPREENDIMENTORURAL
    DO
        INSERT INTO CRE.EMPREENDIMENTORURALIMOVEL (
             IDEMPREENDIMENTORURAL
            ,IDIMOVEL
            ,VALORAREAEXPLORADA
            ,NUMNIRF
            ,NUMSNCR
            ,NUMREGCAR
            ,IDBEMIMOVEL
            --,DATAHORAINICIOSISTEMATPL
            --,DATAHORAFIMSISTEMATPL
            --,DATAHORAINICIOTRANSACAOTPL
            ,NUMOUTORGADAGUA
            ,PERCPRESERVACAO
            ,BOLPOSSUIGLEBA
            ,BOLINDCONFORMIDADEIMOVEL
            ,VALORUNIDADEANIMAL
        )
        VALUES (
             V_IMOVEL.IDEMPREENDIMENTORURAL_NEW
            ,V_IMOVEL.IDIMOVEL
            ,V_IMOVEL.VALORAREAEXPLORADA
            ,V_IMOVEL.NUMNIRF
            ,V_IMOVEL.NUMSNCR
            ,V_IMOVEL.NUMREGCAR
            ,V_IMOVEL.IDBEMIMOVEL
            --,V_IMOVEL.DATAHORAINICIOSISTEMATPL
            --,V_IMOVEL.DATAHORAFIMSISTEMATPL
            --,V_IMOVEL.DATAHORAINICIOTRANSACAOTPL
            ,V_IMOVEL.NUMOUTORGADAGUA
            ,V_IMOVEL.PERCPRESERVACAO
            ,V_IMOVEL.BOLPOSSUIGLEBA
            ,V_IMOVEL.BOLINDCONFORMIDADEIMOVEL
            ,V_IMOVEL.VALORUNIDADEANIMAL
        );

        SET V_ID_EMPREENDIMENTORURALIMOVEL_NEW = IDENTITY_VAL_LOCAL();

        INSERT INTO SESSION.TB_EMPREENDIMENTORURALIMOVEL_MAPA (
             IDEMPREENDIMENTORURALIMOVEL_ORIGEM
            ,IDEMPREENDIMENTORURALIMOVEL_NEW
        )
        VALUES (
             V_IMOVEL.IDEMPREENDIMENTORURALIMOVEL
            ,V_ID_EMPREENDIMENTORURALIMOVEL_NEW
        );
    END FOR;

        ----------------------------------------------------------------
    -- COPIA REGISTROS CRE.EMPREENDIMENTORURALIMOVELGLEBAGEO
    ----------------------------------------------------------------    
    INSERT INTO CRE.EMPREENDIMENTORURALIMOVELGLEBAGEO (
         IDGLEBA
        ,IDEMPREENDIMENTORURALIMOVEL
    )
    SELECT
         S.IDGLEBA
        ,M.IDEMPREENDIMENTORURALIMOVEL_NEW
    FROM CRE.EMPREENDIMENTORURALIMOVELGLEBAGEO S
    INNER JOIN SESSION.TB_EMPREENDIMENTORURALIMOVEL_MAPA M
        ON M.IDEMPREENDIMENTORURALIMOVEL_ORIGEM = S.IDEMPREENDIMENTORURALIMOVEL;


