-- COPY-DATABASE-OBJECT: "USRCRL"."TEST"
CREATE OR REPLACE PROCEDURE "USRCRL"."TEST" (IN indbnm VARCHAR(30), IN intblnm VARCHAR(30))
LANGUAGE SQL
BEGIN
DECLARE statmnt2 VARCHAR(1000); 
DECLARE VAR_COD_TIPO_ARQU CHAR(1);  
DECLARE stmt1 STATEMENT; 

SET statmnt2 = 'SELECT '||indbnm||' FROM CRL.VARIAVELCOMPORTAMENTAL FETCH FIRST 1 ROWS ONLY';
PREPARE stmt1 FROM statmnt2;
EXECUTE stmt1 into VAR_COD_TIPO_ARQU ;
END
;
-- COPY-DATABASE-OBJECT: "USRGEDAD"."LOADDATA"
CREATE OR REPLACE PROCEDURE "USRGEDAD"."LOADDATA"(VSCHEMA VARCHAR(20),
											  VTABELA VARCHAR(100),
											  VCOMANDO VARCHAR(1000)) MODIFIES SQL DATA NOT
DETERMINISTIC LANGUAGE SQL
	BEGIN
		DECLARE  RETCODE INTEGER DEFAULT 0;
		DECLARE  SQLCODE INTEGER DEFAULT 0;
		DECLARE  ROWS_READ INTEGER;
		DECLARE  ROWS_SKIPPED INTEGER;
		DECLARE  ROWS_LOADED INTEGER;
		DECLARE  ROWS_REJECTED INTEGER;
		DECLARE  ROWS_DELETED INTEGER;
		DECLARE  ROWS_COMMITTED INTEGER;
		DECLARE  ROWS_PARTITIONED INTEGER;
		DECLARE  NUM_AGENTINFO_ENTRIES INTEGER;
		DECLARE  MSG_RETRIEVAL VARCHAR(500);
		DECLARE  MSG_REMOVAL VARCHAR(500);
		DECLARE  DATAHORAINICIOCARGA TIMESTAMP;
		DECLARE  RESULT1 RESULT_SET_LOCATOR VARYING;
		DECLARE  CONTINUE HANDLER FOR SQLEXCEPTION,SQLWARNING
BEGIN
	SET RETCODE = SQLCODE;
END;
SET DATAHORAINICIOCARGA = CURRENT TIMESTAMP;
CALL SYSPROC.ADMIN_CMD (VCOMANDO);
ASSOCIATE RESULT SET LOCATORS (RESULT1) WITH
PROCEDURE SYSPROC.ADMIN_CMD;
ALLOCATE RSCUR
CURSOR FOR RESULT SET RESULT1;
FETCH
	RSCUR
INTO
	ROWS_READ,
	ROWS_SKIPPED,
	ROWS_LOADED,
	ROWS_REJECTED,
	ROWS_DELETED,
	ROWS_COMMITTED,
	ROWS_PARTITIONED,
	NUM_AGENTINFO_ENTRIES,
	MSG_RETRIEVAL,
	MSG_REMOVAL;
CLOSE RSCUR WITH RELEASE;
INSERT INTO USRGEDAD.LOADLOG 
VALUES (
		VSCHEMA,
		VTABELA,
		DATAHORAINICIOCARGA,
		CURRENT TIMESTAMP,
		ROWS_READ,
		ROWS_SKIPPED,
		ROWS_LOADED,
		ROWS_REJECTED,
		ROWS_DELETED,
		ROWS_COMMITTED,
		ROWS_PARTITIONED,
		NUM_AGENTINFO_ENTRIES,
		MSG_RETRIEVAL,
		MSG_REMOVAL
	);
END
;

