   REFERENCING NEW AS NEW
   FOR EACH ROW MODE DB2SQL
BEGIN
   SET (NEW.IDINSTITUICAOORIGEM,NEW.IDINSTITUICAO,BOLATIVOINFORMACAOLIMITE) = (SELECT ILA.IDINSTITUICAOORIGEM,IL.IDINSTITUICAO,IL.BOLATIVO
