   BEFORE UPDATE OF IDOPERACAOCREDITO ON CPR.OPERACAOCEDULAPRODUTORURAL
   REFERENCING NEW AS NEW
   FOR EACH ROW MODE DB2SQL
BEGIN
   SET (NEW.DATACADASTROPROPOSTA,NEW.DATAHORAULTIMALIBERACAO) = (SELECT OC.DATACADASTROPROPOSTA,OCC.DATAHORAULTIMALIBERACAO
                                                                 FROM CRE.OPERACAOCREDITO OC LEFT OUTER JOIN CRE.OPERACAOCREDITOCOMPLEMENTO OCC ON OC.IDOPERACAOCREDITO = OCC.IDOPERACAOCREDITO
                                                                 WHERE OC.IDOPERACAOCREDITO = NEW.IDOPERACAOCREDITO);
END;
;
-- COPY-DATABASE-OBJECT: "CRE"."TRG_ANOTACAOCREDITOOCORRENCIA_A_I"
CREATE OR REPLACE TRIGGER "CRE"."TRG_ANOTACAOCREDITOOCORRENCIA_A_I"
    AFTER INSERT ON CRE.ANOTACAOCREDITOOCORRENCIA
    REFERENCING NEW AS NEW 
    FOR EACH ROW MODE DB2SQL 
BEGIN ATOMIC

    -- Se a categoria for IMPEDITIVA RELATIVA e a respectiva coluna não estiver marcada, atualiza a tabela de complemento.

    IF NEW.CODCATEGORIAANOTACAO = 0 THEN

        UPDATE
            CRE.OPERACAOCREDITOCOMPLEMENTO OCP
        SET
            OCP.BOLANOTACAOCREDITOIMPEDITIVARELATIVA = 1
        WHERE
            OCP.IDOPERACAOCREDITO = NEW.IDOPERACAOCREDITO
            AND OCP.BOLANOTACAOCREDITOIMPEDITIVARELATIVA = 0;

    -- Se a categoria for IMPEDITIVA e a respectiva coluna não estiver marcada, atualiza a tabela de complemento.

    ELSEIF NEW.CODCATEGORIAANOTACAO = 1 THEN

        UPDATE
            CRE.OPERACAOCREDITOCOMPLEMENTO OCP
        SET
            OCP.BOLANOTACAOIMPEDITIVA = 1
        WHERE
            OCP.IDOPERACAOCREDITO = NEW.IDOPERACAOCREDITO
            AND OCP.BOLANOTACAOIMPEDITIVA = 0;

    END IF;

END
;
