-- COPY-DATABASE-OBJECT: "CRE"."TRG_LANCAMENTOOPERACAO_TESTE_A_I_U"
CREATE OR REPLACE TRIGGER "CRE"."TRG_LANCAMENTOOPERACAO_TESTE_A_I_U"
   AFTER INSERT OR UPDATE OF DATAHORALANCAMENTOOPERACAO ON CRE.LANCAMENTOOPERACAO_TESTE
   REFERENCING NEW AS NEW
   FOR EACH ROW MODE DB2SQL
BEGIN
   IF NEW.DATAHORALANCAMENTOOPERACAO IS NOT NULL
  AND NEW.CODTIPOCRITERIO = 2 
  AND NEW.BOLESTORNADA = 0 
  AND NEW.DATAHORALANCAMENTOOPERACAO = (SELECT MAX(DATAHORALANCAMENTOOPERACAO) 
                                        FROM CRE.LANCAMENTOOPERACAO
                                        WHERE CODTIPOCRITERIO = 2
                                          AND BOLESTORNADA = 0
                                          AND IDOPERACAOCREDITO = NEW.IDOPERACAOCREDITO)
  AND EXISTS (SELECT 1
              FROM CRE.OPERACAOCREDITOCOMPLEMENTO_TESTE
              WHERE IDOPERACAOCREDITO = NEW.IDOPERACAOCREDITO
                AND DATAHORAULTIMALIBERACAO IS NULL) THEN
                   
      UPDATE CRE.OPERACAOCREDITO_TESTE
      SET DATAXXX = NEW.DATAHORALANCAMENTOOPERACAO 
      WHERE IDOPERACAOCREDITO = NEW.IDOPERACAOCREDITO
        AND NEW.DATAHORALANCAMENTOOPERACAO <> NVL(DATAXXX,'1900-01-01');
   END IF;      
END
;
