-- COPY-DATABASE-OBJECT: "CRE"."TRG_LINHAGRUPOLIBERACAO_A_U"
--SCRIPT-3

CREATE OR REPLACE TRIGGER "CRE"."TRG_LINHAGRUPOLIBERACAO_A_U"
   AFTER UPDATE OF IDINSTITUICAO,BOLATIVO ON CRE.LINHAGRUPOLIBERACAO
   REFERENCING NEW AS NEW OLD AS OLD
   FOR EACH ROW MODE DB2SQL
   WHEN (OLD.BOLATIVO <> NEW.BOLATIVO OR OLD.IDINSTITUICAO <> NEW.IDINSTITUICAO)
BEGIN
   IF OLD.BOLATIVO <> NEW.BOLATIVO  THEN
      UPDATE CRE.LINHAGRUPOLIBERACAODETALHE
      SET BOLATIVO = NEW.BOLATIVO
      WHERE IDGRUPOLINHALIBERACAO = NEW.IDGRUPOLINHALIBERACAO;
   ELSEIF NEW.IDINSTITUICAO <> OLD.IDINSTITUICAO THEN
          UPDATE CRE.LINHAGRUPOLIBERACAODETALHE
          SET IDINSTITUICAO = NEW.IDINSTITUICAO
          WHERE IDGRUPOLINHALIBERACAO = NEW.IDGRUPOLINHALIBERACAO;
   END IF;    
END
;
