-- COPY-DATABASE-OBJECT: "CRE"."TRG_OPERACAOALCADA_A_I"
CREATE OR REPLACE TRIGGER "CRE"."TRG_OPERACAOALCADA_A_I"
    AFTER INSERT OR UPDATE OF CODSITUACAOALCADACREDITO, DESCNIVELATUAL, SIGLAFLUXOAPROVACAO ON CRE.OPERACAOALCADA
    REFERENCING NEW AS NEW 
    FOR EACH ROW MODE DB2SQL 
BEGIN

    -- Atualiza a situação, nível atual, e sigla fluxo da alçada na complemento sempre que for inserido/atualizado o registro na tabela OPERACAOALCADA.

    IF INSERTING THEN 

        -- Na inclusão deve atualizar também a DATAHORAOPERACAOALCADA.
        
        UPDATE
            CRE.OPERACAOCREDITOCOMPLEMENTO OCP
        SET
            OCP.DATAHORAOPERACAOALCADA = CURRENT_TIMESTAMP,
            OCP.CODSITUACAOALCADACREDITO = NEW.CODSITUACAOALCADACREDITO,
            OCP.DESCNIVELATUAL = NEW.DESCNIVELATUAL,
            OCP.SIGLAFLUXOAPROVACAO = NEW.SIGLAFLUXOAPROVACAO
        WHERE
            OCP.IDOPERACAOCREDITO = NEW.IDOPERACAOCREDITO;

    ELSEIF UPDATING THEN

        UPDATE
            CRE.OPERACAOCREDITOCOMPLEMENTO OCP
        SET
            OCP.CODSITUACAOALCADACREDITO = NEW.CODSITUACAOALCADACREDITO,
            OCP.DESCNIVELATUAL = NEW.DESCNIVELATUAL,
