CREATE OR REPLACE TRIGGER "USRDB2TUNE"."TRG_TESTE_B_I"
   BEFORE INSERT ON TESTE
   REFERENCING NEW AS NEW
   FOR EACH ROW
BEGIN
   DECLARE VMENSAGEM VARCHAR(70);
   SET VMENSAGEM = 'Código '||new.codigo||' nome -> '||new.nome||' data -> '||to_char(new.data,'yyyymmdd');
   SIGNAL SQLSTATE '75002'
      SET MESSAGE_TEXT = VMENSAGEM;
END
